ted = listOf("Wohnung B ist die beste."), focus = "die beste", watch = "Superlativ mit die."), PracticeQuestion(prompt = "Sag, dass sie gleich groß sind.", expected = listOf("Sie sind so groß wie die andere."), focus = "so wie", watch = "so + adj + wie = Gleichheit."), PracticeQuestion(prompt = "Wähle und begründe. (B, größer)", expected = listOf("Ich nehme B, weil sie größer ist."), focus = "weil", watch = "weil + Satzbau mit Verb am Ende."), PracticeQuestion(prompt = "Vergleiche die Größe: A 60m², B 80m².", expected = listOf("B ist größer als A."), focus = "größer als", watch = "größer + als."))), exercises = listOf(Exercise(id = "de-foundations-u4-komparativ-e1", kind = "choice", prompt = "Berlin ist ___ ___ München.", options = listOf("größer als", "groß als", "so groß wie", "am größten"), answers = listOf("größer als"), explain = "Komparativ + als."), Exercise(id = "de-foundations-u4-komparativ-e2", kind = "gap", prompt = "Das ist das ___ Restaurant. (gut)", options = listOf(), answers = listOf("beste"), explain = "gut → das beste."), Exercise(id = "de-foundations-u4-komparativ-e3", kind = "order", prompt = "Vergleiche den Preis.", options = listOf(), answers = listOf("Wohnung A ist billiger als B"), explain = "Komparativ + als."), Exercise(id = "de-foundations-u4-komparativ-e4", kind = "written", prompt = "Dein Lieblingsrestaurant.", options = listOf(), answers = listOf("mein lieblingsrestaurant ist <name>", "das beste ist <name>"), explain = "Mein Liebling ist X.")), skills = listOf("grammar:comparatives", "grammar:superlatives", "grammar:connectors", "function:express-opinion"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:comparatives"))))
