    Lesson(id = "de-foundations-u7-register", title = "Man sagt…", goal = "Wiedergeben, was andere behaupten: unpersönlich mit « man » und Passiv mit « werden ».", intro = LessonIntro(explanation = listOf("Unpersönlich: « Man sagt, dass sich das Viertel ändert ». Niemand tritt als Quelle auf.", "Passiv: « Das Konzert wurde abgesagt », « Die Tickets sind ausverkauft ». Sprach der Nachrichten.", "Das Passiv (wurde + Partizip II) hebt das Register; « man » bleibt Alltag."), examples = listOf(ExampleLine(text = "Man sagt, dass sich das Viertel ändert.", meaning = "Unpersönlich: Gerücht."), ExampleLine(text = "Das Konzert wurde wegen des Regens abgesagt.", meaning = "Passiv Präteritum."), ExampleLine(text = "Die Tickets sind ausverkauft.", meaning = "Zustandspassiv (sein)."), ExampleLine(text = "Alle Züge wurden gestrichen.", meaning = "Offizielle Meldung."), ExampleLine(text = "Laut Rathaus verzögern sich die Bauarbeiten.", meaning = "Quelle + Verb."))), expressions = listOf(TargetExpression(text = "man sagt, dass…", meaning = "Gerücht.", note = "…sich das Viertel ändert."), TargetExpression(text = "wurde + Partizip II", meaning = "Passiv.", note = "wurde abgesagt."), TargetExpression(text = "sind + Partizip II", meaning = "Zustand.", note = "sind ausverkauft."), TargetExpression(text = "laut + Quelle", meaning = "Zitieren.", note = "laut Rathaus."), TargetExpression(text = "es heißt, …", meaning = "Offiziell.", note = "es heißt, der Bau…")), situation = "Ihr besprecht die Nachrichten im Viertel: was man sagt, was beschlossen wurde und welcher Quelle ihr weniger vertraut.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Gib das Gerücht weiter: man sagt, dass sich das Viertel ändert.", expected = listOf("Man sagt dass sich das Viertel andert", "Man sagt, dass sich das Viertel ändert"), focus = "man sagt", watch = "Unpersönlich, kein Subjekt."), PracticeQuestion(prompt = "Meldung: das Konzert wurde wegen des Regens abgesagt.", expected = listOf("D