                ConversationTheme("de-b2-kolumne", "Deine Kolumne", "Einerseits… andererseits…", "pencil", "Course", "Ihr schreibt eine Kolumne über die autofreie Innenstadt.", 1)), lessons = listOf(    Lesson(id = "de-foundations-u7-relativsaetze", title = "Die Nachricht, die ich gelesen habe", goal = "Nachrichten mit Relativsätzen erzählen: der/die/das, wo, deren.", intro = LessonIntro(explanation = listOf("Der Relativsatz passt sich an: « Die Nachricht, die ich gelesen habe… », « Der Journalist, der ihn interviewt hat… ».", "« Wo » für Orte: « Der Platz, wo sie demonstriert haben ». « Deren » für Besitz: « Die Firma, deren Chef zurückgetreten ist ».", "In Nachrichten verdichten Relativsätze: wer, wo, was."), examples = listOf(ExampleLine(text = "Die Nachricht, die ich gelesen habe, sagt…", meaning = "Relativsatz (Objekt)."), ExampleLine(text = "Der Journalist, der ihn interviewt hat, trat zurück.", meaning = "Relativsatz (Subjekt)."), ExampleLine(text = "Der Platz, wo sie demonstriert haben, ist zentral.", meaning = "wo + Ort."), ExampleLine(text = "Die Firma, deren Chef zurücktrat, reagierte.", meaning = "deren = Besitz."), ExampleLine(text = "Alles, was ich weiß, kommt vom Radio.", meaning = "alles, was + Verb."))), expressions = listOf(TargetExpression(text = "der/die/das … , der/die/das …", meaning = "Relativpronomen.", note = "die Nachricht, die…"), TargetExpression(text = "… , wo …", meaning = "Ort.", note = "der Platz, wo…"), TargetExpression(text = "deren + Nomen", meaning = "Besitz.", note = "die Firma, deren Chef…"), TargetExpression(text = "alles, was…", meaning = "Verallgemeinern.", note = "alles, was ich weiß."), TargetExpression(text = "Komma vor Relativsatz", meaning = "Rechtschreibung.", note = "immer mit Komma.")), situation = "Ihr fasst eine Nachrichtewoche zusammen: die Story, die euch traf, die Person, die sprach, und der Ort, wo es passierte.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Fasse zusammen: die Nachricht, die ich gelesen habe, sagt, dass das Museum longer öffnet.", expected = listOf("Die Nachricht die ich gelesen habe sagt dass das museum langer offnet", "Die Nachricht, die ich gelesen habe, sagt, dass das Museum länger öffnet"), focus = "die ich gelesen habe", watch = "Relativsatz zur Nachricht."), PracticeQuestion(prompt = "Wer: der Journalist, der ihn interviewt hat, trat zurück.", expected = listOf("Der Journalist der ihn interviewt hat trat zuruck", "Der Journalist, der ihn interviewt hat, trat zurück"), focus = "der ihn interviewt hat", watch = "Relativsatz Subjekt."), PracticeQuestion(prompt = "Ort: der Platz, wo sie demonstriert haben, ist zentral.", expected = listOf("Der Platz wo sie demonstriert haben ist zentral", "Der Platz, wo sie demonstriert haben, ist zentral"), focus = "wo", watch = "wo + Ort."), PracticeQuestion(prompt = "Besitz: die Firma, deren Chef zurücktrat, reagierte.", expected = listOf("Die Firma deren Chef zurucktrat reagierte", "Die Firma, deren Chef zurücktrat, reagierte"), focus = "deren", watch = "deren + Nomen."), PracticeQuestion(prompt = "Verallgemeinere: alles, was ich weiß, kommt vom Radio.", expected = listOf("Alles was ich weiss kommt vom radio", "Alles, was ich weiß, kommt vom Radio"), focus = "alles, was", watch = "alles, was + Verb."))), exercises = listOf(Exercise(id = "de-foundations-u7-relativsaetze-e1", kind = "choice", prompt = "Die Nachricht, ___ ich gelesen habe, ist wichtig.", options = listOf("die", "der", "das", "den"), answers = listOf("die"), explain = "die Nachricht (fem): die."), Exercise(id = "de-foundations-u7-relativsaetze-e2", kind = "gap", prompt = "Der Platz, ___ sie demonstriert haben, ist zentral.", options = listOf(), answers = listOf("wo"), explain = "Ort: wo + Relativsatz, immer mit Komma davor."), Exercise(id = "de-foundations-u7-relativsaetze-e3", kind = "order", prompt = "Subjekt: der Journalist, der ihn interviewt hat, trat zurück.", options = listOf(), answers = listOf("Der Journalist, der ih