    Lesson(id = "de-foundations-u7-argumentieren", title = "Einerseits… andererseits…", goal = "Eine Meinung strukturiert schreiben und verteidigen: These, Argumente, Einräumung, Schluss.", intro = LessonIntro(explanation = listOf("Struktur: These (« Ich finde, wir sollten die Innenstadt autofrei machen »), Argumente (« einerseits…, andererseits… »), Einräumung (« es stimmt, dass…, aber… »).", "Die Einräumung schafft Glaubwürdigkeit: du erkennst die Gegenseite an, bevor du antwortest.", "Schluss mit Gewicht: « Aus all dem verteidige ich die Maßnahme »."), examples = listOf(ExampleLine(text = "Ich finde, wir sollten die Innenstadt autofrei machen.", meaning = "These."), ExampleLine(text = "Einerseits sinkt die Verschmutzung.", meaning = "Argument 1."), ExampleLine(text = "Andererseits leidet der Handel.", meaning = "Argument 2 (gegen)."), ExampleLine(text = "Es stimmt, dass es unbequem ist, aber die Zahlen sagen etwas anderes.", meaning = "Einräumung + Antwort."), ExampleLine(text = "Aus all dem verteidige ich die Maßnahme.", meaning = "Schluss."))), expressions = listOf(TargetExpression(text = "ich finde, wir sollten…", meaning = "These.", note = "…autofrei machen."), TargetExpression(text = "einerseits… andererseits…", meaning = "Argumente.", note = "die zwei Seiten."), TargetExpression(text = "es stimmt, dass…, aber…", meaning = "Einräumung.", note = "anerkennen und antworten."), TargetExpression(text = "die Zahlen sagen…", meaning = "Beweis.", note = "Autoritätsargument."), TargetExpression(text = "aus all dem, …", meaning = "Schluss.", note = "formeller Abschluss.")), situation = "Ihr schreibt eine Meinungskolumne über die autofreie Innenstadt: These, zwei Seiten, Einräumung, Schluss.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "These: ich finde, wir sollten die Innenstadt autofrei machen.", expected = listOf("Ich finde wir sollten die innenstadt autofrei machen", "Ich finde, wir sollten die Innenstadt autofrei machen"), focus = "ich finde", watch = "These + sollen."), PracticeQuestion(prompt = "Argument 1: einerseits sinkt die Verschmutzung.", expected = listOf("Einerseits sinkt die verschmutzung", "Einerseits sinkt die Verschmutzung"), focus = "einerseits", watch = "Erstes Argument."), PracticeQuestion(prompt = "Gegenargument: andererseits leidet der Handel.", expected = listOf("Andererseits leidet der handel", "Andererseits leidet der Handel"), focus = "andererseits", watch = "Zweite Seite."), PracticeQuestion(prompt = "Räum ein: es stimmt, dass es unbequem ist, aber die Zahlen sagen etwas anderes.", expected = listOf("Es stimmt dass es unbequem ist aber die zahlen sagen etwas anderes", "Es stimmt, dass es unbequem ist, aber die Zahlen sagen etwas anderes"), focus = "es stimmt, dass", watch = "Einräumung + aber."), PracticeQuestion(prompt = "Schließe: aus all dem verteidige ich die Maßnahme.", expected = listOf("Aus all dem verteidige ich die massnahme", "Aus all dem verteidige ich die Maßnahme"), focus = "aus all dem", watch = "Formeller Schluss."))), exercises = listOf(Exercise(id = "de-foundations-u7-argumentieren-e1", kind = "choice", prompt = "___ sinkt die Verschmutzung; ___ leidet der Handel.", options = listOf("Einerseits / andererseits", "Erstens / zweitens", "Vor / nach", "Weil / aber"), answers = listOf("Einerseits / andererseits"), explain = "Die zwei Seiten."), Exercise(id = "de-foundations-u7-argumentieren-e2", kind = "gap", prompt = "Es stimmt, dass es unbequem ist, ___ die Zahlen sagen etwas anderes.", options = listOf(), answers = listOf("aber", "doch"), explain = "Einräumung + Kontrast."), Exercise(id = "de-foundations-u7-argumentieren-e3", kind = "order", prompt = "Schluss: aus all dem verteidige ich die Maßnahme.", options = listOf(), answers = listOf("Aus all dem verteidige ich die Maßnahme"), explain = "aus all dem."), Exercise(id = "de-foundations-u7-argumentieren-e4", kind = "written", prompt = "Deine These zum ÖPNV-Ausbau (Straßenbahn).", options = listOf(), answers 