    Lesson(id = "de-foundations-u9-nuancen", title = "Mehr oder weniger", goal = "Meinungen nuancieren: abschwächen, einräumen und mit Abstand verallgemeinern – ohne an Klarheit zu verlieren.", intro = LessonIntro(explanation = listOf("Abschwächen klingt souverän: « Das ist eher eine Vermutung als ein Fakt » – so zeigen Sie Distanz, ohne grob zu widersprechen.", "Einräumen und halten: « Zwar ist der Ansatz teuer, aber er spart Zeit » – zwar + aber balanciert zwei Seiten in einem Satz.", "Verallgemeinern mit Abstand: « Sozusagen ein Kompromiss », « Gewissermaßen ein Neuanfang » – solche Wendungen signalisieren: ich sage es mit Vorsicht."), examples = listOf(ExampleLine(text = "Das ist eher eine Vermutung als ein Fakt.", meaning = "Abschwächung: eher … als."), ExampleLine(text = "Zwar ist der Ansatz teuer, aber er spart Zeit.", meaning = "zwar + aber = Einräumung."), ExampleLine(text = "Sozusagen ein Kompromiss auf Zeit.", meaning = "sozusagen = gewissermaßen."), ExampleLine(text = "Aus meiner Sicht ist das kein Widerspruch.", meaning = "Meinung markieren, sachlich bleiben."), ExampleLine(text = "Das überzeugt mich nicht unbedingt.", meaning = "Verneinen mit Feingefühl."))), expressions = listOf(TargetExpression(text = "eher … als …", meaning = "Vergleich mit Abschwächung.", note = "eher Vermutung als Fakt."), TargetExpression(text = "zwar …, aber …", meaning = "Einräumen und halten.", note = "zwar teuer, aber effektiv."), TargetExpression(text = "sozusagen / gewissermaßen", meaning = "Bildlich, mit Abstand.", note = "sozusagen ein Neuanfang."), TargetExpression(text = "aus meiner Sicht", meaning = "Meinung markieren.", note = "sachlicher als « ich finde »."), TargetExpression(text = "nicht unbedingt / nicht gerade", meaning = "Weich verneinen.", note = "nicht unbedingt überzeugt.")), situation = "Sie bewerten in der Redaktionsschleife Vorschläge des Teams – jedes Urteil bekommt eine Feinjustierung: eher, zwar… aber, sozusagen.", practice = LessonPractice(questions = 