    Lesson(id = "de-foundations-u9-prasentieren", title = "Ideen präsentieren", goal = "Einen kurzen Vortrag strukturieren: zunächst das Thema, im Folgenden die Punkte, zusammenfassend der Kern.", intro = LessonIntro(explanation = listOf("Einstieg mit Fahrplan: « Zunächst gehe ich auf den Hintergrund ein, danach zeige ich zwei Optionen » – die Zuhörer wissen sofort, wohin die Reise geht.", "Im Hauptteil Rote Fäden halten: « Im Folgenden », « anschließend », « daraus folgt » – solche Konnektoren tragen, wenn man frei spricht.", "Abschluss mit Gewicht: « Zusammenfassend bleibt: … », « Zum Schluss möchte ich den Zeitplan betonen » – am Ende nur noch eine Botschaft."), examples = listOf(ExampleLine(text = "Zunächst gehe ich auf den Hintergrund ein.", meaning = "Einstieg: erstes Element."), ExampleLine(text = "Im Folgenden vergleiche ich beide Optionen.", meaning = "Überleitung zum Hauptteil."), ExampleLine(text = "Daraus folgt: Wir brauchen eine Pilotphase.", meaning = "Folgerung ziehen."), ExampleLine(text = "Zusammenfassend sprechen die Zahlen für Variante B.", meaning = "Kern komprimieren."), ExampleLine(text = "Zum Schluss betone ich noch einmal den Zeitplan.", meaning = "Schlussakzent setzen."))), expressions = listOf(TargetExpression(text = "zunächst / anfangs", meaning = "Erster Schritt.", note = "Zunächst zum Hintergrund."), TargetExpression(text = "im Folgenden / anschließend", meaning = "Überleitung.", note = "Im Folgenden vergleiche ich…"), TargetExpression(text = "daraus folgt / folglich", meaning = "Folgern.", note = "Daraus folgt eine Pilotphase."), TargetExpression(text = "zusammenfassend bleibt…", meaning = "Kern nennen.", note = "…eine klare Empfehlung."), TargetExpression(text = "zum Schluss möchte ich … betonen", meaning = "Schlussakzent.", note = "…den Zeitplan.")), situation = "Sie pitchen der Geschäftsführung in drei Minuten ein internes Tool: Fahrplan, zwei Argumente, Folgerung – und ein Schlusssatz, der hängen bleibt.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Einstieg: zunächst gehe ich auf den Hintergrund ein.", expected = listOf("zunachst gehe ich auf den hintergrund ein", "zunächst gehe ich auf den hintergrund ein"), focus = "zunächst", watch = "Strukturwort an Position 1."), PracticeQuestion(prompt = "Überleitung: im Folgenden vergleiche ich beide Optionen.", expected = listOf("im folgenden vergleiche ich beide optionen", "im folgenden stelle ich beide optionen gegenuber", "im folgenden stelle ich beide optionen gegenüber"), focus = "im Folgenden", watch = "Konnektor + Präsens der Ankündigung."), PracticeQuestion(prompt = "Folgerung: daraus folgt, dass wir eine Pilotphase brauchen.", expected = listOf("daraus folgt dass wir eine pilotphase brauchen", "daraus folgt, dass wir eine pilotphase brauchen"), focus = "daraus folgt", watch = "dass-Satz als Inhalt der Folgerung."), PracticeQuestion(prompt = "Kern: zusammenfassend sprechen die Zahlen für Variante B.", expected = listOf("zusammenfassend sprechen die zahlen fur variante b", "zusammenfassend sprechen die zahlen für variante b"), focus = "zusammenfassend", watch = "Kern in einem Satz."), PracticeQuestion(prompt = "Schluss: zum Schluss möchte ich den Zeitplan betonen.", expected = listOf("zum schluss mochte ich den zeitplan betonen", "zum schluss möchte ich den zeitplan betonen"), focus = "zum Schluss", watch = "möchte + betonen: letzter Akzent."))), exercises = listOf(Exercise(id = "de-foundations-u9-prasentieren-e1", kind = "choice", prompt = "Einstieg mit Struktur: ___ gehe ich auf den Hintergrund ein, danach zeige ich die Optionen.", options = listOf("Zunächst", "Deshalb", "Trotzdem", "Stattdessen"), answers = listOf("Zunächst"), explain = "« zunächst » kündigt den ersten Schritt des Vortrags an."), Exercise(id = "de-foundations-u9-prasentieren-e2", kind = "gap", prompt = "Die Zahlen sinken, ___ müssen wir handeln. (Folgerung ziehen)", options = listOf(), answers = listOf("folglich", "daher", "deshalb"), explain = "F