    Lesson(id = "de-foundations-u12-freunde", title = "Wie ist er ?", goal = "Freunde mit Adjektiven beschreiben und fragen: Wie ist er ? Wie ist sie ?", intro = LessonIntro(explanation = listOf("Adjektive für Leute: nett, lustig, schüchtern, fleißig, sportlich. Beispiel: „Mia ist nett.“", "sein + Adjektiv: „Er ist lustig.“ „Sie ist schüchtern.“ So beschreibt man Leute.", "Frage: „Wie ist er ?“ — „Er ist sehr nett.“ Beispiel: „Und Lisa ? Sie ist fleißig.“"), examples = listOf(ExampleLine(text = "Mein Freund Jonas ist sehr nett.", meaning = "Beschreibung: sein + nett."), ExampleLine(text = "Er ist schüchtern, aber sehr fleißig.", meaning = "aber: zwei Adjektive, auch Gegensätze."), ExampleLine(text = "Wie ist deine Schwester ?", meaning = "Nach einer Person fragen."), ExampleLine(text = "Sie ist lustig und sportlich.", meaning = "und: zwei Adjektive zusammen."), ExampleLine(text = "Unser Lehrer ist immer freundlich.", meaning = "Adjektiv nach ist: keine Endung."))), expressions = listOf(TargetExpression(text = "nett / freundlich", meaning = "Positive Leute.", note = "Jonas ist nett."), TargetExpression(text = "schüchtern", meaning = "Nicht viel sprechen vor neuen Leuten.", note = "Sie ist schüchtern."), TargetExpression(text = "fleißig", meaning = "Viel arbeiten und lernen.", note = "Er ist fleißig."), TargetExpression(text = "lustig", meaning = "Man lacht viel.", note = "Mia ist lustig."), TargetExpression(text = "Wie ist er / sie ?", meaning = "Nach einer Person fragen.", note = "Wie ist dein Bruder ?")), situation = "Ben und Lena beschreiben ihre Freunde: Jonas ist schüchtern, aber fleißig. Mia ist lustig.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Fragst nach Bens Bruder.", expected = listOf("Wie ist Bens Bruder ?", "Wie ist er ?", "wie ist er"), focus = "wie ist … ?", watch = "Frage mit wie + sein."), PracticeQuestion(prompt = "Sagt, wie Jonas ist. (nett)", expected = listOf("Er ist nett.", "er ist nett", "er ist sehr nett"), focus