    Lesson(id = "de-foundations-u12-anruf", title = "Ein Anruf", goal = "Am Telefon fragen, ob jemand da ist, und sagen, dass du später anrufst.", intro = LessonIntro(explanation = listOf("Am Telefon: „Hallo, hier ist Nadia.“ So sagt man, wer du bist.", "Frage: „Ist Papa da ?“ — „Nein, er ist nicht da.“ So fragt man, ob jemand da ist.", "anrufen: „Ich rufe später an.“ Beispiel: „Rufst du morgen an ?“"), examples = listOf(ExampleLine(text = "Hallo, hier ist Nadia.", meaning = "Am Telefon: dein Name."), ExampleLine(text = "Ist dein Vater da ?", meaning = "Frage: Ist … da ?"), ExampleLine(text = "Nein, er ist nicht da.", meaning = "Negative Antwort: nicht da."), ExampleLine(text = "Wann ist er wieder da ?", meaning = "Nach der Zeit fragen."), ExampleLine(text = "Ich rufe später an.", meaning = "anrufen: ich rufe … an."))), expressions = listOf(TargetExpression(text = "Hallo, hier ist …", meaning = "Sich am Telefon melden.", note = "hier ist + Name"), TargetExpression(text = "Ist … da ?", meaning = "Fragen, ob jemand da ist.", note = "Ist Mama da ?"), TargetExpression(text = "Er / sie ist nicht da.", meaning = "Sagen, dass jemand weg ist.", note = "Sie ist nicht zu Hause."), TargetExpression(text = "Ich rufe später an.", meaning = "Sagen, dass du noch einmal anrufst.", note = "anrufen: ich rufe an"), TargetExpression(text = "Bis dann!", meaning = "Am Telefon verabschieden.", note = "auch: Tschüss!")), situation = "Nadia ruft zu Hause an. Papa ist nicht da — sie ruft später noch einmal an.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Meldest dich am Telefon. (Nadia)", expected = listOf("Hallo, hier ist Nadia.", "hallo hier ist nadia"), focus = "hier ist …", watch = "Am Telefon sagt man: hier ist + Name."), PracticeQuestion(prompt = "Fragst, ob Papa da ist.", expected = listOf("Ist Papa da ?", "ist papa da"), focus = "ist … da ?", watch = "Frage: Ist + Person + da ?"), PracticeQuestion(prompt = "Sagst, dass Mama nicht da ist.", expected = list