object EnBusinessU1 {
    val unit = CourseUnit(id = "en-business-u1", title = "Clients & deals", subtitle = "Pitch, negotiate, confirm", level = "B1", themes = listOf(ConversationTheme("sales-pitch", "The sales pitch", "Ninety seconds of value", "chart.bar", "Course", "You pitch your service to a skeptical client: problem, solution, proof — then handle the first objection.", 0),
                ConversationTheme("deal-closer", "Closing the deal", "Numbers on the table", "handshake", "Course", "Final round of a negotiation: price, timeline and the sentence that closes it.", 1)), lessons = listOf(    Lesson(id = "en-business-u1-pitch", title = "The pitch", goal = "Pitch a service: problem, solution, proof, in that order.", intro = LessonIntro(explanation = listOf("The pitch skeleton: “Your team wastes hours on X. We automate X. Company A saved 20% in one quarter.”", "Lead with the client's problem, never your product: the problem is why they're listening.", "One number beats ten adjectives: “a 20% saving” does the arguing for you."), examples = listOf(ExampleLine(text = "Your team wastes hours on X.", meaning = "The problem, stated as theirs."), ExampleLine(text = "We automate exactly that.", meaning = "The solution, one line."), ExampleLine(text = "Company A saved 20% in one quarter.", meaning = "Proof with a number."), ExampleLine(text = "What would saving that time mean for you?", meaning = "Hand them the win."), ExampleLine(text = "I'd love to show you a demo.", meaning = "The soft close."))), expressions = listOf(TargetExpression(text = "The problem: your client …", meaning = "Open with their pain.", note = "Their problem, their words."), TargetExpression(text = "The solution: we + verb", meaning = "One line, no jargon.", note = "We automate exactly that."), TargetExpression(text = "Proof: client + number", meaning = "Evidence sells.", note = "Company A saved 20%."), TargetExpression(text = "What would … mean for you?", meaning = "Make it personal.", note = "Time, money, headcount."), TargetExpression(text = "I'd love to show you …", meaning = "The demo ask.", note = "Soft, specific, next step.")), situation = "You pitch to a skeptical operations manager: problem, one-line solution, one proof number — then ask the question that makes it theirs.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Open with the client's problem. (manual invoices)", expected = listOf("Your team spends hours on manual invoices."), focus = "their problem", watch = "Their pain, their words — not your product name."), PracticeQuestion(prompt = "Give the one-line solution. (automation)", expected = listOf("We automate exactly that."), focus = "one line", watch = "One sentence, no feature list."), PracticeQuestion(prompt = "Bring proof. (a client, 20% saved)", expected = listOf("Company A saved 20% in one quarter."), focus = "proof", watch = "Name + number is the strongest proof shape."), PracticeQuestion(prompt = "Make the benefit personal. (question)", expected = listOf("What would your team do with that time?"), focus = "the personal question", watch = "Hand them the win — let them say it."), PracticeQuestion(prompt = "Close softly with a demo.", expected = listOf("I'd love to show you a demo."), focus = "soft close", watch = "Love + demo: soft but specific."))), exercises = listOf(Exercise(id = "en-business-u1-pitch-e1", kind = "choice", prompt = "Your team ___ hours on manual work.", options = listOf("wastes", "waste", "wasting", "to waste"), answers = listOf("wastes"), explain = "Your team = singular: wastes."), Exercise(id = "en-business-u1-pitch-e2", kind = "gap", prompt = "We ___ exactly that. (automate)", options = listOf(), answers = listOf("automate"), explain = "We + base verb."), Exercise(id = "en-business-u1-pitch-e3", kind = "order", prompt = "Bring the proof.", options = listOf(), answers = listOf("Company A saved 20 percent in one quarter"), explain = "Client + number + period."), Exercise(id = "en-business-u1-pitch-e4", kind = "written", prompt = "Ask the personal-benefit question.", options = listOf(), answers = listOf("what would saving that time mean for you", "what would your team do with that time"), explain = "What would … mean for you?")), skills = listOf("function:talk-about-work", "grammar:present-simple", "vocab:work", "function:negotiate"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "en-business-u1-negotiation", title = "Negotiating the deal", goal = "Trade conditions politely: price, timeline, and the deal that closes.", intro = LessonIntro(explanation = listOf("Negotiation is trading, not winning: “If you can do March, we can meet your price.” Every concession has a price tag.", "Conditional offers: “We could accept that if…”, “That would work as long as…”. The if/as long as carries your condition.", "Close with a summary: “So: March delivery, half up front. Do we have a deal?” Repeat it or it didn't happen."), examples = listOf(ExampleLine(text = "If you can do March, we can meet your price.", meaning = "Condition + concession."), ExampleLine(text = "We could accept that as long as costs are covered.", meaning = "as long as = siempre que."), ExampleLine(text = "That's difficult for our timeline.", meaning = "Push back without conflict."), ExampleLine(text = "What if we split the difference?", meaning = "The middle-path move."), ExampleLine(text = "So: March delivery, half up front. Deal?", meaning = "The closing summary."), ExampleLine(text = "Half now, half on delivery — does that work?", meaning = "A structured offer."))), expressions = listOf(TargetExpression(text = "If you …, we …", meaning = "Trade a condition.", note = "If you hurry, we discount."), TargetExpression(text = "as long as …", meaning = "Your red line.", note = "as long as costs are covered."), TargetExpression(text = "That's difficult for …", meaning = "Soft pushback.", note = "…for our timeline."), TargetExpression(text = "What if we …?", meaning = "Middle path.", note = "…split the difference?"), TargetExpression(text = "So we agree on …", meaning = "Close and repeat.", note = "Numbers finish it."), TargetExpression(text = "I'd need something in writing.", meaning = "Protect the agreement.", note = "Even between friends.")), situation = "Final negotiation round: they want March at half price, you need June at full — trade conditions until the summary closes it.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Ask for a faster timeline with a trade. (if / premium)", expected = listOf("If we pay the premium, can you deliver in March?"), focus = "if + trade", watch = "The if carries what you give, not just what you want."), PracticeQuestion(prompt = "State your red line. (costs covered)", expected = listOf("That works as long as our costs are covered."), focus = "as long as", watch = "as long as + present: the red line."), PracticeQuestion(prompt = "Push back softly on the timeline.", expected = listOf("That's difficult for our timeline."), focus = "soft pushback", watch = "Difficult, not impossible — the door stays open."), PracticeQuestion(prompt = "Offer the middle path.", expected = listOf("What if we split the difference?"), focus = "middle path", watch = "What if + present simple proposes it."), PracticeQuestion(prompt = "Ask for the agreement in writing.", expected = listOf("I'd need something in writing."), focus = "in writing", watch = "in writing — the phrase protects both sides."))), exercises = listOf(Exercise(id = "en-business-u1-negotiation-e1", kind = "choice", prompt = "___ you sign today, we can offer a discount.", options = listOf("If", "Unless", "Will", "Are"), answers = listOf("If"), explain = "If + present for the condition."), Exercise(id = "en-business-u1-negotiation-e2", kind = "gap", prompt = "We can travel ___ ___ as costs are covered. (2 words)", options = listOf(), answers = listOf("as long", "so long"), explain = "as long as = siempre que."), Exercise(id = "en-business-u1-negotiation-e3", kind = "order", prompt = "Offer the middle path.", options = listOf(), answers = listOf("What if we split the difference"), explain = "What if + present simple."), Exercise(id = "en-business-u1-negotiation-e4", kind = "written", prompt = "Summarise the deal: March, half up front.", options = listOf(), answers = listOf("so march delivery half up front", "so we agree march delivery half up front"), explain = "So + the numbers.")), skills = listOf("function:negotiate", "grammar:first-conditional", "grammar:connectors", "vocab:work", "speaking:negotiate"), canDo = listOf("solve-everyday-problems"), prerequisites = listOf("grammar:first-conditional")),
    Lesson(id = "en-business-u1-followup", title = "The follow-up", goal = "Confirm agreements in writing: recap, next steps and a clear ask.", intro = LessonIntro(explanation = listOf("The follow-up email exists to prove the meeting happened: “Just to confirm what we agreed…”. Recap in numbered lines.", "Next steps have owners and dates: “Ana will send the contract by Friday.” No owner, no date, no step.", "End with the ask, not a whisper: “Could you confirm by Thursday?” A closing without an ask closes nothing."), examples = listOf(ExampleLine(text = "Just to confirm what we agreed:", meaning = "The recap opener."), ExampleLine(text = "1. Price. 2. Timeline. 3. Contract.", meaning = "Numbered recap."), ExampleLine(text = "Ana will send the contract by Friday.", meaning = "Owner + date."), ExampleLine(text = "Could you confirm by Thursday?", meaning = "The dated ask."), ExampleLine(text = "Looking forward to working together.", meaning = "The warm close."))), expressions = listOf(TargetExpression(text = "Just to confirm, …", meaning = "Open the recap.", note = "…what we agreed in today's call."), TargetExpression(text = "numbered next steps", meaning = "Owner + date each.", note = "1. Contract — Ana — Friday."), TargetExpression(text = "Could you confirm by …?", meaning = "The dated ask.", note = "Thursday creates urgency."), TargetExpression(text = "I'll … by <day>", meaning = "Your own commitments.", note = "I'll send the proposal by Monday."), TargetExpression(text = "Looking forward to …", meaning = "The warm close.", note = "…-ing: working, hearing.")), situation = "After the negotiation call: write the confirmation email — recap the three agreed points, assign one task with a date and ask for confirmation by Thursday.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Open the confirmation email.", expected = listOf("Just to confirm what we agreed in today's call."), focus = "the opener", watch = "It exists to prove the meeting happened."), PracticeQuestion(prompt = "Assign a task with a deadline. (Ana / contract / Friday)", expected = listOf("Ana will send the contract by Friday."), focus = "owner + date", watch = "No owner, no date, no step."), PracticeQuestion(prompt = "Ask for confirmation with a date. (Thursday)", expected = listOf("Could you confirm by Thursday?"), focus = "the dated ask", watch = "A closing without an ask closes nothing."), PracticeQuestion(prompt = "Close warmly for a new client.", expected = listOf("Looking forward to working together."), focus = "warm close", watch = "look forward to + -ing."), PracticeQuestion(prompt = "Commit to your own task with a date. (proposal / Monday)", expected = listOf("I'll send the proposal by Monday."), focus = "I'll + by + date", watch = "Your commitments go in the same email."))), exercises = listOf(Exercise(id = "en-business-u1-followup-e1", kind = "choice", prompt = "Just to ___ what we agreed:", options = listOf("confirm", "check", "say", "remember"), answers = listOf("confirm"), explain = "Just to confirm — the recap opener."), Exercise(id = "en-business-u1-followup-e2", kind = "gap", prompt = "Could you ___ by Thursday? (confirmar)", options = listOf(), answers = listOf("confirm", "reply"), explain = "The dated ask."), Exercise(id = "en-business-u1-followup-e3", kind = "order", prompt = "Assign the task with a deadline.", options = listOf(), answers = listOf("Ana will send the contract by Friday"), explain = "Owner + will + by + date."), Exercise(id = "en-business-u1-followup-e4", kind = "written", prompt = "Close the email warmly.", options = listOf(), answers = listOf("looking forward to working together", "best regards"), explain = "Either warm close works.")), skills = listOf("writing:email", "function:make-requests", "grammar:going-to", "vocab:work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:going-to"))))
}

object EnFoundationsU1 {
    val unit = CourseUnit(id = "en-foundations-u1", title = "First sentences", subtitle = "Say who you are", level = "A1", themes = listOf(ConversationTheme("lang-exchange", "Language-exchange café", "Meet and greet", "person.2", "Course", "You are at a friendly language-exchange café. Meet the learner, exchange names, countries and jobs using the verb to be.", 0),
                ConversationTheme("introductions", "Nice to meet you", "Start somewhere small", "hand.wave", "Connection", "Meet the learner for the first time. Learn their interests through natural introductions.", 0)), lessons = listOf(    Lesson(id = "en-foundations-u1-to-be", title = "The verb “to be”", goal = "Introduce yourself and ask simple questions with am/is/are.", intro = LessonIntro(explanation = listOf("Every English sentence needs a subject and a verb. The most important verb is “to be”. It tells you what someone is, how someone feels, or where something is.", "One verb, three present forms. With I use am: “I am Ana.” With you, we and they use are: “You are my friend.” With he, she and it use is: “She is a doctor.”", "In everyday talk, English shortens it: I'm, you're, he's, she's, it's, we're, they're. When you chat, say “I'm Ana”, not “I am Ana”."), examples = listOf(ExampleLine(text = "I'm Ana. I'm from Spain.", meaning = "Your name and country."), ExampleLine(text = "You are my best friend.", meaning = "A close bond with someone."), ExampleLine(text = "She is a doctor.", meaning = "Someone's profession."), ExampleLine(text = "We are very happy today.", meaning = "A feeling right now."), ExampleLine(text = "The café is near the station.", meaning = "Where a place is."), ExampleLine(text = "They are at work.", meaning = "Someone's location."))), expressions = listOf(TargetExpression(text = "I'm …", meaning = "Introduce yourself.", note = "With your name, age or feeling: I'm Ana. I'm tired."), TargetExpression(text = "I'm from …", meaning = "Say where you come from.", note = "Never “I from …” — the am is obligatory."), TargetExpression(text = "Are you …?", meaning = "Ask about the other person.", note = "Are you a student? Are you tired?"), TargetExpression(text = "Yes, I am. / No, I'm not.", meaning = "Short answers to an Are-you question.", note = "Repeat the verb: never “Yes, I”."), TargetExpression(text = "He's / She's a …", meaning = "Talk about other people's jobs.", note = "He's a teacher — the a matters with professions."), TargetExpression(text = "Nice to meet you.", meaning = "The fixed phrase when you meet someone.", note = "Answer with the same phrase.")), situation = "You meet someone new at a friendly language-exchange café. Introduce yourselves and ask simple questions with the verb to be.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Hello! I'm Ana. What's your name?", expected = listOf("I'm <name>.", "My name is <name>."), focus = "I am / My name is", watch = "Answering only the name without the verb: accept it, then recast with “I'm …”."), PracticeQuestion(prompt = "Where are you from?", expected = listOf("I'm from <country>.", "I am from <country>."), focus = "are + from", watch = "“I from Spain” — recast “I am FROM Spain”, stress am."), PracticeQuestion(prompt = "Are you a student?", expected = listOf("Yes, I am.", "No, I'm not. I'm a <job>."), focus = "short answers with am", watch = "“Yes, I student” — the short answer needs am."), PracticeQuestion(prompt = "How are you today?", expected = listOf("I'm fine.", "I'm good.", "I'm tired."), focus = "I'm + feeling", watch = "“I fine” — recast “I'm fine”."), PracticeQuestion(prompt = "Is your city big or small?", expected = listOf("It's big.", "It's small.", "My city is …"), focus = "is with things and places", watch = "“My city big” — recast “My city IS big”."), PracticeQuestion(prompt = "We're friends now! Where is your family from?", expected = listOf("They're from <country>.", "My family is from <country>."), focus = "they are / a group is", watch = "“My family from …” — recast with is."))), exercises = listOf(Exercise(id = "en-foundations-u1-to-be-e1", kind = "choice", prompt = "She ___ a doctor.", options = listOf("is", "are", "am", "be"), answers = listOf("is"), explain = "With he, she and it, to be becomes is."), Exercise(id = "en-foundations-u1-to-be-e2", kind = "gap", prompt = "They ___ my friends.", options = listOf(), answers = listOf("are"), explain = "With they, to be is always are."), Exercise(id = "en-foundations-u1-to-be-e3", kind = "order", prompt = "Say where you are from.", options = listOf(), answers = listOf("I am from Spain"), explain = "Am goes with I: I am from …"), Exercise(id = "en-foundations-u1-to-be-e4", kind = "written", prompt = "Introduce yourself in one sentence: say your name.", options = listOf(), answers = listOf("I'm <name>", "My name is <name>", "I am <name>"), explain = "I'm Ana / My name is Ana — the verb is never dropped.")), skills = listOf("grammar:verb-be", "grammar:subject-pronouns", "function:introduce-yourself", "vocab:introductions", "speaking:short-answer"), canDo = listOf("introduce-yourself")),
    Lesson(id = "en-foundations-u1-questions", title = "Questions & negatives with “to be”", goal = "Ask yes/no and wh- questions, and say what is not true, with am/is/are.", intro = LessonIntro(explanation = listOf("To ask a yes/no question, put the verb first. “You are tired.” becomes “Are you tired?” “She is a teacher.” becomes “Is she a teacher?”", "To say something is not true, add not. “I am not late.” In talk we shorten: is not → isn't, are not → aren't. And I'm not is already short.", "Real questions add question words: what, where, who, how. They go before the verb: “Where are you from?” Short forms: what's = what is, where's = where is."), examples = listOf(ExampleLine(text = "Are you hungry?", meaning = "A yes/no question with are."), ExampleLine(text = "Is she your sister?", meaning = "Asking about another person."), ExampleLine(text = "I'm not tired.", meaning = "A negative with I."), ExampleLine(text = "He isn't at work today.", meaning = "is not, shortened."), ExampleLine(text = "Where are the keys?", meaning = "Question word + are."), ExampleLine(text = "What's your phone number?", meaning = "what's = what is."))), expressions = listOf(TargetExpression(text = "Are you …?", meaning = "Ask a yes/no question.", note = "Are you OK? Are you new here?"), TargetExpression(text = "I'm not …", meaning = "Say what is not true about you.", note = "I'm not from Madrid — I'm from Seville."), TargetExpression(text = "isn't / aren't", meaning = "Say what is not true about others.", note = "She isn't here. They aren't at home."), TargetExpression(text = "Where is / are …?", meaning = "Ask about a place.", note = "Where's the station? Where are my keys?"), TargetExpression(text = "What's …?", meaning = "Ask what something is.", note = "What's this? What's your number?"), TargetExpression(text = "How old are you?", meaning = "Ask about age.", note = "The answer: I'm twenty-five.")), situation = "You chat with a new neighbour in the lift. Ask simple questions and say what is and isn't true for you.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Hi! Are you new in the building?", expected = listOf("Yes, I am.", "No, I'm not. I'm on the third floor."), focus = "short answers with am", watch = "“Yes, I new” — short answers repeat am."), PracticeQuestion(prompt = "Is your flat big?", expected = listOf("Yes, it is.", "No, it isn't."), focus = "short answers with is", watch = "“No, it not big” — the negative is isn't."), PracticeQuestion(prompt = "I'm Marta, by the way. What's your name?", expected = listOf("I'm <name>.", "My name is <name>."), focus = "what's + name", watch = "“What you name?” — the question needs is: “What's your name?”."), PracticeQuestion(prompt = "Where are you from?", expected = listOf("I'm from <country>.", "I am from <country>."), focus = "where + are", watch = "“Where you from?” — don't drop are."), PracticeQuestion(prompt = "Are your neighbours friendly?", expected = listOf("Yes, they are.", "No, they aren't."), focus = "short answers with are", watch = "“Yes, they friendly” — repeat are."), PracticeQuestion(prompt = "I'm not from this city — I'm from Valencia. And you?", expected = listOf("I'm from <city>.", "I'm not from here either."), focus = "negative with I'm", watch = "“I no from …” — the negative is “I'm not from …”."))), exercises = listOf(Exercise(id = "en-foundations-u1-questions-e1", kind = "choice", prompt = "___ you tired?", options = listOf("Are", "Is", "Am", "Be"), answers = listOf("Are"), explain = "With you, the question starts with Are."), Exercise(id = "en-foundations-u1-questions-e2", kind = "gap", prompt = "___ she your sister?", options = listOf(), answers = listOf("is"), explain = "With she, questions start with Is."), Exercise(id = "en-foundations-u1-questions-e3", kind = "order", prompt = "Ask where the person is from.", options = listOf(), answers = listOf("Where are you from"), explain = "Question word + are + you."), Exercise(id = "en-foundations-u1-questions-e4", kind = "written", prompt = "Make it negative: \"I am late.\"", options = listOf(), answers = listOf("I'm not late", "I am not late"), explain = "I'm not is already short; is not → isn't, are not → aren't.")), skills = listOf("grammar:verb-be", "grammar:present-questions", "function:ask-simple-questions", "speaking:short-answer"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "en-foundations-u1-introduce", title = "Introducing yourself", goal = "Give a complete self-introduction: name, age, country, nationality and job.", intro = LessonIntro(explanation = listOf("A good introduction answers five small questions: your name, your age, your country or city, your nationality, and your job.", "In English, age and nationality use the verb to be. “I'm 30.” “I'm Mexican.” Say “I'm 30”, never “I have 30”.", "With jobs we say a/an: “I'm a nurse.” “He's an engineer.” Nationality words are adjectives: from Spain → I'm Spanish; from Mexico → I'm Mexican."), examples = listOf(ExampleLine(text = "I'm Elena. I'm twenty-eight.", meaning = "Name and age."), ExampleLine(text = "I'm from Peru.", meaning = "Country with from."), ExampleLine(text = "I'm Peruvian.", meaning = "Nationality with be."), ExampleLine(text = "I'm a nurse.", meaning = "Job with a."), ExampleLine(text = "He's an engineer.", meaning = "an before a vowel sound."), ExampleLine(text = "We're students.", meaning = "Plural with are."))), expressions = listOf(TargetExpression(text = "I'm <name>.", meaning = "Your name.", note = "The simplest way to start."), TargetExpression(text = "I'm … years old.", meaning = "Your age.", note = "I'm 25 = I'm twenty-five years old."), TargetExpression(text = "I'm from …", meaning = "Your country or city.", note = "I'm from Colombia."), TargetExpression(text = "I'm <nationality>.", meaning = "Adjective with be: Spanish, Turkish, Brazilian.", note = "From Japan → I'm Japanese."), TargetExpression(text = "I'm a/an <job>.", meaning = "Your job. Use an before a vowel sound.", note = "an artist, a teacher"), TargetExpression(text = "Nice to meet you too.", meaning = "The polite answer to “Nice to meet you”.", note = "Same smile, one extra word: too.")), situation = "First day in class: the teacher asks everyone to stand up and introduce themselves to two classmates.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Good morning! Please introduce yourself.", expected = listOf("I'm <name>.", "My name is <name>."), focus = "opening a self-introduction", watch = "One line is fine — the tutor will ask for more."), PracticeQuestion(prompt = "Lovely to meet you. How old are you?", expected = listOf("I'm <number>.", "I'm <number> years old."), focus = "age with be", watch = "“I have 25” — age uses be: “I'm 25”."), PracticeQuestion(prompt = "Where are you from?", expected = listOf("I'm from <country>.", "I'm from <city>, in <country>."), focus = "origin", watch = "“I'm Spanish from Spain” — keep it simple: “I'm from …”."), PracticeQuestion(prompt = "So you're from Italy — you're Italian, right?", expected = listOf("Yes, I'm Italian.", "That's right."), focus = "nationality adjectives", watch = "“I'm Italy” — the country is Italy, the person is Italian."), PracticeQuestion(prompt = "What's your job?", expected = listOf("I'm a <job>.", "I'm an <job>."), focus = "a/an with jobs", watch = "“I'm teacher” — jobs need a/an: “I'm a teacher”."), PracticeQuestion(prompt = "Great! Now introduce your friend: this is Carlos.", expected = listOf("He's a <job>. He's from <country>.", "This is Carlos. He's …"), focus = "talking about a third person with is", watch = "“Carlos is teacher” — add a: “a teacher”."))), exercises = listOf(Exercise(id = "en-foundations-u1-introduce-e1", kind = "choice", prompt = "I ___ from Spain.", options = listOf("am", "is", "are", "be"), answers = listOf("am"), explain = "With I, always am — even in short answers."), Exercise(id = "en-foundations-u1-introduce-e2", kind = "gap", prompt = "Nice to ___ you.", options = listOf(), answers = listOf("meet"), explain = "The fixed greeting is Nice to meet you."), Exercise(id = "en-foundations-u1-introduce-e3", kind = "order", prompt = "Say your country.", options = listOf(), answers = listOf("I'm from Spain"), explain = "Never “I from …” — the am is obligatory."), Exercise(id = "en-foundations-u1-introduce-e4", kind = "written", prompt = "Say your name and your job.", options = listOf(), answers = listOf("I'm <name> and I'm a <job>", "I'm <name>. I'm a <job>", "My name is <name> and I'm a <job>"), explain = "Use a before jobs: a teacher, a doctor.")), skills = listOf("grammar:verb-be", "function:introduce-yourself", "vocab:introductions", "vocab:work", "speaking:short-answer", "pron:word-stress"), canDo = listOf("introduce-yourself", "describe-people"))))
}

object EnFoundationsU2 {
    val unit = CourseUnit(id = "en-foundations-u2", title = "People & things", subtitle = "Name your world", level = "A1", themes = listOf(ConversationTheme("photo-album", "Family photo album", "Who's who", "photo.on.rectangle.angled", "Course", "You show the learner a family photo album. Name the people, ask about each other's families and say who has what.", 0),
                ConversationTheme("lost-jumper", "The lost jumper", "Whose is it?", "tshirt", "Course", "A jumper appeared in the classroom. Help find its owner: ask what things are, whose they are and what they look like.", 1)), lessons = listOf(    Lesson(id = "en-foundations-u2-articles", title = "a/an, the & plurals", goal = "Talk about one thing, a specific thing and many things.", intro = LessonIntro(explanation = listOf("Use a or an for one of many — any one. Use an before a vowel sound: a book, an apple, an hour.", "Use the when the listener knows exactly which one. First we introduce with a/an (“I have a cat”), then we talk about it with the (“The cat is old”).", "For more than one, most words take -s: book → books. After -s, -sh, -ch, -x we add -es: bus → buses, watch → watches. A few are special: person → people, child → children."), examples = listOf(ExampleLine(text = "I have a question.", meaning = "One of many."), ExampleLine(text = "She's an artist.", meaning = "an before a vowel sound."), ExampleLine(text = "Open the window, please.", meaning = "Both people know which one."), ExampleLine(text = "I have two brothers.", meaning = "Plural with -s."), ExampleLine(text = "The buses are slow.", meaning = "Plural + the."), ExampleLine(text = "The children are at school.", meaning = "Irregular plural: child → children."))), expressions = listOf(TargetExpression(text = "a/an + thing", meaning = "One of many; an before a vowel sound.", note = "a key, an umbrella"), TargetExpression(text = "the + thing", meaning = "The one we both know.", note = "Close the door, please."), TargetExpression(text = "two/three + plural", meaning = "Most words take -s.", note = "three books, ten days"), TargetExpression(text = "-es after s/sh/ch/x", meaning = "bus → buses, watch → watches.", note = "Listen for the extra syllable."), TargetExpression(text = "people / children", meaning = "Special plurals: person → people, child → children.", note = "Never “two persons” in everyday 