    Lesson(id = "en-foundations-u2-this-that", title = "This / that & my / your", goal = "Point at things near and far, and say who they belong to.", intro = LessonIntro(explanation = listOf("Use this for something near you, that for something far from you both. Plurals: these (near) and those (far).", "Possessive words go before the thing: my, your, his, her. “This is my bag.” “That's your coat.” “Her name is Ana.”", "To ask about the owner: “Is this your …?” or “Whose is this?” The answer repeats the owner: “It's mine.” / “No, it's his.”"), examples = listOf(ExampleLine(text = "This is my desk.", meaning = "Near me."), ExampleLine(text = "That's our teacher.", meaning = "Far from us."), ExampleLine(text = "Is this your phone?", meaning = "Asking the owner."), ExampleLine(text = "These are my keys.", meaning = "Plural, near."), ExampleLine(text = "Those are her children.", meaning = "Plural, far."), ExampleLine(text = "Whose umbrella is this?", meaning = "Asking whose it is."))), expressions = listOf(TargetExpression(text = "This is …", meaning = "Near me.", note = "This is my friend Ana."), TargetExpression(text = "That's …", meaning = "Far from us.", note = "That's the bus!"), TargetExpression(text = "Is this your …?", meaning = "Ask if it belongs to the listener.", note = "Is this your seat?"), TargetExpression(text = "my / your / his / her", meaning = "Belonging, before the noun.", note = "his car, her house"), TargetExpression(text = "these / those", meaning = "Plurals: these near, those far.", note = "These shoes, those mountains."), TargetExpression(text = "Whose is this?", meaning = "Ask about the owner.", note = "Answer: “It's mine”.")), situation = "You and the learner arrive early to class and find bags, phones and coats on the tables: identify what's near, what's far, and who owns what.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Good morning! Is this your bag on the chair?", expected = listOf("Yes, it's my bag.", "Yes, it'