object EnFoundationsU3 {
    val unit = CourseUnit(id = "en-foundations-u3", title = "Everyday actions", subtitle = "Your week, out loud", level = "A1", themes = listOf(ConversationTheme("morning-rush", "The morning rush", "Against the clock", "sunrise", "Course", "It's 7:40 and you both have somewhere to be. Describe your morning routine while the clock runs.", 0),
                ConversationTheme("evening-wind-down", "After work", "The quiet hours", "moon.stars", "Course", "It's the end of the day. Tell each other what you do in the evening and how you unwind.", 1)), lessons = listOf(    Lesson(id = "en-foundations-u3-present", title = "Present simple: I / you / we / they", goal = "Talk about routines and facts with I/you/we/they, and ask with do.", intro = LessonIntro(explanation = listOf("The present simple is for habits and facts: “I work in a bank.” “We live near the park.” With I, you, we and they the verb has no ending.", "Questions and negatives use do: “Do you like coffee?” “I don't eat meat.” The main verb goes back to its simple form.", "Short answers repeat do: “Do you speak English?” — “Yes, I do.” / “No, I don't.”"), examples = listOf(ExampleLine(text = "I work from home.", meaning = "Habit, no ending."), ExampleLine(text = "Do you live alone?", meaning = "Question with do."), ExampleLine(text = "We don't watch TV.", meaning = "Negative with don't."), ExampleLine(text = "They play football on Saturdays.", meaning = "Routine + plural."), ExampleLine(text = "Yes, I do.", meaning = "Short answer."), ExampleLine(text = "You know the answer.", meaning = "Fact with you."))), expressions = listOf(TargetExpression(text = "I work / live / study …", meaning = "Habits with no ending.", note = "I live with two friends."), TargetExpression(text = "Do you …?", meaning = "Ask about routines.", note = "Do you work nearby?"), TargetExpression(text = "I don't …", meaning = "Negative habits.", note = "I don't drink coffee."), TargetExpression(text = "Yes, I do. / No, I don't.", meaning = "Short answers with do.", note = "Repeat do, not the verb."), TargetExpression(text = "on Mondays / at weekends", meaning = "When habits happen.", note = "I play tennis on Sundays."), TargetExpression(text = "What do you do?", meaning = "Ask about someone's job.", note = "Answer: “I'm a …”.")), situation = "Two neighbours chat in the square about their week: jobs, habits and what they never do.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "So, what do you do?", expected = listOf("I'm a <job>.", "I work as a <job>.", "I'm a student."), focus = "asking about jobs", watch = "“What you do?” — questions need do."), PracticeQuestion(prompt = "Do you like your job?", expected = listOf("Yes, I do.", "No, I don't.", "It's OK."), focus = "like + do short answers", watch = "“Yes, I like” — short answer is “Yes, I do”."), PracticeQuestion(prompt = "Where do you work?", expected = listOf("I work <place>.", "I work from home.", "I don't work — I study."), focus = "where + do", watch = "“I work in home” — “from home”."), PracticeQuestion(prompt = "Do you speak any other languages?", expected = listOf("Yes, I do. I speak <language>.", "No, I don't."), focus = "do + language verbs", watch = "“I no speak” — “I don't speak”."), PracticeQuestion(prompt = "What do you and your friends do at weekends?", expected = listOf("We play …", "We go …", "We don't go out much."), focus = "we habits", watch = "“We plays” — with we there's no -s."), PracticeQuestion(prompt = "I don't watch much TV. Do you?", expected = listOf("No, I don't.", "Yes, I do. I watch …"), focus = "echo questions with do", watch = "Short answers use do, not the verb."))), exercises = listOf(Exercise(id = "en-foundations-u3-present-e1", kind = "choice", prompt = "They ___ in Madrid.", options = listOf("live", "lives", "living", "does live"), answers = listOf("live"), explain = "With they there is no -s: they live."), Exercise(id = "en-foundations-u3-present-e2", kind = "gap", prompt = "___ you work near here?", options = listOf(), answers = listOf("do"), explain = "Questions with you need Do."), Exercise(id = "en-foundations-u3-present-e3", kind = "order", prompt = "Say you do not eat meat.", options = listOf(), answers = listOf("We don't eat meat"), explain = "don't + base verb: We don't eat."), Exercise(id = "en-foundations-u3-present-e4", kind = "written", prompt = "Say one thing you do every day.", options = listOf(), answers = listOf("I <verb> every day", "Every day I <verb>"), explain = "Present simple for routines: I work, I walk, I cook.")), skills = listOf("grammar:present-simple", "grammar:present-questions", "vocab:daily-routine", "function:talk-about-routines"), canDo = listOf("talk-about-routines"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "en-foundations-u3-third-person", title = "He / she / it + -s & frequency", goal = "Describe another person's routines with the -s ending and say how often things happen.", intro = LessonIntro(explanation = listOf("With he, she and it the present simple verb takes -s: “She works at night.” “He likes jazz.” This -s is small but very important.", "Questions and negatives use does: “Does she live here?” “He doesn't drive.” After does the verb loses its -s: not “Does she works?”", "Frequency words say how often: always, usually, often, sometimes, never. They go before the verb: “I always walk to work.” But after be: “He is never late.”"), examples = listOf(ExampleLine(text = "She works in a hospital.", meaning = "Third person -s."), ExampleLine(text = "He watches TV after dinner.", meaning = "-es after ch."), ExampleLine(text = "Does she speak French?", meaning = "Question with does."), ExampleLine(text = "It doesn't open on Sundays.", meaning = "Negative with doesn't."), ExampleLine(text = "I never drink energy drinks.", meaning = "never + verb."), ExampleLine(text = "He's always on time.", meaning = "Frequency after be."))), expressions = listOf(TargetExpression(text = "She + verb-s", meaning = "Third person needs -s.", note = "She plays the guitar."), TargetExpression(text = "Does he …?", meaning = "Ask about another person.", note = "Does he live alone?"), TargetExpression(text = "doesn't + verb", meaning = "He/she/it negative, no -s.", note = "It doesn't matter."), TargetExpression(text = "always / usually / sometimes / never", meaning = "How often, before the verb.", note = "I usually cook at home."), TargetExpression(text = "-es after ch/sh/s", meaning = "watches, washes, misses.", note = "She watches the news."), TargetExpression(text = "How often …?", meaning = "Ask about frequency.", note = "How often do you swim?")), situation = "You catch up about a mutual friend: describe her routines, how often she does things and what she never does.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Tell me about your best friend — where does she live?", expected = listOf("She lives <place>.", "He lives <place>."), focus = "does + lives", watch = "“Where does she lives?” — after does, no -s."), PracticeQuestion(prompt = "What does he do at weekends?", expected = listOf("He plays …", "He goes …", "He watches …"), focus = "third person -s", watch = "“He play” — he needs -s: “He plays”."), PracticeQuestion(prompt = "Does she like football?", expected = listOf("Yes, she does.", "No, she doesn't."), focus = "does short answers", watch = "“Yes, she likes” — short answer: “Yes, she does”."), PracticeQuestion(prompt = "How often do you cook?", expected = listOf("Every day.", "Twice a week.", "I never cook."), focus = "frequency answers", watch = "“I cook two times week” — “twice a week”."), PracticeQuestion(prompt = "Is your brother always late?", expected = listOf("Yes, he's always late.", "No, he's never late."), focus = "always/never after be", watch = "“He always is late” — after be: “He's always late”."), PracticeQuestion(prompt = "My sister never drinks coffee — she hates it. And your family?", expected = listOf("My <relative> never …", "They always …"), focus = "frequency with family", watch = "“My mum never drink” — keep the -s after never."))), exercises = listOf(Exercise(id = "en-foundations-u3-third-person-e1", kind = "choice", prompt = "He ___ football on Sundays.", options = listOf("plays", "play", "playing", "is play"), answers = listOf("plays"), explain = "With he/she/it the verb takes -s."), Exercise(id = "en-foundations-u3-third-person-e2", kind = "gap", prompt = "She ___ English at night. (study)", options = listOf(), answers = listOf("studies"), explain = "Consonant + y → -ies: study → studies."), Exercise(id = "en-foundations-u3-third-person-e3", kind = "order", prompt = "Say where your sister works.", options = listOf(), answers = listOf("My sister works in a cafe"), explain = "Sister is she → works with -s."), Exercise(id = "en-foundations-u3-third-person-e4", kind = "written", prompt = "Presénte a Ana: ¿qué habla? (inglés)", options = listOf(), answers = listOf("Ana speaks English", "She speaks English"), explain = "Ana = she → speak + s.")), skills = listOf("grammar:third-person-s", "grammar:frequency-adverbs", "function:talk-about-routines", "pron:third-person-s"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "en-foundations-u3-time", title = "Time & daily routine", goal = "Tell the time and describe your day in order.", intro = LessonIntro(explanation = listOf("Ask with “What time is it?” Answer with o'clock for exact hours: “It's seven o'clock.” For halves say half past: “It's half past seven” (7:30).", "Use at for clock times (“at eight”), in the morning/afternoon/evening, and at night.", "Order your day with first, then, after that and finally. They make a story out of your routine."), examples = listOf(ExampleLine(text = "What time is it?", meaning = "Asking the time."), ExampleLine(text = "It's half past six.", meaning = "6:30."), ExampleLine(text = "I get up at six thirty.", meaning = "at + clock time."), ExampleLine(text = "I run in the morning.", meaning = "Part of the day."), ExampleLine(text = "First I shower, then I dress.", meaning = "Order words."), ExampleLine(text = "Finally, I go to bed at eleven.", meaning = "The last step."))), expressions = listOf(TargetExpression(text = "What time is it?", meaning = "The time question.", note = "Answer: “It's …”."), TargetExpression(text = "It's … o'clock / half past …", meaning = "Exact hours and halves.", note = "It's four o'clock."), TargetExpression(text = "at + time", meaning = "Clock times take at.", note = "The film starts at nine."), TargetExpression(text = "in the morning / at night", meaning = "Parts of the day.", note = "in the evening, at night"), TargetExpression(text = "I get up at …", meaning = "Start your day.", note = "Opposite: I go to bed at …"), TargetExpression(text = "first / then / after that / finally", meaning = "Put actions in order.", note = "First coffee, then email.")), situation = "The learner's first day at a new job: plan the morning together, minute by minute, from waking up to the first meeting.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Quick — what time is it?", expected = listOf("It's <time>.", "It's half past <hour>.", "It's <hour> o'clock."), focus = "telling the time", watch = "“Is seven o'clock” — statements need it's."), PracticeQuestion(prompt = "What time do you get up?", expected = listOf("I get up at <time>."), focus = "at + time", watch = "“I get up in seven” — clock times take at."), PracticeQuestion(prompt = "Do you have breakfast before or after your shower?", expected = listOf("Before. First I …, then I …", "After — first I …"), focus = "first/then", watch = "Answer in order: first …, then …"), PracticeQuestion(prompt = "What do you do in the evening?", expected = listOf("In the evening I …", "I usually …"), focus = "in the evening", watch = "“in the night” — evening or “at night”."), PracticeQuestion(prompt = "When do you go to bed?", expected = listOf("I go to bed at <time>.", "Around <time>."), focus = "go to bed", watch = "“I go to the bed” — no the: “go to bed”."), PracticeQuestion(prompt = "Describe your morning in order — first, then, after that.", expected = listOf("First I …, then I …, after that I …"), focus = "sequencing", watch = "Use the order words — don't list with “and, and, and”."))), exercises = listOf(Exercise(id = "en-foundations-u3-time-e1", kind = "choice", prompt = "It's 7:30. It's half ___ seven.", options = listOf("past", "to", "at", "on"), answers = listOf("past"), explain = "Half past = y media."), Exercise(id = "en-foundations-u3-time-e2", kind = "gap", prompt = "I get up ___ seven o'clock.", options = listOf(), answers = listOf("at"), explain = "Clock times take at: at seven."), Exercise(id = "en-foundations-u3-time-e3", kind = "order", prompt = "Say what comes after getting up.", options = listOf(), answers = listOf("Then I have breakfast"), explain = "Then orders your routine."), Exercise(id = "en-foundations-u3-time-e4", kind = "written", prompt = "Say what time you usually get up.", options = listOf(), answers = listOf("I get up at <time>", "I usually get up at <time>"), explain = "get up at + time.")), skills = listOf("grammar:time-expressions", "vocab:daily-routine", "function:tell-time", "listening:number-time"), canDo = listOf("tell-time"), prerequisites = listOf("grammar:present-simple"))))
}

object EnFoundationsU4 {
    val unit = CourseUnit(id = "en-foundations-u4", title = "Getting around", subtitle = "Out in the city", level = "A1", themes = listOf(ConversationTheme("neighbourhood", "A new neighbourhood", "Find your way", "map", "Course", "The learner just moved to the area. Walk the streets together and describe what there is on every corner.", 0),
                ConversationTheme("lost-in-town", "Lost in town", "Ask for help", "location", "Course", "Your phone died and you are lost. Stop people, ask for directions and follow them.", 1)), lessons = listOf(    Lesson(id = "en-foundations-u4-can", title = "Can / can't", goal = "Say what you are able to do, ask others for help and give permission.", intro = LessonIntro(explanation = listOf("can never changes: “I can swim.” “She can swim.” No -s, no to. The negative is can't (or cannot in writing).", "Questions flip it: “Can you swim?” For polite requests: “Can you help me?” For permission: “Can I sit here?”", "Short answers repeat can: “Yes, I can.” / “No, I can't.”"), examples = listOf(ExampleLine(text = "I can ride a bike.", meaning = "Ability."), ExampleLine(text = "She can speak three languages.", meaning = "No -s after she."), ExampleLine(text = "Sorry, I can't come.", meaning = "Negative."), ExampleLine(text = "Can you repeat that, please?", meaning = "Polite request."), ExampleLine(text = "Can I pay by card?", meaning = "Permission."), ExampleLine(text = "Yes, you can.", meaning = "Short answer."))), expressions = listOf(TargetExpression(text = "I can / can't …", meaning = "Ability, no changes.", note = "I can drive, but I can't park!"), TargetExpression(text = "Can you …, please?", meaning = "Polite request.", note = "Can you help me, please?"), TargetExpression(text = "Can I …?", meaning = "Ask permission.", note = "Can I open the window?"), TargetExpression(text = "Yes, of course.", meaning = "Warm yes to a request.", note = "Better than a plain yes."), TargetExpression(text = "Sorry, I can't.", meaning = "Soft no.", note = "Add a reason: I'm busy."), TargetExpression(text = "Can you say that again?", meaning = "Ask for a repeat.", note = "Add: “Slower, please”.")), situation = "You organise a small trip with the learner: who can drive, who can cook, and what you can't do without asking.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Can you drive?", expected = listOf("Yes, I can.", "No, I can't."), focus = "can short answers", watch = "“Yes, I drive” — repeat can: “Yes, I can”."), PracticeQuestion(prompt = "What can you cook?", expected = listOf("I can make <dish>.", "I can't cook at all!"), focus = "can + verb", watch = "“I can to cook” — no to after can."), PracticeQuestion(prompt = "Can your sister swim?", expected = listOf("Yes, she can.", "No, she can't."), focus = "can with he/she", watch = "“She cans swim” — can never takes -s."), PracticeQuestion(prompt = "Can I borrow your pen, please?", expected = listOf("Yes, of course.", "Sure, here you are."), focus = "permission + polite reply", watch = "Answer a request warmly: “Of course”."), PracticeQuestion(prompt = "Sorry, can you speak more slowly?", expected = listOf("No problem.", "Of course. Is this better?"), focus = "polite repeat request", watch = "Practise your “Sorry, can you …?” — it opens every repair."), PracticeQuestion(prompt = "What's one thing you can't do but want to learn?", expected = listOf("I can't <skill>, but I want to learn."), focus = "can't + wish", watch = "“I can't to play” — no to after can't."))), exercises = listOf(Exercise(id = "en-foundations-u4-can-e1", kind = "choice", prompt = "___ you help me, please?", options = listOf("Can", "Are", "Do", "Is"), answers = listOf("Can"), explain = "Requests start with Can you …?"), Exercise(id = "en-foundations-u4-can-e2", kind = "gap", prompt = "I ___ swim, but I can't dive.", options = listOf(), answers = listOf("can"), explain = "can never takes -s and stays with the verb."), Exercise(id = "en-foundations-u4-can-e3", kind = "order", prompt = "Say your mother cannot drive.", options = listOf(), answers = listOf("She can't drive"), explain = "can't + base verb: She can't drive."), Exercise(id = "en-foundations-u4-can-e4", kind = "written", prompt = "Ask permission to open the window.", options = listOf(), answers = listOf("Can I open the window", "Can I open the window, please"), explain = "Can I …? asks for permission.")), skills = listOf("grammar:can", "function:make-requests", "vocab:social-expressions"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "en-foundations-u4-there-is", title = "There is / there are", goal = "Say what exists in a place, and ask about it.", intro = LessonIntro(explanation = listOf("To say something exists, start with there: “There's a pharmacy on the corner.” Singular: there is (there's). Plural: “There are two parks.”", "Negatives: “There isn't a lift.” “There aren't any shops.” Questions: “Is there a bank near here?” “Are there any tickets left?”", "Say where with prepositions: next to, opposite, behind. “The café is next to the bank.”"), examples = listOf(ExampleLine(text = "There's a market on Saturdays.", meaning = "Singular exists."), ExampleLine(text = "There are two lifts.", meaning = "Plural exists."), ExampleLine(text = "There isn't a car park.", meaning = "Singular negative."), ExampleLine(text = "There aren't any bikes left.", meaning = "Plural negative + any."), ExampleLine(text = "Is there wifi here?", meaning = "Existence question."), ExampleLine(text = "The bank is opposite the school.", meaning = "Where exactly."))), expressions = listOf(TargetExpression(text = "There's a/n …", meaning = "One thing exists.", note = "There's a bakery downstairs."), TargetExpression(text = "There are (+ number) …", meaning = "Plural things exist.", note = "There are four rooms."), TargetExpression(text = "Is there … near here?", meaning = "Ask for a place.", note = "Is there a toilet here?"), TargetExpression(text = "There isn't / aren't any …", meaning = "What's missing.", note = "There aren't any chairs."), TargetExpression(text = "next to / opposite / behind", meaning = "Pin things to places.", note = "The bar is opposite us."), TargetExpression(text = "How many … are there?", meaning = "Ask for a number of things.", note = "How many stops are there?")), situation = "You show a visitor around the office building: what's on each floor, what's missing, and where exactly things are.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Is there a supermarket near your flat?", expected = listOf("Yes, there's one <where>.", "No, there isn't."), focus = "is there questions", watch = "“Is a supermarket?” — start with there."), PracticeQuestion(prompt = "How many rooms are there in your home?", expected = listOf("There are <number> rooms.", "There are three: …"), focus = "how many are there", watch = "“How many rooms has?” — with there: “are there”."), PracticeQuestion(prompt = "Is there a lift in the building?", expected = listOf("Yes, there is.", "No, there isn't. It's an old building."), focus = "short answers with there", watch = "“Yes, has lift” — repeat there is."), PracticeQuestion(prompt = "What's in your neighbourhood?", expected = listOf("There's a <place> and there are <things>."), focus = "mixing is/are", watch = "One thing → there's; more → there are."), PracticeQuestion(prompt = "Are there any good cafés around?", expected = listOf("Yes, there are two.", "No, there aren't any."), focus = "any in questions/negatives", watch = "“There aren't some cafés” — negatives take any."), PracticeQuestion(prompt = "Where exactly is the pharmacy?", expected = listOf("It's next to the bank.", "It's opposite the park."), focus = "location prepositions", watch = "“It's in front the bank” — “opposite” or “in front of”."))), exercises = listOf(Exercise(id = "en-foundations-u4-there-is-e1", kind = "choice", prompt = "___ a pharmacy near here?", options = listOf("Is there", "Are there", "There is", "Has"), answers = listOf("Is there"), explain = "Singular questions: Is there …?"), Exercise(id = "en-foundations-u4-there-is-e2", kind = "gap", prompt = "There ___ two parks in my neighbourhood.", options = listOf(), answers = listOf("are"), explain = "Plural things: there are."), Exercise(id = "en-foundations-u4-there-is-e3", kind = "order", prompt = "Say that a market exists on Saturdays.", options = listOf(), answers = listOf("There is a market on Saturdays"), explain = "There is + singular thing."), Exercise(id = "en-foundations-u4-there-is-e4", kind = "written", prompt = "Say what there is in your kitchen.", options = listOf(), answers = listOf("There is <thing>", "There are <things>", "There is a <thing>"), explain = "There is + one thing, there are + many.")), skills = listOf("grammar:there-is-are", "grammar:prepositions-place", "vocab:town"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:articles", "grammar:plurals")),
    Lesson(id = "en-foundations-u4-directions", title = "Directions & place", goal = "Give and follow simple directions from A to B.", intro = LessonIntro(explanation = listOf("Start with go straight on, then turn left or turn right. “Go straight on and turn left at the lights.”", "Say where the place is: on the left, on the right, on the corner, at the end of the street.", "Ask for directions with “How do I get to …?” or “Is it far?” Answers: “Five minutes on foot.”"), examples = listOf(ExampleLine(text = "How do I get to the station?", meaning = "The directions question."), ExampleLine(text = "Go straight on for two streets.", meaning = "Distance first."), ExampleLine(text = "Turn right at the bank.", meaning = "Turn + where."), ExampleLine(text = "It's on the corner.", meaning = "Corner position."), ExampleLine(text = "Is it far from here?", meaning = "Ask about distance."), ExampleLine(text = "About five minutes on foot.", meaning = "Time as distance."))), expressions = listOf(TargetExpression(text = "How do I get to …?", meaning = "Ask for directions.", note = "…to the museum?"), TargetExpression(text = "Go straight on.", meaning = "Keep walking.", note = "For two blocks."), TargetExpression(text = "Turn left / right at …", meaning = "Where to change direction.", note = "at the traffic lights"), TargetExpression(text = "on the left / on the right", meaning = "Which side it's on.", note = "The pharmacy is on your left."), TargetExpression(text = "Is it far?", meaning = "Ask about distance.", note = "Answer: “Ten minutes on foot”."), TargetExpression(text = "Excuse me, …", meaning = "Open every street question.", note = "Excuse me, where's the metro?")), situation = "The learner's phone has died at a crossroads: ask passers-by for the museum, understand the directions and repeat them back.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "You look lost — can I help?", expected = listOf("Yes, please. How do I get to <place>?", "Excuse me, where is <place>?"), focus = "opening a directions ask", watch = "Start with “Excuse me” — it buys goodwill."), PracticeQuestion(prompt = "OK: go straight on and turn left at the lights. Got it?", expected = listOf("Straight on, then left at the lights.", "Got it, thanks!"), focus = "repeating directions", watch = "Repeat the route back to check it."), PracticeQuestion(prompt = "Is the museum far from here?", expected = listOf("About <number> minutes on foot.", "No, it's very close."), focus = "distance answers", watch = "“It has five minutes” — “it's five minutes”."), PracticeQuestion(prompt = "When you leave, the pharmacy is on your right.", expected = listOf("On the right. Got it.", "Thank you very much."), focus = "on the left/right", watch = "“in the right” — sides take on."), PracticeQuestion(prompt = "Where's the nearest metro station?", expected = listOf("Go straight on and it's on the corner.", "Turn right at the bank."), focus = "giving directions", watch = "Give order words: straight, then turn."), PracticeQuestion(prompt = "Perfect. One last thing — is there a toilet in the museum?", expected = listOf("Yes, there is, on the left.", "I don't know."), focus = "combining there is + location", watch = "Tie it together: there is + place word."))), exercises = listOf(Exercise(id = "en-foundations-u4-directions-e1", kind = "choice", prompt = "Go ___ and then turn left.", options = listOf("straight on", "left", "right", "back"), answers = listOf("straight on"), explain = "Straight on = todo recto."), Exercise(id = "en-foundations-u4-directions-e2", kind = "gap", prompt = "Turn left ___ the traffic lights.", options = listOf(), answers = listOf("at"), explain = "Exact points take at: at the lights."), Exercise(id = "en-foundations-u4-directions-e3", kind = "order", prompt = "Say where the bank is (beside).", options = listOf(), answers = listOf("It's next to the bank"), explain = "next to = al lado de."), Exercise(id = "en-foundations-u4-directions-e4", kind = "written", prompt = "Ask where the station is.", options = listOf(), answers = listOf("Where is the station", "Where's the station"), explain = "Question word + is: Where is / Where's.")), skills = listOf("grammar:imperatives", "grammar:prepositions-place", "vocab:directions", "function:ask-for-directions"), canDo = listOf("ask-for-directions"), prerequisites = listOf("grammar:there-is-are"))))
}

object EnFoundationsNow {
    val unit = CourseUnit(id = "en-foundations-now", title = "Right now", subtitle = "What is happening", level = "A1", themes = listOf(ConversationTheme("rainy-window", "The rainy window", "Weather small talk", "cloud.rain", "Course", "You both watch the rain from a café window. Describe the weather and what people are doing outside.", 0),
                ConversationTheme("busy-kitchen", "The busy kitchen", "What is happening now", "fork.knife", "Course", "You are cooking together. Say what everyone is doing right now — and who is doing nothing!", 1)), lessons = listOf(    Lesson(id = "en-foundations-now-continuous", title = "What is happening now", goal = "Describe actions happening at this moment with am/is/are + -ing.", intro = LessonIntro(explanation = listOf("For actions happening right now, use am/is/are + verb-ing: “I am reading. She is cooking. They are playing.”", "The -ing never changes: I am eating, you are eating, he is eating. Only am/is/are changes.", "Spelling: make → making (drop the e), sit → sitting (double the consonant after one short vowel)."), examples = listOf(ExampleLine(text = "I am drinking coffee.", meaning = "An action happening now."), ExampleLine(text = "She is cooking dinner.", meaning = "Another person, is + -ing."), ExampleLine(text = "They are watching TV.", meaning = "Plural: are + -ing."), ExampleLine(text = "It's raining.", meaning = "Weather with it is + -ing."), ExampleLine(text = "He's making a cake.", meaning = "make → making: the e drops."), ExampleLine(text = "The dog is sleeping.", meaning = "Animals do things too."))), expressions = listOf(TargetExpression(text = "I'm …-ing", meaning = "What you are doing now.", note = "I'm reading a book."), TargetExpression(text = "He's / She's …-ing", meaning = "What another person is doing.", note = "She's working today."), TargetExpression(text = "They're …-ing", meaning = "What a group is doing.", note = "They're waiting for the bus."), TargetExpression(text = "It's raining / snowing", meaning = "Weather in progress.", note = "It is always it for weather."), TargetExpression(text = "… right now / at the moment", meaning = "Anchor the action to now.", note = "I'm cooking right now."), TargetExpression(text = "Look! / Listen!", meaning = "Point at an action in progress.", note = "Look! It's snowing!")), situation = "You look out of a busy café window with a friend: say what every person outside is doing at this moment.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Look at Tom — what is he doing? (football)", expected = listOf("He's playing football.", "He is playing football."), focus = "is + -ing", watch = "“He playing” — the is never drops: “He's playing”."), PracticeQuestion(prompt = "What are you doing right now?", expected = listOf("I'm <verb-ing>.", "I am <verb-ing>."), focus = "I'm + -ing", watch = "“I read” is a habit; right now it's “I'm reading”."), PracticeQuestion(prompt = "What's the weather like at this moment? (rain)", expected = listOf("It's raining.", "It is raining."), focus = "it + is + -ing", watch = "“Is raining” alone has no subject — weather needs it."), PracticeQuestion(prompt = "And your friends? (wait for us)", expected = listOf("They're waiting for us.", "They are waiting for us."), focus = "they're + -ing", watch = "“They waiting” — plural needs are."), PracticeQuestion(prompt = "Is Maria working today?", expected = listOf("Yes, she's working today.", "Yes, she is.", "Yes, she's."), focus = "short answer + -ing", watch = "“Yes, she working” — repeat is in the short answer."), PracticeQuestion(prompt = "Say two things you are not doing right now.", expected = listOf("I'm not <verb-ing>.", "I am not <verb-ing>."), focus = "negative -ing", watch = "“I not reading” — the negative is “I'm not reading”."))), exercises = listOf(Exercise(id = "en-foundations-now-continuous-e1", kind = "choice", prompt = "She ___ a letter right now.", options = listOf("is writing", "writes", "write", "writing"), answers = listOf("is writing"), explain = "Right now needs am/is/are + -ing: she is writing."), Exercise(id = "en-foundations-now-continuous-e2", kind = "gap", prompt = "Look! It ___ (rain).", options = listOf(), answers = listOf("is raining", "'s raining", "is raing"), explain = "It is raining — weather takes it."), Exercise(id = "en-foundations-now-continuous-e3", kind = "order", prompt = "Say what they are doing. (TV / watch)", options = listOf(), answers = listOf("They are watching TV"), explain = "They are + watching."), Exercise(id = "en-foundations-now-continuous-e4", kind = "written", prompt = "Complete the pair: make → ___; sit → ___.", options = listOf(), answers = listOf("making, sitting", "making sitting"), explain = "make drops the e; sit doubles the t.")), skills = listOf("grammar:present-continuous", "grammar:verb-be", "function:talk-about-routines"), prerequisites = listOf("grammar:verb-be")),
    Lesson(id = "en-foundations-now-questions", title = "Asking about now", goal = "Ask and answer present-continuous questions, and say what is not happening.", intro = LessonIntro(explanation = listOf("Questions flip the verb: “You are listening.” → “Are you listening?” “She is coming.” → “Is she coming?”", "Negatives add not: “I'm not working today.” “He isn't coming.” “They aren't sleeping.”", "Question words go first: “What are you doing?” “Where is she going?” “Who are you calling?”"), examples = listOf(ExampleLine(text = "Are you listening to me?", meaning = "A yes/no question about now."), ExampleLine(text = "Is the bus coming?", meaning = "Asking about another thing."), ExampleLine(text = "What are you doing?", meaning = "The classic question word question."), ExampleLine(text = "I'm not talking to you!", meaning = "A negative about now."), ExampleLine(text = "Where are they going?", meaning = "Question word + are."), ExampleLine(text = "No, he isn't. He's sleeping.", meaning = "Short answer, then the real action."))), expressions = listOf(TargetExpression(text = "Are you …-ing?", meaning = "Ask about the listener now.", note = "Are you coming with us?"), TargetExpression(text = "Is he/she/it …-ing?", meaning = "Ask about another person.", note = "Is the taxi coming?"), TargetExpression(text = "What are you doing?", meaning = "Ask about the current action.", note = "Nothing much — I'm reading."), TargetExpression(text = "I'm not …-ing", meaning = "Say what is not happening.", note = "I'm not eating meat this week."), TargetExpression(text = "Who is …-ing?", meaning = "Ask which person.", note = "Who is cooking tonight?"), TargetExpression(text = "Quiet! The baby's sleeping.", meaning = "Explain a stopped action.", note = "Why + negative, in one phrase.")), situation = "You phone a friend who is at a party: ask what is happening, who is doing what, and what people are not doing.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Your friend answers the phone. Ask what she is doing.", expected = listOf("What are you doing?"), focus = "what + are", watch = "“What you doing?” — informal speech drops are, but learn the full form."), PracticeQuestion(prompt = "Ask if Tom is coming to the cinema.", expected = listOf("Is Tom coming to the cinema?"), focus = "is + -ing question", watch = "“Tom is coming…?” needs a question mark of order: “Is Tom coming…?”"), PracticeQuestion(prompt = "Say you are not drinking coffee these days.", expected = listOf("I'm not drinking coffee.", "I am not drinking coffee."), focus = "negative -ing", watch = "“I no drinking” — English says “I'm not drinking”."), PracticeQuestion(prompt = "Ask where your guests are going now.", expected = listOf("Where are they going?", "Where are you going?"), focus = "where + are", watch = "“Where they going?” — keep are: “Where are they going?”"), PracticeQuestion(prompt = "Is the baby sleeping? (no)", expected = listOf("No, the baby isn't sleeping.", "No, he isn't.", "No, she isn't.", "No, it isn't."), focus = "short negative answer", watch = "“No, baby not sleeping” — “No, the baby isn't sleeping”."), PracticeQuestion(prompt = "Ask who is making that noise.", expected = listOf("Who is making that noise?", "Who's making that noise?"), focus = "who + is", watch = "“Who making” — who needs is: “Who is making…?”"))), exercises = listOf(Exercise(id = "en-foundations-now-questions-e1", kind = "choice", prompt = "___ you coming with us?", options = listOf("Are", "Is", "Do", "Does"), answers = listOf("Are"), explain = "With you, the present-continuous question starts with Are."), Exercise(id = "en-foundations-now-questions-e2", kind = "gap", prompt = "She ___ ___ working today. (negative, short form)", options = listOf(), answers = listOf("is not", "isn't"), explain = "is not → isn't: She isn't working today."), Exercise(id = "en-foundations-now-questions-e3", kind = "order", prompt = "Ask about their destination.", options = listOf(), answers = listOf("Where are they going"), explain = "Question word + are + they + -ing."), Exercise(id = "en-foundations-now-questions-e4", kind = "written", prompt = "Answer with a full sentence: What are you wearing today?", options = listOf(), answers = listOf("I'm wearing <clothes>", "I am wearing <clothes>", "Today I'm wearing <clothes>"), explain = "I'm wearing + clothes — wear is almost always continuous.")), skills = listOf("grammar:present-continuous", "grammar:present-questions", "function:ask-simple-questions", "speaking:short-answer"), prerequisites = listOf("grammar:present-continuous", "grammar:subject-pronouns")),
    Lesson(id = "en-foundations-now-weather", title = "The weather today", goal = "Talk about today's weather and what people are wearing.", intro = LessonIntro(explanation = listOf("Weather uses it: “It's cold. It's raining. It isn't sunny.” Ask: “What's the weather like?”", "Wear lives in the continuous: “I'm wearing a coat.” “She's wearing a hat.”", "Two present tenses, two jobs: habits use present simple (“It often rains here”), right now uses continuous (“It's raining now”)."), examples = listOf(ExampleLine(text = "What's the weather like?", meaning = "The standard weather question."), ExampleLine(text = "It's cold and windy.", meaning = "Weather with adjectives."), ExampleLine(text = "It's snowing again!", meaning = "A weather action in progress."), ExampleLine(text = "I'm wearing my new jacket.", meaning = "Clothes right now."), ExampleLine(text = "She's wearing a red scarf.", meaning = "Another person's clothes."), ExampleLine(text = "It often rains here, but today the sun is shining.", meaning = "Habit vs right now."))), expressions = listOf(TargetExpression(text = "What's the weather like?", meaning = "Ask about today's weather.", note = "Answer: It's + adjective."), TargetExpression(text = "It's sunny / cloudy / windy", meaning = "Weather adjectives.", note = "Adjectives, not -ing."), TargetExpression(text = "It's raining / snowing", meaning = "Weather actions in progress.", note = "-ing because it is happening now."), TargetExpression(text = "I'm wearing …", meaning = "Your clothes today.", note = "Almost always continuous."), TargetExpression(text = "Take an umbrella!", meaning = "Weather advice.", note = "Imperative — no you."), TargetExpression(text = "What a horrible day!", meaning = "React to the weather.", note = "What a + noun phrase!")), situation = "You are planning a walk with a neighbour: ask about the weather, describe what you are wearing and decide what to take.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "A neighbour opens the door. Ask about the weather.", expected = listOf("What's the weather like?"), focus = "the weather question", watch = "“How is the weather?” also works; “What's the weather like?” is the classic."), PracticeQuestion(prompt = "Describe a perfect beach day. (two adjectives)", expected = listOf("It's sunny and warm.", "It's hot and sunny."), focus = "it's + adjectives", watch = "“Is sunny” — weather needs it: “It's sunny”."), PracticeQuestion(prompt = "It started to rain. What do you say? (verb)", expected = listOf("It's raining.", "It is raining."), focus = "-ing weather", watch = "“It rains now” is a habit form; right now is “It's raining”."), PracticeQuestion(prompt = "Ask what your friend is wearing today.", expected = listOf("What are you wearing?"), focus = "wear + -ing", watch = "“What do you wear?” asks about a habit."), PracticeQuestion(prompt = "Say what you are wearing right now.", expected = listOf("I'm wearing <clothes>."), focus = "I'm wearing", watch = "“I wear a coat” sounds like every day — right now is “I'm wearing”."), PracticeQuestion(prompt = "Your friend has no coat and it's cold. Give advice.", expected = listOf("Take a coat!", "Wear a coat!", "Put on a coat!"), focus = "imperative advice", watch = "“You take a coat” is fine but the natural shout is “Take a coat!”"))), exercises = listOf(Exercise(id = "en-foundations-now-weather-e1", kind = "choice", prompt = "___ the weather like today?", options = listOf("What's", "How's", "What", "Which"), answers = listOf("What's"), explain = "The fixed question is What's the weather like?"), Exercise(id = "en-foundations-now-weather-e2", kind = "gap", prompt = "She ___ ___ a blue dress today. (wear)", options = listOf(), answers = listOf("is wearing", "'s wearing"), explain = "wear in the continuous: is wearing."), Exercise(id = "en-foundations-now-weather-e3", kind = "order", prompt = "Ask about the weather.", options = listOf(), answers = listOf("What's the weather like"), explain = "What is + the weather + like."), Exercise(id = "en-foundations-now-weather-e4", kind = "written", prompt = "It's 35 degrees and the sun is out. Describe the weather (one sentence).", options = listOf(), answers = listOf("it's hot and sunny", "it is hot and sunny", "it's sunny and hot", "it's very hot"), explain = "It's + weather adjectives: hot and sunny.")), skills = listOf("grammar:present-continuous", "vocab:weather", "function:talk-about-weather"), canDo = listOf("talk-about-weather"), prerequisites = listOf("grammar:present-continuous"))))
}

object EnFoundationsDays {
    val unit = CourseUnit(id = "en-foundations-days", title = "Days & feelings", subtitle = "Your week, your health", level = "A1", themes = listOf(ConversationTheme("birthday-plan", "The birthday plan", "Which day works?", "calendar", "Course", "You are planning a small birthday dinner. Compare days, fix a date and divide the tasks.", 0),
                ConversationTheme("pharmacy-stop", "At the pharmacy", "Not feeling well", "cross.case", "Course", "You have small health problems. Say how you feel, what hurts and what you need.", 1)), lessons = listOf(    Lesson(id = "en-foundations-days-calendar", title = "Days, months & dates", goal = "Say the days of the week, months and dates, and make appointments.", intro = LessonIntro(explanation = listOf("Days and months are always capital letters: Monday, May. The week starts with Monday in the UK, Sunday in the US.", "Use on with days (on Monday), in with months and years (in June, in 2026), and at with times (at three o'clock).", "Dates: “My birthday is on 5 May” — say “the fifth of May”. Ordinals: first, second, third… twenty-first."), examples = listOf(ExampleLine(text = "The meeting is on Monday.", meaning = "on + day."), ExampleLine(text = "We're on holiday in July.", meaning = "in + month."), ExampleLine(text = "My birthday is on 5 May.", meaning = "on + date."), ExampleLine(text = "The party starts at eight.", meaning = "at + time."), ExampleLine(text = "See you on Tuesday!", meaning = "Arranging a day."), ExampleLine(text = "What day is it today?", meaning = "The daily question."))), expressions = listOf(TargetExpression(text = "What day is it today?", meaning = "Ask about the day.", note = "It's Wednesday."), TargetExpression(text = "on Monday / on Fridays", meaning = "Days with on.", note = "on Fridays = every Friday."), TargetExpression(text = "in May / in winter", meaning = "Months and seasons with in.", note = "in summer 2026"), TargetExpression(text = "at three o'clock", meaning = "Clock times with at.", note = "at half past seven"), TargetExpression(text = "My birthday is on …", meaning = "Your special date.", note = "on 12 September"), TargetExpression(text = "See you on …!", meaning = "Fix the next meeting.", note = "See you on Thursday!")), situation = "You and a classmate want to study together: compare your weeks, pick a day and a time, and put it in the calendar.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Someone asks about your routine. Say one thing you do on Mondays.", expected = listOf("On Mondays I <activity>.", "I <activity> on Mondays."), focus = "on + day", watch = "“in Monday” — days take on."), PracticeQuestion(prompt = "When is your birthday?", expected = listOf("My birthday is on <date>.", "It's on <date>."), focus = "on + date", watch = "“My birthday is 5 May” — natural English adds on."), PracticeQuestion(prompt = "Which preposition: ___ June, ___ Friday, ___ six o'clock?", expected = listOf("in June, on Friday, at six o'clock"), focus = "in / on / at", watch = "Months take in, days take on, times take at."), PracticeQuestion(prompt = "Arrange to meet a friend next weekend.", expected = listOf("See you on Saturday.", "Let's meet on Sunday."), focus = "arranging a day", watch = "“See you in Saturday” — days take on."), PracticeQuestion(prompt = "What day is it today?", expected = listOf("It's <day>.", "Today is <day>."), focus = "it + day", watch = "“Is Monday” — the answer needs it: “It's Monday”."), PracticeQuestion(prompt = "Say the month after May and the month before September.", expected = listOf("June and August"), focus = "month order", watch = "Capital letters: June, August — never june."))), exercises = listOf(Exercise(id = "en-foundations-days-calendar-e1", kind = "choice", prompt = "The course starts ___ September.", options = listOf("in", "on", "at", "to"), answers = listOf("in"), explain = "Months take in: in September."), Exercise(id = "en-foundations-days-calendar-e2", kind = "gap", prompt = "We always meet ___ Fridays.", options = listOf(), answers = listOf("on"), explain = "Days take on: on Fridays (every Friday)."), Exercise(id = "en-foundations-days-calendar-e3", kind = "order", prompt = "Say when your birthday is. (5 / on / May / My birthday / is)", options = listOf(), answers = listOf("My birthday is on 5 May"), explain = "on + day + month for dates."), Exercise(id = "en-foundations-days-calendar-e4", kind = "gap", prompt = "The class is ___ Monday.", options = listOf(), answers = listOf("on monday"), explain = "Días con on: on Monday.")), skills = listOf("grammar:time-expressions", "function:tell-time", "vocab:social-expressions"), prerequisites = listOf("grammar:time-expressions")),
    Lesson(id = "en-foundations-days-free-time", title = "Free time and hobbies", goal = "Talk about hobbies with play, go and do, and say how often.", intro = LessonIntro(explanation = listOf("Three verbs own the hobbies: play for games (play football), go for -ing activities (go swimming), do for the rest (do yoga).", "Say how often with adverbs: always, usually, often, sometimes, never — they go before the main verb: “I often swim.”", "Ask back: “What do you do in your free time?” “Do you play any sports?”"), examples = listOf(ExampleLine(text = "I play chess with my uncle.", meaning = "play + game."), ExampleLine(text = "She goes swimming on Saturdays.", meaning = "go + -ing activity."), ExampleLine(text = "We do yoga in the park.", meaning = "do + exercise."), ExampleLine(text = "I never watch TV in the morning.", meaning = "never = 0% frequency."), ExampleLine(text = "He usually plays tennis after work.", meaning = "usually + third person -s."), ExampleLine(text = "What do you do in your free time?", meaning = "The standard free-time question."))), expressions = listOf(TargetExpression(text = "What do you do in your free time?", meaning = "Ask about hobbies.", note = "Answer: I play / go / do …"), TargetExpression(text = "play + game", meaning = "Football, chess, video games.", note = "play the guitar for music."), TargetExpression(text = "go + -ing", meaning = "Swimming, running, shopping.", note = "go swimming, not go swim."), TargetExpression(text = "do + yoga / sport", meaning = "General activities.", note = "do exercise three times a week."), TargetExpression(text = "always / often / sometimes / never", meaning = "How often.", note = "Before the verb: I often read."), TargetExpression(text = "That sounds fun!", meaning = "React to a hobby.", note = "Sounds + adjective, no subject.")), situation = "You meet a neighbour at the park: ask about free time, say what you do and how often, and find one thing you both enjoy.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "A neighbour asks about your weekend. Say one hobby you do in your free time.", expected = listOf("I <play/go/do> <hobby>.", "In my free time I <activity>."), focus = "play / go / do", watch = "“I go football” — ball games take play."), PracticeQuestion(prompt = "Ask your friend about their free time.", expected = listOf("What do you do in your free time?"), focus = "the free-time question", watch = "“What you do…?” — questions need do."), PracticeQuestion(prompt = "Say how often you cook. (sometimes)", expected = listOf("I sometimes cook.", "Sometimes I cook."), focus = "frequency position", watch = "“I cook sometimes” is fine too, but “I sometimes cook” is the safest order."), PracticeQuestion(prompt = "Your friend swims every Saturday. Say it. (she)", expected = listOf("She goes swimming every Saturday.", "She swims every Saturday."), focus = "go + -ing", watch = "“She go swimming” — third person needs -s: goes."), PracticeQuestion(prompt = "React positively to a new hobby you hear about.", expected = listOf("That sounds fun!", "That's cool!", "Nice!"), focus = "reacting", watch = "“That sounds funny” means “gracioso” — fun = divertido."), PracticeQuestion(prompt = "Say one thing you never do in your free time.", expected = listOf("I never <activity>."), focus = "never + verb", watch = "“I don't never” — never is already negative."))), exercises = listOf(Exercise(id = "en-foundations-days-free-time-e1", kind = "choice", prompt = "We ___ swimming every summer.", options = listOf("go", "play", "do", "make"), answers = listOf("go"), explain = "go + -ing activity: go swimming."), Exercise(id = "en-foundations-days-free-time-e2", kind = "gap", prompt = "She ___ plays tennis after work. (usual)", options = listOf(), answers = listOf("usually"), explain = "usually goes before the main verb."), Exercise(id = "en-foundations-days-free-time-e3", kind = "order", prompt = "Ask about free time.", options = listOf(), answers = listOf("What do you do in your free time"), explain = "Question word + do + you + verb."), Exercise(id = "en-foundations-days-free-time-e4", kind = "written", prompt = "Name the right verb: ___ chess, ___ yoga, ___ running.", options = listOf(), answers = listOf("play chess, do yoga, go running", "play, do, go"), explain = "play games, do exercise, go + -ing.")), skills = listOf("vocab:hobbies", "grammar:frequency-adverbs", "function:talk-about-routines", "speaking:describe-routine"), canDo = listOf("talk-about-routines"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "en-foundations-days-instructions", title = "Follow the instructions", goal = "Give and follow instructions with imperatives, and politely ask people to do things.", intro = LessonIntro(explanation = listOf("The imperative is the verb alone: “Open the box. Listen carefully. Turn left.” It works for instructions, directions and recipes.", "Negatives use don't: “Don't touch it. Don't worry.”", "Soften with please and let's: “Please sit down.” “Let's start.” Let's = a suggestion for both of us."), examples = listOf(ExampleLine(text = "Open your books, please.", meaning = "A classroom instruction."), ExampleLine(text = "Turn left at the bank.", meaning = "A direction."), ExampleLine(text = "Don't touch the pan — it's hot!", meaning = "A warning."), ExampleLine(text = "Let's take a break.", meaning = "A suggestion for both."), ExampleLine(text = "Please speak slowly.", meaning = "A polite request."), ExampleLine(text = "Press this button first.", meaning = "Step-by-step help."))), expressions = listOf(TargetExpression(text = "Open / Close / Press …", meaning = "Basic instruction verbs.", note = "The verb alone is the command."), TargetExpression(text = "Don't + verb", meaning = "Stop someone politely.", note = "Don't worry."), TargetExpression(text = "Let's + verb", meaning = "Suggest doing it together.", note = "Let's go! = let us go."), TargetExpression(text = "…, please.", meaning = "The softener.", note = "Please can go first too: Please sit down."), TargetExpression(text = "First …, then …", meaning = "Order the steps.", note = "First press, then wait."), TargetExpression(text = "Careful!", meaning = "A short warning.", note = "= Be careful!")), situation = "You help a friend use a new coffee machine: give the steps in order, warn about the hot part and suggest trying it together.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "The class is noisy. What does the teacher say? (quiet)", expected = listOf("Be quiet!", "Quiet, please.", "Please be quiet."), focus = "be imperative", watch = "“You be quiet” is possible but the clean imperative is “Be quiet”."), PracticeQuestion(prompt = "Warn your friend about the hot pan.", expected = listOf("Don't touch the pan!", "Careful, it's hot!"), focus = "don't + verb", watch = "“Not touch” — the negative imperative needs don't."), PracticeQuestion(prompt = "Suggest starting the exercise together.", expected = listOf("Let's start the exercise.", "Let's begin."), focus = "let's + verb", watch = "“Let's to start” — let's takes the bare verb."), PracticeQuestion(prompt = "Give the first two steps for the machine.", expected = listOf("First press the button, then wait.", "Press this button, then wait."), focus = "first / then", watch = "Instructions follow order words: first, then, after that."), PracticeQuestion(prompt = "Ask someone to speak more slowly, politely.", expected = listOf("Please speak slowly.", "Speak slowly, please.", "Could you speak slowly?"), focus = "polite request", watch = "“Speak slow” — the adverb is slowly."), PracticeQuestion(prompt = "Tell your friend not to worry about the mistake.", expected = listOf("Don't worry!", "Don't worry about it."), focus = "don't worry", watch = "“No worry” is not English — “Don't worry”."))), exercises = listOf(Exercise(id = "en-foundations-days-instructions-e1", kind = "choice", prompt = "___ worry — it's easy!", options = listOf("Don't", "Not", "No", "Doesn't"), answers = listOf("Don't"), explain = "The negative imperative is Don't + verb."), Exercise(id = "en-foundations-days-instructions-e2", kind = "gap", prompt = "___ start with question one. (suggestion for both)", options = listOf(), answers = listOf("let's", "lets", "let us"), explain = "Let's = a suggestion for both of us."), Exercise(id = "en-foundations-days-instructions-e3", kind = "order", prompt = "Politely ask for quiet.", options = listOf(), answers = listOf("Please be quiet"), explain = "Be + adjective works in imperatives."), Exercise(id = "en-foundations-days-instructions-e4", kind = "written", prompt = "Put in order: press / first / this button / .", options = listOf(), answers = listOf("press this button first", "first press this button"), explain = "first can go before or after the instruction.")), skills = listOf("grammar:imperatives", "function:make-requests", "vocab:social-expressions"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "en-foundations-days-feelings", title = "How do you feel?", goal = "Describe feelings and small health problems, and ask about other people.", intro = LessonIntro(explanation = listOf("Feelings use be: “I'm tired. She's happy. They're hungry.” Health problems use have got: “I've got a headache.”", "Ask: “How are you feeling?” “What's wrong?” Answer: “I don't feel well.” “My leg hurts.”", "Small comfort: “Get better soon!” “Take care!”"), examples = listOf(ExampleLine(text = "I'm so tired today.", meaning = "A feeling with be."), ExampleLine(text = "I've got a headache.", meaning = "A health problem with have got."), ExampleLine(text = "My back hurts.", meaning = "A body part + hurts."), ExampleLine(text = "What's wrong?", meaning = "Ask about a problem."), ExampleLine(text = "She isn't feeling well.", meaning = "Feeling ill, continuous."), ExampleLine(text = "Get better soon!", meaning = "A warm goodbye to someone ill."))), expressions = listOf(TargetExpression(text = "I'm tired / hungry / happy", meaning = "Feelings with be.", note = "Never “I have tired”."), TargetExpression(text = "I've got a headache / a cold", meaning = "Small health problems.", note = "have got + a + illness."), TargetExpression(text = "My … hurts.", meaning = "Point at the pain.", note = "My throat hurts."), TargetExpression(text = "What's wrong?", meaning = "Notice someone's problem.", note = "= What's the matter?"), TargetExpression(text = "I don't feel well.", meaning = "The general “me siento mal”.", note = "well = fine, here."), TargetExpression(text = "Get better soon! / Take care!", meaning = "Warm wishes.", note = "Fixed phrases.")), situation = "A colleague looks pale at work: ask what is wrong, they describe small problems, and you comfort them and give simple advice.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Your friend looks sad. Ask what's wrong.", expected = listOf("What's wrong?", "What's the matter?"), focus = "noticing", watch = "“What you have?” — the fixed question is “What's wrong?”"), PracticeQuestion(prompt = "Say you have a pain in your head.", expected = listOf("I've got a headache.", "I have a headache.", "My head hurts."), focus = "have got + illness", watch = "“I have headache” — the article matters: “a headache”."), PracticeQuestion(prompt = "Say how you feel today. (tired)", expected = listOf("I'm tired.", "I'm very tired today."), focus = "be + feeling", watch = "“I have tired” — feelings take be."), PracticeQuestion(prompt = "Your colleague says she doesn't feel well. Comfort her.", expected = listOf("Get better soon!", "Take care!", "Go home and rest."), focus = "comforting", watch = "Any warm fixed phrase works here."), PracticeQuestion(prompt = "Ask about your friend's back pain today.", expected = listOf("How is your back today?", "Is your back better?", "Does your back still hurt?"), focus = "asking about pain", watch = "“How is your back?” is the natural follow-up."), PracticeQuestion(prompt = "Say two things you need when you have a cold.", expected = listOf("I need water and rest.", "I need tea and tissues."), focus = "need + noun", watch = "need + noun for things, need + to + verb for actions."))), exercises = listOf(Exercise(id = "en-foundations-days-feelings-e1", kind = "choice", prompt = "I ___ so tired today.", options = listOf("'m", "have", "am having", "do"), answers = listOf("'m"), explain = "Feelings take be: I'm tired."), Exercise(id = "en-foundations-days-feelings-e2", kind = "gap", prompt = "I've ___ a terrible headache.", options = listOf(), answers = listOf("got", "get"), explain = "have got a headache — got completes the pair."), Exercise(id = "en-foundations-days-feelings-e3", kind = "order", prompt = "Ask about a problem you notice.", options = listOf(), answers = listOf("What is wrong"), explain = "The fixed question: What's wrong?"), Exercise(id = "en-foundations-days-feelings-e4", kind = "written", prompt = "Your throat hurts. Say it two ways.", options = listOf(), answers = listOf("my throat hurts", "i've got a sore throat", "i have a sore throat", "my throat is sore"), explain = "My X hurts or I've got a sore throat.")), skills = listOf("vocab:feelings", "vocab:health", "function:talk-about-health", "grammar:have-got"), prerequisites = listOf("grammar:have-got", "grammar:verb-be"))))
}

object EnFoundationsTransport {
    val unit = CourseUnit(id = "en-foundations-transport", title = "On the move", subtitle = "Buses, trains, tickets", level = "A1", themes = listOf(ConversationTheme("ticket-machine", "The ticket machine", "Which ticket?", "ticket", "Course", "You help a visitor buy the right ticket from a machine: zones, singles, day passes — one step at a time.", 0),
                ConversationTheme("wrong-bus", "The wrong bus", "Where does it go?", "bus", "Course", "You are on the wrong bus together. Ask the driver, check the map and find the way back.", 1)), lessons = listOf(    Lesson(id = "en-foundations-transport-bus-train", title = "Bus & train", goal = "Buy tickets and ask about buses and trains: times, platforms and prices.", intro = LessonIntro(explanation = listOf("At the station, four questions do everything: “Which bus goes to…?” “What time is the next train?” “How much is a ticket?” “Which platform?”", "Transport words travel in pairs: bus / bus stop, train / train station, plane / airport. Learn the pair, not the word alone.", "Prices use how much: “How much is a single ticket?” Answers: “It's two euros fifty.”"), examples = listOf(ExampleLine(text = "Which bus goes to the airport?", meaning = "The route question."), ExampleLine(text = "What time is the next train?", meaning = "The time question."), ExampleLine(text = "How much is a day ticket?", meaning = "The price question."), ExampleLine(text = "Which platform is it?", meaning = "Where to wait."), ExampleLine(text = "A single to the centre, please.", meaning = "One-way ticket."), ExampleLine(text = "Is this seat free?", meaning = "On the bus or train."))), expressions = listOf(TargetExpression(text = "Which bus/train goes to …?", meaning = "Ask for the route.", note = "The 12 goes to the centre."), TargetExpression(text = "What time is the next …?", meaning = "Ask the timetable.", note = "At ten past."), TargetExpression(text = "How much is a ticket to …?", meaning = "Ask the price.", note = "A single or a return?"), TargetExpression(text = "A single / a return, please.", meaning = "One-way or both ways.", note = "return = ida y vuelta."), TargetExpression(text = "Which platform?", meaning = "Where to get on.", note = "Platform 3."), TargetExpression(text = "Does this bus stop at …?", meaning = "Check your stop.", note = "Yes, near the park.")), situation = "You help a visitor at the station: choose the bus, buy two singles, find the platform and check the next departure.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "A visitor wants the airport. Ask the route question.", expected = listOf("Which bus goes to the airport?"), focus = "route question", watch = "“What bus for airport?” — the full question is “Which bus goes to…?”"), PracticeQuestion(prompt = "Ask about the next train to Madrid.", expected = listOf("What time is the next train to Madrid?"), focus = "time question", watch = "“When is the next train?” also works."), PracticeQuestion(prompt = "Ask the price of a ticket to the centre.", expected = listOf("How much is a ticket to the centre?"), focus = "price question", watch = "How much is / are — plural: “How much are the tickets?”"), PracticeQuestion(prompt = "Buy one ticket, one way, politely.", expected = listOf("A single to the centre, please.", "One single, please."), focus = "single", watch = "A return is both ways — check what the visitor wants."), PracticeQuestion(prompt = "Ask where to wait for the train.", expected = listOf("Which platform is it?", "What platform does it leave from?"), focus = "platform", watch = "platform = andén — not “station” again."), PracticeQuestion(prompt = "Check the bus stops near the park.", expected = listOf("Does this bus stop near the park?"), focus = "stop at", watch = "“Does this bus go in the park?” — stop at + place."))), exercises = listOf(Exercise(id = "en-foundations-transport-bus-train-e1", kind = "choice", prompt = "___ much is a day ticket?", options = listOf("How", "What", "Which", "When"), answers = listOf("How"), explain = "Prices take How much: How much is…?"), Exercise(id = "en-foundations-transport-bus-train-e2", kind = "gap", prompt = "The train to the airport leaves from ___ 3. (andén)", options = listOf(), answers = listOf("platform"), explain = "Platform 3 = andén 3."), Exercise(id = "en-foundations-transport-bus-train-e3", kind = "order", prompt = "Ask the route question.", options = listOf(), answers = listOf("Which bus goes to the airport"), explain = "Which + bus + goes to + place."), Exercise(id = "en-foundations-transport-bus-train-e4", kind = "written", prompt = "Buy a one-way ticket politely.", options = listOf(), answers = listOf("a single to <place> please", "one single please", "a single please"), explain = "A single to…, please.")), skills = listOf("vocab:transport", "grammar:time-expressions", "function:tell-time", "writing:sentence"), canDo = listOf("use-transport"), prerequisites = listOf("grammar:time-expressions")),
    Lesson(id = "en-foundations-transport-commute", title = "How do you get to work?", goal = "Describe how you travel to work or school with by + transport.", intro = LessonIntro(explanation = listOf("by + transport for the means: “by bus, by train, by car, by bike, by plane”. On foot for walking: “I go to work on foot.”", "The question: “How do you get to work?” Answers add a time: “It takes twenty minutes.”", "get to + place = arrive: “I get to the office at nine.” get home — no to: “I get home at six.”"), examples = listOf(ExampleLine(text = "I go to work by bike.", meaning = "by + transport."), ExampleLine(text = "She goes to school on foot.", meaning = "Walking = on foot."), ExampleLine(text = "How do you get to work?", meaning = "The commute question."), ExampleLine(text = "It takes twenty minutes by bus.", meaning = "Duration of the trip."), ExampleLine(text = "I get to the office at nine.", meaning = "Arrive at + place."), ExampleLine(text = "I get home at six.", meaning = "get home — no to."))), expressions = listOf(TargetExpression(text = "by bus / train / bike / car", meaning = "The means of travel.", note = "Never “with bus”."), TargetExpression(text = "on foot", meaning = "Walking.", note = "Not “by foot” in careful English."), TargetExpression(text = "How do you get to …?", meaning = "Ask about the journey.", note = "get to + place."), TargetExpression(text = "It takes + time", meaning = "Duration.", note = "It takes ten minutes on foot."), TargetExpression(text = "I get to work at …", meaning = "Arrival time.", note = "get home, get here: no to."), TargetExpression(text = "The traffic is terrible.", meaning = "Explain the delay.", note = "Traffic is uncountable.")), situation = "You compare morning routines with a colleague: how you each get to work, how long it takes and why you would never cycle uphill.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Ask your colleague about their journey to work.", expected = listOf("How 