object EnFoundationsOut {
    val unit = CourseUnit(id = "en-foundations-out", title = "Out and about", subtitle = "Shops, chats, help", level = "A1", themes = listOf(ConversationTheme("supermarket-run", "The supermarket run", "Food and needs", "cart", "Course", "You shop together for the weekend: find things, ask prices and check the list.", 0),
                ConversationTheme("new-in-town", "New in town", "Small talk", "sun.haze", "Course", "You chat with someone at the bus stop: the weather, the weekend, the neighbourhood.", 1)), lessons = listOf(    Lesson(id = "en-foundations-out-supermarket", title = "At the supermarket", goal = "Shop for food: name aisles, ask where things are and say what you need.", intro = LessonIntro(explanation = listOf("Supermarket words come in groups: the fruit section, the dairy section, the frozen food aisle.", "Ask for locations: “Where is the milk?” “Which aisle has the bread?” Answers: “Aisle three, next to the juice.”", "Say needs with need + noun: “We need rice, eggs and tomatoes.”"), examples = listOf(ExampleLine(text = "Where is the milk?", meaning = "The location question."), ExampleLine(text = "It's in aisle three.", meaning = "The answer."), ExampleLine(text = "We need rice and eggs.", meaning = "Say your needs."), ExampleLine(text = "Is this bread fresh?", meaning = "Check quality."), ExampleLine(text = "Do you have any fresh fish today?", meaning = "Ask about availability."))), expressions = listOf(TargetExpression(text = "Where is the …?", meaning = "Ask for a place.", note = "…the sugar?"), TargetExpression(text = "Which aisle has …?", meaning = "Ask for the section.", note = "…the pasta?"), TargetExpression(text = "We need + food", meaning = "Say what to buy.", note = "We need coffee."), TargetExpression(text = "How much is/are …?", meaning = "Price, again.", note = "How much are the eggs?"), TargetExpression(text = "Is this … fresh?", meaning = "Check the food.", note = "Is this fish fresh?"), TargetExpression(text = "Anything else?", meaning = "The cashier's question.", note = "No, that's all, thanks."), TargetExpression(text = "Is this the only …?", meaning = "Check the options.", note = "Is this the only bread?")), situation = "You shop for a weekend with friends: find six things on the list, ask where two of them are and check one price.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Say two things you need for breakfast.", expected = listOf("We need <food> and <food>."), focus = "need + food", watch = "Food words have no plural here: “We need bread”, not “breads”."), PracticeQuestion(prompt = "Ask where the sugar is.", expected = listOf("Where is the sugar?"), focus = "where is", watch = "Sugar is uncountable: “Where is”, not “Where are”."), PracticeQuestion(prompt = "Ask the price of the eggs.", expected = listOf("How much are the eggs?"), focus = "plural price", watch = "Plural things take are: How much ARE the eggs?"), PracticeQuestion(prompt = "The cashier asks “Anything else?”. Answer politely.", expected = listOf("No, that's all, thanks.", "No, that's all."), focus = "closing the shop", watch = "“That's all” is the friendly full stop."), PracticeQuestion(prompt = "Ask if the bread is fresh.", expected = listOf("Is this bread fresh?", "Is the bread fresh?"), focus = "fresh", watch = "fresh = recién hecho — bread, fish, fruit."))), exercises = listOf(Exercise(id = "en-foundations-out-supermarket-e1", kind = "choice", prompt = "Where ___ the milk?", options = listOf("is", "are", "do", "does"), answers = listOf("is"), explain = "Uncountable: the milk is."), Exercise(id = "en-foundations-out-supermarket-e2", kind = "gap", prompt = "We ___ rice and tomatoes. (necesitamos)", options = listOf(), answers = listOf("need"), explain = "need + food."), Exercise(id = "en-foundations-out-supermarket-e3", kind = "order", prompt = "Ask about the eggs. (how / are / much / the eggs)", options = listOf(), answers = listOf("How much are the eggs"), explain = "Plural price: How much are…?"), Exercise(id = "en-foundations-out-supermarket-e4", kind = "written", prompt = "Name two things on your shopping list.", options = listOf(), answers = listOf("we need <food> and <food>", "i need <food> and <food>"), explain = "We need X and Y.")), skills = listOf("vocab:food", "grammar:there-is-are", "function:go-shopping", "writing:sentence"), canDo = listOf("go-shopping"), prerequisites = listOf("grammar:there-is-are")),
    Lesson(id = "en-foundations-out-smalltalk", title = "Small talk", goal = "Chat politely with strangers: the weather, the weekend and friendly exits.", intro = LessonIntro(explanation = listOf("Small talk has safe topics: the weather, the weekend, the neighbourhood. Politics and salary are not small talk.", "The rhythm: comment + question. “Cold today, isn't it? Do you know if the bus is late?”", "Exit kindly: “Well, have a good one!” — you don't need a reason to stop."), examples = listOf(ExampleLine(text = "Cold today, isn't it?", meaning = "Weather opener."), ExampleLine(text = "Any plans for the weekend?", meaning = "The classic question."), ExampleLine(text = "Nothing much — you?", meaning = "Return the question."), ExampleLine(text = "Have a good one!", meaning = "Friendly exit."), ExampleLine(text = "The bus is always late on Mondays.", meaning = "A safe complaint."))), expressions = listOf(TargetExpression(text = "Comment + isn't it?", meaning = "Weather opener.", note = "Lovely day, isn't it?"), TargetExpression(text = "Any plans for the weekend?", meaning = "Ask about Saturday.", note = "Nothing special planned."), TargetExpression(text = "Nothing much — you?", meaning = "Answer and return.", note = "The ping-pong of chat."), TargetExpression(text = "Have a good one!", meaning = "Exit kindly.", note = "= have a good day."), TargetExpression(text = "See you around!", meaning = "Exit for strangers.", note = "You'll meet again."), TargetExpression(text = "This weather is crazy, right?", meaning = "Weather small talk 2.0.", note = "right? invites agreement.")), situation = "You wait at a bus stop next to a neighbour you half-know: open with the weather, ask about the weekend and exit kindly when the bus arrives.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Open with the weather. (cold)", expected = listOf("Cold today, isn't it?"), focus = "isn't it?", watch = "The tag asks for agreement: “Cold today, isn't it?”"), PracticeQuesti