    Lesson(id = "en-foundations-out-asking-help", title = "Asking for help", goal = "Ask strangers for help in a shop or street, and thank them properly.", intro = LessonIntro(explanation = listOf("Open with excuse me: “Excuse me, where's the lift?” It signals a request is coming.", "Requests with can: “Can you help me?” “Can I ask something?” After help, say thank you + a follow-up.", "If you don't understand, say so: “Sorry, can you repeat that?” — people are kind about it."), examples = listOf(ExampleLine(text = "Excuse me, where's the lift?", meaning = "Open + question."), ExampleLine(text = "Can you help me, please?", meaning = "The request."), ExampleLine(text = "Sorry, can you repeat that?", meaning = "Didn't hear."), ExampleLine(text = "Thank you very much!", meaning = "Close warmly."), ExampleLine(text = "Could you say that more slowly, please?", meaning = "A kind second request."))), expressions = listOf(TargetExpression(text = "Excuse me, …", meaning = "Start any request.", note = "Excuse me, is this seat free?"), TargetExpression(text = "Can you help me?", meaning = "Ask for help.", note = "help me with + thing."), TargetExpression(text = "Can I ask something?", meaning = "Softer opener.", note = "Of course!"), TargetExpression(text = "Sorry, can you repeat that?", meaning = "Didn't hear.", note = "repeat that, not “repeat” alone."), TargetExpression(text = "Thank you very much!", meaning = "Close with warmth.", note = "You're welcome comes back."), TargetExpression(text = "Is this the right way to…?", meaning = "Check direction.", note = "…the station?")), situation = "You are lost in a shopping centre: ask two strangers for help, ask one to repeat, and thank both warmly.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Start your request to a stranger politely.", expected = listOf("Excuse me, where is the <place>?"), focus = "excuse me", watch = "excuse me opens; thank you closes."), PracticeQuestion(prompt = "Ask someone to help you with a heavy bag.", expected = listOf("Can you help me with this bag, please?"), focus = "can you", watch = "can + you + base verb."), PracticeQuestion(prompt = "You didn't hear the answer. Say so.", expected = listOf("Sorry, can you repeat that?"), focus = "repeat", watch = "repeat that — “repeat?” alone is blunt."), PracticeQuestion(prompt = "Thank the person warmly.", expected = listOf("Thank you very much!", "Thanks a lot!"), focus = "closing", watch = "Warm thanks finish the exchange."), PracticeQuestion(prompt = "Ask someone to speak more slowly.", expected = listOf("Could you say that more slowly, please?", "Can you speak more slowly, please?"), focus = "could you", watch = "could you is softer than can you — use it twice and people will love you."))), exercises = listOf(Exercise(id = "en-foundations-out-asking-help-e1", kind = "choice", prompt = "___ me, where's the lift?", options = listOf("Excuse", "Sorry for", "Thank", "Hello you"), answers = listOf("Excuse"), explain = "Excuse me opens any request."), Exercise(id = "en-foundations-out-asking-help-e2", kind = "gap", prompt = "Can you ___ that again, please? (repeat)", options = listOf(), answers = listOf("repeat"), explain = "repeat that, please."), Exercise(id = "en-foundations-out-asking-help-e3", kind = "order", prompt = "Ask for help with a bag.", options = listOf(), answers = listOf("Can you help me with this bag"), explain = "can you help me with + thing."), Exercise(id = "en-foundations-out-asking-help-e4", kind = "written", prompt = "Thank someone who helped you a lot.", options = listOf(), answers = listOf("thank you very much", "thanks a lot"), explain = "Two warm closers.")), skills = listOf("function:make-requests", "grammar:can", "vocab:social-expressions", "writing:sentence"), canDo = listOf("solve-everyday-problems"), prerequisites = listOf("grammar:subject-pronouns"))))
