    Lesson(id = "en-foundations-friends-likes", title = "What do you like?", goal = "Talk about likes and dislikes with love, like, don't like and hate.", intro = LessonIntro(explanation = listOf("The pattern: subject + love/like/don't like/hate + noun or verb-ing: “I love music.” “She likes dancing.”", "Ask: “Do you like…?” Short answers repeat do: “Yes, I do. / No, I don't.”", "Strong words: love is 100%, like is warm, don't like is polite, hate is strong — use hate for fun, carefully."), examples = listOf(ExampleLine(text = "I love music.", meaning = "100% positive."), ExampleLine(text = "She likes dancing.", meaning = "like + -ing for activities."), ExampleLine(text = "I don't like coffee.", meaning = "Polite negative."), ExampleLine(text = "Do you like football?", meaning = "The question."), ExampleLine(text = "I hate Mondays!", meaning = "Strong — often funny."), ExampleLine(text = "I quite like her podcasts.", meaning = "quite softens like."))), expressions = listOf(TargetExpression(text = "I love / like + noun", meaning = "Positive feelings.", note = "I like your bag."), TargetExpression(text = "love / like + -ing", meaning = "Activities.", note = "I love swimming."), TargetExpression(text = "Do you like …?", meaning = "Ask.", note = "Do you like cats?"), TargetExpression(text = "Yes, I do / No, I don't", meaning = "Short answers.", note = "Repeat do."), TargetExpression(text = "I don't like …", meaning = "Polite negative.", note = "Softer than hate."), TargetExpression(text = "My favourite … is …", meaning = "The top one.", note = "My favourite food is pasta."), TargetExpression(text = "…is not really my thing.", meaning = "Polite dislike.", note = "Horror films are not my thing.")), situation = "You and a friend find common ground: ask about food, music and weekends, and discover one thing you both hate.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Ask if your friend likes cats.", expected = listOf("Do you like cats?"), focus =