    Lesson(id = "en-foundations-friends-plans", title = "Plans with friends", goal = "Arrange to meet: suggest, check free time and confirm the plan.", intro = LessonIntro(explanation = listOf("Arrange in three steps: suggest (“Do you want to…?”), check time (“Are you free on Saturday?”), confirm (“See you at eight!”).", "Do you want to + verb is the friendliest opener between equals. Let's works once you agree.", "Times and places finish the plan: “At eight, at the main square.” A plan without a place is a wish."), examples = listOf(ExampleLine(text = "Do you want to see a film?", meaning = "The friendly opener."), ExampleLine(text = "Are you free on Saturday?", meaning = "Check the time."), ExampleLine(text = "Let's meet at eight.", meaning = "Confirm the detail."), ExampleLine(text = "See you at the main square!", meaning = "Place confirmed."), ExampleLine(text = "Sorry, I can't. Sunday?", meaning = "Decline + counter-offer."), ExampleLine(text = "I'll check my diary and let you know.", meaning = "A soft maybe."))), expressions = listOf(TargetExpression(text = "Do you want to + verb?", meaning = "Open the plan.", note = "Do you want to go out?"), TargetExpression(text = "Are you free + day?", meaning = "Check the diary.", note = "Are you free on Friday?"), TargetExpression(text = "Let's + verb + time/place", meaning = "Confirm.", note = "Let's meet at seven."), TargetExpression(text = "at + time, at/in + place", meaning = "The details.", note = "At eight, at the square."), TargetExpression(text = "Sorry, I can't. …?", meaning = "Decline + retry.", note = "…How about Sunday?"), TargetExpression(text = "See you …!", meaning = "Close the plan.", note = "See you Saturday!"), TargetExpression(text = "I can't wait!", meaning = "Enthusiasm for the plan.", note = "can't wait + for/to.")), situation = "You arrange a Saturday with a friend: suggest an activity, check Saturday, hear a no, move to Sunday and confirm time and place.", practice = LessonPractice(questions = lis