                ConversationTheme("restaurant", "Dinner out", "A table for two", "fork.knife", "Course", "You book and enjoy a dinner out: order dishes, say what you love and hate, and ask for the bill.", 1)), lessons = listOf(    Lesson(id = "en-foundations-u5-some-any", title = "Some / any & countables", goal = "Talk about food quantities: what you have, what you need and how much.", intro = LessonIntro(explanation = listOf("Countable things have a plural: one apple, two apples. Uncountable things have no plural: water, rice, milk, bread.", "Use some in affirmative sentences (“We've got some rice”) and any in questions and negatives (“Have we got any milk?” “There isn't any bread.”).", "To count uncountables, add a container: a bottle of water, a kilo of rice, a loaf of bread."), examples = listOf(ExampleLine(text = "We need some onions.", meaning = "Affirmative some."), ExampleLine(text = "Do we have any eggs?", meaning = "Question any."), ExampleLine(text = "There isn't any sugar.", meaning = "Negative any."), ExampleLine(text = "Can I have a bottle of water?", meaning = "Counting water."), ExampleLine(text = "How much rice do we need?", meaning = "much for uncountables."), ExampleLine(text = "How many tomatoes are left?", meaning = "many for countables."))), expressions = listOf(TargetExpression(text = "some + plural/uncountable", meaning = "An unstated amount.", note = "some apples, some water"), TargetExpression(text = "any in questions/negatives", meaning = "Do we have any…? We don't have any…", note = "any eggs, any time"), TargetExpression(text = "a bottle/kilo/loaf of …", meaning = "Count the uncountable.", note = "two bottles of milk"), TargetExpression(text = "How much …?", meaning = "Uncountables.", note = "How much butter is left?"), TargetExpression(text = "How many …?", meaning = "Countables.", note = "How many peppers do we need?"), TargetExpression(text = "a little / a few", meaning = "Small amounts: a little + uncountable, a few + plural.", note 