    Lesson(id = "en-foundations-telling-problems", title = "Explaining a problem", goal = "Structure a problem clearly: context, what happened, what you want.", intro = LessonIntro(explanation = listOf("The three-step structure: context (“I rented a car on Friday”), problem (“it broke down on the motorway”), request (“I'd like a refund or a replacement”).", "Stay factual, not emotional: “The engine stopped three times” beats “your car is terrible!”", "Signal the request: “So what I'd like is…” — the listener knows the explanation has landed somewhere."), examples = listOf(ExampleLine(text = "I rented a car from your airport office.", meaning = "Context first."), ExampleLine(text = "It broke down twice on Saturday.", meaning = "The problem, factually."), ExampleLine(text = "I'd like a replacement or a refund.", meaning = "The request."), ExampleLine(text = "This is the second time it's happened.", meaning = "History strengthens the case."), ExampleLine(text = "What can you do about it?", meaning = "Hand the problem over."))), expressions = listOf(TargetExpression(text = "Context first: …", meaning = "Set the scene.", note = "I bought it last week."), TargetExpression(text = "The problem is …", meaning = "Say it plainly.", note = "…it doesn't charge."), TargetExpression(text = "I'd like …", meaning = "State the request.", note = "I'd like a replacement."), TargetExpression(text = "This is the second time …", meaning = "Show the pattern.", note = "…it's happened."), TargetExpression(text = "What can you do about it?", meaning = "Pass the ball.", note = "Polite but firm.")), situation = "You call about a faulty rental: give context, describe the two failures factually, and ask for one of two clear solutions.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Give the context of your complaint. (rented Friday)", expected = listOf("I rented a car from your office on Friday."), focus = "context", watch = "Dates and places first — emotions later (or never)."), PracticeQuestion(prompt = "Describe the failure factually. (broke down twice)", expected = listOf("It broke down twice on Saturday."), focus = "factual", watch = "Twice is a fact; “terrible” is an opinion."), PracticeQuestion(prompt = "State your request clearly.", expected = listOf("I'd like a replacement or a refund."), focus = "the request", watch = "Two options make agreement easier."), PracticeQuestion(prompt = "Show it's a pattern. (second time)", expected = listOf("This is the second time it's happened."), focus = "the pattern", watch = "Second time strengthens the case."), PracticeQuestion(prompt = "Hand the problem to them.", expected = listOf("What can you do about it?"), focus = "pass the ball", watch = "The question puts them on the hook, politely."))), exercises = listOf(Exercise(id = "en-foundations-telling-problems-e1", kind = "choice", prompt = "I'd like ___ refund, please.", options = listOf("a", "an", "some", "the my"), answers = listOf("a"), explain = "a refund — consonant sound."), Exercise(id = "en-foundations-telling-problems-e2", kind = "gap", prompt = "The engine ___ ___ three times. (stop, past)", options = listOf(), answers = listOf("stopped"), explain = "stop → stopped."), Exercise(id = "en-foundations-telling-problems-e3", kind = "order", prompt = "State your request.", options = listOf(), answers = listOf("Id like a replacement or a refund"), explain = "I'd like + option or option."), Exercise(id = "en-foundations-telling-problems-e4", kind = "written", prompt = "Open a complaint: you bought a phone last week.", options = listOf(), answers = listOf("i bought a phone last week", "i bought this phone last week"), explain = "Context: what, when.")), skills = listOf("function:solve-problems", "grammar:past-simple-regular", "grammar:connectors", "vocab:social-expressions"), canDo = listOf("solve-everyday-problems"), prerequisites = listOf("grammar:past-simple-regular"))))
