object EnFoundationsViewpoints {
    val unit = CourseUnit(id = "en-foundations-viewpoints", title = "Viewpoints", subtitle = "Argue, report, imagine", level = "B2", themes = listOf(ConversationTheme("debate-club", "Debate night", "Take a side", "person.3", "Course", "You debate a topical question: state your position, imagine alternatives, report what the data says.", 0),
                ConversationTheme("negotiation-table", "The negotiation", "Find the middle", "scale.3d", "Course", "You negotiate a work arrangement: conditions, consequences and a deal both sides can accept.", 1)), lessons = listOf(    Lesson(id = "en-foundations-viewpoints-second-conditional", title = "Second conditional", goal = "Imagine unreal presents and alternatives with if + past, would + verb.", intro = LessonIntro(explanation = listOf("Unreal presents use if + past simple, would + verb: “If I had more time, I would learn the piano.” The time is now/forward — the past form only marks unreality.", "Questions: “What would you do if you lost your job?” I'd = I would.", "Softer advice uses would in the result: “If I were you, I'd negotiate.” Note the fixed phrase If I were you."), examples = listOf(ExampleLine(text = "If I won the lottery, I would travel for a year.", meaning = "An unreal present."), ExampleLine(text = "If I were you, I'd ask for a raise.", meaning = "Advice with were."), ExampleLine(text = "Would you move abroad if you got the chance?", meaning = "Question form."), ExampleLine(text = "I wouldn't say that if I weren't sure.", meaning = "Negative on both sides."), ExampleLine(text = "If we had a bigger budget, we could hire help.", meaning = "could = would be able to."), ExampleLine(text = "Compare: “If it rains, we'll stay” (real) vs “If it rained, we'd stay” (unlikely).", meaning = "First vs second conditional."))), expressions = listOf(TargetExpression(text = "If + past, would + verb", meaning = "Unreal present.", note = "If I had time, I would cook."), TargetExpression(text = "If I were you, I'd …", meaning = "The advice formula.", note = "were, not was, in formal English."), TargetExpression(text = "What would you do if …?", meaning = "The hypothetical question.", note = "Perfect for debates."), TargetExpression(text = "I'd never …", meaning = "A firm unreal negative.", note = "I'd never lie to a client."), TargetExpression(text = "could / 