    Lesson(id = "en-foundations-viewpoints-negotiation", title = "Negotiating", goal = "Negotiate politely: propose conditions, concede ground and close a deal.", intro = LessonIntro(explanation = listOf("Proposals soften with could/would: “Could we possibly move the deadline?” “Would it help if I took the night shift?”", "Concede with a condition: “That works if…”, “As long as…, I'm happy to…”. Push back without conflict: “I see your point, however…”", "Close: “Shall we say…?”, “So we agree on…”, “I think we have a deal.”"), examples = listOf(ExampleLine(text = "Could we possibly start at ten?", meaning = "A softened proposal."), ExampleLine(text = "That works if the report arrives on Thursday.", meaning = "A conditional yes."), ExampleLine(text = "As long as I keep Fridays free, I'm happy to travel.", meaning = "As long as = condition."), ExampleLine(text = "I see your point; however, the budget is fixed.", meaning = "Pushback without conflict."), ExampleLine(text = "What if we split the difference?", meaning = "A middle-ground move."), ExampleLine(text = "Shall we say thirty percent?", meaning = "The closing formula."))), expressions = listOf(TargetExpression(text = "Could we possibly …?", meaning = "A polite proposal.", note = "possibly = extra soft."), TargetExpression(text = "That works if …", meaning = "Yes, with a condition.", note = "Condition first, then agreement."), TargetExpression(text = "as long as …", meaning = "Your red lines.", note = "As long as costs stay under X."), TargetExpression(text = "I see your point; however …", meaning = "Respectful disagreement.", note = "Acknowledge, then contrast."), TargetExpression(text = "What if we …?", meaning = "Offer a middle path.", note = "What if we split the costs?"), TargetExpression(text = "Shall we say …?", meaning = "Close the deal.", note = "Numbers finish negotiations.")), situation = "You negotiate a remote-work arrangement with your manager: propose, concede, push back once and close with a concrete deal.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Politely propose a later start time.", expected = listOf("Could we possibly start at ten?", "Would it be possible to start later?"), focus = "softened proposal", watch = "Bare commands sound abrupt in negotiation; use could/would."), PracticeQuestion(prompt = "Accept travelling, with one condition. (as long as)", expected = listOf("That works as long as I keep Fridays free.", "As long as costs are covered, I'm happy to travel."), focus = "as long as", watch = "as long as + present simple for your condition."), PracticeQuestion(prompt = "Disagree respectfully with a tight deadline.", expected = listOf("I see your point; however, the deadline is too tight.", "I understand, however we need two more days."), focus = "acknowledge + however", watch = "Acknowledge first — however lands softer after agreement words."), PracticeQuestion(prompt = "Offer a middle ground on price.", expected = listOf("What if we split the difference?", "What if we meet in the middle?"), focus = "what if", watch = "what if + present simple proposes the path."), PracticeQuestion(prompt = "Close the deal on a number. (thirty percent)", expected = listOf("Shall we say thirty percent?"), focus = "closing", watch = "shall we say + the final number."), PracticeQuestion(prompt = "State the deal you both reached.", expected = listOf("So we agree on: remote Mondays and a Thursday report.", "So we agree: I travel twice a month, you cover the costs."), focus = "summarising", watch = "Good negotiators summarise: “So we agree on…”."))), exercises = listOf(Exercise(id = "en-foundations-viewpoints-negotiation-e1", kind = "choice", prompt = "___ we possibly move the meeting to Thursday?", options = listOf("Could", "Must", "Will", "Should"), answers = listOf("Could"), explain = "Could we possibly…? is the softest proposal."), Exercise(id = "en-foundations-viewpoints-negotiation-e2", kind = "gap", prompt = "That works ___ ___ as the budget is approved. (2 words: condition)", options = listOf(), answers = listOf("as long", "so long"), explain = "as long as / so long as = siempre que."), Exercise(id = "en-foundations-viewpoints-negotiation-e3", kind = "order", prompt = "Respectfully disagree.", options = listOf(), answers = listOf("I see your point however the budget is fixed"), explain = "Acknowledge, then contrast."), Exercise(id = "en-foundations-viewpoints-negotiation-e4", kind = "written", prompt = "Close a deal at ten percent.", options = listOf(), answers = listOf("shall we say ten percent", "shall we say 10 percent", "shall we say 10%"), explain = "Shall we say + number closes it.")), skills = listOf("function:negotiate", "grammar:second-conditional", "grammar:connectors", "speaking:negotiate", "vocab:work"), canDo = listOf("solve-everyday-problems"), prerequisites = listOf("grammar:connectors", "grammar:modal-should"))))
}

object EnFoundationsMedia {
    val unit = CourseUnit(id = "en-foundations-media", title = "Media & argument", subtitle = "News, claims, debate", level = "B2", themes = listOf(ConversationTheme("editorial-meeting", "The editorial meeting", "What's the story?", "newspaper", "Course", "You pitch a story: what happened, why now, why anyone should care — in ninety seconds.", 0),
                ConversationTheme("letters-page", "The letters page", "Claim and counter", "envelope", "Course", "You respond to an opinion piece: concede a point, then dismantle it politely.", 1)), lessons = listOf(    Lesson(id = "en-foundations-media-news-language", title = "The language of news", goal = "Read and report news: passive reporting, headline grammar and attribution.", intro = LessonIntro(explanation = listOf("Headlines drop words: “Bridge reopened after repairs” = The bridge has been reopened. Learn to expand them.", "Attribution protects reporters: “It is believed that…”, “according to sources”. Nobody said it; it is said.", "The passive rules news because events matter more than doers: “Measures were announced” — by whom, later, maybe."), examples = listOf(ExampleLine(text = "Bridge reopened after repairs.", meaning = "A headline: expand to a full sentence."), ExampleLine(text = "It is believed that costs will fall.", meaning = "Attribution without a source."), ExampleLine(text = "Measures were announced on Tuesday.", meaning = "Event-focused passive."), ExampleLine(text = "The minister is thought to favour delays.", meaning = "is thought to + verb."), ExampleLine(text = "According to the report, numbers fell.", meaning = "according to = the source."))), expressions = listOf(TargetExpression(text = "… was/were + participle", meaning = "The reporting backbone.", note = "The road was closed."), TargetExpression(text = "It is said/believed that …", meaning = "Source-free attribution.", note = "It is believed that…"), TargetExpression(text = "is thought to + verb", meaning = "Report others' claims.", note = "He is thought to have left."), TargetExpression(text = "according to …", meaning = "Name the source.", note = "according to the report."), TargetExpression(text = "are expected to + verb", meaning = "Predictions from others.", note = "Talks are expected to continue."), TargetExpression(text = "Headline → sentence", meaning = "Expand dropped words.", note = "“Man rescues cat” = A man has rescued a cat.")), situation = "You brief a colleague on this morning's news: expand three headlines into full sentences and attribute every claim you can't verify.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Expand the headline: “Bridge reopened”.", expected = listOf("The bridge has been reopened."), focus = "headline → sentence", watch = "Add the dropped words: has been + participle."), PracticeQuestion(prompt = "Report unverified costs. (it / believe)", expected = listOf("It is believed that costs will fall."), focus = "attribution", watch = "It is believed protects the speaker."), PracticeQuestion(prompt = "Attribute a number to its source. (report)", expected = listOf("According to the report, sales fell by 10%."), focus = "according to", watch = "according to names the source."), PracticeQuestion(prompt = "Report what people think about the minister. (thought / delay)", expected = listOf("The minister is thought to favour delays."), focus = "is thought to", watch = "is thought to have + participle for past acts."), PracticeQuestion(prompt = "Report expected talks.", expected = listOf("Talks are expected to continue."), focus = "are expected to", watch = "Passive prediction: nobody predicts, it is expected."))), exercises = listOf(Exercise(id = "en-foundations-media-news-language-e1", kind = "choice", prompt = "The road ___ closed since March.", options = listOf("has been", "is been", "was being", "had being"), answers = listOf("has been"), explain = "Present perfect passive: has been closed."), Exercise(id = "en-foundations-media-news-language-e2", kind = "gap", prompt = "It is ___ that costs will fall. (believe)", options = listOf(), answers = listOf("believed"), explain = "It is believed that…"), Exercise(id = "en-foundations-media-news-language-e3", kind = "order", prompt = "Expand the headline.", options = listOf(), answers = listOf("The bridge has been reopened after repairs"), explain = "has been + participle + detail."), Exercise(id = "en-foundations-media-news-language-e4", kind = "written", prompt = "Attribute the fall to the report.", options = listOf(), answers = listOf("according to the report sales fell", "sales fell according to the report"), explain = "according to + source.")), skills = listOf("grammar:passive-intro", "grammar:present-perfect", "grammar:relative-clauses", "function:express-opinion"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:past-simple-regular")),
    Lesson(id = "en-foundations-media-opinion-pieces", title = "Opinion pieces", goal = "Build a written argument: claim, support, concession, rebuttal.", intro = LessonIntro(explanation = listOf("The four-move structure: claim (“Remote work is here to stay”), support (evidence), concession (“Admittedly, not every job…”), rebuttal (“But the trend is clear”).", "Concession words buy credibility: admittedly, granted, while it's true that… — you look fair before you disagree.", "Endings circle back: “For all its flaws, the evidence points one way.” Repeat the claim, changed by everything before it."), examples = listOf(ExampleLine(text = "Remote work is here to stay.", meaning = "The claim — short and bare."), ExampleLine(text = "Studies show a 13% productivity rise.", meaning = "Support with numbers."), ExampleLine(text = "Admittedly, not every job can be remote.", meaning = "The concession."), ExampleLine(text = "But the trend is unmistakable.", meaning = "The rebuttal."), ExampleLine(text = "For all its flaws, the evidence points one way.", meaning = "The circular close."))), expressions = listOf(TargetExpression(text = "The claim: …", meaning = "State it bare.", note = "One sentence, no hedging yet."), TargetExpression(text = "Support: studies show / data suggests", meaning = "Bring evidence.", note = "Numbers beat adjectives."), TargetExpression(text = "Admittedly, … / Granted, …", meaning = "Concede fairly.", note = "Fairness buys trust."), TargetExpression(text = "But / However, …", meaning = "Rebut.", note = "But the core point stands."), TargetExpression(text = "For all its flaws, …", meaning = "Circle back.", note = "The claim, transformed.")), situation = "You draft a 120-word opinion piece on four-day weeks: claim, one piece of support, one fair concession, one rebuttal, one close.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "State your claim about four-day weeks. (here to stay)", expected = listOf("Four-day weeks are here to stay."), focus = "the claim", watch = "Short. Bare. Debatable."), PracticeQuestion(prompt = "Add one number as support.", expected = listOf("Trials report a 13% productivity rise."), focus = "support", watch = "A number does the arguing for you."), PracticeQuestion(prompt = "Concede fairly: not every job. (admittedly)", expected = listOf("Admittedly, not every job can be done remotely."), focus = "the concession", watch = "admittedly + the strongest counter-case."), PracticeQuestion(prompt = "Rebut the concession. (but / trend)", expected = listOf("But the trend is unmistakable."), focus = "the rebuttal", watch = "However also works — but is punchier."), PracticeQuestion(prompt = "Close by circling back.", expected = listOf("For all its flaws, the evidence points one way."), focus = "the close", watch = "The claim returns, stronger."))), exercises = listOf(Exercise(id = "en-foundations-media-opinion-pieces-e1", kind = "choice", prompt = "___ not every job can be remote, the trend is clear.", options = listOf("Admittedly", "Because", "So", "Unless"), answers = listOf("Admittedly"), explain = "admittedly concedes before rebutting."), Exercise(id = "en-foundations-media-opinion-pieces-e2", kind = "gap", prompt = "Studies ___ a 13% productivity rise. (show)", options = listOf(), answers = listOf("show"), explain = "studies show + number."), Exercise(id = "en-foundations-media-opinion-pieces-e3", kind = "order", prompt = "The circular close.", options = listOf(), answers = listOf("For all its flaws the evidence points one way"), explain = "for all its flaws + claim."), Exercise(id = "en-foundations-media-opinion-pieces-e4", kind = "written", prompt = "State your claim about four-day weeks.", options = listOf(), answers = listOf("four-day weeks are here to stay", "four day weeks are here to stay"), explain = "Short, bare, debatable.")), skills = listOf("writing:argument", "grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "vocab:work"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:first-conditional"))))
}

object EnFoundationsNuance {
    val unit = CourseUnit(id = "en-foundations-nuance", title = "Nuance & register", subtitle = "Say it the better way", level = "C1", themes = listOf(ConversationTheme("formal-swap", "The register swap", "Same idea, different room", "arrow.triangle.swap", "Course", "You rephrase the same message for different audiences: a friend, a client, a complaint, a keynote.", 0),
                ConversationTheme("idiom-lab", "The idiom lab", "Sound natural", "text.bubble", "Course", "You upgrade literal sentences with natural chunks and idioms — carefully, one at a time.", 1)), lessons = listOf(    Lesson(id = "en-foundations-nuance-register", title = "Register: formal vs informal", goal = "Rephrase the same message for different audiences and levels of formality.", intro = LessonIntro(explanation = listOf("Informal leans on phrasal verbs and contractions: “We'll set up a call.” Formal prefers single verbs: “We will arrange a call.”", "Requests climb the ladder of politeness: “Send it” → “Can you send it?” → “Could you send it?” → “I would be grateful if you could send it.”", "Written formality also changes vocabulary: get → receive, help → assistance, but → however, kids → children."), examples = listOf(ExampleLine(text = "We'll set up a call tomorrow. (informal)", meaning = "Phrasal + contraction."), ExampleLine(text = "We will arrange a call tomorrow. (formal)", meaning = "Single verb, no contraction."), ExampleLine(text = "Can you send the invoice?", meaning = "Neutral request."), ExampleLine(text = "I would be grateful if you could send the invoice.", meaning = "Formal request."), ExampleLine(text = "Sorry, that doesn't work for me. (informal)", meaning = "Soft refusal."), ExampleLine(text = "Unfortunately, that arrangement is not feasible. (formal)", meaning = "Formal refusal."))), expressions = listOf(TargetExpression(text = "set up vs arrange", meaning = "Phrasal informal, single verb formal.", note = "Same meaning, different room."), TargetExpression(text = "I would be grateful if you could …", meaning = "The formal request.", note = "Emails, clients, institutions."), TargetExpression(text = "Unfortunately, … is not feasible.", meaning = "The formal no.", note = "feasible = possible/viable."), TargetExpression(text = "get → receive", meaning = "Upgrade everyday verbs.", note = "We received your message."), TargetExpression(text = "kids → children", meaning = "Register-sensitive nouns.", note = "Formal writing avoids kids."), TargetExpression(text = "Sorry about that → I apologise for the inconvenience.", meaning = "Apology ladder.", note = "Match the damage.")), situation = "One message, three rooms: say the same cancellation to a friend, then to a client, then in a formal complaint — and feel the register move.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Say informally that you'll organise a call.", expected = listOf("I'll set up a call.", "We'll set up a call."), focus = "informal register", watch = "Phrasal verbs + contractions are the informal markers."), PracticeQuestion(prompt = "Now say it formally. (arrange)", expected = listOf("We will arrange a call.", "I will arrange a call."), focus = "formal register", watch = "Single verb, no contraction."), PracticeQuestion(prompt = "Make this formal: “Can you send the report?”", expected = listOf("I would be grateful if you could send the report.", "Could you please send the report?"), focus = "request ladder", watch = "would be grateful is the top rung for email."), PracticeQuestion(prompt = "Refuse formally: the arrangement doesn't work.", expected = listOf("Unfortunately, that arrangement is not feasible.", "Unfortunately, we are unable to accept the arrangement."), focus = "formal refusal", watch = "Formal refusals start with unfortunately and avoid contractions."), PracticeQuestion(prompt = "Make this formal: “Sorry about the delay.”", expected = listOf("I apologise for the delay.", "Please accept my apologies for the delay."), focus = "apology ladder", watch = "Match formality to the damage."), PracticeQuestion(prompt = "Spot the register: “We received your message” vs “We got your message”.", expected = listOf("we received your message is formal", "we got your message is informal"), focus = "get vs receive", watch = "Same meaning; receive belongs to formal writing."))), exercises = listOf(Exercise(id = "en-foundations-nuance-register-e1", kind = "choice", prompt = "Which is the FORMAL request?", options = listOf("I would be grateful if you could reply.", "Can you reply?", "Reply please.", "Reply when you can!"), answers = listOf("I would be grateful if you could reply."), explain = "would be grateful marks formal register."), Exercise(id = "en-foundations-nuance-register-e2", kind = "gap", prompt = "Formal single verb: We will ___ a meeting. (phrasal: set up)", options = listOf(), answers = listOf("arrange", "organise", "organize"), explain = "set up → arrange/organise."), Exercise(id = "en-foundations-nuance-register-e3", kind = "order", prompt = "Formal apology.", options = listOf(), answers = listOf("I apologise for the inconvenience"), explain = "The formal apology formula."), Exercise(id = "en-foundations-nuance-register-e4", kind = "written", prompt = "Make it formal: “We got your email.”", options = listOf(), answers = listOf("we received your email", "we have received your email"), explain = "get → receive.")), skills = listOf("vocab:social-expressions", "function:negotiate", "writing:email", "function:talk-about-work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:connectors", "grammar:modal-must-have-to")),
    Lesson(id = "en-foundations-nuance-chunks", title = "Natural chunks", goal = "Replace literal sentences with natural chunks and idioms — precisely, not decoratively.", intro = LessonIntro(explanation = listOf("Chunks are ready-made phrases native speakers reach for: “It depends.” “That makes sense.” “As far as I know…” “I'm not sure about that.”", "Idioms carry culture and risk: “It's a grey area” is safe and useful; rare or dated idioms can sound costume-y. One per conversation is plenty.", "Upgrading literal speech: “I don't decide yet” → “I'm still on the fence.” The chunk must match the meaning exactly."), examples = listOf(ExampleLine(text = "It depends on the weather.", meaning = "The universal answer chunk."), ExampleLine(text = "That makes sense.", meaning = "Accepting an explanation."), ExampleLine(text = "As far as I know, the flight is on time.", meaning = "Limited certainty."), ExampleLine(text = "I'm still on the fence.", meaning = "Undecided."), ExampleLine(text = "It's a bit of a grey area.", meaning = "Not clearly one thing or the other."), ExampleLine(text = "Let's play it by ear.", meaning = "Decide as things happen."))), expressions = listOf(TargetExpression(text = "It depends.", meaning = "Conditional answer.", note = "…on + factor: on the price."), TargetExpression(text = "That makes sense.", meaning = "Understanding confirmed.", note = "Never “it has sense”."), TargetExpression(text = "As far as I know, …", meaning = "Soften a claim.", note = "Knowledge may be incomplete."), TargetExpression(text = "I'm on the fence.", meaning = "No decision yet.", note = "Sitting between two options."), TargetExpression(text = "a grey area", meaning = "Unclear rules or meaning.", note = "The law here is a grey area."), TargetExpression(text = "play it by ear", meaning = "Improvise the plan.", note = "No fixed script.")), situation = "You coach a colleague before a difficult meeting: swap their literal lines for natural chunks — and decide which idioms to avoid.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Answer naturally when asked if remote work is better.", expected = listOf("It depends.", "It depends on the job."), focus = "it depends", watch = "“It depends of” — English takes on."), PracticeQuestion(prompt = "Confirm you understood the explanation.", expected = listOf("That makes sense."), focus = "makes sense", watch = "Never “it has sense” — the chunk is makes sense."), PracticeQuestion(prompt = "Soften a claim about tomorrow's schedule.", expected = listOf("As far as I know, it's free.", "As far as I know, the schedule hasn't changed."), focus = "limited certainty", watch = "The chunk admits your knowledge might be incomplete."), PracticeQuestion(prompt = "Say you haven't decided between the two offers.", expected = listOf("I'm still on the fence."), focus = "undecided", watch = "The fence sits between two options — that's the image."), PracticeQuestion(prompt = "Say the rule is unclear. (idiom)", expected = listOf("It's a bit of a grey area.", "It's a grey area."), focus = "grey area", watch = "grey (BrE) or gray (AmE) — both fine."), PracticeQuestion(prompt = "Say you'll decide as things happen. (idiom)", expected = listOf("Let's play it by ear.", "We'll play it by ear."), focus = "play it by ear", watch = "ear, not year — it comes from music."))), exercises = listOf(Exercise(id = "en-foundations-nuance-chunks-e1", kind = "choice", prompt = "Which chunk means “no decision yet”?", options = listOf("I'm on the fence.", "It's a grey area.", "It depends.", "That makes sense."), answers = listOf("I'm on the fence."), explain = "On the fence = between two options, undecided."), Exercise(id = "en-foundations-nuance-chunks-e2", kind = "gap", prompt = "That ___ sense — thanks for explaining.", options = listOf(), answers = listOf("makes"), explain = "makes sense, never has sense."), Exercise(id = "en-foundations-nuance-chunks-e3", kind = "order", prompt = "Soften your claim about the flight.", options = listOf(), answers = listOf("As far as I know the flight is on time"), explain = "as far as I know + the claim."), Exercise(id = "en-foundations-nuance-chunks-e4", kind = "written", prompt = "Fix: “It depends of the price.”", options = listOf(), answers = listOf("it depends on the price"), explain = "depend on + factor.")), skills = listOf("vocab:social-expressions", "function:express-opinion", "speaking:sustained-conversation", "writing:argument"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:connectors")),
    Lesson(id = "en-foundations-nuance-hedging", title = "Hedging & precision", goal = "Fine-tune opinions: soften, intensify and qualify like a confident speaker.", intro = LessonIntro(explanation = listOf("Hedging protects accuracy: “tends to”, “to some extent”, “arguably”, “in most cases”. Strong claims need strong evidence — otherwise hedge.", "Intensifiers scale: slightly < rather < considerably < far. “Far more efficient” is stronger than “slightly more efficient”.", "Precision beats intensity: “a threefold increase” > “a lot more”. Numbers, examples and scope (“in this case”) make opinions defensible."), examples = listOf(ExampleLine(text = "This approach tends to work better.", meaning = "A hedged claim."), ExampleLine(text = "To some extent, I agree.", meaning = "Partial agreement."), ExampleLine(text = "Arguably, it's the best option on the table.", meaning = "Opinion with room."), ExampleLine(text = "The new version is far more stable.", meaning = "A strong, clear difference."), ExampleLine(text = "Costs fell by roughly a third.", meaning = "Precision with a number."), ExampleLine(text = "In this specific case, I'd wait.", meaning = "Scope limiting."))), expressions = listOf(TargetExpression(text = "tends to + verb", meaning = "General pattern, not law.", note = "Prices tend to rise in summer."), TargetExpression(text = "to some extent / to a degree", meaning = "Partial truth.", note = "Agreement with reservations."), TargetExpression(text = "arguably", meaning = "Defensible opinion.", note = "Arguably the best paella in town."), TargetExpression(text = "slightly / rather / considerably / far", meaning = "The intensity scale.", note = "far > considerably > rather > slightly."), TargetExpression(text = "by roughly a third", meaning = "Approximate precision.", note = "roughly, about, approximately."), TargetExpression(text = "in this specific case", meaning = "Limit the scope.", note = "No universal claims.")), situation = "You present an opinion to a skeptical audience: claim, hedge, quantify and limit scope — then defend it once challenged.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Hedge a claim about remote productivity.", expected = listOf("Remote work tends to increase productivity.", "It tends to work better for focused tasks."), focus = "tends to", watch = "tends to + base verb softens the pattern without killing it."), PracticeQuestion(prompt = "Agree, but only partly.", expected = listOf("To some extent, I agree.", "I agree to a degree."), focus = "partial agreement", watch = "The quantifier keeps the disagreement alive."), PracticeQuestion(prompt = "Give a defensible superlative opinion about a restaurant.", expected = listOf("Arguably, it's the best ramen in the city."), focus = "arguably", watch = "arguably signals: I can defend this."), PracticeQuestion(prompt = "Rank the intensifiers: slightly / far / rather. (weakest to strongest)", expected = listOf("slightly, rather, far"), focus = "intensity scale", watch = "slightly < rather < considerably < far."), PracticeQuestion(prompt = "Be precise about a cost drop: from 90 to 60. (roughly)", expected = listOf("Costs fell by roughly a third."), focus = "approximate numbers", watch = "roughly + fraction beats “a lot less”."), PracticeQuestion(prompt = "Limit your advice so it isn't universal.", expected = listOf("In this specific case, I'd wait.", "In this case, I'd wait before deciding."), focus = "scope", watch = "in this case protects the advice from other contexts."))), exercises = listOf(Exercise(id = "en-foundations-nuance-hedging-e1", kind = "choice", prompt = "Which claim is the most hedged?", options = listOf("It tends to work better.", "It always works.", "It works.", "It never fails."), answers = listOf("It tends to work better."), explain = "tends to is the hedged pattern claim."), Exercise(id = "en-foundations-nuance-hedging-e2", kind = "gap", prompt = "The new engine is ___ more efficient. (strongest intensifier)", options = listOf(), answers = listOf("far", "considerably"), explain = "far (or considerably) is stronger than slightly."), Exercise(id = "en-foundations-nuance-hedging-e3", kind = "order", prompt = "Give a partial agreement.", options = listOf(), answers = listOf("To some extent I agree"), explain = "to some extent + I agree."), Exercise(id = "en-foundations-nuance-hedging-e4", kind = "written", prompt = "Fix: “It depends of the context.”", options = listOf(), answers = listOf("it depends on the context"), explain = "depend on — the preposition is on.")), skills = listOf("grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "writing:argument"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:connectors")),
    Lesson(id = "en-foundations-nuance-academic", title = "The academic voice", goal = "State positions in academic and professional registers: impersonal, evidenced, measured.", intro = LessonIntro(explanation = listOf("The academic voice removes the “I”: “This paper argues that…”, “The data suggests…”, “It has been observed that…”. The claim carries the sentence, not the person.", "Evidence verbs scale certainty: demonstrate > suggest > indicate > appear to. Choose the verb that matches the strength of your data.", "Structure is visible: “First… Second… Taken together, these findings…” — the reader should always know where they are."), examples = listOf(ExampleLine(text = "This paper argues that hybrid models outperform either extreme.", meaning = "The thesis sentence."), ExampleLine(text = "The data suggests a modest effect.", meaning = "suggests = careful."), ExampleLine(text = "The results demonstrate a clear correlation.", meaning = "demonstrate = strong evidence."), ExampleLine(text = "It has been observed that remote teams innovate differently.", meaning = "Impersonal passive reporting."), ExampleLine(text = "Taken together, these findings point to a structural cause.", meaning = "Synthesis marker."), ExampleLine(text = "Further research is needed to confirm the effect.", meaning = "The classic closing hedge."))), expressions = listOf(TargetExpression(text = "This paper/chapter argues that …", meaning = "State the thesis.", note = "argue = defend a position."), TargetExpression(text = "The data suggests / demonstrates …", meaning = "Certainty scaled to evidence.", note = "Choose the honest verb."), TargetExpression(text = "It has been observed that …", meaning = "Impersonal reporting.", note = "Passive keeps the I out."), TargetExpression(text = "Taken together, …", meaning = "Synthesise several points.", note = "Ends the middle, opens the close."), TargetExpression(text = "Further research is needed …", meaning = "The honest limit.", note = "Every study ends here."), TargetExpression(text = "with respect to / regarding", meaning = "Formal topic shifts.", note = "Regarding costs, the picture differs.")), situation = "You present a controversial finding to a skeptical panel: thesis, evidence verbs that match your data, visible structure and an honest limit.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "State your thesis formally. (hybrid models outperform)", expected = listOf("This paper argues that hybrid models outperform either extreme."), focus = "thesis", watch = "argues that + full clause — the position, not the topic."), PracticeQuestion(prompt = "Your evidence is moderate. Choose the verb. (the data / a modest effect)", expected = listOf("The data suggests a modest effect."), focus = "scaled verbs", watch = "demonstrates would overclaim; suggests is honest."), PracticeQuestion(prompt = "Your evidence is strong. Choose the verb. (clear correlation)", expected = listOf("The results demonstrate a clear correlation."), focus = "scaled verbs", watch = "With strong data, demonstrates is the honest choice."), PracticeQuestion(prompt = "Report an observation without saying who observed it.", expected = listOf("It has been observed that remote teams innovate differently."), focus = "impersonal passive", watch = "It + has been + participle keeps the voice out."), PracticeQuestion(prompt = "Synthesise two findings into one conclusion.", expected = listOf("Taken together, these findings point to a structural cause."), focus = "synthesis", watch = "Taken together announces the synthesis."), PracticeQuestion(prompt = "Close with the honest limit of the study.", expected = listOf("Further research is needed to confirm the effect."), focus = "the limit", watch = "Every credible study admits its edge."))), exercises = listOf(Exercise(id = "en-foundations-nuance-academic-e1", kind = "choice", prompt = "The data ___ a modest effect. (moderate evidence)", options = listOf("suggests", "demonstrates", "proves", "ignores"), answers = listOf("suggests"), explain = "Moderate evidence takes suggests, not demonstrates."), Exercise(id = "en-foundations-nuance-academic-e2", kind = "gap", prompt = "It has ___ observed that remote teams innovate differently.", options = listOf(), answers = listOf("been"), explain = "Impersonal passive: has been + participle."), Exercise(id = "en-foundations-nuance-academic-e3", kind = "order", prompt = "State the thesis.", options = listOf(), answers = listOf("This paper argues that hybrid models outperform either extreme"), explain = "This paper argues that + claim."), Exercise(id = "en-foundations-nuance-academic-e4", kind = "written", prompt = "Close the study honestly.", options = listOf(), answers = listOf("further research is needed to confirm the effect", "further research is needed"), explain = "The classic honest close.")), skills = listOf("writing:argument", "grammar:passive-intro", "function:express-opinion", "function:talk-about-work", "grammar:connectors"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:passive-intro", "grammar:connectors")),
    Lesson(id = "en-foundations-nuance-presenting", title = "Presenting with confidence", goal = "Signpost a talk, land key points and handle questions without losing your footing.", intro = LessonIntro(explanation = listOf("Signposts keep audiences aboard: “I'll start with…”, “That brings me to…”, “So, to sum up…”. Say where you are; nobody resents a map.", "Land key points with a pause and a restatement: “The one thing to remember is this.” Silence sells importance.", "Hard questions get a frame: “That's exactly the point — my answer is twofold.” Buying structure, not stalling."), examples = listOf(ExampleLine(text = "I'll start with why this matters.", meaning = "The opening signpost."), ExampleLine(text = "That brings me to the results.", meaning = "The transition."), ExampleLine(text = "The one thing to remember is this.", meaning = "Point-landing phrase."), ExampleLine(text = "So, to sum up: three findings, one conclusion.", meaning = "The summary signpost."), ExampleLine(text = "That's exactly the point — and my answer is twofold.", meaning = "Handling the hard question."))), expressions = listOf(TargetExpression(text = "I'll start with …", meaning = "Open the map.", note = "I'll start with the problem."), TargetExpression(text = "That brings me to …", meaning = "Transition.", note = "…to the second point."), TargetExpression(text = "The one thing to remember is …", meaning = "Land the point.", note = "Then pause. Let it sit."), TargetExpression(text = "So, to sum up …", meaning = "Signal the close.", note = "Repeat the three parts."), TargetExpression(text = "That's exactly the point.", meaning = "Own the hard question.", note = "Then answer in two parts."), TargetExpression(text = "I'm glad you asked that.", meaning = "Buy a second, kindly.", note = "Use sparingly — overdone it's a cliché.")), situation = "You present a small project to a skeptical room: signpost the three parts, land one key sentence and survive two tough questions.", practice = LessonPrac