    val unit = CourseUnit(id = "en-tech-u1", title = "Shipping software", subtitle = "Standup, tickets, demos", level = "B1", themes = listOf(ConversationTheme("standup-scene", "The daily stand-up", "Yesterday, today, blocked", "clock.badge", "Course", "Ninety seconds each: what moved, what's next, what's stuck — and one honest blocker.", 0),
                ConversationTheme("demo-scene", "The demo", "Show, don't drown", "play.rectangle", "Course", "You demo a new feature to non-technical colleagues: what it does, why it matters, what's next.", 1)), lessons = listOf(    Lesson(id = "en-tech-u1-standup", title = "The stand-up", goal = "Report progress in three sentences: done, doing, blocked.", intro = LessonIntro(explanation = listOf("The stand-up spine: “Yesterday I finished X. Today I'm working on Y. I'm blocked on Z.” Past, present, blocker.", "Blockers name the thing and the person: “I'm blocked on the API — waiting on Marta's review.”", "Detail is for after: “Let's take that offline” = interesting, but not now."), examples = listOf(ExampleLine(text = "Yesterday I finished the login flow.", meaning = "Done: past simple."), ExampleLine(text = "Today I'm working on the API.", meaning = "Doing: continuous."), ExampleLine(text = "I'm blocked on Marta's review.", meaning = "The blocker + owner."), ExampleLine(text = "Let's take that offline.", meaning = "Not now, but noted."), ExampleLine(text = "No blockers from me.", meaning = "The clean report."))), expressions = listOf(TargetExpression(text = "finished X (yesterday)", meaning = "Done work.", note = "past simple."), TargetExpression(text = "I'm working on Y (today)", meaning = "Current work.", note = "present continuous."), TargetExpression(text = "I'm blocked on Z", meaning = "Name the blocker.", note = "on + the thing."), TargetExpression(text = "waiting on + person", meaning = "Who you need.", note = "waiting on Marta."), TargetExpression(text = "take it offline", meaning = "Park the detail.", note = "after the stand-up.")), situation = "Your three sentences: what you finished yesterday, what you're on today, and the one honest blocker — plus park one detail for later.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Report finished work. (the login flow)", expected = listOf("Yesterday I finished the login flow."), focus = 