    Lesson(id = "en-tech-u1-demo", title = "The demo", goal = "Demo a feature to non-technical colleagues: what, why, what's next.", intro = LessonIntro(explanation = listOf("Demo grammar: “Here you can see…”, “Watch what happens when I…”, “And that's it — three clicks instead of twenty.”", "Translate the tech: not “the API caches responses” but “it opens instantly, even offline”. Benefits, not architecture.", "Own the bugs before they're found: “Export is still slow — that's next on the list.”"), examples = listOf(ExampleLine(text = "Here you can see the new dashboard.", meaning = "Point at the screen."), ExampleLine(text = "Watch what happens when I click save.", meaning = "The live moment."), ExampleLine(text = "Three clicks instead of twenty.", meaning = "The benefit, counted."), ExampleLine(text = "Export is still slow — that's next.", meaning = "Own the known bug."), ExampleLine(text = "That's the demo — questions welcome.", meaning = "The close."))), expressions = listOf(TargetExpression(text = "Here you can see …", meaning = "Show the screen.", note = "…the new dashboard."), TargetExpression(text = "Watch what happens when …", meaning = "The live moment.", note = "…I click save."), TargetExpression(text = "X instead of Y", meaning = "Count the win.", note = "Three clicks instead of twenty."), TargetExpression(text = "… — that's next on the list", meaning = "Own the flaw.", note = "Known bug, known plan."), TargetExpression(text = "Questions welcome.", meaning = "The open close.", note = "Then stop talking.")), situation = "Demo the new offline mode to the sales team: show the moment, count the benefit, own the known bug and invite questions.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Show the new screen.", expected = listOf("Here you can see the new offline mode."), focus = "here you can see", watch = "Point while you name it."), PracticeQuestion(prompt = "Create the live moment. (click sync)", expected = listOf("Watch what happens when I click sync."), focus = "watch what happens", watch = "Then click. The pause builds it."), PracticeQuestion(prompt = "Count the benefit. (3 clicks vs 20)", expected = listOf("Three clicks instead of twenty."), focus = "instead of", watch = "Numbers carry the benefit."), PracticeQuestion(prompt = "Own the known bug. (slow export)", expected = listOf("Export is still slow — that's next on the list."), focus = "own the bug", watch = "Say it before they find it."), PracticeQuestion(prompt = "Close and invite questions.", expected = listOf("That's the demo — questions welcome."), focus = "the open close", watch = "Then actually stop talking."))), exercises = listOf(Exercise(id = "en-tech-u1-demo-e1", kind = "choice", prompt = "Here you can ___ the new dashboard.", options = listOf("see", "watch", "look", "view"), answers = listOf("see"), explain = "Here you can see + thing."), Exercise(id = "en-tech-u1-demo-e2", kind = "gap", prompt = "___ what happens when I click sync.", options = listOf(), answers = listOf("watch"), explain = "Watch what happens when…"), Exercise(id = "en-tech-u1-demo-e3", kind = "order", prompt = "Count the benefit.", options = listOf(), answers = listOf("Three clicks instead of twenty"), explain = "X instead of Y."), Exercise(id = "en-tech-u1-demo-e4", kind = "written", prompt = "Own the slow export.", options = listOf(), answers = listOf("export is still slow thats next on the list", "its still slow thats next"), explain = "Known bug, known plan.")), skills = listOf("function:talk-about-work", "grammar:present-continuous", "grammar:comparatives", "vocab:work", "speaking:sustained-conversation"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:comparatives")),
    Lesson(id = "en-tech-u1-tickets", title = "Tickets & bugs", goal = "Write and explain a bug report: steps, expected, actual — and a severity.", intro = LessonIntro(explanation = listOf("A bug report is a story with evidence: “Steps: open the app offline. Expected: cached data. Actual: a blank screen.”", "Severity is a scale, not a shout: blocker > critical > major > minor. A blocker means nobody can work.", "Reproduce before you report: “It happens every time on Android, but not on iOS.” The pattern is the clue."), examples = listOf(ExampleLine(text = "Steps: open the app offline.", meaning = "How to reproduce."), ExampleLine(text = "Expected: cached data appears.", meaning = "What should happen."), ExampleLine(text = "Actual: a blank screen.", meaning = "What really happens."), ExampleLine(text = "It's a blocker — nobody can log in.", meaning = "The severity."), ExampleLine(text = "It happens every time on Android.", meaning = "The pattern."))), expressions = listOf(TargetExpression(text = "Steps to reproduce", meaning = "The recipe.", note = "Numbered, exact, short."), TargetExpression(text = "Expected vs actual", meaning = "The gap is the bug.", note = "Both, always."), TargetExpression(text = "blocker / critical / major / minor", meaning = "The severity scale.", note = "blocker stops the team."), TargetExpression(text = "every time / intermittently", meaning = "The pattern.", note = "intermittent = a veces."), TargetExpression(text = "I'll take a look today.", meaning = "The pickup.", note = "Own it or route it.")), situation = "A colleague reports the app eats typed notes offline: write the report as steps, expected, actual, mark the severity and pick it up.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Give the steps to reproduce. (open offline, type, close)", expected = listOf("Steps: open the app offline, type a note and close it."), focus = "steps", watch = "Numbered, exact, short."), PracticeQuestion(prompt = "Say expected vs actual. (note saved vs note lost)", expected = listOf("Expected: the note is saved. Actual: the note is lost."), focus = "the gap", watch = "Both halves — the gap is the bug."), PracticeQuestion(prompt = "Set the severity if nobody loses data. (major)", expected = listOf("It's a major, not a blocker — no data loss for most users."), focus = "severity", watch = "A blocker stops everyone; a major hurts some."), PracticeQuestion(prompt = "Pick it up.", expected = listOf("I'll take a look today."), focus = "pickup", watch = "Own it or route it to the owner."), PracticeQuestion(prompt = "Say how often the bug happens. (every time, Android)", expected = listOf("It happens every time on Android."), focus = "the pattern", watch = "The pattern is the clue to the cause."))), exercises = listOf(Exercise(id = "en-tech-u1-tickets-e1", kind = "choice", prompt = "Expected: the note is saved. ___: the note is lost.", options = listOf("Actual", "Usually", "Maybe", "Blocked"), answers = listOf("Actual"), explain = "Expected vs actual — the gap is the bug."), Exercise(id = "en-tech-u1-tickets-e2", kind = "gap", prompt = "Nobody can log in — it's a ___. (severidad máxima)", options = listOf(), answers = listOf("blocker"), explain = "A blocker stops the whole team."), Exercise(id = "en-tech-u1-tickets-e3", kind = "order", prompt = "Give the steps.", options = listOf(), answers = listOf("Open the app offline and type a note"), explain = "Numbered, exact, short."), Exercise(id = "en-tech-u1-tickets-e4", kind = "written", prompt = "Pick up the bug for today.", options = listOf(), answers = listOf("ill take a look today", "i will take a look today"), explain = "Own it or route it.")), skills = listOf("function:talk-about-work", "grammar:present-simple", "grammar:passive-intro", "vocab:work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:present-simple"))))
}

object EnWorkU1 {
    val unit = CourseUnit(id = "en-work-u1", title = "The working day", subtitle = "Meetings, emails, interviews", level = "B1", themes = listOf(ConversationTheme("monday-standup", "Monday stand-up", "Report your week", "clock", "Course", "You report progress in a stand-up: what you did, what you're doing, what's blocked.", 0),
                ConversationTheme("interview-roleplay", "The interview rehearsal", "Sell your experience", "person.badge.key", "Course", "A job interview rehearsal: present yourself, describe projects and answer the hard questions.", 1)), lessons = listOf(    Lesson(id = "en-work-u1-meetings", title = "In meetings", goal = "Report progress, ask for clarification and disagree politely in a meeting.", intro = LessonIntro(explanation = listOf("Structure beats improvisation: “Last week I finished X. This week I'm working on Y. I'm blocked on Z.”", "Clarify before you guess: “Sorry, could you clarify that?” “Just to make sure I understand…”", "Disagree with data, not people: “I see it slightly differently — the numbers show…”"), examples = listOf(ExampleLine(text = "Last week I finished the report.", meaning = "Done work, past simple."), ExampleLine(text = "This week I'm working on the budget.", meaning = "Current work, continuous."), ExampleLine(text = "I'm blocked on the approvals.", meaning = "Say what stops you."), ExampleLine(text = "Sorry, could you clarify that?", meaning = "Ask before assuming."), ExampleLine(text = "Just to make sure I understand: we ship on Friday?", meaning = "Confirm decisions."), ExampleLine(text = "I see it slightly differently — the data shows a drop.", meaning = "Data-based disagreement."))), expressions = listOf(TargetExpression(text = "Last week I finished …", meaning = "Report completed work.", note = "Past simple for done things."), TargetExpression(text = "This week I'm working on …", meaning = "Report current work.", note = "Continuous for in progress."), TargetExpression(text = "I'm blocked on …", meaning = "Name the blocker.", note = "Blocked on + thing, not person."), TargetExpression(text = "Could you clarify …?", meaning = "Ask precisely.", note = "Clarify + the specific point."), TargetExpression(text = "Just to make sure I understand, …", meaning = "Confirm decisions.", note = "Repeat the decision back."), TargetExpression(text = "I see it slightly differently.", meaning = "Soft disagreement.", note = "Then bring your data.")), situation = "Monday stand-up: report what you finished, what you're on and what's blocked; clarify one point and politely disagree with a plan once.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Report one thing you finished last week.", expected = listOf("Last week I finished <task>."), focus = "past simple reporting", watch = "“Last week I finish” — done work takes past simple."), PracticeQuestion(prompt = "Report what you're doing this week.", expected = listOf("This week I'm working on <task>."), focus = "current work", watch = "“This week I work on” sounds like a routine — use the continuous."), PracticeQuestion(prompt = "Tell the team what is blocking you. (approvals)", expected = listOf("I'm blocked on the approvals."), focus = "blockers", watch = "“I'm blocked by the approvals” also works; “I block on” doesn't."), PracticeQuestion(prompt = "Ask for clarification about the deadline.", expected = listOf("Sorry, could you clarify the deadline?", "Could you clarify when the deadline is?"), focus = "clarifying", watch = "Clarify + the thing: the deadline, the owner, the scope."), PracticeQuestion(prompt = "Confirm a decision you half-heard. (ship on Friday)", expected = listOf("Just to make sure I understand: we ship on Friday?"), focus = "confirming", watch = "Repeat the decision back as a question."), PracticeQuestion(prompt = "Disagree with a plan, politely, with data.", expected = listOf("I see it slightly differently — the data shows a drop.", "I see your point; however, the numbers say otherwise."), focus = "soft disagreement", watch = "Data first, tone soft: no “you're wrong”."))), exercises = listOf(Exercise(id = "en-work-u1-meetings-e1", kind = "choice", prompt = "Last week I ___ the report.", options = listOf("finished", "finish", "am finishing", "was finishing"), answers = listOf("finished"), explain = "Last week + past simple for completed work."), Exercise(id = "en-work-u1-meetings-e2", kind = "gap", prompt = "This week I'm ___ on the budget. (work)", options = listOf(), answers = listOf("working"), explain = "Current work: I'm working on."), Exercise(id = "en-work-u1-meetings-e3", kind = "order", prompt = "Ask for clarification politely.", options = listOf(), answers = listOf("Could you clarify that please"), explain = "Could you clarify + object (+ please)."), Exercise(id = "en-work-u1-meetings-e4", kind = "written", prompt = "Say what blocks you: the client's approval.", options = listOf(), answers = listOf("i'm blocked on the client's approval", "i am blocked on the approval", "i'm blocked by the client's approval"), explain = "blocked on/by + the thing.")), skills = listOf("function:talk-about-work", "grammar:past-simple-regular", "grammar:present-continuous", "function:make-requests", "speaking:sustained-conversation"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:present-simple", "grammar:present-continuous")),
    Lesson(id = "en-work-u1-emails", title = "Professional emails", goal = "Write short professional emails: request, confirm and follow up.", intro = LessonIntro(explanation = listOf("Email skeleton: greeting → purpose in line one → details → clear ask → sign-off. “Hi Marta, I'm writing about… Could you…? Thanks, Dan.”", "Requests: “Could you send… by Wednesday?” Deadlines make asks actionable. Follow-ups stay light: “Just following up on my email below.”", "Register: no contractions is safer in formal mail; “I would be grateful if…” is the formal ask."), examples = listOf(ExampleLine(text = "I'm writing about Thursday's meeting.", meaning = "Purpose in line one."), ExampleLine(text = "Could you send the figures by Wednesday?", meaning = "Request + deadline."), ExampleLine(text = "Please find the report attached.", meaning = "The attachment line."), ExampleLine(text = "Just following up on my email below.", meaning = "Light follow-up."), ExampleLine(text = "I would be grateful if you could confirm.", meaning = "Formal ask."), ExampleLine(text = "Best regards, Daniel", meaning = "Safe sign-off."))), expressions = listOf(TargetExpression(text = "I'm writing about / to ask about …", meaning = "Open with purpose.", note = "No weather talk in work mail."), TargetExpression(text = "Could you … by <day>?", meaning = "Request + deadline.", note = "A deadline is kindness."), TargetExpression(text = "Please find … attached.", meaning = "Point at the file.", note = "attached, not annexed."), TargetExpression(text = "Just following up on …", meaning = "Nudge without nagging.", note = "Light tone, clear reference."), TargetExpression(text = "I would be grateful if you could …", meaning = "The formal ask.", note = "Clients, institutions, bosses' bosses."), TargetExpression(text = "Best regards / Kind regards", meaning = "Safe sign-offs.", note = "Cheers is for friends only.")), situation = "You need numbers from a busy colleague: write the request, set a deadline, and then follow up two days later — politely.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Open an email about the quarterly figures.", expected = listOf("I'm writing about the quarterly figures."), focus = "purpose first", watch = "Line one states the topic — no “I hope you are well” padding needed."), PracticeQuestion(prompt = "Ask for the figures with a deadline. (Wednesday)", expected = listOf("Could you send the figures by Wednesday?"), focus = "request + deadline", watch = "by + day: “until Wednesday” is different — by is the limit."), PracticeQuestion(prompt = "Point to the report you attached.", expected = listOf("Please find the report attached."), focus = "attachment line", watch = "The fixed phrase is find … attached."), PracticeQuestion(prompt = "Follow up on an unanswered email, lightly.", expected = listOf("Just following up on my email below."), focus = "follow-up", watch = "“Why didn't you answer?” is never the opening."), PracticeQuestion(prompt = "Make the formal version of the ask. (confirm attendance)", expected = listOf("I would be grateful if you could confirm your attendance."), focus = "formal register", watch = "would be grateful + if you could."), PracticeQuestion(prompt = "Choose a safe sign-off for a client.", expected = listOf("Best regards.", "Kind regards."), focus = "sign-off", watch = "Cheers and hugs stay with friends."))), exercises = listOf(Exercise(id = "en-work-u1-emails-e1", kind = "choice", prompt = "I'm writing ___ the invoice.", options = listOf("about", "of", "for see", "on see"), answers = listOf("about"), explain = "I'm writing about + topic."), Exercise(id = "en-work-u1-emails-e2", kind = "gap", prompt = "Could you send it ___ Friday? (deadline)", options = listOf(), answers = listOf("by"), explain = "by Friday = not later than Friday."), Exercise(id = "en-work-u1-emails-e3", kind = "order", prompt = "The attachment line.", options = listOf(), answers = listOf("Please find the report attached"), explain = "find + file + attached."), Exercise(id = "en-work-u1-emails-e4", kind = "written", prompt = "Formal ask: confirm attendance.", options = listOf(), answers = listOf("i would be grateful if you could confirm your attendance", "i would be grateful if you could confirm attendance"), explain = "I would be grateful if you could…")), skills = listOf("writing:email", "function:make-requests", "grammar:modal-should", "vocab:work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:modal-should")),
    Lesson(id = "en-work-u1-interviews", title = "Job interviews", goal = "Present yourself, describe achievements and handle hard questions in an interview.", intro = LessonIntro(explanation = listOf("The achievement formula: situation → action → result. “The team was behind (S). I rebuilt the schedule (A) and we shipped on time (R).”", "Weakness questions want honesty plus growth: “I used to over-plan; now I timebox decisions.”", "Buy time politely: “That's a good question — let me think for a second.” Silence feels longer to you than to them."), examples = listOf(ExampleLine(text = "I've led a team of five for three years.", meaning = "Present perfect for ongoing relevance."), ExampleLine(text = "The project was behind, so I rebuilt the schedule.", meaning = "Situation + action."), ExampleLine(text = "As a result, we shipped two weeks early.", meaning = "Result with a number if possible."), ExampleLine(text = "I used to over-plan; now I timebox decisions.", meaning = "Weakness + growth."), ExampleLine(text = "That's a good question — let me think for a second.", meaning = "Buying time."), ExampleLine(text = "I'm particularly proud of the migration project.", meaning = "Selective pride."))), expressions = listOf(TargetExpression(text = "I've + participle + for/since", meaning = "Experience that continues.", note = "I've worked here since 2021."), TargetExpression(text = "The situation was …, so I …", meaning = "Story spine.", note = "S-A-R: situation, action, result."), TargetExpression(text = "As a result, …", meaning = "Land the outcome.", note = "Numbers beat adjectives."), TargetExpression(text = "I used to …; now I …", meaning = "Weakness + growth.", note = "Never say “I'm a perfectionist”."), TargetExpression(text = "Let me think for a second.", meaning = "Buy time.", note = "Then answer in structure."), TargetExpression(text = "I'm particularly proud of …", meaning = "Choose your highlight.", note = "One story, told well.")), situation = "Interview rehearsal: introduce your experience, tell one achievement with S-A-R, answer the weakness question and negotiate next steps.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Describe your current role and how long you've had it.", expected = listOf("I've worked as a <role> for <time>.", "I've been a <role> since <year>."), focus = "present perfect", watch = "for + period, since + point."), PracticeQuestion(prompt = "Tell one achievement as a story. (situation → action → result)", expected = listOf("The project was behind, so I rebuilt the schedule, and as a result we shipped on time."), focus = "S-A-R", watch = "The result is the point — land it with as a result."), PracticeQuestion(prompt = "Answer the weakness question honestly with growth.", expected = listOf("I used to over-plan; now I timebox decisions."), focus = "weakness + growth", watch = "used to for the old habit, now for the fix."), PracticeQuestion(prompt = "Buy time on a hard question.", expected = listOf("That's a good question — let me think for a second."), focus = "buying time", watch = "Then structure the answer: point, example, close."), PracticeQuestion(prompt = "Explain why you want this job. (growth + contribution)", expected = listOf("I want to grow into <area>, and I believe I can contribute <strength>."), focus = "two-sided motivation", watch = "What you gain AND what you bring."), PracticeQuestion(prompt = "Close the interview politely.", expected = listOf("Thank you — I look forward to hearing from you."), focus = "closing", watch = "look forward to + -ing."))), exercises = listOf(Exercise(id = "en-work-u1-interviews-e1", kind = "choice", prompt = "I've worked here ___ 2021.", options = listOf("since", "for", "from", "during"), answers = listOf("since"), explain = "since + point in time; for + period."), Exercise(id = "en-work-u1-interviews-e2", kind = "gap", prompt = "___ a result, we shipped two weeks early.", options = listOf(), answers = listOf("as"), explain = "As a result + outcome."), Exercise(id = "en-work-u1-interviews-e3", kind = "order", prompt = "Buy time politely.", options = listOf(), answers = listOf("That's a good question let me think for a second"), explain = "The buying-time formula."), Exercise(id = "en-work-u1-interviews-e4", kind = "written", prompt = "Weakness + growth: over-plan → timebox.", options = listOf(), answers = listOf("i used to over-plan now i timebox decisions", "i used to over plan now i timebox decisions"), explain = "used to (old) + now (new).")), skills = listOf("grammar:present-perfect", "grammar:used-to", "function:talk-about-work", "speaking:justify-opinion", "function:introduce-yourself"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:present-perfect", "grammar:used-to"))))
}

object EsFoundationsU1 {
    val unit = CourseUnit(id = "es-foundations-u1", title = "First sentences", subtitle = "Say who you are", level = "A1", themes = listOf(ConversationTheme("lang-exchange", "Language-exchange café", "Meet and greet", "person.2", "Course", "You are at a friendly language-exchange café in Madrid. Meet the learner, exchange names, countries and jobs using the verb ser.", 0),
                ConversationTheme("introductions", "Nice to meet you", "Start somewhere small", "hand.wave", "Connection", "Meet the learner for the first time. Learn their interests through natural introductions.", 1)), lessons = listOf(    Lesson(id = "es-foundations-u1-ser", title = "The verb “ser”", goal = "Introduce yourself and say who people are with soy, eres, es, somos, son.", intro = LessonIntro(explanation = listOf("Every Spanish sentence needs a subject and a verb. The most important verb for saying who you are is “ser”.", "One verb, five present forms: yo soy, tú eres, él/ella es, nosotros somos, ellos/ellas son. With “you” formal, use usted es.", "Use ser for identity and origin: “Soy Ana”, “Soy de España”, “Es profesora”. These facts do not change, so ser is the verb."), examples = listOf(ExampleLine(text = "Soy Ana. Soy de España.", meaning = "Your name and country."), ExampleLine(text = "Eres mi mejor amigo.", meaning = "A close bond with someone."), ExampleLine(text = "Ella es profesora.", meaning = "Someone's profession."), ExampleLine(text = "Somos muy felices hoy.", meaning = "A feeling that defines right now."), ExampleLine(text = "El café es cercano a la estación.", meaning = "Where a place is."), ExampleLine(text = "Ellos son de Madrid.", meaning = "Someone's origin."))), expressions = listOf(TargetExpression(text = "Soy …", meaning = "Introduce yourself.", note = "With your name, job or feeling: Soy Ana. Soy profesora."), TargetExpression(text = "Soy de …", meaning = "Say where you come from.", note = "Never “Soy España” — the de is obligatory: Soy de España."), TargetExpression(text = "¿Eres …?", meaning = "Ask about the other person.", note = "¿Eres estudiante? ¿Eres de aquí?"), TargetExpression(text = "Sí, lo soy. / No, no lo soy.", meaning = "Short answers to an ¿Eres…? question.", note = "Repeat the verb through lo: never just “Sí”."), TargetExpression(text = "Es …", meaning = "Say what someone else is.", note = "Es profesor — the article is often dropped with jobs: Es médico."), TargetExpression(text = "Encantado de conocerte.", meaning = "The fixed phrase when you meet someone.", note = "Answer with Encantada if you are a woman, or Igualmente.")), situation = "You meet someone new at a friendly language-exchange café in Madrid. Introduce yourselves and ask simple questions with the verb ser.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "¡Hola! Soy Ana. ¿Cómo te llamas?", expected = listOf("Me llamo <name>.", "Soy <name>."), focus = "Me llamo / Soy", watch = "Answering only the name without the verb: accept it, then recast “Me llamo …”."), PracticeQuestion(prompt = "¿De dónde eres?", expected = listOf("Soy de <country>."), focus = "ser + de", watch = "“Soy España” — recast “Soy DE España”, stress de."), PracticeQuestion(prompt = "¿Eres estudiante?", expected = listOf("Sí, lo soy.", "No, no lo soy."), focus = "short answers with ser", watch = "“Sí estudiante” — the short answer needs the verb."), PracticeQuestion(prompt = "¿Cómo estás hoy?", expected = listOf("Estoy bien.", "Estoy cansado.", "Estoy feliz."), focus = "estar for feelings", watch = "“Soy cansado” — recast “Estoy cansado”: feelings take estar."), PracticeQuestion(prompt = "Tu ciudad, ¿es grande o pequeña?", expected = listOf("Es grande.", "Es pequeña.", "Mi ciudad es …"), focus = "es with things and places", watch = "“Mi ciudad grande” — recast “Mi ciudad ES grande”."), PracticeQuestion(prompt = "¡Ya somos amigos! ¿De dónde es tu familia?", expected = listOf("Es de <country>.", "Mi familia es de <country>."), focus = "es for a group's origin", watch = "“Mi familia de …” — recast with es."))), exercises = listOf(Exercise(id = "es-foundations-u1-ser-e1", kind = "choice", prompt = "Ella ___ profesora.", options = listOf("es", "eres", "soy", "somos"), answers = listOf("es"), explain = "With él/ella/usted, ser becomes es."), Exercise(id = "es-foundations-u1-ser-e2", kind = "gap", prompt = "Nosotros ___ de Madrid.", options = listOf(), answers = listOf("somos"), explain = "With nosotros, ser is siempre somos."), Exercise(id = "es-foundations-u1-ser-e3", kind = "order", prompt = "Say where you are from.", options = listOf(), answers = listOf("Soy de España"), explain = "Soy + de + country: Soy de España."), Exercise(id = "es-foundations-u1-ser-e4", kind = "written", prompt = "Introduce yourself in one sentence: say your name.", options = listOf(), answers = listOf("Me llamo <name>", "Soy <name>"), explain = "Me llamo Ana / Soy Ana — the verb is never dropped.")), skills = listOf("grammar:verb-be", "grammar:subject-pronouns", "function:describe-people", "speaking:short-answer"), canDo = listOf("describe-people"), prerequisites = listOf("grammar:verb-be")),
    Lesson(id = "es-foundations-u1-questions", title = "Questions & negatives", goal = "Ask yes/no questions and say what is not true, with ¿Eres…? and no soy.", intro = LessonIntro(explanation = listOf("To ask a yes/no question in Spanish, keep the word order and just add the question marks — your voice goes up at the end: “¿Eres Ana?”", "Question words carry an accent: ¿Qué? ¿Dónde? ¿Cómo? They go first: “¿De dónde eres?”", "To say something is not true, put no before the verb: “No soy Ana”, “No somos amigos”. In answers, no… twice is normal: “No, no lo soy”."), examples = listOf(ExampleLine(text = "¿Eres tú profesora?", meaning = "A yes/no question with eres."), ExampleLine(text = "No soy de Madrid.", meaning = "A negative with soy."), ExampleLine(text = "¿De dónde eres?", meaning = "Question word + eres."), ExampleLine(text = "Él no es mi hermano.", meaning = "A negative about another person."), ExampleLine(text = "¿Sois vosotros vecinos?", meaning = "Asking a group."), ExampleLine(text = "¿Qué es esto?", meaning = "What is this?"))), expressions = listOf(TargetExpression(text = "¿Eres …?", meaning = "Ask a yes/no question.", note = "Same order as the statement, just the marks and rising tone."), TargetExpression(text = "No soy …", meaning = "Say what is not true about you.", note = "No always goes before the verb: No soy de Sevilla."), TargetExpression(text = "¿De dónde eres?", meaning = "Ask where someone is from.", note = "De dónde, two words with accents."), TargetExpression(text = "No es …", meaning = "Say what someone else is not.", note = "Él no es mi jefe."), TargetExpression(text = "¿Verdad?", meaning = "Tag a statement to check it.", note = "Es tu casa, ¿verdad?"), TargetExpression(text = "Claro.", meaning = "The natural yes in talk.", note = "Also: Por supuesto.")), situation = "You chat with a new neighbour in the lift in Madrid. Ask simple yes/no questions and say what is and isn't true for you.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "¿Eres de aquí?", expected = listOf("Sí, soy de aquí.", "No, no soy de aquí."), focus = "short answers", watch = "One-word “Sí” — recast with the verb: Sí, soy de aquí."), PracticeQuestion(prompt = "¿Eres profesor o estudiante?", expected = listOf("Soy profesor.", "Soy estudiante.", "Soy profesora."), focus = "choice with ser", watch = "Accept either; recast with the article dropped: Soy profesor."), PracticeQuestion(prompt = "¿Tu familia es grande?", expected = listOf("Sí, es grande.", "No, no es grande."), focus = "es in questions about others", watch = "“Mi familia es grande, ¿verdad?” is also fine."), PracticeQuestion(prompt = "¿De dónde eres tú?", expected = listOf("Soy de <country>."), focus = "de dónde + soy", watch = "“Soy de” never “Soy en”."), PracticeQuestion(prompt = "Dime algo que no eres.", expected = listOf("No soy <job>.", "No soy de <country>."), focus = "negation with no soy", watch = "“No soy” before the rest: never “Soy no”."), PracticeQuestion(prompt = "¿Somos amigos ya?", expected = listOf("Sí, somos amigos.", "Claro, somos amigos."), focus = "somos in questions", watch = "“Sí, estamos amigos” mixes ser and estar — recast with somos."))), exercises = listOf(Exercise(id = "es-foundations-u1-questions-e1", kind = "choice", prompt = "¿___ tú de Barcelona?", options = listOf("Eres", "Es", "Soy", "Somos"), answers = listOf("Eres"), explain = "With tú, questions start with Eres."), Exercise(id = "es-foundations-u1-questions-e2", kind = "gap", prompt = "Ella no ___ mi hermana.", options = listOf(), answers = listOf("es"), explain = "no + es: with ella the negative keeps es."), Exercise(id = "es-foundations-u1-questions-e3", kind = "order", prompt = "Say you are not from Seville.", options = listOf(), answers = listOf("No soy de Sevilla"), explain = "No goes first: No soy de Sevilla."), Exercise(id = "es-foundations-u1-questions-e4", kind = "written", prompt = "Make it negative: \"Soy de Valencia.\"", options = listOf(), answers = listOf("No soy de Valencia"), explain = "no + soy: No soy de Valencia.")), skills = listOf("grammar:verb-be", "grammar:present-questions", "function:ask-simple-questions", "speaking:short-answer"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "es-foundations-u1-introduce", title = "Introducing yourself", goal = "Give a complete self-introduction: name, country, nationality and job.", intro = LessonIntro(explanation = listOf("A full Spanish introduction has four pieces: your name, your city or country, your nationality and your job.", "For the name: “Me llamo Ana” (I call myself Ana) or simply “Soy Ana”. For origin: “Soy de España”. Nationalities are lower-case: “soy española”.", "Jobs with ser drop the article: “Soy profesora”, not “Soy una profesora”. Add “Mucho gusto” at the end to close politely."), examples = listOf(ExampleLine(text = "Me llamo Ana. Mucho gusto.", meaning = "Your name plus a polite close."), ExampleLine(text = "Soy de Sevilla, del sur de España.", meaning = "City inside country."), ExampleLine(text = "Soy española, de Andalucía.", meaning = "Nationality plus region."), ExampleLine(text = "Soy enfermera en un hospital.", meaning = "Job plus workplace."), ExampleLine(text = "Tengo veinticinco años.", meaning = "Your age — with tener, not ser."), ExampleLine(text = "Encantada. ¿Y tú?", meaning = "Close and bounce the question back."))), expressions = listOf(TargetExpression(text = "Me llamo …", meaning = "Give your name.", note = "Literally “I call myself”. Also: Mi nombre es …"), TargetExpression(text = "Soy + nationality", meaning = "Say your nationality.", note = "española, francesa, alemana — nationality is lower-case in Spanish."), TargetExpression(text = "Soy de …", meaning = "Say your city or country.", note = "Soy de Sevilla; Soy de España."), TargetExpression(text = "Trabajo en …", meaning = "Say where you work.", note = "Trabajo en un hospital / en una escuela."), TargetExpression(text = "Mucho gusto.", meaning = "Polite close when you meet someone.", note = "Answer: Igualmente."), TargetExpression(text = "¿Y tú?", meaning = "Bounce the question back.", note = "—Soy de Madrid. ¿Y tú?")), situation = "Your first day at a language school in Madrid. Present yourself completely to the class: name, city, nationality and job.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "¿Cómo te llamas?", expected = listOf("Me llamo <name>.", "Soy <name>."), focus = "name formulas", watch = "Both are fine; recast the shorter one as Me llamo for variety."), PracticeQuestion(prompt = "¿De dónde eres?", expected = listOf("Soy de <country>."), focus = "origin", watch = "Never drop de: Soy DE <country>."), PracticeQuestion(prompt = "¿Cuál es tu nacionalidad?", expected = listOf("Soy <nationality>."), focus = "nationality with ser", watch = "Lower-case: soy española, not Española."), PracticeQuestion(prompt = "¿A qué te dedicas?", expected = listOf("Soy <job>.", "Trabajo en <place>."), focus = "jobs without article", watch = "“Soy una profesora” — recast dropping the article."), PracticeQuestion(prompt = "¿Y dónde vives?", expected = listOf("Vivo en <city>."), focus = "vivo en", watch = "“Vivo a Madrid” — recast with en."), PracticeQuestion(prompt = "¡Encantado! ¿Y tú, de qué trabajas?", expected = listOf("Soy <job>.", "Trabajo de <job>."), focus = "bounce back and answer", watch = "Accept Soy de <job>? No — recast: Trabajo DE/Soy <job>."))), exercises = listOf(Exercise(id = "es-foundations-u1-introduce-e1", kind = "choice", prompt = "___ Ana. Mucho gusto.", options = listOf("Me llamo", "Me llamo de", "Llamo", "Estoy"), answers = listOf("Me llamo"), explain = "Me llamo + name: one piece, no de."), Exercise(id = "es-foundations-u1-introduce-e2", kind = "gap", prompt = "Soy ___ Italia. (nationality)", options = listOf(), answers = listOf("italiana"), explain = "Nationality is lower-case: italiana, italiano."), Exercise(id = "es-foundations-u1-introduce-e3", kind = "order", prompt = "Say your name and city.", options = listOf(), answers = listOf("Soy Ana y soy de Madrid"), explain = "Two soy pieces, both with their verb."), Exercise(id = "es-foundations-u1-introduce-e4", kind = "written", prompt = "Give your complete introduction: name and country.", options = listOf(), answers = listOf("Me llamo <name> y soy de <country>", "Soy <name> y soy de <country>", "Me llamo <name>, soy de <country>"), explain = "Name + origin, each with its verb.")), skills = listOf("grammar:verb-be", "function:introduce-yourself", "vocab:introductions", "pron:word-stress"), canDo = listOf("introduce-yourself"))))
}

object EsFoundationsU2 {
    val unit = CourseUnit(id = "es-foundations-u2", title = "Mi día a día", subtitle = "Rutinas y planes", level = "A1", themes = listOf(ConversationTheme("manana-locura", "Mañana de locos", "La rutina contra el reloj", "sunrise", "Course", "Cuentas tu mañana minuto a minuto: qué haces, a qué hora y qué siempre se olvida.", 0),
                ConversationTheme("finde-juntos", "El finde juntos", "¿Qué hacemos?", "figure.walk", "Course", "Planes para el sábado con un amigo: qué quieres hacer y a qué hora os veis.", 1)), lessons = listOf(    Lesson(id = "es-foundations-u2-rutina", title = "Mi rutina", goal = "Contar tu día con verbos en presente y las horas.", intro = LessonIntro(explanation = listOf("El presente sirve para rutinas: «Me levanto a las siete. Desayuno café y tostadas. Salgo de casa a las ocho».", "Los reflejos van con pronombre: «me levanto, me ducho, me acuesto» — el me es parte del verbo.", "Las horas en punto o y media: «a las siete», «a las siete y media». Con a: «a las ocho salgo»."), examples = listOf(ExampleLine(text = "Me levanto a las siete.", meaning = "El primer verbo del día."), ExampleLine(text = "Desayuno café y tostadas.", meaning = "El desayuno, sin pronombre."), ExampleLine(text = "Me ducho y salgo de casa a las ocho.", meaning = "Dos acciones seguidas."), ExampleLine(text = "Ceno a las nueve y me acuesto a las once.", meaning = "La rutina de noche."), ExampleLine(text = "Los sábados me levanto tarde.", meaning = "El hábito de fin de semana."))), expressions = listOf(TargetExpression(text = "Me levanto a las …", meaning = "El inicio.", note = "…siete, o tarde los sábados."), TargetExpression(text = "Desayuno / ceno …", meaning = "Comidas como verbos.", note = "Desayuno café."), TargetExpression(text = "Me ducho / me acuesto", meaning = "Reflejos del día.", note = "El me es obligatorio."), TargetExpression(text = "Salgo de casa a las …", meaning = "La salida.", note = "salir de + lugar."), TargetExpression(text = "Los sábados …", meaning = "El hábito de finde.", note = "plural = todos los sábados.")), situation = "Cuentas tu mañana a un amigo nuevo: hora de levantarte, desayuno, ducha, salida — y cómo cambia el sábado.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di a qué hora te levantas entre semana.", expected = listOf("Me levanto a las <hora> entre semana."), focus = "me levanto", watch = "El reflejo lleva me: me levanto, no levanto me."), PracticeQuestion(prompt = "Di qué desayunas.", expected = listOf("Desayuno <comida> y <comida>."), focus = "desayunar", watch = "Desayuno café — el verbo y la comida comparten raíz."), PracticeQuestion(prompt = "Di a qué hora sales de casa.", expected = listOf("Salgo de casa a las <hora>."), focus = "salir de", watch = "salir DE casa — la preposición importa."), PracticeQuestion(prompt = "Di cómo cambia tu sábado.", expected = listOf("Los sábados me levanto tarde."), focus = "los + día", watch = "Los sábados = todos los sábados."), PracticeQuestion(prompt = "Di a qué hora te acuestas.", expected = listOf("Me acuesto a las <hora>."), focus = "me acuesto", watch = "Reflejo: me acuesto, no acuesto me."))), exercises = listOf(Exercise(id = "es-foundations-u2-rutina-e1", kind = "choice", prompt = "Me ___ a las siete todos los días.", options = listOf("levanto", "levanto me", "levanta", "levantarse"), answers = listOf("levanto"), explain = "Me levanto: el me va delante."), Exercise(id = "es-foundations-u2-rutina-e2", kind = "gap", prompt = "___ café y tostadas. (desayunar)", options = listOf(), answers = listOf("Desayuno", "desayuno"), explain = "Primera persona: desayuno."), Exercise(id = "es-foundations-u2-rutina-e3", kind = "order", prompt = "Di a qué hora sales.", options = listOf(), answers = listOf("Salgo de casa a las ocho"), explain = "salgo de + lugar + a las + hora."), Exercise(id = "es-foundations-u2-rutina-e4", kind = "written", prompt = "Di tu hábito de los sábados.", options = listOf(), answers = listOf("los sábados me levanto tarde", "los sabados desayuno tarde"), explain = "Los + día + presente.")), skills = listOf("grammar:present-simple", "grammar:time-expressions", "vocab:daily-routine", "function:talk-about-routines"), canDo = listOf("talk-about-routines"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "es-foundations-u2-barrio", title = "Mi barrio", goal = "Decir qué hay en tu barrio con hay y dónde está.", intro = LessonIntro(explanation = listOf("Hay sirve para todo lo que existe: «Hay una plaza, dos bares y una frutería». No cambia con plural.", "Para preguntar: «¿Hay una farmacia por aquí?». Para negar: «No hay cine, lo siento».", "Ubica con cerca de / al lado de / enfrente de: «La frutería está enfrente del parque»."), examples = listOf(ExampleLine(text = "Hay una plaza y dos bares.", meaning = "hay no cambia con plural."), ExampleLine(text = "¿Hay una farmacia por aquí?", meaning = "La pregunta útil."), ExampleLine(text = "No hay cine en mi barrio.", meaning = "La negación."), ExampleLine(text = "La frutería está enfrente del parque.", meaning = "Ubicación exacta."), ExampleLine(text = "Todo está cerca de mi casa.", meaning = "El resumen cómodo."))), expressions = listOf(TargetExpression(text = "Hay + lugar", meaning = "Decir qué existe.", note = "Hay una panadería."), TargetExpression(text = "¿Hay … por aquí?", meaning = "Preguntar.", note = "…una farmacia?"), TargetExpression(text = "No hay …", meaning = "Lo que falta.", note = "No hay metro, lo siento."), TargetExpression(text = "está enfrente de / al lado de", meaning = "Ubicación.", note = "enfrente del parque."), TargetExpression(text = "cerca de mi casa", meaning = "La distancia.", note = "todo está cerca.")), situation = "Un visitante pregunta qué hay en tu barrio: nombra cuatro sitios, di lo que falta y ubica tu favorito.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di dos sitios que hay en tu barrio.", expected = listOf("Hay <lugar> y <lugar>."), focus = "hay", watch = "Hay no cambia: hay uno, hay dos."), PracticeQuestion(prompt = "Di lo que no hay. (cine)", expected = listOf("No hay cine en mi barrio."), focus = "no hay", watch = "No hay + lugar sin artículo."), PracticeQuestion(prompt = "Pregunta si hay farmacia cerca.", expected = listOf("¿Hay una farmacia por aquí?"), focus = "por aquí", watch = "por aquí = cerca, en esta zona."), PracticeQuestion(prompt = "Ubica tu sitio favorito.", expected = listOf("<Lugar> está enfrente de <lugar>."), focus = "enfrente de", watch = "enfrente DE + lugar."), PracticeQuestion(prompt = "Di que todo está cerca de tu casa.", expected = listOf("Todo está cerca de mi casa."), focus = "cerca de", watch = "cerca DE mi casa."))), exercises = listOf(Exercise(id = "es-foundations-u2-barrio-e1", kind = "choice", prompt = "___ dos bares y una panadería.", options = listOf("Hay", "Están", "Es", "Son"), answers = listOf("Hay"), explain = "Hay para decir qué existe."), Exercise(id = "es-foundations-u2-barrio-e2", kind = "gap", prompt = "No ___ metro en mi barrio. (existe)", options = listOf(), answers = listOf("hay"), explain = "No hay + lugar."), Exercise(id = "es-foundations-u2-barrio-e3", kind = "order", prompt = "Pregunta por una farmacia.", options = listOf(), answers = listOf("Hay una farmacia por aqui cerca"), explain = "¿Hay + lugar + por aquí?"), Exercise(id = "es-foundations-u2-barrio-e4", kind = "written", prompt = "Di qué hay enfrente de tu casa.", options = listOf(), answers = listOf("hay <lugar> enfrente de mi casa", "esta <lugar>"), explain = "Hay + lugar + enfrente de.")), skills = listOf("vocab:town", "grammar:there-is-are", "grammar:prepositions-place", "function:ask-simple-questions"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:there-is-are")),
    Lesson(id = "es-foundations-u2-planes", title = "Planes para el finde", goal = "Proponer planes con vamos a y quedar.", intro = LessonIntro(explanation = listOf("El futuro cercano: ir a + infinitivo. «El sábado vamos a ir al mercado». Va conjugado el ir, no el segundo verbo.", "Proponer: «¿Vamos al parque?», «¿Quieres venir?». Quedar es el verbo de las citas: «¿Quedamos a las seis?»", "Confirmar con hora y lugar: «Perfecto, a las seis en la plaza». Un plan sin lugar es un deseo."), examples = listOf(ExampleLine(text = "El sábado vamos a ir al mercado.", meaning = "ir a + infinitivo."), ExampleLine(text = "¿Quieres venir con nosotros?", meaning = "Invitar."), ExampleLine(text = "¿Quedamos a las seis en la plaza?", meaning = "Quedar = la cita."), ExampleLine(text = "Perfecto, ahí nos vemos.", meaning = "Confirmar."), ExampleLine(text = "Si llueve, lo dejamos para el domingo.", meaning = "El plan B."))), expressions = listOf(TargetExpression(text = "vamos a + infinitivo", meaning = "El plan conjunto.", note = "vamos a ir al mercado."), TargetExpression(text = "¿Quieres venir?", meaning = "Invitar.", note = "venir con + personas."), TargetExpression(text = "¿Quedamos a las … en …?", meaning = "La cita.", note = "quedar = vernos."), TargetExpression(text = "Perfecto / Vale", meaning = "Confirmar.", note = "Vale es el sí español."), TargetExpression(text = "Si llueve, …", meaning = "El plan B.", note = "si + presente, plan.")), situation = "Organizas el sábado con un amigo: propones mercado, quedáis a las seis en la plaza y dejáis el plan B si llueve.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Proponer el plan del sábado. (mercado, vamos a)", expected = listOf("El sábado vamos a ir al mercado."), focus = "vamos a", watch = "ir conjugado + a + infinitivo."), PracticeQuestion(prompt = "Invitar a tu amigo.", expected = listOf("¿Quieres venir conmigo?"), focus = "venir", watch = "venir con + persona."), PracticeQuestion(prompt = "Quedar en hora y lugar. (6, plaza)", expected = listOf("¿Quedamos a las seis en la plaza?"), focus = "quedar", watch = "quedar = vernos, citarse."), PracticeQuestion(prompt = "Dejar plan B si llueve.", expected = listOf("Si llueve, lo dejamos para el domingo."), focus = "si + presente", watch = "si + presente + plan."), PracticeQuestion(prompt = "Invita a tu amigo al plan.", expected = listOf("¿Quieres venir conmigo?", "¿Quieres venir con nosotros?"), focus = "venir", watch = "venir CON + persona."))), exercises = listOf(Exercise(id = "es-foundations-u2-planes-e1", kind = "choice", prompt = "El sábado vamos a ___ al mercado.", options = listOf("ir", "vamos", "van", "iremos"), answers = listOf("ir"), explain = "ir a + infinitivo: el segundo va sin conjugar."), Exercise(id = "es-foundations-u2-planes-e2", kind = "gap", prompt = "¿___ quedar a las seis? (proponer)", options = listOf(), answers = listOf("Quedamos", "Podemos"), explain = "¿Quedamos a las…?"), Exercise(id = "es-foundations-u2-planes-e3", kind = "order", prompt = "Confirmar la cita.", options = listOf(), answers = listOf("Quedamos a las seis en la plaza"), explain = "quedar + a las + hora + en + lugar."), Exercise(id = "es-foundations-u2-planes-e4", kind = "written", prompt = "Tu plan B si llueve.", options = listOf(), answers = listOf("si llueve lo dejamos para el domingo", "si llueve vamos al cine"), explain = "Si + presente + plan.")), skills = listOf("grammar:going-to", "function:make-future-plans", "vocab:social-expressions", "grammar:present-questions"), canDo = listOf("make-future-plans"), prerequisites = listOf("grammar:going-to"))))
}

object EsFoundationsU3 {
    val unit = CourseUnit(id = "es-foundations-u3", title = "La comida", subtitle = "Ingredientes y recetas", level = "A1", themes = listOf(ConversationTheme("cocina-juntos", "Cocinando juntos", "Receta sencilla", "fork.knife", "Course", "Cocináis una paella: revisáis ingredientes, seguid los pasos y compartimos.", 0),
