    Lesson(id = "es-foundations-u4-futuro", title = "El futuro", goal = "Hablar de planes con ir a + infinitivo y expresar intención.", intro = LessonIntro(explanation = listOf("El futuro cercano: ir a + infinitivo. «Voy a estudiar esta noche». «Vamos a viajar en verano».", "Preguntar: «¿Vas a venir?» «¿Qué vas a hacer?» — el verbo ir se conjuga, el infinitivo no.", "Irregulares en el infinitivo se mantienen: «Voy a hacer la cena» (no «hacer» cambia)."), examples = listOf(ExampleLine(text = "Voy a estudiar esta noche.", meaning = "ir a + infinitivo."), ExampleLine(text = "Vamos a viajar en verano.", meaning = "Nosotros: vamos a."), ExampleLine(text = "¿Vas a venir a la fiesta?", meaning = "Pregunta con ir a."), ExampleLine(text = "Va a llover, no salgas.", meaning = "Predicción: va a + verbo."), ExampleLine(text = "No voy a trabajar el sábado.", meaning = "Negativo: no voy a."))), expressions = listOf(TargetExpression(text = "voy / vas / va a + inf", meaning = "El futuro cercano.", note = "Voy a comer."), TargetExpression(text = "vamos a + inf", meaning = "Nosotros.", note = "Vamos a viajar."), TargetExpression(text = "¿Vas a + inf?", meaning = "Preguntar.", note = "¿Vas a venir?"), TargetExpression(text = "no voy a + inf", meaning = "Negar el plan.", note = "No voy a salir."), TargetExpression(text = "va a + inf (clima)", meaning = "Predicción.", note = "Va a llover.")), situation = "Planificáis el finde: uno propone, el otro acepta o rechaza, y decidís hora y lugar.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di qué vas a hacer este finde. (descansar)", expected = listOf("Voy a descansar este finde."), focus = "voy a", watch = "voy a + infinitivo."), PracticeQuestion(prompt = "Pregunta qué va a hacer tu amigo.", expected = listOf("¿Qué vas a hacer?"), focus = "la pregunta", watch = "¿Qué + vas a + infinitivo?"), PracticeQuestion(prompt = "Di que no vas a salir el sábado.", expected = listOf("No voy a salir el sábado."), focus = "no vo