    val unit = CourseUnit(id = "es-foundations-u5", title = "Experiencias y opiniones", subtitle = "Contar lo vivido", level = "B1", themes = listOf(ConversationTheme("viaje-inolvidable", "El viaje inolvidable", "Presente perfecto", "airplane", "Course", "Habéis viajado mucho: comparad experiencias con he/ha + participio.", 0),
