    Lesson(id = "es-foundations-u5-antes-ahora", title = "Antes y ahora", goal = "Comparar el pasado con el presente usando antes/imperiético y ahora/presente.", intro = LessonIntro(explanation = listOf("Antes + imperfecto: «Antes vivía en Madrid». Ahora + presente: «Ahora vivo en Barcelona».", "El imperfecto describe hábitos del pasado: «Iba al parque todos los días». «Jugaba al fútbol».", "La contraste: «Antes tenía tiempo, ahora no tengo nada»."), examples = listOf(ExampleLine(text = "Antes vivía en Madrid.", meaning = "antes + imperfecto."), ExampleLine(text = "Ahora vivo en Barcelona.", meaning = "ahora + presente."), ExampleLine(text = "Iba al parque todos los días.", meaning = "imperfecto: hábito pasado."), ExampleLine(text = "Antes tenía más tiempo libre.", meaning = "tener → tenía."), ExampleLine(text = "Ahora trabajo desde casa.", meaning = "ahora + presente."))), expressions = listOf(TargetExpression(text = "Antes + imperfecto", meaning = "El pasado habitual.", note = "Antes vivía…"), TargetExpression(text = "Ahora + presente", meaning = "El presente.", note = "Ahora trabajo…"), TargetExpression(text = "-ía / -aba", meaning = "El imperfecto.", note = "vivía, comía, trabajaba."), TargetExpression(text = "tenía / iba / era", meaning = "Imperfectos frecuentes.", note = "tenía tiempo."), TargetExpression(text = "ahora no …", meaning = "El contraste negativo.", note = "ahora no tengo tiempo.")), situation = "Comparáis vuestra vida de estudiantes con la vida de ahora: horarios, hobbies, dinero, libertad.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di dónde vivías antes. (Madrid)", expected = listOf("Antes vivía en Madrid."), focus = "antes + imperfecto", watch = "vivía = imperfecto de vivir."), PracticeQuestion(prompt = "Di qué hacías todos los días. (ir al parque)", expected = listOf("Iba al parque todos los días."), focus = "iba", watch = "ir → iba en imperfecto."), PracticeQuestion(prompt = "Di qué haces ahora.", expected = list