    val unit = CourseUnit(id = "es-foundations-u8", title = "Opiniones y matices", subtitle = "Si tuviera…", level = "B2", themes = listOf(ConversationTheme("es-b2-hipotesis", "Planes imposibles", "Si tuviera tiempo", "sparkles", "Course", "Debatís qué haríais con tiempo libre infinito y proponéis un compromiso real.", 0),
