    Lesson(id = "es-foundations-u8-registro", title = "Se dice que…", goal = "Hablar de lo que otros afirman: estilo impersonal con « se » y pasiva con « ser + participio ».", intro = LessonIntro(explanation = listOf("El impersonal: « Se dice que el barrio cambia ». No importa quién lo dice.", "La pasiva con participio: « El concierto fue cancelado », « Las entradas se han agotado ». Común en noticias.", "El registro sube con la pasiva y baja con el impersonal: noticias « oficiales » frente a rumor de barrio."), examples = listOf(ExampleLine(text = "Se dice que el barrio va a cambiar.", meaning = "Impersonal: rumor."), ExampleLine(text = "El concierto fue cancelado por la lluvia.", meaning = "Pasiva + agente."), ExampleLine(text = "Las entradas se han agotado.", meaning = "Pasiva refleja."), ExampleLine(text = "Se han cancelado todos los trenes.", meaning = "Noticia oficial."), ExampleLine(text = "Según el ayuntamiento, se retrasará la obra.", meaning = "Fuente + impersonal."))), expressions = listOf(TargetExpression(text = "Se dice que…", meaning = "Rumor.", note = "…el barrio va a cambiar."), TargetExpression(text = "fue/será + participio", meaning = "Pasiva.", note = "fue cancelado."), TargetExpression(text = "se han + participio", meaning = "Pasiva refleja.", note = "se han agotado."), TargetExpression(text = "Según + fuente", meaning = "Citar.", note = "Según el ayuntamiento."), TargetExpression(text = "se retrasará / se cancelará", meaning = "Futuro impersonal.", note = "noticias.")), situation = "Comentáis las noticias del barrio: qué se dice, qué se ha decidido y qué fuente creéis menos.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Transmite el rumor: se dice que el barrio va a cambiar.", expected = listOf("Se dice que el barrio va a cambiar"), focus = "se dice que", watch = "Impersonal, sin sujeto."), PracticeQuestion(prompt = "Noticia: el concierto fue cancelado por la lluvia.", expected = listOf("El concierto fue cancelado por