    Lesson(id = "es-foundations-u8-negociar", title = "¿Y si lo dejamos en 50?", goal = "Negociar un acuerdo: proponer con condicional, poner condiciones y cerrar.", intro = LessonIntro(explanation = listOf("Proponer: « ¿Y si lo dejáramos en 50 ? », « Yo te daría 60 si incluyes el transporte ».", "Poner condiciones: « Solo si me lo entregas hoy », « A cambio, te pido… ».", "Cerrar: « Trato hecho », « De acuerdo, pero con una condición »."), examples = listOf(ExampleLine(text = "¿Y si lo dejáramos en 50 ?", meaning = "Propuesta con subjuntivo."), ExampleLine(text = "Te daría 60 si incluyes el transporte.", meaning = "Condicional + condición."), ExampleLine(text = "Solo si me lo entregas hoy.", meaning = "Condición dura."), ExampleLine(text = "A cambio, te pido la garantía.", meaning = "Contraoferta."), ExampleLine(text = "Trato hecho.", meaning = "Cierre."))), expressions = listOf(TargetExpression(text = "¿Y si lo dejáramos en…?", meaning = "Proponer precio.", note = "dejáramos en 50."), TargetExpression(text = "…ría si + presente", meaning = "Condiciones.", note = "te daría 60 si…"), TargetExpression(text = "solo si…", meaning = "Condición dura.", note = "solo si es hoy."), TargetExpression(text = "a cambio, …", meaning = "Contraoferta.", note = "a cambio, la garantía."), TargetExpression(text = "trato hecho", meaning = "Cerrar.", note = "tras el acuerdo.")), situation = "Regateáis una mesa de segunda mano: abrís alto, ofrecéis con condiciones y cerráis a mitad de camino.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Propone precio: ¿y si lo dejáramos en 50?", expected = listOf("Y si lo dejaramos en 50", "¿Y si lo dejáramos en 50 ?"), focus = "¿y si…?", watch = "dejáramos: subjuntivo de propuesta."), PracticeQuestion(prompt = "Ofrece con condición: te daría 60 si incluyes el transporte.", expected = listOf("Te daria 60 si incluyes el transporte", "Te daría 60 si incluyes el transporte"), focus = "daría si", watch = "Condicional + si + pre