                ConversationTheme("es-c1-matices", "El matiz", "Más o menos", "bubble-left-and-text", "Course", "Debatís un proyecto sin posturas absolutas: practicáis el sí parcial, la reformulación y el cierre.", 1)), lessons = listOf(    Lesson(id = "es-foundations-u10-registro", title = "Cómo lo digo", goal = "Adaptar el registro: lo mismo para un cliente que para un compañero, sin sonar ni rígido ni descuidado.", intro = LessonIntro(explanation = listOf("El registro formal alarga y cortesiza: « Le agradecería que me confirmara la fecha ». El coloquial acorta y tutea: « ¿Me confirmas la fecha ? ».", "El email formal se abre con « Le escribo para… » o « En relación con… » y se cierra con « Quedo a su disposición » o « Un cordial saludo ».", "Los conectores delatan el tono: « no obstante » suena formal, « pero » es neutro y « o sea » delata conversación de pasillo."), examples = listOf(ExampleLine(text = "Le escribo en relación con el contrato.", meaning = "Apertura formal de email."), ExampleLine(text = "¿Te viene bien el jueves a las diez ?", meaning = "Coloquial: proponer hora."), ExampleLine(text = "Le agradecería una respuesta cuanto antes.", meaning = "Petición formal."), ExampleLine(text = "Oye, ¿me pasas el informe cuando puedas ?", meaning = "Petición coloquial."), ExampleLine(text = "No obstante, quedo a su disposición.", meaning = "Cierre formal con conector."))), expressions = listOf(TargetExpression(text = "Le/Les agradecería que + subjuntivo", meaning = "Petición formal.", note = "Le agradecería que lo revisara."), TargetExpression(text = "¿Te viene bien…?", meaning = "Coloquial: cerrar cita.", note = "¿Te viene bien el martes ?"), TargetExpression(text = "en relación con…", meaning = "Presentar un asunto, formal.", note = "en relación con el contrato."), TargetExpression(text = "no obstante", meaning = "Contraste, registro formal.", note = "No obstante, hay un detalle."), TargetExpression(text = "Un cordial saludo", meaning = "Despedida formal de email.", note = "antes de la firma.")), situation = "Comparáis el mismo encargo en dos versiones — email para un cliente y mensaje para un compañero — y decidís qué registro pide cada destinatario.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Pide con cortesía formal: le agradecería que me confirmara la fecha.", expected = listOf("Le agradeceria que me confirmara la fecha", "Le agradecería que me confirmara la fecha"), focus = "le agradecería", watch = "Que + subjuntivo: confirmara."), PracticeQuestion(prompt = "Propón hora en confianza: ¿te viene bien el jueves a las diez?", expected = listOf("Te viene bien el jueves a las diez", "¿Te viene bien el jueves a las diez ?"), focus = "¿te viene bien?", watch = "Coloquial: tú, no usted."), PracticeQuestion(prompt = "Despide un email formal: un cordial saludo.", expected = listOf("Un cordial saludo", "Saludos cordiales"), focus = "cordial", watch = "Despedida formal de email."), PracticeQuestion(prompt = "Contrasta en formal: no obstante, quedo a su disposición.", expected = listOf("No obstante quedo a su disposicion", "No obstante, quedo a su disposición"), focus = "no obstante", watch = "Conector formal, entre comas."), PracticeQuestion(prompt = "Pide informal: oye, ¿me pasas el informe cuando puedas?", expected = listOf("Oye me pasas el informe cuando puedas", "Oye, ¿me pasas el informe cuando puedas ?"), focus = "oye", watch = "Apelativo coloquial de atención."))), exercises = listOf(Exercise(id = "es-foundations-u10-registro-e1", kind = "choice", prompt = "___ agradecería que me confirmara la fecha lo antes posible.", options = listOf("Le", "Te", "Yo", "Me"), answers = listOf("Le"), explain = "Cortesía formal: le agradecería (de usted)."), Exercise(id = "es-foundations-u10-registro-e2", kind = "gap", prompt = "Hubo retrasos; ___, el proyecto sigue en marcha. (conector formal de contraste)", options = listOf(), answers = listOf("no obstante", "sin embargo"), explain = "No obstante / sin embargo: contraste en registro formal."), Exercise(id = "es-foundations-u10-registro-e3", kind = "choice", prompt = "¿Cuál es la versión formal de « te escribo por lo del contrato » ?", options = listOf("Le escribo en relación con el contrato", "Te suelto lo del contrato", "Te paso lo del contrato ese", "Le comento una cosita del contrato"), answers = listOf("Le escribo en relación con el contrato"), explain = "En relación con: fórmula formal para presentar un asunto."), Exercise(id = "es-foundations-u10-registro-e4", kind = "written", prompt = "Pide por email, en registro formal, que te confirmen la fecha de la reunión.", options = listOf(), answers = listOf("le agradeceria que me confirmaran la fecha de la reunion", "le agradecería que me confirmaran la fecha de la reunión", "quisiera pedirle que confirmara la fecha de la reunión"), explain = "Le agradecería que + subjuntivo: petición formal por escrito.")), skills = listOf("vocab:social-expressions", "function:talk-about-work", "writing:email", "grammar:connectors"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:connectors")),
    Lesson(id = "es-foundations-u10-matices", title = "Más o menos", goal = "Matizar opiniones: acordar a medias, reformular y situar el punto de vista propio.", intro = LessonIntro(explanation = listOf("Para matizar: « En cierto modo sí, pero… », « Hasta cierto punto lo comparto ». No niegas ni aceptas del todo.", "Para reformular: « por así decirlo », « Digamos que… ». Avisan de que la palabra elegida no es exacta.", "Para situar tu opinión: « Desde mi punto de vista », « A mi juicio ». Pesan más que un simple « creo que »."), examples = listOf(ExampleLine(text = "En cierto modo, tienes razón.", meaning = "Acuerdo parcial."), ExampleLine(text = "Hasta cierto punto lo comparto.", meaning = "Delimita el acuerdo."), ExampleLine(text = "Es, por así decirlo, un puente.", meaning = "Aviso de metáfora."), ExampleLine(text = "Desde mi punto de vista, sobra la reunión.", meaning = "Opinión situada."), ExampleLine(text = "Digamos que fue un malentendido.", meaning = "Suaviza el juicio."))), expressions = listOf(TargetExpression(text = "En cierto modo, …", meaning = "Acuerdo parcial.", note = "En cierto modo, sí."), TargetExpression(text = "hasta cierto punto", meaning = "Matiza el alcance.", note = "Hasta cierto punto lo entiendo."), TargetExpression(text = "por así decirlo", meaning = "Reformula con tacto.", note = "tras una metáfora."), TargetExpression(text = "Desde mi punto de vista, …", meaning = "Opinión con peso.", note = "equivale a para mí, pero más formal."), TargetExpression(text = "Digamos que…", meaning = "Suaviza.", note = "Digamos que no fue así.")), situation = "Valoráis el último proyecto en equipo: nadie quiere un sí o un no rotundos, y practicáis la respuesta intermedia.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Matiza: en cierto modo, tienes razón.", expected = listOf("En cierto modo tienes razon", "En cierto modo, tienes razón"), focus = "en cierto modo", watch = "Acuerdo parcial, no total."), PracticeQuestion(prompt = "A