    Lesson(id = "es-foundations-u10-presentar", title = "Presentar ideas", goal = "Estructurar una intervención breve: abrir, encadenar argumentos y cerrar con una conclusión limpia.", intro = LessonIntro(explanation = listOf("Abre marcando el camino: « Para empezar », « En primer lugar ». El oyente sabe que viene una secuencia.", "Encadena sin saltos: « Por otra parte », « A esto se añade que… ». Cada idea engancha con la anterior.", "Cierra con señal clara: « En resumen », « Para concluir ». Una sola idea final, no tres."), examples = listOf(ExampleLine(text = "Para empezar, repasemos los datos.", meaning = "Abre la secuencia."), ExampleLine(text = "En primer lugar, el presupuesto.", meaning = "Primer punto."), ExampleLine(text = "Por otra parte, falta tiempo.", meaning = "Añade un argumento."), ExampleLine(text = "A esto se añade que el equipo es nuevo.", meaning = "Encadena otra razón."), ExampleLine(text = "En resumen: adelante, pero con calendario.", meaning = "Conclusión breve."))), expressions = listOf(TargetExpression(text = "Para empezar, …", meaning = "Abre.", note = "Para empezar, los datos."), TargetExpression(text = "en primer lugar", meaning = "Primer punto.", note = "tras él: en segundo lugar."), TargetExpression(text = "por otra parte, …", meaning = "Añade otra cara.", note = "Por otra parte, el tiempo."), TargetExpression(text = "a esto se añade que…", meaning = "Encadena razones.", note = "A esto se añade que…"), TargetExpression(text = "En resumen, …", meaning = "Cierra.", note = "En resumen: sí, pero tarde.")), situation = "Cada uno presenta en dos minutos una propuesta: abrir con un punto claro, encadenar dos razones y cerrar con una sola frase.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Abre: para empezar, repasemos los datos.", expected = listOf("Para empezar repasemos los datos", "Para empezar, repasemos los datos"), focus = "para empezar", watch = "Señal de apertura."), PracticeQuestion(prompt = "Primer punto: en primer lugar, el presupuesto.", expected = listOf("En primer lugar el presupuesto", "En primer lugar, el presupuesto"), focus = "en primer lugar", watch = "Después: en segundo lugar."), PracticeQuestion(prompt = "Añade otra cara: por otra parte, falta tiempo.", expected = listOf("Por otra parte falta tiempo", "Por otra parte, falta tiempo"), focus = "por otra parte", watch = "Añade un argumento nuevo."), PracticeQuestion(prompt = "Encadena: a esto se añade que el equipo es nuevo.", expected = listOf("A esto se anade que el equipo es nuevo", "A esto se añade que el equipo es nuevo"), focus = "a esto se añade", watch = "Engancha con lo anterior."), PracticeQuestion(prompt = "Cierra: en resumen, adelante, pero con calendario.", expected = listOf("En resumen adelante pero con calendario", "En resumen, adelante, pero con calendario"), focus = "en resumen", watch = "Una sola idea final."))), exercises = listOf(Exercise(id = "es-foundations-u10-presentar-e1", kind = "choice", prompt = "___ empezar, repasemos los números del trimestre.", options = listOf("Para", "Por", "Al", "En"), answers = listOf("Para"), explain = "Para empezar: fórmula de apertura."), Exercise(id = "es-foundations-u10-presentar-e2", kind = "gap", prompt = "La propuesta tiene ventajas; ___, exige presupuesto y tiempo. (conector que añade otra cara)", options = listOf(), answers = listOf("por otra parte", "por otro lado"), explain = "Por otra parte / por otro lado: añaden un argumento nuevo."), Exercise(id = "es-foundations-u10-presentar-e3", kind = "choice", prompt = "¿Cuál de estas fórmulas sirve para cerrar una intervención ?", options = listOf("En resumen", "Para empezar", "En primer lugar", "A esto se añade"), answers = listOf("En resumen"), explain = "En resumen anuncia la conclusión; las demás organizan la secuencia."), Exercise(id = "es-foundations-u10-presentar-e4", kind = "written", prompt = "Cierra la presentación de tu propuesta con la fórmula de resumen.", options = listOf(), answers = listOf("en resumen la propuesta avanza pero en enero", "en resumen, la propuesta avanza, pero en enero", "para concluir la propuesta avanza pero en enero"), explain = "En resumen + una sola idea: cierre de discurso.")), skills = listOf("speaking:sustained-conversation", "function:talk-about-work", "grammar:connectors", "vocab:work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:connectors"))))
}

object EsFoundationsU11 {
    val unit = CourseUnit(id = "es-foundations-u11", title = "Mi casa", subtitle = "Mi espacio", level = "A1", themes = listOf(ConversationTheme("mi-espacio", "Mi espacio", "Habitaciones y muebles", "house", "Course", "Describes tu piso: el salón, la cocina y lo que hay en cada habitación.", 0),
                ConversationTheme("compartir-casa", "Compartimos casa", "Cosas y personas", "bed", "Course", "Hablas de tu compañero de piso: su habitación, sus cosas y su rutina.", 1)), lessons = listOf(    Lesson(id = "es-foundations-u11-casa", title = "Mi piso", goal = "Describir tu piso: habitaciones, muebles y qué hay en cada sitio.", intro = LessonIntro(explanation = listOf("Para decir qué existe usamos «hay»: «En la cocina hay una mesa». Negamos con «no hay»: «No hay garaje».", "Las habitaciones de casa: el salón, la cocina, el dormitorio y el baño. «El piso tiene dos habitaciones».", "Para preguntar: «¿Cuántas habitaciones hay?». Respondes: «Hay dos: el salón y el dormitorio»."), examples = listOf(ExampleLine(text = "Mi piso es pequeño.", meaning = "Describir el piso."), ExampleLine(text = "En el salón hay un sofá y una mesa.", meaning = "Decir qué hay."), ExampleLine(text = "La cocina tiene una ventana grande.", meaning = "Describir una habitación."), ExampleLine(text = "No hay garaje.", meaning = "Decir que algo no existe."), ExampleLine(text = "¿Cuántas habitaciones hay?", meaning = "Preguntar por espacios."))), expressions = listOf(TargetExpression(text = "hay un / una …", meaning = "Decir qué existe (singular).", note = "Hay un sofá nuevo."), TargetExpression(text = "no hay …", meaning = "Decir que no existe.", note = "No hay ascensor."), TargetExpression(text = "el salón / la cocina", meaning = "Habitaciones de casa.", note = "El salón es grande."), TargetExpression(text = "el dormitorio / el baño", meaning = "Más habitaciones.", note = "El baño está a la derecha."), TargetExpression(text = "¿Cuántas habitaciones hay?", meaning = "Preguntar por espacios.", note = "Hay dos habitaciones.")), situation = "Hablas de tu piso nuevo: dos habitaciones, un salón con sofá azul y una cocina pequeña sin lavavajillas.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Describe tu salón: di que hay un sofá y una mesa.", expected = listOf("En mi salon hay un sofa y una mesa", "En mi salón hay un sofá y una mesa"), focus = "hay", watch = "hay + un/una en singular."), PracticeQuestion(prompt = "Pregunta cuántas habitaciones tiene el piso.", expected = listOf("¿Cuantas habitaciones tiene el piso?", "¿Cuántas habitaciones tiene el piso?"), focus = "cuántas", watch = "En preguntas, cuántas lleva tilde."), PracticeQuestion(prompt = "Di qué hay en la cocina.", expected = listOf("Hay una mesa y dos sillas", "hay una mesa y dos sillas"), focus = "hay", watch = "hay nunca cambia: hay una mesa, hay dos sillas."), PracticeQuestion(prompt = "Habla de tu casa: el número de habitaciones.", expected = listOf("Mi piso tiene tres habitaciones", "mi piso tiene tres habitaciones"), focus = "tiene", watch = "El piso tiene + cantidad."), PracticeQuestion(prompt = "Pregunta si hay lavavajillas.", expected = listOf("¿Hay lavavajillas en la cocina?", "¿Hay lava platos en la cocina?"), focus = "¿hay…?", watch = "Pregunta con ¿Hay…? + sustantivo."))), exercises = listOf(Exercise(id = "es-foundations-u11-casa-e1", kind = "choice", prompt = "En el salón ___ un sofá grande.", options = listOf("hay", "es", "tiene", "está"), answers = listOf("hay"), explain = "Hay + un/una: decir qué existe en un lugar."), Exercise(id = "es-foundations-u11-casa-e2", kind = "gap", prompt = "Mi piso ___ dos habitaciones. (tener)", options = listOf(), answers = listOf("tiene"), explain = "tiene: el piso posee habitaciones."), Exercise(id = "es-foundations-u11-casa-e3", kind = "order", prompt = "Di qué hay en el salón: un sofá y una mesa.", options = listOf(), answers = listOf("En el salón hay un sofá y una mesa"), explain = "hay + muebles del salón."), Exercise(id = "es-foundations-u11-casa-e4", kind = "written", prompt = "Pregunta cuántas habitaciones hay.", options = listOf(), answers = listOf("¿Cuantas habitaciones hay en el piso?", "¿Cuántas habitaciones hay en el piso?"), explain = "¿Cuántas… hay? con tilde en cuántas.")), skills = listOf("grammar:there-is-are", "grammar:present-simple", "vocab:home", "function:ask-simple-questions"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "es-foundations-u11-lugares", title = "¿Dónde está?", goal = "Decir dónde están las cosas: encima de, debajo de y al lado de.", intro = LessonIntro(explanation = listOf("Para preguntar lugar: «¿Dónde está el teléfono?». Respondes con está + lugar: «Está en la mesa».", "Las preposiciones de lugar: encima de, debajo de, al lado de. «La lámpara está encima de la mesa».", "También usas delante de y detrás de: «El gato está debajo de la cama»."), examples = listOf(ExampleLine(text = "¿Dónde está el gato?", meaning = "Preguntar lugar."), ExampleLine(text = "Está encima de la mesa.", meaning = "Posición superior."), ExampleLine(text = "El periódico está debajo de la cama.", meaning = "Posición inferior."), ExampleLine(text = "La silla está al lado de la ventana.", meaning = "Junto a la ventana."), ExampleLine(text = "El móvil está en el cajón.", meaning = "Dentro: en."))), expressions = listOf(TargetExpression(text = "¿Dónde está …?", meaning = "Preguntar por una cosa.", note = "¿Dónde están las llaves? (plural)"), TargetExpression(text = "encima de", meaning = "Sobre algo.", note = "El libro está encima de la mesa."), TargetExpression(text = "debajo de", meaning = "Bajo algo.", note = "El gato está debajo de la silla."), TargetExpression(text = "al lado de", meaning = "Junto a algo.", note = "La cama está al lado de la ventana."), TargetExpression(text = "delante de / detrás de", meaning = "Antes o después en el espacio.", note = "El coche está delante de la casa.")), situation = "Buscas las llaves en casa: están encima de la mesa del salón, al lado de un periódico viejo.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Pregunta dónde está la llave.", expected = listOf("¿Donde esta la llave?", "¿Dónde está la llave?"), focus = "¿dónde está?", watch = "dónde con tilde en preguntas."), PracticeQuestion(prompt = "Di que el libro está sobre la mesa.", expected = listOf("El libro esta encima de la mesa", "El libro está encima de la mesa