    Lesson(id = "es-foundations-u11-companeros", title = "Mi compañero de piso", goal = "Describir a tu compañero de piso y hablar de sus cosas con mi, tu y su.", intro = LessonIntro(explanation = listOf("Los posesivos: mi, tu, su. «Mi compañero se llama Pablo». «Tu habitación es la grande».", "su = de él o de ella. «Ana trabaja mucho; su trabajo es interesante».", "Para describir personas: «Es simpático y muy ordenado». «Trabaja por la noche»."), examples = listOf(ExampleLine(text = "Mi compañero de piso se llama Pablo.", meaning = "Decir el nombre."), ExampleLine(text = "Su habitación está limpia.", meaning = "su = de Pablo."), ExampleLine(text = "Es simpático pero ruidoso.", meaning = "Describir carácter."), ExampleLine(text = "Mi compañera estudia medicina.", meaning = "Compañera: femenino."), ExampleLine(text = "Tu bici está en el balcón.", meaning = "tu = de ti."))), expressions = listOf(TargetExpression(text = "mi / mis", meaning = "Poseedor: yo.", note = "Mis llaves están aquí."), TargetExpression(text = "tu / tus", meaning = "Poseedor: tú.", note = "Tu móvil suena."), TargetExpression(text = "su / sus", meaning = "Poseedor: él o ella.", note = "Sus libros están en el salón."), TargetExpression(text = "se llama …", meaning = "Decir el nombre.", note = "Mi compañera se llama Ana."), TargetExpression(text = "Es + adjetivo", meaning = "Describir carácter.", note = "Es ordenado y simpático.")), situation = "Presentas a Pablo: comparte la cocina, trabaja de noche y sus cosas siempre están en el salón.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di cómo se llama tu compañero de piso.", expected = listOf("Mi compañero se llama Pablo", "mi compañero se llama pablo"), focus = "se llama", watch = "se llama + nombre."), PracticeQuestion(prompt = "Di que la habitación de él es pequeña.", expected = listOf("Su habitacion es pequena", "Su habitación es pequeña"), focus = "su", watch = "su = de él o de ella."), PracticeQuestion(prompt = "Describe el carácter de tu compañera: simpática y ordenada.", expected = listOf("Es simpatica y ordenada", "Es simpática y ordenada"), focus = "es + adjetivo", watch = "Adjetivo femenino: -a."), PracticeQuestion(prompt = "Habla de tus llaves: están en la cocina.", expected = listOf("Mis llaves estan en la cocina", "Mis llaves están en la cocina"), focus = "mis", watch = "mi → mis en plural."), PracticeQuestion(prompt = "Pregunta a tu compañero por su bici.", expected = listOf("¿Donde esta tu bici?", "¿Dónde está tu bici?"), focus = "tu", watch = "tu posesivo, sin tilde; tú pronombre, con tilde."))), exercises = listOf(Exercise(id = "es-foundations-u11-companeros-e1", kind = "choice", prompt = "Pablo es mi compañero y ___ habitación es la roja.", options = listOf("su", "tu", "mis", "nuestra"), answers = listOf("su"), explain = "su = de él: la habitación de Pablo."), Exercise(id = "es-foundations-u11-companeros-e2", kind = "gap", prompt = "___ llaves están en la mesa. (posesivo de yo)", options = listOf(), answers = listOf("Mis"), explain = "mi → mis en plural: mis llaves."), Exercise(id = "es-foundations-u11-companeros-e3", kind = "order", prompt = "Presenta a tu compañera: se llama Ana.", options = listOf(), answers = listOf("Mi compañera se llama Ana"), explain = "mi + persona + se llama + nombre."), Exercise(id = "es-foundations-u11-companeros-e4", kind = "written", prompt = "Habla del carácter de él.", options = listOf(), answers = listOf("es muy simpatico", "Es muy simpático"), explain = "Es + adjetivo: simpático lleva tilde.")), skills = listOf("grammar:possessives", "function:describe-people", "vocab:home", "grammar:present-simple"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:possessives"))))
}

object EsFoundationsU12 {
    val unit = CourseUnit(id = "es-foundations-u12", title = "Mi barrio", subtitle = "Cerca de casa", level = "A1", themes = listOf(ConversationTheme("sitios-cercanos", "Sitios cercanos", "¿Qué hay por aquí?", "map", "Course", "Buscas sitios cerca de casa: supermercado, farmacia, parque y parada de autobús.", 0),
                ConversationTheme("fruta-fresca", "Fruta del barrio", "La frutería de abajo", "cart", "Course", "Compras fruta en la frutería del barrio: kilos, medio kilo y buen precio.", 1)), lessons = listOf(    Lesson(id = "es-foundations-u12-sitios", title = "¿Hay un supermercado?", goal = "Preguntar por sitios del barrio con ¿hay? y responder con hay / no hay.", intro = LessonIntro(explanation = listOf("Para preguntar por sitios: «¿Hay un supermercado por aquí?». «¿Hay una farmacia cerca?».", "Para responder: «Sí, hay uno en la esquina». «No, no hay nada cerca».", "Sitios del barrio: el supermercado, la farmacia, el parque y la parada de autobús."), examples = listOf(ExampleLine(text = "¿Hay un supermercado por aquí?", meaning = "Preguntar por un sitio."), ExampleLine(text = "Sí, hay uno en la esquina.", meaning = "Responder que sí."), ExampleLine(text = "¿Hay una farmacia cerca?", meaning = "Preguntar distancia."), ExampleLine(text = "No, aquí no hay banco.", meaning = "Responder que no."), ExampleLine(text = "La parada de autobús está en la avenida.", meaning = "Situar un sitio."))), expressions = listOf(TargetExpression(text = "¿Hay … por aquí?", meaning = "Preguntar por sitios.", note = "¿Hay un cajero por aquí?"), TargetExpression(text = "hay uno / hay una", meaning = "Responder que sí.", note = "¿Un bar? Hay uno al lado."), TargetExpression(text = "no hay nada", meaning = "Responder que no.", note = "No hay nada cerca."), TargetExpression(text = "la esquina", meaning = "El final de la calle.", note = "Está en la esquina."), TargetExpression(text = "la parada de autobús", meaning = "Sitio del barrio.", note = "La parada está cerca.")), situation = "Llegas al barrio y preguntas: hay un supermercado en la esquina, una farmacia cerca y una parada de autobús en la avenida.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Pregunta si hay un supermercado por aquí.", expected = listOf("¿Hay un supermercado por aqui?", "¿Hay un supermercado por aquí?"), focus = "¿hay…?", watch = "Pregunta con ¿Hay…? + un/una."), PracticeQuestion(prompt = "Responde que sí: hay un bar al lado.", expected = listOf("Si hay uno al lado", "Sí, hay uno al lado"), focus = "hay uno", watch = "hay uno/una sustituye al sitio."), PracticeQuestion(prompt = "Pregunta si hay una farmacia cerca.", expected = listOf("¿Hay una farmacia cerca?", "¿Hay una farmacia por aquí?"), focus = "¿hay una…?", watch = "farmacia es femenino: una."), PracticeQuestion(prompt = "Preguntan por un banco. Di que no hay.", expected = listOf("No hay nada cerca", "no hay nada cerca"), focus = "no hay nada", watch = "nada = ningún sitio."), PracticeQuestion(prompt = "Di dónde está la parada de autobús: en la avenida.", expected = listOf("La parada de autobus esta en la avenida", "La parada de autobús está en la avenida"), focus = "está en", watch = "Sitios concretos: está + en."))), exercises = listOf(Exercise(id = "es-foundations-u12-sitios-e1", kind = "choice", prompt = "¿___ una farmacia por aquí?", options = listOf("Hay", "Es", "Está", "Son"), answers = listOf("Hay"), explain = "¿Hay…? pregunta si existe un sitio."), Exercise(id = "es-foundations-u12-sitios-e2", kind = "gap", prompt = "¿Un cajero? Sí, hay ___ en la esquina. (masculino)", options = listOf(), answers = listOf("uno"), explain = "hay uno sustituye al sustantivo masculino."), Exercise(id = "es-foundations-u12-sitios-e3", kind = "order", prompt = "Responde afirmativamente: preguntan por un bar.", options = listOf(), answers = listOf("Hay un bar en la esquina"), explain = "hay + sitio + lugar."), Exercise(id = "es-foundations-u12-sitios-e4", kind = "written", prompt = "Preguntan por un banco en esta calle. Responde negativamente.", options = listOf(), answers = listOf("No hay nada cerca", "No hay ningun banco aqui", "No hay ningún banco aquí"), explain = "No hay nada / no hay ningún + sustantivo.")), skills = listOf("grammar:there-is-are", "grammar:present-questions", "vocab:town", "function:a