    Lesson(id = "es-foundations-u12-direcciones", title = "¿Cómo llego?", goal = "Pedir y dar direcciones básicas: siga recto, gire a la izquierda, está cerca.", intro = LessonIntro(explanation = listOf("Para pedir direcciones: «Perdone, ¿cómo llego a la estación?». «¿Está lejos?».", "Para dar direcciones: «Siga recto». «Gire a la izquierda». «Gire a la derecha en el semáforo».", "Para la distancia: «Está a cinco minutos». «Está muy cerca, no necesita autobús»."), examples = listOf(ExampleLine(text = "Perdone, ¿cómo llego a la estación?", meaning = "Pedir direcciones."), ExampleLine(text = "Siga recto dos calles.", meaning = "Dar una dirección."), ExampleLine(text = "Gire a la izquierda en el semáforo.", meaning = "Indicar un giro."), ExampleLine(text = "¿Está lejos?", meaning = "Preguntar distancia."), ExampleLine(text = "No, está a cinco minutos andando.", meaning = "Decir que está cerca."))), expressions = listOf(TargetExpression(text = "¿Cómo llego a …?", meaning = "Pedir direcciones.", note = "¿Cómo llego al parque?"), TargetExpression(text = "siga recto", meaning = "Seguir de frente.", note = "Siga recto hasta la plaza."), TargetExpression(text = "gire a la izquierda / derecha", meaning = "Indicar un giro.", note = "Gire a la derecha."), TargetExpression(text = "está cerca / lejos", meaning = "Distancia.", note = "Está muy cerca."), TargetExpression(text = "a cinco minutos", meaning = "Tiempo andando.", note = "Está a cinco minutos.")), situation = "Preguntas por la estación: siga recto, gire a la izquierda en la farmacia y está a diez minutos andando.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Pide direcciones para ir a la estación, con educación.", expected = listOf("Perdone, ¿como llego a la estacion?", "Perdone, ¿cómo llego a la estación?"), focus = "¿cómo llego?", watch = "Perdone para llamar la atención."), PracticeQuestion(prompt = "Di que la persona debe seguir de frente.", expected = listOf("Siga recto", "siga recto"), focus = "siga recto", watch = "Fórmula de usted: siga."), PracticeQuestion(prompt = "Indica un giro a la izquierda.", expected = listOf("Gire a la izquierda", "gire a la izquierda"), focus = "gire a", watch = "gire a la izquierda / a la derecha."), PracticeQuestion(prompt = "Pregunta si el museo está lejos.", expected = listOf("¿Esta lejos el museo?", "¿Está lejos el museo?"), focus = "¿está lejos?", watch = "está con tilde."), PracticeQuestion(prompt = "Tranquiliza a la persona: el paseo dura cinco minutos.", expected = listOf("Esta a cinco minutos andando", "Está a cinco minutos andando"), focus = "a + tiempo", watch = "a cinco minutos = tiempo a pie."))), exercises = listOf(Exercise(id = "es-foundations-u12-direcciones-e1", kind = "choice", prompt = "Para llegar al parque, ___ recto.", options = listOf("siga", "gire", "está", "toma"), answers = listOf("siga"), explain = "siga recto = continuar de frente."), Exercise(id = "es-foundations-u12-direcciones-e2", kind = "gap", prompt = "En el semáforo, gire a la ___. (dirección)", options = listOf(), answers = listOf("izquierda"), explain = "a la izquierda = girar a la mano izquierda."), Exercise(id = "es-foundations-u12-direcciones-e3", kind = "order", prompt = "Indica el giro a la izquierda.", options = listOf(), answers = listOf("Gire a la izquierda"), explain = "gire a + izquierda/derecha."), Exercise(id = "es-foundations-u12-direcciones-e4", kind = "written", prompt = "Indica el giro: hay que girar en el semáforo.", options = listOf(), answers = listOf("Gire a la derecha en el semaforo", "Gire a la derecha en el semáforo"), explain = "Gire a la derecha en + lugar.")), skills = listOf("function:ask-for-directions", "vocab:directions", "grammar:present-simple", "vocab:town"), canDo = listOf("ask-for-directions"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "es-foundations-u12-tienda", title = "En la frutería", goal = "Comprar fruta en el barrio: cantidades, calidad y fórmulas de trato.", intro = LessonIntro(explanation = listOf("En la frutería el vendedor pregunta: «¿Qué le pongo?». Tú respondes la cantidad: «Medio kilo de plátanos».", "Más cantidades: «Un kilo de naranjas». «Doscientos gramos de fresas». «Una sandía».", "Para terminar: «Eso es todo, gracias». El vendedor pregunta: «¿Algo más?»."), examples = listOf(ExampleLine(text = "Buenos días, ¿qué le pongo?", meaning = "El vendedor saluda."), ExampleLine(text = "Medio kilo de plátanos, por favor.", meaning = "Pedir cantidad."), ExampleLine(text = "¿Están buenas las fresas?", meaning = "Preguntar calidad."), ExampleLine(text = "¿Algo más?", meaning = "El vendedor pregunta."), ExampleLine(text = "Eso es todo, gracias.", meaning = "Terminar la compra."))), expressions = listOf(TargetExpression(text = "¿Qué le pongo?", meaning = "El vendedor pregunta.", note = "Respondes con la cantidad."), TargetExpression(text = "medio kilo de …", meaning = "Peso.", note = "Medio kilo de plátanos."), TargetExpression(text = "¿Están buenas …?", meaning = "Calidad de la fruta.", note = "Sí, están muy dulces."), TargetExpression(text = "¿Algo más?", meaning = "Preguntar si falta algo.", note = "Nada más, gracias."), TargetExpression(text = "Eso es todo.", meaning = "Cerrar la compra.", note = "Eso es todo, gracias.")), situation = "Compras en la frutería de tu calle: medio kilo de plátanos, una sandía y preguntas si las fresas están buenas.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "El vendedor pregunta qué quieres. Pide medio kilo de plátanos.", expected = listOf("Me pone medio kilo de platanos", "Me pone medio kilo de plátanos"), focus = "me pone", watch = "me pone + cantidad."), PracticeQuestion(prompt = "Pregunta si las fresas están buenas.", expected = listOf("¿Estan buenas las fresas?", "¿Están buenas las fresas?"), focus = "¿están buenas?", watch = "buenas concuerda con fresas."), PracticeQuestion(prompt = "Pide un kilo de naranjas.", expected = listOf("Me pone un kilo de naranjas", "Quiero un kilo de naranjas", "quiero un kilo de naranjas"), focus = "kilo", watch = "un kilo de + fruta."), PracticeQuestion(prompt = "El vendedor pregunta si falta algo. Di que no.", expected = listOf("Nada mas gracias", "Nada más, gracias"), focus = "nada más", watch = "Nada más = eso es todo."), PracticeQuestion(prompt = "Di que ya terminaste la compra.", expected = listOf("Eso es todo gracias", "Eso es todo, gracias"), focus = "eso es todo", watch = "Fórmula para cerrar."))), exercises = listOf(Exercise(id = "es-foundations-u12-tienda-e1", kind = "choice", prompt = "Buenos días, ¿qué le ___?", options = listOf("pongo", "pone", "pones", "ponemos"), answers = listOf("pone"), explain = "El vendedor dice: ¿qué le pongo?"), Exercise(id = "es-foundations-u12-tienda-e2", kind = "gap", prompt = "Quiero ___ kilo de manzanas. (ni uno ni dos)", options = listOf(), answers = listOf("medio"), explain = "medio kilo = 500 gramos."), Exercise(id = "es-foundations-u12-tienda-e3", kind = "order", prompt = "Pide medio kilo de plátanos.", options = listOf(), answers = listOf("Me pone medio kilo de plátanos"), explain = "me pone + cantidad + fruta."), Exercise(id = "es-foundations-u12-tienda-e4", kind = "written", prompt = "El vendedor pregunta «¿Algo más?». Responde que no, cortésmente.", options = listOf(), answers = listOf("Nada mas gracias", "Nada más, gracias", "Eso es todo, gracias"), explain = "Nada más, gracias = no quiero nada más.")), skills = listOf("function:go-shopping", "grammar:quantities", "vocab:food", "grammar:present-simple"), canDo = listOf("go-shopping"), prerequisites = listOf("grammar:present-simple"))))
