object EsFoundationsU13 {
    val unit = CourseUnit(id = "es-foundations-u13", title = "Mi gente", subtitle = "Familia y amigos", level = "A1", themes = listOf(ConversationTheme("mi-familia", "Mi familia", "Personas y posesivos", "figure-2", "Course", "Presentas a tu familia: tus padres, tus hermanos y un tío muy simpático.", 0),
                ConversationTheme("mis-amigos", "Mis amigos", "Carácter y llamadas", "heart", "Course", "Describes a tus amigos por teléfono y quedas con ellos para el sábado.", 1)), lessons = listOf(    Lesson(id = "es-foundations-u13-familia", title = "Mi familia", goal = "Presentar a tu familia: padres, hermanos y tíos, con tengo y los posesivos.", intro = LessonIntro(explanation = listOf("La familia: mi madre, mi padre, mi hermano y mi hermana. «Tengo un hermano y dos hermanas».", "Usamos tengo para hablar de tu familia: «Tengo un tío muy simpático». Si no hay: «No tengo hermanos».", "Los posesivos acompañan a la familia: «mi madre», «tu padre», «su mujer». «Mis padres viven en Madrid»."), examples = listOf(ExampleLine(text = "Tengo un hermano y una hermana.", meaning = "Decir quién está en tu familia."), ExampleLine(text = "Mi padre se llama Luis.", meaning = "Presentar a tu padre."), ExampleLine(text = "Tengo un tío muy gracioso.", meaning = "Hablar de un tío."), ExampleLine(text = "No tengo abuelos.", meaning = "Decir que alguien no está."), ExampleLine(text = "Mis padres viven en Sevilla.", meaning = "Hablar de tus padres, en plural."))), expressions = listOf(TargetExpression(text = "mi madre / mi padre", meaning = "Tus padres.", note = "Mi madre es profesora."), TargetExpression(text = "mi hermano / mi hermana", meaning = "Tus hermanos.", note = "Mi hermana tiene diez años."), TargetExpression(text = "el tío / la tía", meaning = "Los hermanos de tus padres.", note = "Tengo una tía en Valencia."), TargetExpression(text = "los abuelos", meaning = "El abuelo y la abuela.", note = "Mis abuelos viven cerca."), TargetExpression(text = "tengo … / no tengo …", meaning = "Decir quién está en tu familia.", note = "Tengo dos primos.")), situation = "Presentas a tu familia: tus padres, tu hermano pequeño y un tío que vive en Barcelona.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di que tienes un hermano y una hermana.", expected = listOf("