object FrFoundationsU1 {
    val unit = CourseUnit(id = "fr-foundations-u1", title = "First sentences", subtitle = "Say who you are", level = "A1", themes = listOf(ConversationTheme("lang-exchange", "Language-exchange café", "Meet and greet", "person.2", "Course", "You are at a friendly language-exchange café in Lyon. Meet the learner, exchange names, countries and jobs using the verb être.", 0),
                ConversationTheme("introductions", "Nice to meet you", "Start somewhere small", "hand.wave", "Connection", "Meet the learner for the first time. Learn their interests through natural introductions.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u1-etre", title = "The verb “être”", goal = "Introduce yourself and say who people are with je suis, tu es, il est, nous sommes, vous êtes, ils sont.", intro = LessonIntro(explanation = listOf("Every French sentence needs a subject and a verb. The verb for saying who you are is “être”.", "Six forms, one per subject: je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont. French never drops the subject: say “Je suis”, not just “Suis”.", "Use être for identity and origin: “Je suis Ana”, “Je suis de France”, “Il est professeur”. Put “de” after a city: “Je suis de Lyon”."), examples = listOf(ExampleLine(text = "Je suis Ana. Je suis de France.", meaning = "Your name and country."), ExampleLine(text = "Tu es mon meilleur ami.", meaning = "A close bond with someone."), ExampleLine(text = "Elle est professeure.", meaning = "Someone's profession."), ExampleLine(text = "Nous sommes très contents aujourd'hui.", meaning = "A feeling that defines right now."), ExampleLine(text = "Le café est près de la gare.", meaning = "Where a place is."), ExampleLine(text = "Ils sont de Paris.", meaning = "Someone's origin."))), expressions = listOf(TargetExpression(text = "Je suis …", meaning = "Introduce yourself.", note = "With your name or job: Je suis Ana. Je suis professeure."), TargetExpression(text = "Je suis de …", meaning = "Say where you come from.", note = "Never “Je suis France” — the de is obligatory: Je suis de France."), TargetExpression(text = "Tu es … ?", meaning = "Ask about the other person.", note = "Tu es étudiant ? Tu es d'ici ?"), TargetExpression(text = "Oui, je le suis. / Non, pas du tout.", meaning = "Short answers to a Tu es… ? question.", note = "Repeat the verb through le."), TargetExpression(text = "Il est / Elle est …", meaning = "Say what someone else is.", note = "Elle est médecin — jobs often drop the article."), TargetExpression(text = "Enchanté(e).", meaning = "The fixed phrase when you meet someone.", note = "Add -e if you are a woman: Enchantée.")), situation = "You meet someone new at a friendly language-exchange café in Lyon. Introduce yourselves and ask simple questions with the verb être.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Bonjour ! Je suis Ana. Comment tu t'appelles ?", expected = listOf("Je m'appelle <name>.", "Moi, c'est <name>."), focus = "Je m'appelle / Moi, c'est", watch = "Answering only the name: accept it, then recast “Je m'appelle …”."), PracticeQuestion(prompt = "Tu es de quelle ville ?", expected = listOf("Je suis de <city>.", "Je viens de <city>."), focus = "être + de", watch = "“Je suis Lyon” — recast “Je suis DE Lyon”."), PracticeQuestion(prompt = "Tu es étudiant ?", expected = listOf("Oui, je le suis.", "Non, je ne le suis pas."), focus = "short answers with être", watch = "One-word “Oui” — recast with the verb."), PracticeQuestion(prompt = "Comment ça va, aujourd'hui ?", expected = listOf("Ça va bien.", "Je suis fatigué.", "Je suis content."), focus = "être for feelings", watch = "“Je vais content” mixes verbs — recast with Je suis."), PracticeQuestion(prompt = "Ta ville, elle est grande ou petite ?", expected = listOf("Elle est grande.", "Elle est petite.", "Ma ville est …"), focus = "est with places", watch = "“Ma ville grande” — recast “Ma ville EST grande”."), PracticeQuestion(prompt = "On est amis maintenant ! Ta famille est de où ?", expected = listOf("Elle est de <country>.", "Ma famille est de <country>."), focus = "est for a group's origin", watch = "“Ma famille de …” — recast with est."))), exercises = listOf(Exercise(id = "fr-foundations-u1-etre-e1", kind = "choice", prompt = "Elle ___ professeure.", options = listOf("est", "es", "suis", "sommes"), answers = listOf("est"), explain = "With il/elle, être becomes est."), Exercise(id = "fr-foundations-u1-etre-e2", kind = "gap", prompt = "Nous ___ de Lyon.", options = listOf(), answers = listOf("sommes"), explain = "With nous, être is toujours sommes."), Exercise(id = "fr-foundations-u1-etre-e3", kind = "order", prompt = "Say where you are from.", options = listOf(), answers = listOf("Je suis de France"), explain = "Je suis + de + country: Je suis de France."), Exercise(id = "fr-foundations-u1-etre-e4", kind = "written", prompt = "Introduce yourself in one sentence: say your name.", options = listOf(), answers = listOf("Je m'appelle <name>", "Je suis <name>", "Moi c'est <name>"), explain = "Je m'appelle Ana / Je suis Ana — the subject is never dropped.")), skills = listOf("grammar:verb-be", "grammar:subject-pronouns", "function:describe-people", "speaking:short-answer"), canDo = listOf("describe-people"), prerequisites = listOf("grammar:verb-be")),
    Lesson(id = "fr-foundations-u1-questions", title = "Questions & negatives", goal = "Ask yes/no questions and say what is not true, with Tu es… ? and je ne suis pas.", intro = LessonIntro(explanation = listOf("Spoken French asks yes/no questions with rising intonation: “Tu es fatigué ?” The formal way adds est-ce que: “Est-ce que tu es fatigué ?”", "To negate, wrap the verb: ne + verb + pas. With être: “Je ne suis pas fatigué”, “Il n'est pas professeur” — ne becomes n' before a vowel.", "Question words go first: “Où es-tu ?”, “Qu'est-ce que c'est ?” — and they always carry their accents."), examples = listOf(ExampleLine(text = "Tu es professeure ?", meaning = "A yes/no question with es."), ExampleLine(text = "Je ne suis pas de Paris.", meaning = "A negative with suis."), ExampleLine(text = "Où es-tu ?", meaning = "Question word + es."), ExampleLine(text = "Il n'est pas mon frère.", meaning = "A negative about another person."), ExampleLine(text = "Vous êtes voisins ?", meaning = "Asking a group."), ExampleLine(text = "Qu'est-ce que c'est ?", meaning = "What is this?"))), expressions = listOf(TargetExpression(text = "Tu es … ?", meaning = "Ask a yes/no question.", note = "Spoken style: rising tone. Formal: Est-ce que tu es … ?"), TargetExpression(text = "Je ne suis pas …", meaning = "Say what is not true about you.", note = "ne + suis + pas wraps the verb."), TargetExpression(text = "Où es-tu ?", meaning = "Ask where someone is.", note = "Où with its accent, always."), TargetExpression(text = "Il n'est pas …", meaning = "Say what someone else is not.", note = "ne becomes n' before a vowel: n'est."), TargetExpression(text = "C'est ça ?", meaning = "Tag a statement to check it.", note = "Tu es d'ici, c'est ça ?"), TargetExpression(text = "Bien sûr.", meaning = "The natural yes in talk.", note = "Also: Exact.")), situation = "You chat with a new neighbour in the lift in Lyon. Ask simple yes/no questions and say what is and isn't true for you.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Tu es d'ici ?", expected = listOf("Oui, je suis d'ici.", "Non, je ne suis pas d'ici."), focus = "short answers", watch = "One-word “Oui” — recast with the verb: Oui, je suis d'ici."), PracticeQuestion(prompt = "Tu es professeur ou étudiant ?", expected = listOf("Je suis professeur.", "Je suis étudiant.", "Je suis professeure."), focus = "choice with être", watch = "Accept either; note the article stays dropped."), PracticeQuestion(prompt = "Ta famille est grande ?", expected = listOf("Oui, elle est grande.", "Non, elle n'est pas grande."), focus = "est in questions about others", watch = "“Elle n'est pas grande” — n' before est."), PracticeQuestion(prompt = "Tu es de où, toi ?", expected = listOf("Je suis de <country>.", "Je viens de <country>."), focus = "où + es", watch = "“Je suis à France” — recast with de: Je suis DE France."), PracticeQuestion(prompt = "Dis-moi quelque chose que tu n'es pas.", expected = listOf("Je ne suis pas <job>.", "Je ne suis pas de <country>."), focus = "negation ne…pas", watch = "Both parts needed: ne before, pas after."), PracticeQuestion(prompt = "On est amis maintenant ?", expected = listOf("Oui, on est amis.", "Bien sûr, on est amis."), focus = "on est", watch = "“On sommes” doesn't exist — on always takes est."))), exercises = listOf(Exercise(id = "fr-foundations-u1-questions-e1", kind = "choice", prompt = "¿ ___ tu de Marseille ?", options = listOf("Es", "Est", "Suis", "Êtes"), answers = listOf("Es"), explain = "With tu, the question starts with Es: Tu es de… ?"), Exercise(id = "fr-foundations-u1-questions-e2", kind = "gap", prompt = "Elle ___ pas ma sœur.", options = listOf(), answers = listOf("n'est"), explain = "ne + est → n'est pas: n' before the vowel."), Exercise(id = "fr-foundations-u1-questions-e3", kind = "order", prompt = "Say you are not from Nantes.", options = listOf(), answers = listOf("Je ne suis pas de Nantes"), explain = "ne + suis + pas wraps the verb."), Exercise(id = "fr-foundations-u1-questions-e4", kind = "written", prompt = "Make it negative: \"Je suis de Bordeaux.\"", options = listOf(), answers = listOf("Je ne suis pas de Bordeaux"), explain = "ne…pas around suis: Je ne suis pas de Bordeaux.")), skills = listOf("grammar:verb-be", "grammar:present-questions", "function:ask-simple-questions", "speaking:short-answer"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "fr-foundations-u1-introduce", title = "Introducing yourself", goal = "Give a complete self-introduction: name, city, nationality and job.", intro = LessonIntro(explanation = listOf("A full French introduction has four pieces: your name, your city, your nationality and your job.", "For the name: “Je m'appelle Ana” or “Moi, c'est Ana”. For origin: “Je suis de Lyon”. Nationalities are lower-case: “je suis française”.", "Jobs with être usually drop the article: “Je suis professeure”. Close with “Enchantée” and bounce the question back with “Et toi ?”"), examples = listOf(ExampleLine(text = "Je m'appelle Ana. Enchantée.", meaning = "Your name plus a polite close."), ExampleLine(text = "Je suis de Lyon, dans le sud-est.", meaning = "City inside country."), ExampleLine(text = "Je suis française, de la région Rhône.", meaning = "Nationality plus region."), ExampleLine(text = "Je suis infirmière à l'hôpital.", meaning = "Job plus workplace."), ExampleLine(text = "J'ai vingt-cinq ans.", meaning = "Your age — with avoir, not être."), ExampleLine(text = "Et toi ? Tu fais quoi ?", meaning = "Bounce the question back."))), expressions = listOf(TargetExpression(text = "Je m'appelle …", meaning = "Give your name.", note = "Literally “I call myself”. Also: Moi, c'est …"), TargetExpression(text = "Je suis + nationality", meaning = "Say your nationality.", note = "française, allemande, italienne — lower-case in French."), TargetExpression(text = "Je suis de …", meaning = "Say your city or country.", note = "Je suis de Lyon; Je suis de France."), TargetExpression(text = "Je travaille à …", meaning = "Say where you work.", note = "Je travaille à l'hôpital / dans une école."), TargetExpression(text = "Enchanté(e).", meaning = "Polite close when you meet someone.", note = "Answer: Moi aussi."), TargetExpression(text = "Et toi ?", meaning = "Bounce the question back.", note = "—Je suis de Lyon. Et toi ?")), situation = "Your first day at a language school in Lyon. Present yourself completely to the class: name, city, nationality and job.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Comment tu t'appelles ?", expected = listOf("Je m'appelle <name>.", "Moi, c'est <name>."), focus = "name formulas", watch = "Both are fine; recast the shorter one as Je m'appelle for variety."), PracticeQuestion(prompt = "Tu viens d'où ?", expected = listOf("Je viens de <country>.", "Je suis de <country>."), focus = "origin", watch = "Never drop de: Je viens DE <country>."), PracticeQuestion(prompt = "Tu es de quelle nationalité ?", expected = listOf("Je suis <nationality>."), focus = "nationality with être", watch = "Lower-case: je suis française, not Française."), PracticeQuestion(prompt = "Tu fais quoi dans la vie ?", expected = listOf("Je suis <job>.", "Je travaille comme <job>."), focus = "jobs without article", watch = "“Je suis une professeure” — recast dropping the article."), PracticeQuestion(prompt = "Et tu habites où ?", expected = listOf("J'habite à <city>."), focus = "j'habite à", watch = "“J'habite à Lyon” — à for cities."), PracticeQuestion(prompt = "Enchanté ! Et toi, tu fais quoi ?", expected = listOf("Je suis <job>."), focus = "bounce back and answer", watch = "Recast with Je suis + job."))), exercises = listOf(Exercise(id = "fr-foundations-u1-introduce-e1", kind = "choice", prompt = "___ Ana. Enchantée.", options = listOf("Je m'appelle", "Je m'appelle de", "J'appelle", "Je suis de"), answers = listOf("Je m'appelle"), explain = "Je m'appelle + name: one piece, no de."), Exercise(id = "fr-foundations-u1-introduce-e2", kind = "gap", prompt = "Je suis ___ Italie. (nationality)", options = listOf(), answers = listOf("italienne"), explain = "Nationality is lower-case: italienne, italien."), Exercise(id = "fr-foundations-u1-introduce-e3", kind = "order", prompt = "Say your name and city.", options = listOf(), answers = listOf("Je suis Ana et je suis de Lyon"), explain = "Two suis pieces, each with its subject."), Exercise(id = "fr-foundations-u1-introduce-e4", kind = "written", prompt = "Give your complete introduction: name and country.", options = listOf(), answers = listOf("Je m'appelle <name> et je suis de <country>", "Je suis <name> et je suis de <country>"), explain = "Name + origin, each with its subject.")), skills = listOf("grammar:verb-be", "function:introduce-yourself", "vocab:introductions", "pron:word-stress"), canDo = listOf("introduce-yourself"))))
}

