    val unit = CourseUnit(id = "fr-foundations-u2", title = "Mon quotidien", subtitle = "Routine et projets", level = "A1", themes = listOf(ConversationTheme("matinee-folle", "Matinée folle", "Contre le réveil", "sunrise", "Course", "Tu racontes ta matinée minute par minute : heures, habitudes et oublis.", 0),
                ConversationTheme("samedi-ensemble", "Samedi ensemble", "On fait quoi ?", "figure.walk", "Course", "Des projets pour samedi avec un ami : marché, heure, lieu de rendez-vous.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u2-routine", title = "Ma routine", goal = "Raconter ta journée au présent avec les heures.", intro = LessonIntro(explanation = listOf("Le présent raconte les habitudes : « Je me lève à sept heures. Je prends un café. Je pars à huit heures. »", "Les verbes réflexifs gardent me/te/se : « je me lève, je me douche, je me couche » — le pronom fait partie du verbe.", "Les heures : « à sept heures », « à sept heures et demie ». Avec à : « à huit heures, je pars »."), examples = listOf(ExampleLine(text = "Je me lève à sept heures.", meaning = "Le premier verbe."), ExampleLine(text = "Je prends un café le matin.", meaning = "La boisson du réveil."), ExampleLine(text = "Je me douche et je pars à huit heures.", meaning = "Deux actions de suite."), ExampleLine(text = "Le samedi, je me lève tard.", meaning = "L'habitude du week-end."), ExampleLine(text = "Je me couche vers onze heures.", meaning = "Le soir, avec vers."))), expressions = listOf(TargetExpression(text = "Je me lève à …", meaning = "Le réveil.", note = "me + lève : inséparables."), TargetExpression(text = "Je prends mon petit-déjeuner", meaning = "Le matin.", note = "prendre le petit-déjeuner."), TargetExpression(text = "Je pars à …", meaning = "La sortie.", note = "partir de + lieu."), TargetExpression(text = "Le samedi, …", meaning = "L'habitude.", note = "le + jour = chaque jour."), TargetExpression(text = "Je me couche vers …", meaning = "Le coucher.", note = "vers = environ.")), situation = "Tu racontes ta matinée à un nouvel ami : réveil, petit-déjeuner, douche, départ — et le changement du samedi.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Dis à quelle heure tu te lèves en semaine.", expected = listOf("Je me lève à <heure> en semaine."), focus = "je me lève", watch = "me/te/se font partie du verbe."), PracticeQuestion(prompt = "Dis ce que tu prends au petit-déjeuner.", expected = listOf("Je prends un café et des toasts."), focus = "prendre", watch = "prendre le petit-déjeuner = desayunar."), PracticeQuestion(prompt = "Dis à quelle heure tu pars de chez toi.", expected = listOf("Je pars de chez moi à <heure>."), focus = "partir de", watch = "partir DE chez moi."), PracticeQuestion(prompt = "Dis ton habitude du samedi.", expected = listOf("Le samedi, je me lève tard."), focus = "le + jour", watch = "le samedi = cada sábado."), PracticeQuestion(prompt = "Dis à quelle heure tu te couches.", expected = listOf("Je me couche vers <heure>."), focus = "je me couche", watch = "me couche — vers = hacia las."))), exercises = listOf(Exercise(id = "fr-foundations-u2-routine-e1", kind = "choice", prompt = "Je ___ ___ à sept heures.", options = listOf("me lève", "lève me", "se lève", "lever"), answers = listOf("me lève"), explain = "me/te/se + verbe : je me lève."), Exercise(id = "fr-foundations-u2-routine-e2", kind = "gap", prompt = "Je ___ un café le matin. (prendre)", options = listOf(), answers = listOf("prends"), explain = "je prends : prendre fait prendre."), Exercise(id = "fr-foundations-u2-routine-e3", kind = "order", prompt = "Dis ton départ.", options = listOf(), answers = listOf("Je pars de chez moi a huit heures"), explain = "je pars de + lieu."), Exercise(id = "fr-foundations-u2-routine-e4", kind = "written", prompt = "Ton habitude du samedi.", options = listOf(), answers = listOf("le samedi je me leve tard", "le samedi je me leve tard"), explain = "le + jour + présent.")), skills = listOf("grammar:present-simple", "grammar:time-expressions", "vocab:daily-routine", "function:talk-about-routines"), canDo = listOf("talk-about-routines"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "fr-foundations-u2-quartier", title = "Mon quartier", goal = "Dire ce qu'il y a dans ton quartier avec il y a.", intro = LessonIntro(explanation = listOf("Il y a ne change jamais : « Il y a une boulangerie, deux cafés et un parc. »", "Pour demander : « Il y a une pharmacie par ici ? ». Pour nier : « Il n'y a pas de cinéma. »", "Situer : en face de, à côté de, près de : « La boulangerie est en face du parc. »"), examples = listOf(ExampleLine(text = "Il y a une boulangerie et deux cafés.", meaning = "il y a, toujours pareil."), ExampleLine(text = "Il y a une pharmacie par ici ?", meaning = "La question utile."), ExampleLine(text = "Il n'y a pas de cinéma.", meaning = "La négation, avec de."), ExampleLine(text = "La boulangerie est en face du parc.", meaning = "La localisation."), ExampleLine(text = "Tout est près de chez moi.", meaning = "Le résumé."))), expressions = listOf(TargetExpression(text = "Il y a + lieu", meaning = "Dire ce qui existe.", note = "Il y a un parc."), TargetExpression(text = "Il y a … par ici ?", meaning = "Demander.", note = "…une pharmacie ?"), TargetExpression(text = "Il n'y a pas de …", meaning = "Ce qui manque.", note = "pas de cinéma."), TargetExpression(text = "en face de / à côté de", meaning = "Situer.", note = "en face du parc."), TargetExpression(text = "près de chez moi", meaning = "La distance.", note = "tout est près.")), situation = "Un visiteur demande ton quartier : nomme quatre lieux, dis ce qui manque et situe ton préféré.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Nomme deux lieux de ton quartier.", expected = listOf("Il y a <lieu> et <lieu>."), focus = "il y a", watch = "il y a ne change jamais."), PracticeQuestion(prompt = "Dis ce qui manque. (cinéma)", expected = listOf("Il n'y a pas de cinéma dans mon quartier."), focus = "pas de", watch = "négation : pas DE cinéma."), PracticeQuestion(prompt = "Demande s'il y a une pharmacie.", expected = listOf("Il y a une pharmacie par ici ?"), focus = "par ici", watch = "par ici = cerca, por esta zona."), PracticeQuestion(prompt = "Situe ton lieu préféré.", expected = listOf("<Lieu> est en face de <lieu>."), focus = "en face de", watch = "en face DE + lieu."), PracticeQuestion(prompt = "Dis que tout est près de chez toi.", expected = listOf("Tout est près de chez moi."), focus = "près de", watch = "près DE chez moi."))), exercises = listOf(Exercise(id = "fr-foundations-u2-quartier-e1", kind = "choice", prompt = "___ une boulangerie et deux cafés.", options = listOf("Il y a", "Ils sont", "C'est", "Il est"), answers = listOf("Il y a"), explain = "il y a pour l'existence."), Exercise(id = "fr-foundations-u2-quartier-e2", kind = "gap", prompt = "Il n'y a ___ de cinéma ici. (negación)", options = listOf(), answers = listOf("pas"), explain = "il n'y a pas de + lieu."), Exercise(id = "fr-foundations-u2-quartier-e3", kind = "order", prompt = "Demande une pharmacie.", options = listOf(), answers = listOf("Il y a une pharmacie par ici"), explain = "Il y a + lieu + par ici ?"), Exercise(id = "fr-foundations-u2-quartier-e4", kind = "written", prompt = "Dis ce qu'il y a devant chez toi.", options = listOf(), answers = listOf("il y a <lieu> en face de chez moi", "il y a un parc"), explain = "Il y a + lieu + en face de.")), skills = listOf("vocab:town", "grammar:there-is-are", "grammar:prepositions-place", "function:ask-simple-questions"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:there-is-are")),
    Lesson(id = "fr-foundations-u2-projets", title = "Des projets pour samedi", goal = "Proposer des projets avec on va et fixer un rendez-vous.", intro = LessonIntro(explanation = listOf("Le futur proche : aller + infinitif. « Samedi, on va aller au marché. » C'est aller qui se conjugue.", "Proposer : « On va au marché ? », « Tu veux venir ? ». Se donner rendez-vous : « On se retrouve à six heures ? »", "Confirmer avec lieu et heure : « Parfait, six heures, devant le parc. » Un plan sans lieu reste un rêve."), examples = listOf(ExampleLine(text = "Samedi, on va aller au marché.", meaning = "aller + infinitif."), ExampleLine(text = "Tu veux venir avec nous ?", meaning = "L'invitation."), ExampleLine(text = "On se retrouve à six heures, devant le parc ?", meaning = "Le rendez-vous."), ExampleLine(text = "Parfait, c'est noté.", meaning = "La confirmation."), ExampleLine(text = "S'il pleut, on reporte à dimanche.", meaning = "Le plan B."))), expressions = listOf(TargetExpression(text = "on va + infinitif", meaning = "Le projet du groupe.", note = "on va aller au marché."), TargetExpression(text = "Tu veux venir ?", meaning = "Inviter.", note = "venir avec nous."), TargetExpression(text = "On se retrouve à … , …", meaning = "Le rendez-vous.", note = "heure + lieu."), TargetExpression(text = "Parfait / C'est noté", meaning = "Confirmer.", note = "c'est noté = queda apuntado."), TargetExpression(text = "S'il pleut, on …", meaning = "Le plan B.", note = "si + présent.")), situation = "Tu organises samedi avec un ami : le marché, rendez-vous à six heures devant le parc, et plan B s'il pleut.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Propose le marché avec on va.", expected = listOf("Samedi, on va aller au marché."), focus = "on va", watch = "aller conjugué + infinitif."), PracticeQuestion(prompt = "Invite ton ami.", expected = listOf("Tu veux venir avec nous ?"), focus = "venir", watch = "venir AVEC quelqu'un."), PracticeQuestion(prompt = "Fixe le rendez-vous. (6h, le parc)", expected = listOf("On se retrouve à six heures, devant le parc ?"), focus = "se retrouver", watch = "heure + lieu."), PracticeQuestion(prompt = "Donne le plan B. (pluie / dimanche)", expected = listOf("S'il pleut, on reporte à dimanche."), focus = "si + présent", watch = "si + présent + plan."), PracticeQuestion(prompt = "Invite ton ami au plan.", expected = listOf("Tu veux venir avec nous ?"), focus = "venir", watch = "venir AVEC nous."))), exercises = listOf(Exercise(id = "fr-foundations-u2-projets-e1", kind = "choice", prompt = "Samedi, on va ___ au marché.", options = listOf("aller", "allons", "vont", "irons"), answers = listOf("aller"), explain = "aller + infinitif : le second reste à l'infinitif."), Exercise(id = "fr-foundations-u2-projets-e2", kind = "gap", prompt = "On ___ retrouve à six heures ? (rendez-vous)", options = listOf(), answers = listOf("se"), explain = "on se retrouve = nos vemos."), Exercise(id = "fr-foundations-u2-projets-e3", kind = "order", prompt = "Fixe le rendez-vous.", options = listOf(), answers = listOf("On se retrouve a six heures devant le parc"), explain = "on se retrouve + heure + lieu."), Exercise(id = "fr-foundations-u2-projets-e4", kind = "written", prompt = "Le plan B s'il pleut.", options = listOf(), answers = listOf("sil pleut on reporte a dimanche", "s'il pleut on va a dimanche"), explain = "si + présent + plan.")), skills = listOf("grammar:going-to", "function:make-future-plans", "vocab:social-expressions", "grammar:present-questions"), canDo = listOf("make-future-plans"), prerequisites = listOf("grammar:going-to"))))
}

object FrFoundationsU3 {
    val unit = CourseUnit(id = "fr-foundations-u3", title = "Le passé", subtitle = "Qu'est-ce que tu as fait ?", level = "A2", themes = listOf(ConversationTheme("weekend-passe", "Le week-end passé", "Passé composé", "clock.arrow.circlepath", "Course", "Vous racontez votre week-end : sorties, repas, rencontres — au passé composé.", 0),
                ConversationTheme("voyage-dernier", "Le voyage de l'année dernière", "Se souvenir", "airplane", "Course", "Un voyage mémorable : où vous êtes allé, ce que vous avez vu.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u3-passe-compose", title = "Le passé composé", goal = "Raconter des actions terminées avec avoir/être + participe passé.", intro = LessonIntro(explanation = listOf("Le passé composé = auxiliaire (avoir ou être) + participe passé. « J'ai mangé. Elle est allée. »", "La plupart des verbes prennent avoir. Les verbes de mouvement (aller, venir, partir) prennent être.", "Avec être, le participe s'accorde : « Elle est allée » (féminin + e), « Ils sont allés » (masculin pluriel + s)."), examples = listOf(ExampleLine(text = "J'ai mangé une paella hier.", meaning = "avoir + mangé."), ExampleLine(text = "Elle est allée au cinéma.", meaning = "être + allée (féminin)."), ExampleLine(text = "Nous avons vu un film.", meaning = "avoir + vu (voir → vu)."), ExampleLine(text = "Ils sont partis tôt.", meaning = "être + partis (pluriel)."), ExampleLine(text = "Tu as fait tes devoirs ?", meaning = "avoir + fait (faire → fait)."))), expressions = listOf(TargetExpression(text = "j'ai / tu as / il a + pp", meaning = "avoir + participe.", note = "J'ai mangé."), TargetExpression(text = "je suis / elle est + pp", meaning = "Être pour mouvement.", note = "Je suis allé(e)."), TargetExpression(text = "fait / dit / vu / écrit", meaning = "Participes irréguliers.", note = "faire → fait."), TargetExpression(text = "accord avec être", meaning = "e/s selon le sujet.", note = "elle est allée, ils sont allés."), TargetExpression(text = "hier / la semaine dernière", meaning = "Marqueurs de temps.", note = "Hier, j'ai vu…")), situation = "Vous racontez votre week-end : ce que vous avez fait, avec qui, et une surprise.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Dis une action du week-end. (manger au restaurant)", expected = listOf("J'ai ma