    Lesson(id = "fr-b1-antes-ahora", title = "Avant et maintenant", goal = "Opposer le passé et le présent avec l'imparfait et les connecteurs.", intro = LessonIntro(explanation = listOf("L'imparfait peint le passé régulier : « Avant, j'habitais en ville. »", "L'opposition : « Avant… maintenant… ». « Avant je fumais, maintenant je cours. »", "Les connecteurs : « mais », « parce que », « donc ». « C'était fatigant, donc j'ai déménagé. »"), examples = listOf(ExampleLine(text = "Avant, j'habitais en ville.", meaning = "imparfait du passé."), ExampleLine(text = "Maintenant, je vis à la campagne.", meaning = "présent contrasté."), ExampleLine(text = "Avant je fumais, maintenant je cours.", meaning = "Changement de vie."), ExampleLine(text = "C'était fatigant, donc j'ai déménagé.", meaning = "donc = conséquence."), ExampleLine(text = "Je préfère ma vie actuelle, parce que…", meaning = "parce que = cause."))), expressions = listOf(TargetExpression(text = "Avant, j'…-ais", meaning = "imparfait.", note = "j'habitais, je faisais."), TargetExpression(text = "maintenant, je …", meaning = "présent.", note = "maintenant je vis…"), TargetExpression(text = "mais / donc / parce que", meaning = "Connecteurs.", note = "mais = contraste."), TargetExpression(text = "je préfère …", meaning = "Opinion.", note = "je préfère ma vie…"), TargetExpression(text = "C'était + adjectif", meaning = "Cadre du passé.", note = "C'était calme.")), situation = "Vous comparez la vie d'avant et d'aujourd'hui : la ville et la campagne, le travail et le temps libre, et pourquoi vous avez changé.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Dis qu'avant tu habitais en ville.", expected = listOf("Avant j'habitais en ville.", "Avant, j'habitais en ville."), focus = "imparfait", watch = "-ais : j'habitais."), PracticeQuestion(prompt = "Dis que maintenant tu vis à la campagne.", expected = listOf("Maintenant je vis à la campagne.", "Maintenant, je vis à la campagne."), focus = "maintenant", watch = "présent pour maintenant."), PracticeQuestion(prompt = "Oppose : avant tu fumais, maintenant tu cours.", expected = listOf("Avant je fumais maintenant je cours.", "Avant, je fumais, maintenant je cours."), focus = "avant/maintenant", watch = "deux temps opposés."), PracticeQuestion(prompt = "Donne la conséquence : c'était fatigant, donc tu as déménagé.", expected = listOf("C'était fatigant donc j'ai déménagé.", "C'était fatigant, donc j'ai déménagé."), focus = "donc", watch = "donc + conséquence."), PracticeQuestion(prompt = "Dis ce que tu préfères et pourquoi.", expected = listOf("Je préfère ma vie actuelle parce que je suis plus libre.", "Je préfère ma vie maintenant."), focus = "parce que", watch = "parce que + cause."))), exercises = listOf(Exercise(id = "fr-b1-antes-ahora-e1", kind = "choice", prompt = "Avant, j'___ en ville. (habiter, imparfait)", options = listOf("habitais", "habite", "ai habité", "habiterai"), answers = listOf("habitais"), explain = "imparfait : -ais."), Exercise(id = "fr-b1-antes-ahora-e2", kind = "gap", prompt = "C'était fatigant, ___ j'ai déménagé. (conséquence)", options = listOf(), answers = listOf("donc"), explain = "donc = conséquence."), Exercise(id = "fr-b1-antes-ahora-e3", kind = "order", prompt = "Oppose : avant je fumais, maintenant je cours.", options = listOf(), answers = listOf("Avant je fumais maintenant je cours"), explain = "avant + imparfait, maintenant + présent."), Exercise(id = "fr-b1-antes-ahora-e4", kind = "written", prompt = "Dis ce qui a changé : maintenant tu travailles de chez toi.", options = listOf(), answers = listOf("maintenant je travaille de chez moi", "maintenant je travaille chez moi"), explain = "maintenant + présent.")), skills = listOf("grammar:used-to", "grammar:connectors", "function:express-opinion"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:used-to"))))
