                ConversationTheme("fr-b2-marche", "Le marchandage", "Et si on se retrouvait à 50 ?", "handshake", "Course", "Vous négociez un achat d'occasion : offre, conditions, accord.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u7-hypothetique", title = "Si j'avais le temps…", goal = "Opiner sur l'irréel : si + imparfait, puis le conditionnel.", intro = LessonIntro(explanation = listOf("L'hypothèse irréelle : « Si j'avais plus de temps, je voyagerais plus ». Si + imparfait, puis conditionnel (-rais).", "Jamais « si + conditionnel » : on dit « si j'avais », pas « si j'aurais ».", "Pour conseiller avec tact : « À ta place, j'essaierais », « Ce n'est pas que je ne veux pas ; c'est que je ne peux pas »."), examples = listOf(ExampleLine(text = "Si j'avais plus de temps, je voyagerais plus.", meaning = "Irréel du présent."), ExampleLine(text = "À ta place, j'essaierais.", meaning = "Conseil avec tact."), ExampleLine(text = "Si je pouvais, je changerais de travail.", meaning = "pouvoir → pouvais / pourrais."), ExampleLine(text = "Et si on se voyait jeudi ?", meaning = "Proposition douce."), ExampleLine(text = "Ce n'est pas que je ne veux pas ; je ne peux pas.", meaning = "Nuance vouloir/pouvoir."))), expressions = listOf(TargetExpression(text = "si + imparfait, …-rais", meaning = "Hypothèse.", note = "Si j'avais…, je voyagerais."), TargetExpression(text = "avoir → avais", meaning = "Imparfait clé.", note = "Si j'avais le temps."), TargetExpression(text = "pouvoir → pouvais", meaning = "Imparfait clé.", note = "Si je pouvais, je le ferais."), TargetExpression(text = "à ta place, je …-rais", meaning = "Conseil.", note = "…j'essaierais."), TargetExpression(text = "et si + imparfait ?", meaning = "Proposition.", note = "Et si on essayait ?")), situation = "Vous débnez des plans impossibles : plus de temps, un autre métier, une autre ville — puis un vrai compromis pour ce mois-ci.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Ton hypo