                ConversationTheme("fr-b2-chronique", "Ta chronique", "D'un côté… de l'autre…", "pencil", "Course", "Vous écrivez une chronique sur la piétonnisation du centre.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u7-relatives", title = "La nouvelle que j'ai lue", goal = "Raconter l'actualité avec les relatives : qui, que, où, dont.", intro = LessonIntro(explanation = listOf("La relative précise le nom : « La nouvelle que j'ai lue dit que… », « Le journaliste qui l'a interviewé… ».", "« Où » pour les lieux : « La place où ils ont manifesté ». « Dont » remplit « de + qqch » : « l'affaire dont tout le monde parle ».", "Dans les infos, les relatives compressent : qui, où, quoi."), examples = listOf(ExampleLine(text = "La nouvelle que j'ai lue dit que…", meaning = "Relative objet."), ExampleLine(text = "Le journaliste qui l'a interviewé a démissionné.", meaning = "Relative sujet."), ExampleLine(text = "La place où ils ont manifesté est centrale.", meaning = "où + lieu."), ExampleLine(text = "L'affaire dont tout le monde parle a rebondi.", meaning = "dont = de + ça."), ExampleLine(text = "Tout ce que je sais vient de la radio.", meaning = "tout ce que + verbe."))), expressions = listOf(TargetExpression(text = "le/la que…", meaning = "Relative.", note = "la nouvelle que j'ai lue."), TargetExpression(text = "qui…", meaning = "Sujet/personne.", note = "qui l'a interviewé."), TargetExpression(text = "où…", meaning = "Lieu.", note = "la place où…"), TargetExpression(text = "dont…", meaning = "de + qqch.", note = "l'affaire dont…"), TargetExpression(text = "tout ce que…", meaning = "Généraliser.", note = "tout ce que je sais.")), situation = "Vous résumez une semaine d'actualité : l'histoire qui vous a marqué, la personne qui a parlé et le lieu où c'est arrivé.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Résume : la nouvelle que tu as lue dit que le musée agrandit ses horaires.", expected = listOf("La nouvelle que j'ai lue dit qu