    Lesson(id = "fr-foundations-u7-argumenter", title = "D'un côté… de l'autre…", goal = "Écrire et défendre une opinion structurée : thèse, arguments, concession, conclusion.", intro = LessonIntro(explanation = listOf("Structure : thèse (« Je pense qu'on devrait piétonniser le centre »), arguments (« d'un côté…, de l'autre… »), concession (« c'est vrai que…, mais… »).", "La concession crédibilise : tu reconnais l'argument adverse avant de le répondre.", "Conclusion avec poids : « Pour tout cela, je défends la mesure »."), examples = listOf(ExampleLine(text = "Je pense qu'on devrait piétonniser le centre.", meaning = "Thèse."), ExampleLine(text = "D'un côté, la pollution baisse.", meaning = "Argument 1."), ExampleLine(text = "De l'autre, le commerce souffre.", meaning = "Argument 2 (contraire)."), ExampleLine(text = "C'est vrai que c'est gênant, mais les chiffres disent autre chose.", meaning = "Concession + réponse."), ExampleLine(text = "Pour tout cela, je défends la mesure.", meaning = "Conclusion."))), expressions = listOf(TargetExpression(text = "je pense qu'on devrait…", meaning = "Thèse.", note = "…piétonniser."), TargetExpression(text = "d'un côté… de l'autre…", meaning = "Arguments.", note = "les deux faces."), TargetExpression(text = "c'est vrai que…, mais…", meaning = "Concession.", note = "reconnaître puis répondre."), TargetExpression(text = "les chiffres disent…", meaning = "Preuve.", note = "argument d'autorité."), TargetExpression(text = "pour tout cela, …", meaning = "Conclusion.", note = "registre soutenu.")), situation = "Vous écrivez une chronique d'opinion sur la piétonnisation du centre : thèse, deux faces, concession et conclusion.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Thèse : je pense qu'on devrait piétonniser le centre.", expected = listOf("Je pense qu'on devrait pietonniser le centre", "Je pense qu'on devrait piétonniser le centre"), focus = "je pense que", watch = "Thèse + devoir."), PracticeQuestion(prompt = "Argument 1 : d'un côté, la pollution baisse.", expected = listOf("D'un cote la pollution baisse", "D'un côté, la pollution baisse"), focus = "d'un côté", watch = "Premier argument."), PracticeQuestion(prompt = "Argument contraire : de l'autre, le commerce souffre.", expected = listOf("De l'autre le commerce souffre", "De l'autre, le commerce souffre"), focus = "de l'autre", watch = "Seconde face."), PracticeQuestion(prompt = "Concède : c'est vrai que c'est gênant, mais les chiffres disent autre chose.", expected = listOf("C'est vrai que c'est genant mais les chiffres disent autre chose", "C'est vrai que c'est gênant, mais les chiffres disent autre chose"), focus = "c'est vrai que", watch = "Concession + mais."), PracticeQuestion(prompt = "Conclus : pour tout cela, je défends la mesure.", expected = listOf("Pour tout cela je defends la mesure", "Pour tout cela, je défends la mesure"), focus = "pour tout cela", watch = "Conclusion formelle."))), exercises = listOf(Exercise(id = "fr-foundations-u7-argumenter-e1", kind = "choice", prompt = "___ un côté, la pollution baisse.", options = listOf("D'", "Pour", "Dans", "Par"), answers = listOf("D'"), explain = "d'un côté = premier argument."), Exercise(id = "fr-foundations-u7-argumenter-e2", kind = "gap", prompt = "C'est vrai que c'est gênant, ___ les chiffres disent autre chose.", options = listOf(), answers = listOf("mais"), explain = "Concession + contraste."), Exercise(id = "fr-foundations-u7-argumenter-e3", kind = "order", prompt = "Conclusion : pour tout cela, je défends la mesure.", options = listOf(), answers = listOf("Pour tout cela, je défends la mesure"), explain = "pour tout cela."), Exercise(id = "fr-foundations-u7-argumenter-e4", kind = "written", prompt = "Ta thèse sur l'extension du tramway.", options = listOf(), answers = listOf("je pense qu'on devrait prolonger le tramway", "je pense qu'on devrait agrandir le tram"), explain = "Je pense qu'on devrait…")), skills = listOf("writing:argument", "grammar:connectors", "function:express-opinion", "speaking:justify-opinion"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:connectors"))))
