    val unit = CourseUnit(id = "fr-foundations-u9", title = "Nuances et registres", subtitle = "Le dire mieux", level = "C1", themes = listOf(ConversationTheme("fr-c1-registres", "Les registres", "Soutenu ou familier", "sparkles", "Course", "Vous réécrivez un e-mail trop familier, puis un e-mail trop raide, jusqu'à trouver le ton juste.", 0),
                ConversationTheme("fr-c1-nuancer", "Nuancer", "Plus ou moins", "bubble-left-and-text", "Course", "En réunion, tout le monde tranche ; vous, vous accordez, conditionnez et modulez sans vous contredire.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u9-registre", title = "Comment le dire", goal = "Choisir le bon registre : du e-mail soutenu à la remarque orale, sans fausse note.", intro = LessonIntro(explanation = listOf("Le registre se joue d'abord sur les verbes : « Je me permets de vous écrire » (soutenu) remplace « Je t'envoie un mot » (familier).", "À l'écrit professionnel, le « vous » est la règle et les tournures nommées montent le ton : « bien vouloir », « je vous prie de ».", "Les connecteurs trahissent le registre : « néanmoins », « toutefois », « par ailleurs » tiennent la longueur d'phrase ; « du coup », « genre » la plombent."), examples = listOf(ExampleLine(text = "Je me permets de vous écrire au sujet de votre annonce.", meaning = "Ouverture formelle d'e-mail."), ExampleLine(text = "Je vous prie de bien vouloir me répondre d'ici vendredi.", meaning = "Demande très polie (soutenu)."), ExampleLine(text = "Nous avons toutefois constaté un léger retard.", meaning = "Concession en registre soutenu."), ExampleLine(text = "Par ailleurs, le prix de la livraison a augmenté.", meaning = "Argument supplémentaire (soutenu)."), ExampleLine(text = "Je reste à votre disposition pour toute question.", meaning = "Formule de clôture d'e-mail."))), expressions = listOf(TargetExpression(text = "je me permets de + infinitif", meaning = "Ouvrir un e-mail.", note = "Jamais « je te permets » à un inconnu."), TargetExpression(text = "je vous prie de bien vouloir…", meaning = "Demander avec égards.", note = "…me répondre d'ici vendredi."), TargetExpression(text = "néanmoins / toutefois", meaning = "« Mais » en soutenu.", note = "Nous avons toutefois un doute."), TargetExpression(text = "par ailleurs", meaning = "Ajouter un argument.", note = "Remplace « 