    val unit = CourseUnit(id = "fr-foundations-u10", title = "Ma maison", subtitle = "Mon espace", level = "A1", themes = listOf(ConversationTheme("visite-appart", "La visite de l'appart", "Il y a / il n'y a pas", "house", "Course", "Vous visitez un petit appartement du quartier : les pièces, les meubles, et ce qui manque.", 0),
                ConversationTheme("coloc-recherche", "La colocation", "Mon, ma, mes", "bed", "Course", "Karim arrive avec ses cartons : sa chambre, ses livres — et vous présentez vos choses.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u10-maison", title = "Mon appart", goal = "Dire ce qu'il y a chez toi : les pièces et les meubles avec il y a.", intro = LessonIntro(explanation = listOf("Pour dire ce qui existe, on utilise « il y a » : « Il y a une grande cuisine. Il y a deux chambres. »", "Un, une pour le singulier, des pour le pluriel : « Il y a un canapé, une table, des chaises. »", "La négation : « Il n'y a pas de garage. » Devant une voyelle, de devient d' : « Il n'y a pas d'ascenseur. »"), examples = listOf(ExampleLine(text = "Il y a une grande cuisine.", meaning = "La pièce pour cuisiner."), ExampleLine(text = "Il y a deux chambres.", meaning = "La pièce pour dormir."), ExampleLine(text = "Dans le salon, il y a un canapé.", meaning = "Les meubles du salon."), ExampleLine(text = "Il y a des chaises dans la cuisine.", meaning = "Le pluriel avec des."), ExampleLine(text = "Il n'y a pas d'ascenseur.", meaning = "La négation avec d'."))), expressions = listOf(TargetExpression(text = "Il y a + un / une / des", meaning = "Dire ce qui existe.", note = "Il y a un lit dans la chambre."), TargetExpression(text = "Il n'y a pas de …", meaning = "La négation.", note = "pas de garage ; pas d'ascenseur."), TargetExpression(text = "la salle de bains", meaning = "La pièce pour se laver.", note = "les toilettes, c'est à côté."), TargetExpression(text = "un deux-pièces", meaning = "Un petit appartement.", note = "une pièce = une chambre."), TargetExpression(text = "C'est grand / petit.", meaning = "La taille.", note = "C'est petit mais clair.")), situation = "Vous visitez un petit appartement : deux pièces, une cuisine claire, pas d'ascenseur — et vous demandez s'il y a un balcon.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Dis ce qu'il y a dans ta cuisine.", expected = listOf("Il y a une table et des chaises.", "Dans ma cuisine, il y a une table et des chaises."), focus = "il y a", watch = "des pour le pluriel."), PracticeQuestion(prompt = "L'immeuble n'a pas de place pour la voiture. Dis-le.", expected = listOf("Il n'y a pas de garage.", "Il n'y a pas de parking."), focus = "pas de", watch = "négation : pas DE + nom."), PracticeQuestion(prompt = "Demandez au propriétaire s'il y a un balcon.", expected = listOf("Il y a un balcon ?", "Est-ce qu'il y a un balcon ?"), focus = "question", watch = "est-ce que + il y a."), PracticeQuestion(prompt = "Dis ce qu'il y a dans ta chambre.", expected = listOf("Il y a un lit et une armoire.", "Il y a un lit et un bureau."), focus = "la chambre", watch = "un lit, une armoire."), PracticeQuestion(prompt = "L'appartement est au cinquième étage. Dis que l'immeuble n'a pas d'ascenseur.", expected = listOf("Il n'y a pas d'ascenseur.", "Il n'y a pas d'ascenseur dans l'immeuble."), focus = "d'ascenseur", watch = "de devient d' devant une voyelle."))), exercises = listOf(Exercise(id = "fr-foundations-u10-maison-e1", kind = "choice", prompt = "___ ___ une grande cuisine dans ton appart ?", options = listOf("Il y a", "Il est", "C'est", "Elle a"), answers = listOf("Il y a"), explain = "il y a = il existe ; il est = identité."), Exercise(id = "fr-foundations-u10-maison-e2", kind = "gap", prompt = "Dans la chambre, il y a ___ grand lit.", options = listOf(), answers = listOf("un"), explain = "un lit : masculin singulier."), Exercise(id = "fr-foundations-u10-maison-e3", kind = "order", prompt = "Décrivez la cuisine.", options = listOf(), answers = listOf("Il y a une table dans la cuisine"), explain = "il y a + article + nom + lieu."), Exercise(id = "fr-foundations-u10-maison-e4", kind = "written", prompt = "Dis ce qu'il y a dans le salon : un canapé bleu et une télé.", options = listOf(), answers = listOf("il y a un canapé bleu et une télé", "il y a un canape bleu et une tele"), explain = "il y a + un/une + meuble.")), skills = listOf("grammar:there-is-are", "grammar:present-simple", "vocab:home", "function:ask-simple-questions"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "fr-foundations-u10-endroits", title = "Où est-ce ?", goal = "Situer les objets : sur, sous, à côté de — et demander où est la chose.", intro = LessonIntro(explanation = listOf("Les mots de lieu : « sur » (en haut) et « sous » (en bas) : « Le chat est sur le lit. Les clés sont sous la table. »", "« À côté de » dit la proximité : « à côté du canapé » (le), « à côté de la fenêtre » (la), « à côté des livres » (les).", "Pour demander : « Où est le chat ? » (un seul objet), « Où sont les clés ? » (plusieurs objets)."), examples = listOf(ExampleLine(text = "Le chat est sur le lit.", meaning = "En haut du lit."), ExampleLine(text = "Les clés sont sous la table.", meaning = "En bas de la table."), ExampleLine(text = "La lampe est à côté du canapé.", meaning = "Près du canapé."), ExampleLine(text = "Où est la salle de bains ?", meaning = "Demander une pièce."), ExampleLine(text = "Où sont mes clés ?", meaning = "Plusieurs objets."))), expressions = listOf(TargetExpression(text = "sur", meaning = "En haut.", note = "sur le lit, sur la table."), TargetExpression(text = "sous", meaning = "En bas.", note = "sous le canapé."), TargetExpression(text = "à côté de / du / de la", meaning = "Près.", note = "à côté du frigo."), TargetExpression(text = "Où est … ?", meaning = "Un seul objet.", note = "Où est le chat ?"), TargetExpression(text = "Où sont … ?", meaning = "Plusieurs objets.", note = "Où sont les clés ?")), situation = "Le chat joue à cache-cache dans l'appartement : sur le lit, sous la table, à côté du frigo — et vous cherchez aussi vos clés.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Le chat est en haut du lit. Dis-le avec sur.", expected = listOf("Le chat est sur le lit.", "Il est sur le lit."), focus = "sur", watch = "sur = en haut de."), PracticeQuestion(prompt = "Les chaussures sont en bas du lit. Dis-le avec sous.", expected = listOf("Les chaussures sont sous le lit.", "Elles sont sous le lit."), focus = "sous", watch =