    Lesson(id = "fr-foundations-u10-coloc", title = "Mon colocataire", goal = "Présenter ton colocataire et parler de tes choses avec mon, ma, mes.", intro = LessonIntro(explanation = listOf("mon, ma, mes disent à qui est la chose : « mon frère, ma sœur, mes amis. »", "mon devant un mot masculin, ma devant un mot féminin, mes au pluriel : « mon colocataire, ma chambre, mes meubles. »", "Pour décrire une personne : « Il est grand et sympa. » « Elle est très gentille. »"), examples = listOf(ExampleLine(text = "Mon colocataire s'appelle Karim.", meaning = "mon + masculin."), ExampleLine(text = "Ma chambre est petite mais claire.", meaning = "ma + féminin."), ExampleLine(text = "Mes voisins sont très gentils.", meaning = "mes + pluriel."), ExampleLine(text = "Karim est grand et sympa.", meaning = "La description."), ExampleLine(text = "Il aime la musique et le foot.", meaning = "Les goûts."))), expressions = listOf(TargetExpression(text = "mon …", meaning = "Possessif masculin.", note = "mon frère, mon colocataire."), TargetExpression(text = "ma …", meaning = "Possessif féminin.", note = "ma chambre, ma sœur."), TargetExpression(text = "mes …", meaning = "Possessif pluriel.", note = "mes amis, mes clés."), TargetExpression(text = "Il est / Elle est …", meaning = "Décrire quelqu'un.", note = "Elle est très sympa."), TargetExpression(text = "Il / Elle aime …", meaning = "Les goûts.", note = "Il aime le foot.")), situation = "Karim arrive avec ses cartons : sa chambre, ses livres, sa guitare — et vous présentez vos choses à lui.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Présente ton colocataire : il s'appelle Karim.", expected = listOf("Mon colocataire s'appelle Karim.", "Mon colocataire, c'est Karim."), focus = "mon", watch = "colocataire = mot masculin."), PracticeQuestion(prompt = "Ta chambre est petite. Dis-le avec mon, ma ou mes.", expected = listOf("Ma chambre est petite.", "Ma chambre est vraiment petite."), focus = "ma", watch = "chambre = féminin : ma."), PracticeQuestion(prompt = "Tes amis sont gentils. Dis-le avec mon, ma ou mes.", expected = listOf("Mes amis sont gentils.", "Mes amis sont très gentils."), focus = "mes", watch = "pluriel : mes."), PracticeQuestion(prompt = "Comment est Karim ? Donnez deux qualités.", expected = listOf("Il est grand et sympa.", "Karim est grand et sympa."), focus = "description", watch = "il/elle est + adjectif."), PracticeQuestion(prompt = "Dis ce qu'aime ta colocataire Léa : la musique.", expected = listOf("Elle aime la musique.", "Léa aime la musique.", "Lea aime la musique."), focus = "elle aime", watch = "elle + aime + activité."))), exercises = listOf(Exercise(id = "fr-foundations-u10-coloc-e1", kind = "choice", prompt = "___ chambre est en désordre, désolé !", options = listOf("Ma", "Mon", "Mes", "Me"), answers = listOf("Ma"), explain = "chambre = féminin : ma."), Exercise(id = "fr-foundations-u10-coloc-e2", kind = "gap", prompt = "J'habite avec ___ deux frères.", options = listOf(), answers = listOf("mes"), explain = "frères = pluriel : mes."), Exercise(id = "fr-foundations-u10-coloc-e3", kind = "order", prompt = "Présente ta colocataire et son caractère.", options = listOf(), answers = listOf("Ma colocataire est grande et sympa"), explain = "ma + nom + être + adjectif."), Exercise(id = "fr-foundations-u10-coloc-e4", kind = "written", prompt = "Décris ta colocataire Léa.", options = listOf(), answers = listOf("elle est grande et gentille", "léa est grande et gentille"), explain = "elle est + adjectifs.")), skills = listOf("grammar:possessives", "function:describe-people", "vocab:home", "grammar:present-simple"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:possessives"))))
