    val unit = CourseUnit(id = "fr-foundations-u11", title = "Mon quartier", subtitle = "Près de chez moi", level = "A1", themes = listOf(ConversationTheme("carte-du-quartier", "La carte du quartier", "Les lieux utiles", "map", "Course", "Vous cherchez les lieux du quartier : boulangerie, pharmacie, banque, parc et gare.", 0),
                ConversationTheme("le-primeur", "Le primeur du coin", "Fruits et légumes", "cart", "Course", "Chez le primeur du quartier : vous choisissez vos fruits et vous payez.", 1)), lessons = listOf(    Lesson(id = "fr-foundations-u11-lieux", title = "Y a-t-il un supermarché ?", goal = "Demander ce qu'il y a dans le quartier avec est-ce qu'il y a.", intro = LessonIntro(explanation = listOf("Pour demander un lieu : « Est-ce qu'il y a un supermarché près d'ici ? » Ou plus court : « Il y a une boulangerie ici ? »", "La réponse : « Oui, il y en a une à côté. » Négatif : « Non, il n'y en a pas. »", "Les lieux du quartier : la boulangerie, la pharmacie, la banque, la gare, le parc."), examples = listOf(ExampleLine(text = "Est-ce qu'il y a une boulangerie près d'ici ?", meaning = "Demander un lieu."), ExampleLine(text = "Oui, il y en a une à côté.", meaning = "Réponse affirmative."), ExampleLine(text = "Non, il n'y en a pas.", meaning = "Réponse négative."), ExampleLine(text = "Il y a un parc près de la gare.", meaning = "Situer deux lieux."), ExampleLine(text = "La pharmacie est ouverte le dimanche ?", meaning = "Une question utile."))), expressions = listOf(TargetExpression(text = "Est-ce qu'il y a … ?", meaning = "Demander un lieu.", note = "…un supermarché près d'ici ?"), TargetExpression(text = "près d'ici", meaning = "À quelques minutes.", note = "près d'ici = tout proche."), TargetExpression(text = "il y en a un / une", meaning = "Répondre oui.", note = "une boulangerie → il y en a une."), TargetExpression(text = "il n'y en a pas", meaning = "Répondre non.", note = "= il n'y a pas de lieu."), TargetExpression(text = "la boulangerie", meaning = "Le pain du quartier.", note = "la pharmacie : les médicaments.")), situation = "Vous êtes nouveau dans le quartier : vous cherchez une boulangerie, une pharmacie et un endroit pour courir.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Demandez s'il y a une boulangerie près d'ici.", expected = listOf("Est-ce qu'il y a une boulangerie près d'ici ?", "Il y a une boulangerie près d'ici ?", "Est-ce qu'il y a une boulangerie pres d'ici ?"), focus = "est-ce qu'il y a", watch = "est-ce que + il y a."), PracticeQuestion(prompt = "La pharmacie est dans la rue d'à côté. Répondez oui.", expected = listOf("Oui, il y en a une à côté.", "Oui, il y a une pharmacie à côté.", "Oui, il y en a une a cote."), focus = "il y en a", watch = "une pharmacie → il y en a une."), PracticeQuestion(prompt = "Il n'y a pas de banque ici. Répondez négativement.", expected = listOf("Non, il n'y en a pas.", "Non, il n'y a pas de banque."), focus = "négation", watch = "en = de ce lieu."), PracticeQuestion(prompt = "Demandez s'il y a un parc dans le quartier.", expected = listOf("Est-ce qu'il y a un parc dans le quartier ?", "Il y a un parc dans le quartier ?"), focus = "un parc", watch = "un parc : masculin singulier."), PracticeQuestion(prompt = "Situez la gare : elle est proche du parc.", expected = listOf("La gare est près du parc.", "Elle est près du parc.", "La gare est pres du parc."), focus = "près de", watch = "près du (masc.), près de la (fém.)."))), exercises = listOf(Exercise(id = "fr-foundations-u11-lieux-e1", kind = "choice", prompt = "___ ___ ___ une pharmacie près d'ici ?", options = listOf("Est-ce qu'il y a", "Est-ce qu'il est", "Est-ce que c'est", "Il y est"), answers = listOf("Est-ce qu'il y a"), explain = "il y a pour dire l'existence d'un lieu."), Exercise(id = "fr-foundations-u11-lieux-e2", kind = "gap", prompt = "Oui, il y en ___ une, à côté de la banque.", options = listOf(), answers = listOf("a"), explain = "il y en a une = elle existe."), Exercise(id = "fr-foundations-u11-lieux-e3", kind = "order", prompt = "Demandez un parc dans le quartier.", options = listOf(), answers = listOf("Il y a un parc dans le quartier"), explain = "il y a + article + lieu."), Exercise(id = "fr-foundations-u11-lieux-e4", kind = "written", prompt = "La banque est loin. Dites qu'il n'y en