    Lesson(id = "fr-foundations-u11-directions", title = "Comment y aller ?", goal = "Demander le chemin et comprendre : tout droit, à gauche, à droite.", intro = LessonIntro(explanation = listOf("Pour demander le chemin : « Pardon, où est la gare ? Comment y aller ? »", "Les directions à l'impératif : « Allez tout droit. Tournez à gauche au feu. Tournez à droite après la boulangerie. »", "La distance : « C'est près. C'est à cinq minutes à pied. »"), examples = listOf(ExampleLine(text = "Pardon, où est la gare ?", meaning = "Attirer l'attention."), ExampleLine(text = "Allez tout droit.", meaning = "Ne tournez pas."), ExampleLine(text = "Tournez à gauche au feu.", meaning = "Le carrefour."), ExampleLine(text = "C'est à cinq minutes à pied.", meaning = "La distance à pied."), ExampleLine(text = "C'est près de la boulangerie.", meaning = "Un lieu connu pour situer."))), expressions = listOf(TargetExpression(text = "Comment y aller ?", meaning = "Demander le chemin.", note = "y = à ce lieu."), TargetExpression(text = "Allez tout droit.", meaning = "La direction.", note = "tout droit = en ligne."), TargetExpression(text = "Tournez à gauche / à droite.", meaning = "Le carrefour.", note = "au feu, après la banque."), TargetExpression(text = "à … minutes à pied", meaning = "La distance.", note = "à cinq minutes à pied."), TargetExpression(text = "C'est près / loin.", meaning = "Près ou loin.", note = "près = à côté.")), situation = "Un touriste vous demande la gare : tout droit, à gauche au feu — cinq minutes à pied, c'est près.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Un inconnu vous arrête. Demandez la gare.", expected = listOf("Pardon, où est la gare ?", "Où est la gare, s'il vous plaît ?", "Ou est la gare, s'il vous plait ?"), focus = "où est", watch = "où est + lieu ?"), PracticeQuestion(prompt = "Guidez quelqu'un : la rue continue tout droit. Employez l'impératif.", expected = listOf("Allez tout droit.", "Vous allez tout droit."), focu