    Lesson(id = "fr-foundations-u11-fruitier", title = "Chez le primeur", goal = "Acheter des fruits au primeur du quartier : quantités et prix.", intro = LessonIntro(explanation = listOf("Au primeur, on commande avec la quantité : « Je voudrais un kilo de pommes. Deux cents grammes de fraises. »", "Le vendeur propose : « Vous désirez ? Avec ceci ? » On répond : « C'est tout, merci. »", "Le prix : « C'est combien, les fraises ? » — « Ça fait trois euros. »"), examples = listOf(ExampleLine(text = "Bonjour, je voudrais un kilo de pommes.", meaning = "La commande."), ExampleLine(text = "Je prends aussi deux bananes.", meaning = "Ajouter un article."), ExampleLine(text = "C'est combien, les fraises ?", meaning = "Le prix."), ExampleLine(text = "Avec ceci ?", meaning = "Le vendeur propose."), ExampleLine(text = "Ça fait trois euros.", meaning = "Le total."))), expressions = listOf(TargetExpression(text = "Je voudrais + quantité", meaning = "Commander.", note = "un kilo de pommes."), TargetExpression(text = "Je prends …", meaning = "Choisir.", note = "Je prends deux bananes."), TargetExpression(text = "C'est combien, … ?", meaning = "Le prix.", note = "…les fraises ?"), TargetExpression(text = "Avec ceci ?", meaning = "Le vendeur propose.", note = "= autre chose ?"), TargetExpression(text = "C'est tout, merci.", meaning = "Terminer l'achat.", note = "= rien d'autre.")), situation = "Samedi matin, chez le primeur du quartier : un kilo de pommes, deux bananes — et vous demandez le prix des fraises.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Commandez un kilo de pommes.", expected = listOf("Je voudrais un kilo de pommes.", "Un kilo de pommes, s'il vous plaît.", "Un kilo de pommes, s'il vous plait."), focus = "je voudrais", watch = "je voudrais + quantité + produit."), PracticeQuestion(prompt = "Demandez le prix des fraises.", expected = listOf("C'est combien, les fraises ?", "C'est combien les fraises ?"), focus = "combien", watch = "c'est combien + article + fruit."), PracticeQuestion(prompt = "Ajoutez deux bananes à votre commande.", expected = listOf("Je prends deux bananes.", "Et deux bananes, aussi."), focus = "je prends", watch = "je prends = je choisis."), PracticeQuestion(prompt = "Le vendeur propose encore quelque chose. Refusez poliment.", expected = listOf("C'est tout, merci.", "C'est tout merci.", "Rien d'autre, merci."), focus = "c'est tout", watch = "= je ne veux rien d'autre."), PracticeQuestion(prompt = "Dites le total : trois euros.", expected = listOf("Ça fait trois euros.", "Ca fait trois euros."), focus = "ça fait", watch = "ça fait + prix."))), exercises = listOf(Exercise(id = "fr-foundations-u11-fruitier-e1", kind = "choice", prompt = "Bonjour, madame, je ___ un kilo de pommes, s'il vous plaît.", options = listOf("voudrais", "vouloir", "voudra", "voulu"), answers = listOf("voudrais"), explain = "je voudrais : la forme polie de vouloir."), Exercise(id = "fr-foundations-u11-fruitier-e2", kind = "gap", prompt = "C'est ___ , les fraises ?", options = listOf(), answers = listOf("combien"), explain = "c'est combien = demandez le prix."), Exercise(id = "fr-foundations-u11-fruitier-e3", kind = "order", prompt = "Commandez deux bananes.", options = listOf(), answers = listOf("Je voudrais deux bananes"), explain = "je voudrais + quantité + fruit."), Exercise(id = "fr-foundations-u11-fruitier-e4", kind = "written", prompt = "Refusez poliment la proposition du vendeur.", options = listOf(), answers = listOf("c'est tout merci", "c'est tout, merci.", "rien d'autre, merci."), explain = "formule fixe pour terminer.")), skills = listOf("function:go-shopping", "grammar:quantities", "vocab:food", "grammar:present-simple"), canDo = listOf("go-shopping"), prerequisites = listOf("grammar:present-simple"))))
