object ItFoundationsU1 {
    val unit = CourseUnit(id = "it-foundations-u1", title = "First sentences", subtitle = "Say who you are", level = "A1", themes = listOf(ConversationTheme("lang-exchange", "Language-exchange café", "Meet and greet", "person.2", "Course", "You are at a friendly language-exchange café in Roma. Meet the learner, exchange names, countries and jobs using the verb essere.", 0),
                ConversationTheme("introductions", "Nice to meet you", "Start somewhere small", "hand.wave", "Connection", "Meet the learner for the first time. Learn their interests through natural introductions.", 1)), lessons = listOf(    Lesson(id = "it-foundations-u1-essere", title = "The verb “essere”", goal = "Introduce yourself and say who people are with sono, sei, è, siamo, siete, sono.", intro = LessonIntro(explanation = listOf("Every Italian sentence needs a subject and a verb. The verb for saying who you are is “essere”.", "Six forms: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono. Italian often drops the subject: “Sono Ana” already means I am Ana.", "Use essere for identity and origin: “Sono di Roma”, “È insegnante”. Put “di” before a city: “Sono di Roma”."), examples = listOf(ExampleLine(text = "Sono Ana. Sono di Italia.", meaning = "Your name and country."), ExampleLine(text = "Sei il mio migliore amico.", meaning = "A close bond with someone."), ExampleLine(text = "Lei è insegnante.", meaning = "Someone's profession."), ExampleLine(text = "Siamo molto felici oggi.", meaning = "A feeling that defines right now."), ExampleLine(text = "Il caffè è vicino alla stazione.", meaning = "Where a place is."), ExampleLine(text = "Loro sono di Milano.", meaning = "Someone's origin."))), expressions = listOf(TargetExpression(text = "Sono …", meaning = "Introduce yourself.", note = "With your name or job: Sono Ana. Sono insegnante."), TargetExpression(text = "Sono di …", meaning = "Say where you come from.", note = "Never “Sono Italia” — the di is obligatory: Sono di Roma."), TargetExpression(text = "Sei … ?", meaning = "Ask about the other person.", note = "Sei studente? Sei di qui?"), TargetExpression(text = "Sì, lo sono. / No, non lo sono.", meaning = "Short answers to a Sei… ? question.", note = "Repeat the verb through lo."), TargetExpression(text = "È …", meaning = "Say what someone else is.", note = "È medico — jobs often drop the article."), TargetExpression(text = "Piacere di conoscerti.", meaning = "The fixed phrase when you meet someone.", note = "Answer with Piacere mio, or simply Piacere.")), situation = "You meet someone new at a friendly language-exchange café in Roma. Introduce yourselves and ask simple questions with the verb essere.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Ciao! Sono Ana. Tu come ti chiami?", expected = listOf("Mi chiamo <name>.", "Sono <name>."), focus = "Mi chiamo / Sono", watch = "Answering only the name: accept it, then recast “Mi chiamo …”."), PracticeQuestion(prompt = "Di dove sei?", expected = listOf("Sono di <city>.", "Vengo da <city>."), focus = "essere + di", watch = "“Sono Roma” — recast “Sono DI Roma”."), PracticeQuestion(prompt = "Sei studente?", expected = listOf("Sì, lo sono.", "No, non lo sono."), focus = "short answers with essere", watch = "One-word “Sì” — recast with the verb."), PracticeQuestion(prompt = "Come stai, oggi?", expected = listOf("Sto bene.", "Sono stanco.", "Sono contento."), focus = "stare for feelings", watch = "“Sono bene” — recast “Sto bene”: feelings take stare here."), PracticeQuestion(prompt = "La tua città, è grande o piccola?", expected = listOf("È grande.", "È piccola.", "La mia città è …"), focus = "è with places", watch = "“La mia città grande” — recast “La mia città È grande”."), PracticeQuestion(prompt = "Ora siamo amici! Di dove è la tua famiglia?", expected = listOf("È di <country>.", "La mia famiglia è di <country>."), focus = "è for a group's origin", watch = "“La mia famiglia di …” — recast with è."))), exercises = listOf(Exercise(id = "it-foundations-u1-essere-e1", kind = "choice", prompt = "Lei ___ insegnante.", options = listOf("è", "sei", "sono", "siamo"), answers = listOf("è"), explain = "With lui/lei, essere becomes è."), Exercise(id = "it-foundations-u1-essere-e2", kind = "gap", prompt = "Noi ___ di Milano.", options = listOf(), answers = listOf("siamo"), explain = "With noi, essere is sempre siamo."), Exercise(id = "it-foundations-u1-essere-e3", kind = "order", prompt = "Say where you are from.", options = listOf(), answers = listOf("Sono di Roma"), explain = "Sono + di + city: Sono di Roma."), Exercise(id = "it-foundations-u1-essere-e4", kind = "written", prompt = "Introduce yourself in one sentence: say your name.", options = listOf(), answers = listOf("Mi chiamo <name>", "Sono <name>"), explain = "Mi chiamo Ana / Sono Ana — the subject can be dropped.")), skills = listOf("grammar:verb-be", "grammar:subject-pronouns", "function:describe-people", "speaking:short-answer"), canDo = listOf("describe-people"), prerequisites = listOf("grammar:verb-be")),
    Lesson(id = "it-foundations-u1-questions", title = "Questions & negatives", goal = "Ask yes/no questions and say what is not true, with Sei… ? and non sono.", intro = LessonIntro(explanation = listOf("Italian asks yes/no questions with rising intonation — same words, same order: “Sei Ana?”", "Question words go first: “Di dove sei?”, “Cosa è questo?” — and they carry their accents: perché, dove.", "To negate, put non before the verb: “Non sono Ana”, “Non siamo amici”. No second part is needed, unlike English."), examples = listOf(ExampleLine(text = "Sei insegnante?", meaning = "A yes/no question with sei."), ExampleLine(text = "Non sono di Milano.", meaning = "A negative with sono."), ExampleLine(text = "Di dove sei?", meaning = "Question word + sei."), ExampleLine(text = "Lui non è mio fratello.", meaning = "A negative about another person."), ExampleLine(text = "Siete vicini di casa?", meaning = "Asking a group."), ExampleLine(text = "Cosa è questo?", meaning = "What is this?"))), expressions = listOf(TargetExpression(text = "Sei … ?", meaning = "Ask a yes/no question.", note = "Just the marks and rising tone."), TargetExpression(text = "Non sono …", meaning = "Say what is not true about you.", note = "Non always goes before the verb."), TargetExpression(text = "Di dove sei?", meaning = "Ask where someone is from.", note = "Di dove, two words."), TargetExpression(text = "Lui non è …", meaning = "Say what someone else is not.", note = "Lui non è il mio capo."), TargetExpression(text = "Vero?", meaning = "Tag a statement to check it.", note = "Sei di qui, vero?"), TargetExpression(text = "Certo.", meaning = "The natural yes in talk.", note = "Also: Esatto.")), situation = "You chat with a new neighbour in the lift in Roma. Ask simple yes/no questions and say what is and isn't true for you.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Sei di qui?", expected = listOf("Sì, sono di qui.", "No, non sono di qui."), focus = "short answers", watch = "One-word “Sì” — recast with the verb: Sì, sono di qui."), PracticeQuestion(prompt = "Sei insegnante o studente?", expected = listOf("Sono insegnante.", "Sono studente.", "Sono studentessa."), focus = "choice with essere", watch = "Accept either; the article stays dropped."), PracticeQuestion(prompt = "La tua famiglia è grande?", expected = listOf("Sì, è grande.", "No, non è grande."), focus = "è in questions about others", watch = "“Non è grande” — non before è."), PracticeQuestion(prompt = "Di dove sei, tu?", expected = listOf("Sono di <country>.", "Vengo da <country>."), focus = "di dove + sei", watch = "“Sono a Roma” for origin — recast with di."), PracticeQuestion(prompt = "Dimmi una cosa che non sei.", expected = listOf("Non sono <job>.", "Non sono di <country>."), focus = "negation with non sono", watch = "“Sono non” doesn't exist — non first."), PracticeQuestion(prompt = "Siamo amici, ora?", expected = listOf("Sì, siamo amici.", "Certo, siamo amici."), focus = "siamo in questions", watch = "“Sì, stiamo amici” mixes essere and stare — recast with siamo."))), exercises = listOf(Exercise(id = "it-foundations-u1-questions-e1", kind = "choice", prompt = "___ tu di Bologna?", options = listOf("Sei", "È", "Sono", "Siamo"), answers = listOf("Sei"), explain = "With tu, the question starts with Sei."), Exercise(id = "it-foundations-u1-questions-e2", kind = "gap", prompt = "Lei non ___ mia sorella.", options = listOf(), answers = listOf("è"), explain = "non + è: the negative keeps è."), Exercise(id = "it-foundations-u1-questions-e3", kind = "order", prompt = "Say you are not from Napoli.", options = listOf(), answers = listOf("Non sono di Napoli"), explain = "Non goes first: Non sono di Napoli."), Exercise(id = "it-foundations-u1-questions-e4", kind = "written", prompt = "Make it negative: \"Sono di Firenze.\"", options = listOf(), answers = listOf("Non sono di Firenze"), explain = "non + sono: Non sono di Firenze.")), skills = listOf("grammar:verb-be", "grammar:present-questions", "function:ask-simple-questions", "speaking:short-answer"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "it-foundations-u1-introduce", title = "Introducing yourself", goal = "Give a complete self-introduction: name, city, nationality and job.", intro = LessonIntro(explanation = listOf("A full Italian introduction has four pieces: your name, your city, your nationality and your job.", "For the name: “Mi chiamo Ana” or “Sono Ana”. For origin: “Sono di Roma”. Nationalities are lower-case: “sono italiana”.", "Jobs with essere drop the article: “Sono insegnante”. Close with “Piacere” and bounce the question back with “E tu?”"), examples = listOf(ExampleLine(text = "Mi chiamo Ana. Piacere.", meaning = "Your name plus a polite close."), ExampleLine(text = "Sono di Roma, del centro.", meaning = "City inside country."), ExampleLine(text = "Sono italiana, di Roma.", meaning = "Nationality plus city."), ExampleLine(text = "Sono infermiera in un ospedale.", meaning = "Job plus workplace."), ExampleLine(text = "Ho venticinque anni.", meaning = "Your age — with avere, not essere."), ExampleLine(text = "E tu? Che lavoro fai?", meaning = "Bounce the question back."))), expressions = listOf(TargetExpression(text = "Mi chiamo …", meaning = "Give your name.", note = "Literally “I call myself”. Also: Sono …"), TargetExpression(text = "Sono + nationality", meaning = "Say your nationality.", note = "italiana, tedesca, francese — lower-case in Italian."), TargetExpression(text = "Sono di …", meaning = "Say your city or country.", note = "Sono di Roma; Sono di Italia."), TargetExpression(text = "Lavoro in …", meaning = "Say where you work.", note = "Lavoro in un ospedale / in una scuola."), TargetExpression(text = "Piacere.", meaning = "Polite close when you meet someone.", note = "Answer: Piacere mio."), TargetExpression(text = "E tu?", meaning = "Bounce the question back.", note = "—Sono di Roma. E tu?")), situation = "Your first day at a language school in Roma. Present yourself completely to the class: name, city, nationality and job.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Come ti chiami?", expected = listOf("Mi chiamo <name>.", "Sono <name>."), focus = "name formulas", watch = "Both are fine; recast the shorter one as Mi chiamo for variety."), PracticeQuestion(prompt = "Di dove sei?", expected = listOf("Sono di <country>."), focus = "origin", watch = "Never drop di: Sono DI <country>."), PracticeQuestion(prompt = "Che nazionalità hai?", expected = listOf("Sono <nationality>."), focus = "nationality with essere", watch = "Lower-case: sono italiana, not Italiana."), PracticeQuestion(prompt = "Che lavoro fai?", expected = listOf("Sono <job>.", "Faccio <job>."), focus = "jobs without article", watch = "“Sono un insegnante” — recast dropping the article."), PracticeQuestion(prompt = "E dove abiti?", expected = listOf("Abito a <city>."), focus = "abito a", watch = "“Abito a Roma” — a for cities."), PracticeQuestion(prompt = "Piacere! E tu, che fai?", expected = listOf("Sono <job>."), focus = "bounce back and answer", watch = "Recast with Sono + job."))), exercises = listOf(Exercise(id = "it-foundations-u1-introduce-e1", kind = "choice", prompt = "___ Ana. Piacere.", options = listOf("Mi chiamo", "Mi chiamo di", "Chiamo", "Sto"), answers = listOf("Mi chiamo"), explain = "Mi chiamo + name: one piece, no di."), Exercise(id = "it-foundations-u1-introduce-e2", kind = "gap", prompt = "Sono ___ Germania. (nationality)", options = listOf(), answers = listOf("tedesca"), explain = "Nationality is lower-case: tedesca, tedesco."), Exercise(id = "it-foundations-u1-introduce-e3", kind = "order", prompt = "Say your name and city.", options = listOf(), answers = listOf("Sono Ana e sono di Roma"), explain = "Two sono pieces, both with their verb."), Exercise(id = "it-foundations-u1-introduce-e4", kind = "written", prompt = "Give your complete introduction: name and country.", options = listOf(), answers = listOf("Mi chiamo <name> e sono di <country>", "Sono <name> e sono di <country>"), explain = "Name + origin, each with its verb.")), skills = listOf("grammar:verb-be", "function:introduce-yourself", "vocab:introductions", "pron:word-stress"), canDo = listOf("introduce-yourself"))))
}

object ItFoundationsU2 {
    val unit = CourseUnit(id = "it-foundations-u2", title = "La mia giornata", subtitle = "Routine e progetti", level = "A1", themes = listOf(ConversationTheme("mattina-folle", "Mattina folle", "Contro la sveglia", "sunrise", "Course", "Racconti la tua mattina minuto per minuto: ore, abitudini e dimenticanze.", 0),
                ConversationTheme("sabato-insieme", "Sabato insieme", "Cosa facciamo?", "figure.walk", "Course", "Piani per sabato con un amico: mercato, ora e luogo dell'appuntamento.", 1)), lessons = listOf(    Lesson(id = "it-foundations-u2-routine", title = "La mia routine", goal = "Raccontare la giornata al presente con le ore.", intro = LessonIntro(explanation = listOf("Il presente racconta le abitudini: « Mi sveglio alle sette. Faccio colazione. Esco alle otto. »", "I verbi riflessivi portano mi/ti/si : « mi sveglio, mi faccio la doccia, mi addormento » — il pronombre fa parte del verbo.", "Le ore: « alle sette », « alle sette e mezza ». Con a : « alle otto esco »."), examples = listOf(ExampleLine(text = "Mi sveglio alle sette.", meaning = "Il primo verbo."), ExampleLine(text = "Faccio colazione con un caffè.", meaning = "La colazione come verbo."), ExampleLine(text = "Mi faccio la doccia ed esco alle otto.", meaning = "Due azioni di fila."), ExampleLine(text = "La domenica mi sveglio tardi.", meaning = "L'abitudine del weekend."), ExampleLine(text = "Mi addormento verso le undici.", meaning = "La sera, con verso."))), expressions = listOf(TargetExpression(text = "Mi sveglio alle …", meaning = "La sveglia.", note = "mi + sveglio: ins separabili."), TargetExpression(text = "Faccio colazione", meaning = "La colazione.", note = "fare colazione = desayunar."), TargetExpression(text = "Esco di casa alle …", meaning = "L'uscita.", note = "uscire di + luogo."), TargetExpression(text = "La domenica, …", meaning = "L'abitudine.", note = "la + giorno = ogni domenica."), TargetExpression(text = "Mi addormento verso …", meaning = "Il sonno.", note = "verso = sobre las.")), situation = "Racconti la tua mattina a un nuovo amico: sveglia, colazione, doccia, uscita — e come cambia la domenica.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di a che ora ti svegli in settimana.", expected = listOf("Mi sveglio alle <ora> in settimana."), focus = "mi sveglio", watch = "Il riflessivo porta mi: mi sveglio."), PracticeQuestion(prompt = "Di cosa fai colazione.", expected = listOf("Faccio colazione con <cibo>."), focus = "fare colazione", watch = "fare colazione = desayunar."), PracticeQuestion(prompt = "Di a che ora esci di casa.", expected = listOf("Esco di casa alle <ora>."), focus = "uscire di", watch = "uscire DI casa."), PracticeQuestion(prompt = "Di la tua abitudine della domenica.", expected = listOf("La domenica mi sveglio tardi."), focus = "la + giorno", watch = "la domenica = ogni domenica."), PracticeQuestion(prompt = "Di a che ora ti addormenti.", expected = listOf("Mi addormento verso le <ora>."), focus = "mi addormento", watch = "verso = sobre las."))), exercises = listOf(Exercise(id = "it-foundations-u2-routine-e1", kind = "choice", prompt = "Mi ___ alle sette tutti i giorni.", options = listOf("sveglio", "sveglio me", "sveglia", "svegliarmi"), answers = listOf("sveglio"), explain = "Mi sveglio: il pronome va davanti."), Exercise(id = "it-foundations-u2-routine-e2", kind = "gap", prompt = "___ colazione con un caffè. (fare colazione)", options = listOf(), answers = listOf("Faccio", "faccio"), explain = "fare colazione: io faccio."), Exercise(id = "it-foundations-u2-routine-e3", kind = "order", prompt = "Di a che ora esci.", options = listOf(), answers = listOf("Esco di casa alle otto"), explain = "esco di + luogo + alle + ora."), Exercise(id = "it-foundations-u2-routine-e4", kind = "written", prompt = "La tua abitudine della domenica.", options = listOf(), answers = listOf("la domenica mi sveglio tardi", "di domenica faccio colazione tardi"), explain = "la + giorno + presente.")), skills = listOf("grammar:present-simple", "grammar:time-expressions", "vocab:daily-routine", "function:talk-about-routines"), canDo = listOf("talk-about-routines"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "it-foundations-u2-quartiere", title = "Il mio quartiere", goal = "Dire cosa c'è nel tuo quartiere con c'è / ci sono.", intro = LessonIntro(explanation = listOf("C'è per uno, ci sono per tanti: « C'è un bar, ci sono due negozi ». Non cambia per le domande: « C'è una farmacia qui vicino? »", "Negativo: « Non c'è un cinema, mi dispiace ». Con non c'è il nome resta senza articolo.", "Locazioni: davanti a, vicino a, accanto a : « Il bar è davanti al parco ». A si fonde: al, dal, nel."), examples = listOf(ExampleLine(text = "C'è un bar e ci sono due negozi.", meaning = "c'è uno, ci sono tanti."), ExampleLine(text = "C'è una farmacia qui vicino?", meaning = "La domanda utile."), ExampleLine(text = "Non c'è un cinema qui.", meaning = "La negazione."), ExampleLine(text = "Il bar è davanti al parco.", meaning = "davanti al = delante del."), ExampleLine(text = "Tutto è vicino a casa mia.", meaning = "Il riassunto comodo."))), expressions = listOf(TargetExpression(text = "C'è / ci sono + luogo", meaning = "Dire cosa c'è.", note = "c'è uno, ci sono tanti."), TargetExpression(text = "C'è … qui vicino?", meaning = "Chiedere.", note = "…una farmacia?"), TargetExpression(text = "Non c'è …", meaning = "Quello che manca.", note = "Non c'è cinema."), TargetExpression(text = "davanti a / vicino a", meaning = "Situare.", note = "davanti al parco."), TargetExpression(text = "vicino a casa mia", meaning = "La distanza.", note = "tutto è vicino.")), situation = "Un visitatore chiede del tuo quartiere: nomna quattro posti, di' cosa manca e situa il tuo preferito.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Nomina due posti del tuo quartiere.", expected = listOf("C'è <luogo> e ci sono <luoghi>."), focus = "c'è / ci sono", watch = "c'è uno, ci sono tanti."), PracticeQuestion(prompt = "Di' cosa manca. (cinema)", expected = listOf("Non c'è un cinema nel mio quartiere."), focus = "non c'è", watch = "Non c'è + luogo."), PracticeQuestion(prompt = "Chiedi se c'è una farmacia.", expected = listOf("C'è una farmacia qui vicino?"), focus = "qui vicino", watch = "qui vicino = aquí cerca."), PracticeQuestion(prompt = "Situa il tuo posto preferito.", expected = listOf("<Luogo> è davanti a <luogo>."), focus = "davanti a", watch = "davanti A + luogo."), PracticeQuestion(prompt = "Di' che tutto è vicino a casa tua.", expected = listOf("Tutto è vicino a casa mia."), focus = "vicino a", watch = "vicino A casa mia."))), exercises = listOf(Exercise(id = "it-foundations-u2-quartiere-e1", kind = "choice", prompt = "___ un bar e ci sono due negozi.", options = listOf("C'è", "Ci sono", "È", "Sono"), answers = listOf("C'è"), explain = "C'è per uno solo."), Exercise(id = "it-foundations-u2-quartiere-e2", kind = "gap", prompt = "Non ___ un cinema qui. (esiste)", options = listOf(), answers = listOf("c'è"), explain = "Non c'è + luogo."), Exercise(id = "it-foundations-u2-quartiere-e3", kind = "order", prompt = "Chiedi una farmacia.", options = listOf(), answers = listOf("Ce una farmacia qui vicino"), explain = "C'è + luogo + qui vicino?"), Exercise(id = "it-foundations-u2-quartiere-e4", kind = "written", prompt = "Di' cosa c'è davanti a casa tua.", options = listOf(), answers = listOf("ce <luogo> davanti a casa mia", "c'è <luogo> davanti a casa mia"), explain = "C'è + luogo + davanti a.")), skills = listOf("vocab:town", "grammar:there-is-are", "grammar:prepositions-place", "function:ask-simple-questions"), canDo = listOf("describe-home"), prerequisites = listOf("grammar:there-is-are")),
    Lesson(id = "it-foundations-u2-progetti", title = "Piani per sabato", goal = "Proporre piani con si va a e fissare un appuntamento.", intro = LessonIntro(explanation = listOf("Il futuro vicino: andare a + infinito. « Sabato si va al mercato » oppure « noi andiamo al mercato ».", "Proporre: « Andiamo al mercato? », « Vuoi venire? ». Darsi appuntamento: « Ci vediamo alle sei in piazza? »", "Confermare con ora e luogo: « Perfetto, alle sei davanti al parco ». Un piano senza luogo è un desiderio."), examples = listOf(ExampleLine(text = "Sabato andiamo al mercato.", meaning = "Presente con valore di futuro."), ExampleLine(text = "Vuoi venire con noi?", meaning = "L'invito."), ExampleLine(text = "Ci vediamo alle sei in piazza?", meaning = "L'appuntamento."), ExampleLine(text = "Perfetto, ci vediamo lì.", meaning = "La conferma."), ExampleLine(text = "Se piove, lo spostiamo a domenica.", meaning = "Il piano B."))), expressions = listOf(TargetExpression(text = "andiamo a + infinito", meaning = "Il progetto.", note = "andiamo al mercato."), TargetExpression(text = "Vuoi venire?", meaning = "Invitare.", note = "venire con noi."), TargetExpression(text = "Ci vediamo alle … in …", meaning = "L'appuntamento.", note = "ci vediamo = nos vemos."), TargetExpression(text = "Perfetto / D'accordo", meaning = "Confermare.", note = "d'accordo = de acuerdo."), TargetExpression(text = "Se piove, …", meaning = "Il piano B.", note = "se + presente + piano.")), situation = "Organizzi il sabato con un amico: mercato, appuntamento alle sei davanti al parco, e piano B se piove.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Proponi il mercato con noi.", expected = listOf("Sabato andiamo al mercato."), focus = "andiamo", watch = "noi andiamo = presente per il futuro."), PracticeQuestion(prompt = "Invita il tuo amico.", expected = listOf("Vuoi venire con noi?"), focus = "venire", watch = "venire CON noi."), PracticeQuestion(prompt = "Fissa l'appuntamento. (6, piazza)", expected = listOf("Ci vediamo alle sei in piazza?"), focus = "ci vediamo", watch = "ci vediamo alle + ora."), PracticeQuestion(prompt = "Dai il piano B se piove.", expected = listOf("Se piove, lo spostiamo a domenica."), focus = "se + presente", watch = "se + presente + piano."), PracticeQuestion(prompt = "Invita il tuo amico al piano.", expected = listOf("Vuoi venire con noi?"), focus = "venire", watch = "venire CON noi."))), exercises = listOf(Exercise(id = "it-foundations-u2-progetti-e1", kind = "choice", prompt = "Sabato ___ al mercato.", options = listOf("andiamo", "vado", "va", "andare"), answers = listOf("andiamo"), explain = "noi andiamo: presente per il futuro."), Exercise(id = "it-foundations-u2-progetti-e2", kind = "gap", prompt = "Ci ___ alle sei in piazza? (vedersi)", options = listOf(), answers = listOf("vediamo"), explain = "ci vediamo = nos vemos."), Exercise(id = "it-foundations-u2-progetti-e3", kind = "order", prompt = "Fissa l'appuntamento.", options = listOf(), answers = listOf("Ci vediamo alle sei in piazza"), explain = "ci vediamo + alle + ora + in + luogo."), Exercise(id = "it-foundations-u2-progetti-e4", kind = "written", prompt = "Il piano B se piove.", options = listOf(), answers = listOf("se piove lo spostiamo a domenica", "se piove andiamo al cinema"), explain = "se + presente + piano.")), skills = listOf("grammar:going-to", "function:make-future-plans", "vocab:social-expressions", "grammar:present-questions"), canDo = listOf("make-future-plans"), prerequisites = listOf("grammar:going-to"))))
}

object ItFoundationsU3 {
    val unit = CourseUnit(id = "it-foundations-u3", title = "Il passato", subtitle = "Cosa hai fatto ?", level = "A2", themes = listOf(ConversationTheme("weekend-passato", "Il weekend passato", "Passato prossimo", "clock.arrow.circlepath", "Course", "Raccontate il weekend: cosa avete fatto, dove siete andati.", 0),
