                ConversationTheme("it-c1-sfumature", "Più o meno", "Sfumare le opinioni", "sparkles", "Course", "Valutate una proposta con tatto: accordo parziale, rilievo gentile, chiusura chiara.", 1)), lessons = listOf(    Lesson(id = "it-foundations-u9-registro", title = "Come lo dico", goal = "Dire la stessa cosa in due registri: l'email formale alla dirigenza e il messaggio al collega.", intro = LessonIntro(explanation = listOf("Il registro è la veste della lingua: « Le scrivo per informarLa che la riunione è stata rinviata » e « Ehi, la riunione è slittata » dicono la stessa cosa in due mondi diversi.", "Nel formale: Lei con la maiuscola, forme piene, nessuna elisione (« Le invio », « in allegato », « La ringrazio in anticipo »). Nel colloquiale: tu, elisioni (« ti mando », « facciamo »), battute brevi.", "I connettivi tengono insieme i due mondi: « pertanto » e « tuttavia » reggono la relazione; « comunque » e « infatti » la chat."), examples = listOf(ExampleLine(text = "Le scrivo per informarLa che la riunione è stata rinviata a giovedì.", meaning = "Email formale: Lei + passivo."), ExampleLine(text = "Ehi, la riunione è slittata a giovedì.", meaning = "Stessa notizia in chat, registro colloquiale."), ExampleLine(text = "La ringrazio in anticipo per la Sua disponibilità.", meaning = "Chiusura formale, prima della risposta."), ExampleLine(text = "Ti ringrazio mille, mi hai tolto un peso!", meaning = "Ringraziamento caloroso tra pari."), ExampleLine(text = "Pertanto, La invito a confermare la Sua partecipazione entro venerdì.", meaning = "Connettivo formale + richiesta precisa."))), expressions = listOf(TargetExpression(text = "Le scrivo per…", meaning = "Apertura formale di email.", note = "Le scrivo per confermare la riunione."), TargetExpression(text = "in allegato", meaning = "Trasmettere un file.", note = "In allegato Le invio il preventivo."), TargetExpression(text = "La ringrazio in anticipo", meaning = "Chiusura cortese.", note = "Si usa prima di ricevere la risposta."), TargetExpression(text = "slittare", meaning = "Posticiparsi (di un impegno).", note = "La riunione è slittata di una settimana."), TargetExpression(text = "pertanto", meaning = "Connettivo formale di conclusione.", note = "Pertanto Le chiedo una conferma.")), situation = "Riscrivete la stessa notizia due volte: un'email alla dirigenza e un messaggio al collega di fiducia. Poi leggete le due versioni ad alta voce e confrontate i registri.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Apri un'email formale per confermare la tua presenza alla riunione.", expected = listOf("le scrivo per confermare la mia presenza di giovedì", "le scrivo per confermare la mia presenza di giovedi", "le confermo la mia presenza"), focus = "Le + verbo pieno", watch = "Mai « Ciao »; Lei con la maiuscola nell'email."), PracticeQuestion(prompt = "Comunica in modo formale che il documento richiesto è allegato.", expected = listOf("in allegato le invio il documento", "le invio in allegato il documento richiesto", "allego il documento richiesto"), focus = "in allegato", watch = "« allegato » singolare per un solo file."), PracticeQuestion(prompt = "Rendi colloquiale la notizia che l'incontro è stato posticipato.", expected = listOf("l'incontro è slittato", "l'incontro e slittato", "la riunione è slittata"), focus = "slittare", watch = "Colloquiale: « slittare » invece di « rinviare »."), PracticeQuestion(prompt = "Chiudi l'email ringraziando prima ancora di ricevere la risposta.", expected = listOf("la ringrazio in anticipo", "la ringrazio in anticipo per la disponibilità", "ringrazio sin d'ora per l'attenzione"), focus = "in anticipo", watch = "« in anticipo » si usa prima del ricevimento."), PracticeQuestion(prompt = "Chiedi formalmente una conferma entro venerdì, aprendo col connettivo conclusivo che vale « per questo motivo ».", expected = listOf("pertanto le chiedo una conferma entro venerdì", "pertanto le chiedo una conferma entro venerdi", 