    Lesson(id = "it-foundations-u9-sfumature", title = "Più o meno", goal = "Sfumare opinioni e giudizi per discutere senza scontri: distacco, concessione, morbidezza.", intro = LessonIntro(explanation = listOf("Per non suonare categorici, l'italiano professionale sfuma: « in un certo senso, è una buona base di lavoro » accorda senza chiudere la discussione.", "« Per così dire » ammorbidisce una parola forte: « è una soluzione, per così dire, provvisoria » avverte senza offendere.", "« A mio avviso » separa l'opinione dalla persona: si discute l'idea, non chi l'ha proposta."), examples = listOf(ExampleLine(text = "In un certo senso, la proposta regge.", meaning = "Accordo parziale, non totale."), ExampleLine(text = "È un promemoria, per così dire, informale.", meaning = "Ammorbidisce il giudizio."), ExampleLine(text = "A mio avviso, va rifinita la parte finale.", meaning = "Opinione personale, tono professionale."), ExampleLine(text = "Direi quasi che è pronta; manca solo la sintesi.", meaning = "Sfuma senza negare."), ExampleLine(text = "Sotto certi aspetti sì, sotto altri no.", meaning = "Opinione divisa, senza scontro."))), expressions = listOf(TargetExpression(text = "in un certo senso", meaning = "Accordo parziale.", note = "In un certo senso, sì; però servono dati."), TargetExpression(text = "per così dire", meaning = "Ammorbidire una parola.", note = "È un registro, per così dire, medio."), TargetExpression(text = "a mio avviso", meaning = "Opinione con distacco.", note = "A mio avviso, conviene rivederla."), TargetExpression(text = "direi quasi", meaning = "Sfumare un'affermazione.", note = "Direi quasi che ci siamo."), TargetExpression(text = "sotto certi aspetti", meaning = "Concessione.", note = "Sotto certi aspetti ha ragione lui.")), situation = "Valutate il progetto di un collega: applaudite con misura, criticate con tatto e chiudete sempre con una proposta, non con un giudizio a secco.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Concorda in parte con la proposta del collega (locuzione di tre parole con « senso »).", expected = listOf("in un certo senso sono d'accordo", "in un certo senso la proposta regge", "in un certo senso hai ragione"), focus = "in un certo senso", watch = "Non « in certo senso »: serve l'articolo."), PracticeQuestion(prompt = "Ammorbidisci il giudizio che la relazione è incompleta (locuzione con « così »).", expected = listOf("la relazione è per così dire ancora una bozza", "è per così dire incompleta", "per così dire è un primo passo"), focus = "per così dire", watch = "Si incornicia tra due virgole."), PracticeQuestion(prompt = "Dai la tua opinione professionale su quale parte rifinire (formula con « avviso »).", expected = listOf("a mio avviso va rifinita la conclusione", "a mio avviso manca solo la sintesi", "a mio avviso il capitolo finale è il più debole"), focus = "a mio avviso", watch = "Regge l'indicativo: « a mio avviso va… »."), PracticeQuestion(prompt = "Dì che il progetto è quasi pronto senza escludere i difetti (formula con « quasi »).", expected = listOf("direi quasi che è pronto", "direi quasi che il progetto è pronto", "direi quasi di sì"), focus = "direi quasi", watch = "Sfuma senza negare."), PracticeQuestion(prompt = "Riconosci un merito parziale all'altro prima del tuo rilievo (locuzione con « aspetti »).", expected = listOf("sotto certi aspetti ha ragione", "sotto certi aspetti la sua analisi funziona", "hai ragione sotto certi aspetti"), focus = "sotto certi aspetti", watch = "Prima la concessione, poi il rilievo."))), exercises = listOf(Exercise(id = "it-foundations-u9-sfumature-e1", kind = "choice", prompt = "« ___ avviso, la proposta merita attenzione. »", options = listOf("A mio", "Al mio", "In mio", "Per mio"), answers = listOf("A mio"), explain = "Formula fissa di distacco: a mio avviso."), Exercise(id = "it-foundations-u9-sfumature-e2", kind = "gap", prompt = "La relazione è, ___, ancora una bozza. (locuzione di tre parole che ammorbidisce)", options = listOf(), answers = listOf("per così dire"), explain = "Per così dire incornicia il giudizio."), Exercise(id = "it-foundations-u9-sfumature-e3", kind = "written", prompt = "Concorda con tatto con l'idea del collega e chiedi una rifinitura: apri con la locuzione che contiene « senso ».", options = listOf(), answers = listOf("in un certo senso l'idea funziona ma va rifinita", "in un certo senso sono d'accordo però chiederei una rifinitura", "in un certo senso sono d'accordo pero chiederei una rifinitura"), explain = "In un certo senso + concessione + richiesta."), Exercise(id = "it-foundations-u9-sfumature-e4", kind = "written", prompt = "Giustifica in tono professionale perché preferisci lavorare in team: apri con la formula che contiene « avviso ».", options = listOf(), answers = listOf("a mio avviso il team aiuta a vedere i punti ciechi", "a mio avviso lavorare in team riduce gli errori", "a mio avviso il team rende le decisioni più solide"), explain = "A mio avviso + motivo professionale.")), skills = listOf("function:express-opinion", "speaking:justify-opinion", "grammar:connectors", "vocab:collocations"), canDo = listOf("express-opinion"), prerequisites = listOf("grammar:connectors")),
    Lesson(id = "it-foundations-u9-presentare", title = "Presentare le idee", goal = "Strutturare un intervento breve in riunione: apertura, transizione, sintesi e chiusura.", intro = LessonIntro(explanation = listOf("Un intervento breve ha tre mosse: aprire con « per iniziare », sviluppare i punti, chiudere con « per concludere ».", "« In sintesi » comprime: due frasi al massimo, poi si passa alla proposta concreta.", "Se cambiate argomento, annunciatelo: « venendo ai costi », « passo ai tempi » tengono il filo e non perdono la sala."), examples = listOf(ExampleLine(text = "Per iniziare, un dato: le iscrizioni sono cresciute.", meaning = "Apertura con un dato."), ExampleLine(text = "Venendo ai costi, restiamo nel budget.", meaning = "Transizione annunciata."), ExampleLine(text = "In sintesi, la prova ha funzionato.", meaning = "Comprime i punti in una frase."), ExampleLine(text = "Per concludere, chiediamo due settimane per il prototipo.", meaning = "Chiusura con richiesta precisa."), ExampleLine(text = "Se posso aggiungere una sfumatura, il campione è ancora grezzo.", meaning = "Entra nel dibattito con garbo."))), expressions = listOf(TargetExpression(text = "per iniziare", meaning = "Aprire l'intervento.", note = "Per iniziare, ringrazio i relatori."), TargetExpression(text = "venendo a…", meaning = "Cambiare punto.", note = "Venendo ai tempi, servono otto settimane."), TargetExpression(text = "in sintesi", meaning = "Comprimere.", note = "In sintesi: sì, ma con risorse."), TargetExpression(text = "per concludere", meaning = "Chiudere.", note = "Per concludere, vi chiedo un feedback."), TargetExpression(text = "se posso aggiungere…", meaning = "Intervenire con garbo.", note = "Se posso aggiungere una sfumatura…")), situation = "Presentate al team una proposta in un minuto: aprite con un dato, sviluppate due argomenti e chiudete con una richiesta precisa, con cosa e quando.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Apri il tuo intervento con un dato sulle iscrizioni (locuzione d'apertura di due parole).", expected = listOf("per iniziare un dato le iscrizioni sono cresciute", "per iniziare ecco un dato sulle iscrizioni", "per iniziare le iscrizioni crescono"), focus = "per iniziare", watch = "Un solo dato, poi si sviluppa."), PracticeQuestion(prompt = "Annuncia che passi ai costi (formula di transizione).", expected = listOf("venendo ai costi", "venendo ai costi restiamo nel budget", "passo ora ai costi"), focus = "venendo a", watch = "« Venendo ai » + plurale."), PracticeQuestion(prompt = "Comprimi in una frase l'esito positivo della prova (formula di sintesi).", expected = listOf("in sintesi la prova ha funzionato", "in sintesi siamo nel budget e nei tempi", "in sintesi il bilancio è positivo"), focus = "in sintesi", watch = "Due frasi al massimo, poi la proposta."), PracticeQuestion(prompt = "Chiudi chiedendo un feedback entro venerdì (locuzione di chiusura).", expected = listOf("per concludere vi chiedo un feedback entro venerdì", "per concludere attendiamo il vostro feedback entro venerdi", "chiudo chiedendovi un feedback entro venerdì"), focus = "per concludere", watch = "La richiesta è precisa: cosa e quando."), PracticeQuestion(prompt = "Entra nel dibattito con garbo per aggiungere una riserva (formula cortese con « se posso »).", expected = listOf("se posso aggiungere una sfumatura il campione è ancora grezzo", "se posso aggiungere qualcosa servono più test", "se posso aggiungere una riserva i tempi sono stretti"), focus = "se posso aggiungere", watch = "La cortesia prima del contenuto."))), exercises = listOf(Exercise(id = "it-foundations-u9-presentare-e1", kind = "choice", prompt = "« ___ iniziare, un dato: le iscrizioni sono cresciute. »", options = listOf("Per", "In", "A", "Da"), answers = listOf("Per"), explain = "Locuzione d'apertura: per iniziare."), Exercise(id = "it-foundations-u9-presentare-e2", kind = "gap", prompt = "___ sintesi, il bilancio della prova è positivo. (preposizione semplice)", options = listOf(), answers = listOf("In"), explain = "In sintesi comprime i punti."), Exercise(id = "it-foundations-u9-presentare-e3", kind = "written", prompt = "Apri il tuo intervento sulle vendite con la locuzione d'apertura seguita da un dato.", options = listOf(), answers = listOf("per iniziare ecco i dati sulle vendite", "per iniziare un dato le vendite sono cresciute", "per iniziare le vendite sono cresciute del dieci per cento"), explain = "Per iniziare + dato."), Exercise(id = "it-foundations-u9-presentare-e4", kind = "written", prompt = "Chiudi il tuo intervento chiedendo due settimane per il prototipo: apri con la locuzione di chiusura.", options = listOf(), answers = listOf("per concludere chiediamo due settimane per il prototipo", "per concludere vi chiedo due settimane per il prototipo", "per concludere servono due settimane per il prototipo"), explain = "Per concludere + richiesta precisa.")), skills = listOf("speaking:sustained-conversation", "function:talk-about-work", "grammar:connectors", "vocab:work"), canDo = listOf("talk-about-work"), prerequisites = listOf("grammar:connectors"))))
