    val unit = CourseUnit(id = "it-foundations-u10", title = "Casa mia", subtitle = "Il mio spazio", level = "A1", themes = listOf(ConversationTheme("casa-stanze", "Le stanze di casa", "C'è / ci sono", "house", "Course", "Entri nel tuo appartamento nuovo: descrivi le stanze e i mobili.", 0),
                ConversationTheme("il-mio-spazio", "Le mie cose", "Dov'è ?", "bed", "Course", "Ogni cosa al suo posto: cerchi le tue cose e presenti il coinquilino.", 1)), lessons = listOf(    Lesson(id = "it-foundations-u10-casa", title = "Il mio appartamento", goal = "Descrivere le stanze e i mobili di casa con c'è e ci sono.", intro = LessonIntro(explanation = listOf("Per una cosa usi c'è: « Nella cucina c'è un tavolo ». Per più cose usi ci sono: « Nella cucina ci sono due sedie ».", "La domanda è semplice: « C'è il bagno ? » — « Sì, c'è ». E la negazione: « Non c'è la lavatrice ».", "Le stanze di casa: « la cucina », « la camera da letto », « il bagno », « il soggiorno ». « Il soggiorno è grande e luminoso »."), examples = listOf(ExampleLine(text = "C'è un divano nel soggiorno.", meaning = "Una cosa sola."), ExampleLine(text = "Ci sono due camere.", meaning = "Più cose."), ExampleLine(text = "Non c'è la lavatrice.", meaning = "Negare."), ExampleLine(text = "Il bagno è piccolo ma pulito.", meaning = "Descrivere una stanza."), ExampleLine(text = "La cucina è grande ?", meaning = "Chiedere di una stanza."))), expressions = listOf(TargetExpression(text = "c'è + singolare", meaning = "Una cosa sola.", note = "C'è un tavolo."), TargetExpression(text = "ci sono + plurale", meaning = "Più cose.", note = "Ci sono due sedie."), TargetExpression(text = "non c'è / non ci sono", meaning = "Negare.", note = "Non c'è la lavatrice."), TargetExpression(text = "C'è … ?", meaning = "Chiedere.", note = "C'è il bagno ?"), TargetExpression(text = "la camera da letto", meaning = "La stanza per dormire.", note = "La camera è luminosa.")), situation = "Entri nel tuo appartamento nuovo e lo descrivi a un'amica: la cucina, il soggiorno e le due camere.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Dì dove sta il divano: nel soggiorno.", expected = listOf("Nel soggiorno c'è un divano.", "Nel soggiorno c'e un divano.", "In soggiorno c'è un divano."), focus = "c'è", watch = "c'è = hay (una cosa)."), PracticeQuestion(prompt = "Conta i mobili della cucina: due sedie.", expected = listOf("In cucina ci sono due sedie.", "Nella cucina ci sono due sedie."), focus = "ci sono", watch = "ci sono = hay (plurale)."), PracticeQuestion(prompt = "Dì che la lavatrice manca.", expected = listOf("Non c'è la lavatrice.", "Non c'e la lavatrice.", "Non c'è lavatrice."), focus = "non c'è", watch = "non c'è = no hay."), PracticeQuestion(prompt = "Chiedi se la casa ha il bagno.", expected = listOf("C'è il bagno ?", "C'e il bagno ?", "C'è un bagno ?"), focus = "c'è…?", watch = "Domanda con c'è."), PracticeQuestion(prompt = "Descrivi la tua camera: piccola ma luminosa.", expected = listOf("La camera è piccola ma luminosa.", "La mia camera è piccola ma luminosa.", "La camera e piccola ma luminosa."), focus = "essere + aggettivo", watch = "ma = pero."), PracticeQuestion(prompt = "Contiamo le finestre del soggiorno: due.", expected = listOf("Nel soggiorno ci sono due finestre.", "In soggiorno ci sono due finestre."), focus = "ci sono", watch = "Due cose → ci sono."))), exercises = listOf(Exercise(id = "it-foundations-u10-casa-e1", kind = "choice", prompt = "___ un divano nel soggiorno.", options = listOf("C'è", "Ci sono", "Sono", "Hanno"), answers = listOf("C'è"), explain = "Una cosa sola → c'è."), Exercise(id = "it-foundations-u10-casa-e2", kind = "gap", prompt = "Nella cucina ___ due sedie. (essere)", options = listOf(), answers = listOf("ci sono"), explain = "Plurale → ci sono."), Exercise(id = "it-foundations-u10-casa-e3", kind = "order", prompt = "Descrivi il bagno: piccolo, ma pulito.", options = listOf(), answers = listOf("Il bagno è piccolo ma pulito"), explain = "essere + aggettivo."), Exercise(id = "it-foundations-u10-casa-e4", kind = "written", prompt = "Descrivi il soggiorno: una finestra grande.", options = listOf(), answers = listOf("Nel soggiorno c'è una finestra grande.", "Nel soggiorno c'e una finestra grande.", "In soggiorno c'è una f