    Lesson(id = "it-foundations-u10-posti", title = "Dov'è ?", goal = "Dire dov'è una cosa: sopra, sotto, accanto a.", intro = LessonIntro(explanation = listOf("Per chiedere dove sta una cosa: « Dov'è il gatto ? ». La risposta usa il posto: « È sotto il letto ».", "Sopra = sulla superficie: « Il libro è sopra il tavolo ». Sotto = in basso: « Le scarpe sono sotto il letto ».", "Accanto a = di lato: « La lampada è accanto al letto ». Vicino a = non lontano: « Il bagno è vicino alla cucina »."), examples = listOf(ExampleLine(text = "Dov'è il gatto ?", meaning = "Chiedere il posto."), ExampleLine(text = "È sopra il tavolo.", meaning = "Sulla superficie."), ExampleLine(text = "Le chiavi sono sotto il divano.", meaning = "In basso."), ExampleLine(text = "La sedia è accanto al tavolo.", meaning = "Di lato."), ExampleLine(text = "Il bagno è vicino alla cucina.", meaning = "Non lontano."))), expressions = listOf(TargetExpression(text = "Dov'è … ?", meaning = "Chiedere il posto.", note = "Dov'è il gatto ?"), TargetExpression(text = "sopra", meaning = "Sulla superficie.", note = "sopra il tavolo."), TargetExpression(text = "sotto", meaning = "In basso.", note = "sotto il letto."), TargetExpression(text = "accanto a", meaning = "Di lato.", note = "accanto al letto."), TargetExpression(text = "vicino a", meaning = "Non lontano.", note = "vicino alla finestra.")), situation = "Cerchi le tue cose in casa: il libro è sopra il tavolo, le chiavi sono sotto il divano e la lampada è accanto al letto.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Dì dove sta il libro: sulla superficie del tavolo.", expected = listOf("Il libro è sopra il tavolo.", "Il libro e sopra il tavolo.", "Sta sopra il tavolo."), focus = "sopra", watch = "sopra = encima de."), PracticeQuestion(prompt = "Dì dove stanno le scarpe: in basso.", expected = listOf("Le scarpe sono sotto il letto.", "Sono sotto il letto."), focus = "sotto", watch = "sotto = debajo de."), PracticeQuestion(prompt 