    Lesson(id = "it-foundations-u11-indicazioni", title = "Come arrivo ?", goal = "Chiedere e dare indicazioni semplici: dritto, sinistra, destra, vicino.", intro = LessonIntro(explanation = listOf("Per chiedere la strada: « Scusi, come arrivo al supermercato ? ». La risposta usa vada: « Vada sempre dritto ».", "Per girare: « Alla piazza giri a sinistra ». Poi la distanza: « Il supermercato è lì, vicino al parco ».", "Per ringraziare: « Grazie mille ! ». La risposta: « Prego ! »."), examples = listOf(ExampleLine(text = "Scusi, come arrivo alla stazione ?", meaning = "Chiedere la strada."), ExampleLine(text = "Vada sempre dritto.", meaning = "Indicazione."), ExampleLine(text = "All'angolo giri a sinistra.", meaning = "Indicazione."), ExampleLine(text = "È vicino, cinque minuti a piedi.", meaning = "Distanza."), ExampleLine(text = "Grazie mille ! — Prego !", meaning = "Educate."))), expressions = listOf(TargetExpression(text = "come arrivo a/al/alla … ?", meaning = "Chiedere la strada.", note = "come arrivo al supermercato ?"), TargetExpression(text = "vada sempre dritto", meaning = "Indicazione.", note = "dritto fino alla piazza."), TargetExpression(text = "giri a sinistra/destra", meaning = "Girare.", note = "giri a destra alla farmacia."), TargetExpression(text = "è vicino / è lì", meaning = "Distanza corta.", note = "è lì, vicino al parco."), TargetExpression(text = "grazie mille — prego", meaning = "Educate.", note = "Prego !")), situation = "Cerchi il supermercato: una signora ti spiega la strada e tu ringrazi.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Chiedi la strada per il supermercato.", expected = listOf("Scusi, come arrivo al supermercato ?", "Come arrivo al supermercato ?"), focus = "come arrivo", watch = "come arrivo a…? = ¿cómo llego a…?"), PracticeQuestion(prompt = "Dai l'indicazione: sempre dritto.", expected = listOf("Vada sempre dritto.", "Vada dritto."), focus = "vada dritto", watch = "vada = formal (usted)."), PracticeQuestion(prompt = "Dai l'indicazione: alla piazza, a sinistra.", expected = listOf("Alla piazza giri a sinistra.", "Giri a sinistra alla piazza."), focus = "giri a sinistra", watch = "giri = gire; sinistra = izquierda."), PracticeQuestion(prompt = "Dai la distanza: cinque minuti a piedi.", expected = listOf("È vicino, cinque minuti a piedi.", "E vicino, cinque minuti a piedi."), focus = "è vicino", watch = "vicino = cerca."), PracticeQuestion(prompt = "Ringrazia con forza.", expected = listOf("Grazie mille !", "Grazie mille"), focus = "grazie mille", watch = "mille = mil."), PracticeQuestion(prompt = "Rispondi a un grazie.", expected = listOf("Prego !", "Prego"), focus = "prego", watch = "prego = de nada."))), exercises = listOf(Exercise(id = "it-foundations-u11-indicazioni-e1", kind = "choice", prompt = "Scusi, come arrivo ___ supermercato ?", options = listOf("al", "allo", "a il", "della"), answers = listOf("al"), explain = "a + il → al."), Exercise(id = "it-foundations-u11-indicazioni-e2", kind = "gap", prompt = "Vada sempre ___, poi giri a destra. (avanti, linea retta)", options = listOf(), answers = listOf("dritto"), explain = "andare dritto = seguir recto."), Exercise(id = "it-foundations-u11-indicazioni-e3", kind = "order", prompt = "Dai l'indicazione: dritto.", options = listOf(), answers = listOf("Vada sempre dritto"), explain = "vada + sempre + dritto."), Exercise(id = "it-foundations-u11-indicazioni-e4", kind = "written", prompt = "Dì che il supermercato è a poca distanza: due minuti a piedi.", options = listOf(), answers = listOf("Il supermercato è vicino.", "Il supermercato e vicino.", "È vicino, due minuti a piedi."), explain = "vicino + minuti a piedi.")), skills = listOf("function:ask-for-directions", "vocab:directions", "grammar:present-simple", "vocab:town"), canDo = listOf("ask-for-directions"), prerequisites = listOf("grammar:present-simple")),
