    Lesson(id = "it-foundations-u12-amici", title = "Com'è ?", goal = "Descrivere amici e parenti con gli aggettivi: simpatico, timido, lavoratore.", intro = LessonIntro(explanation = listOf("Per descrivere una persona si usa essere + aggettivo: « Marco è simpatico. Giulia è simpatica. » Maschile in -o, femminile in -a.", "Al plurale l'aggettivo cambia: « I miei amici sono simpatici. Le mie amiche sono simpatiche. »", "Aggettivi utili per il carattere: « Luca è timido, non parla molto. Paolo è lavoratore, lavora tanto. » Per chiedere: « Com'è Giulia ? »"), examples = listOf(ExampleLine(text = "Marco è simpatico.", meaning = "Maschile: simpatico."), ExampleLine(text = "Giulia è simpatica.", meaning = "Femminile: simpatica."), ExampleLine(text = "Luca è un po' timido.", meaning = "Timido: non parla molto."), ExampleLine(text = "Paolo è molto lavoratore.", meaning = "Lavoratore: lavora tanto."), ExampleLine(text = "Le mie amiche sono gentili.", meaning = "Plurale femminile: -i / -e."))), expressions = listOf(TargetExpression(text = "Com'è … ?", meaning = "Chiedere il carattere.", note = "Com'è Marco ? È simpatico."), TargetExpression(text = "simpatico / simpatica", meaning = "Gentile, piacevole.", note = "Plurale: simpatici / simpatiche."), TargetExpression(text = "timido / timida", meaning = "Non parla molto.", note = "Mia cugina è timida."), TargetExpression(text = "lavoratore / lavoratrice", meaning = "Lavora molto.", note = "Paolo è molto lavoratore."), TargetExpression(text = "un po' …", meaning = "Un piccolo grado.", note = "È un po' timido.")), situation = "Alla festa di Giulia ci sono amici nuovi: chi è simpatico, chi è timido — e tu descrivi le persone.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Descrivi Marco: piacevole.", expected = listOf("Marco è simpatico.", "Marco e simpatico."), focus = "simpatico", watch = "Maschile: simpatico."), PracticeQuestion(prompt = "Descrivi Anna: piacevole.", expected = listOf("Anna è simpatica.", "Anna e simpatica."), focus = "simpatica", watch = "Femminile: simpatica."), PracticeQuestion(prompt = "Luca non parla molto. Descrivilo.", expected = listOf("Luca è timido.", "Luca e timido.", "Luca è un po' timido."), focus = "timido", watch = "Timido = persona riservata."), PracticeQuestion(prompt = "Paolo lavora tanto. Descrivilo.", expected = listOf("Paolo è lavoratore.", "Paolo e lavoratore."), focus = "lavoratore", watch = "Lavoratore = lavora molto."), PracticeQuestion(prompt = "Chiedi il carattere di Giulia.", expected = listOf("Com'è Giulia ?", "Com'e Giulia ?"), focus = "com'è", watch = "Com'è = come + è."))), exercises = listOf(Exercise(id = "it-foundations-u12-amici-e1", kind = "choice", prompt = "Giulia parla con tutti: è molto ___.", options = listOf("simpatica", "simpatico", "simpatici", "simpatiche"), answers = listOf("simpatica"), explain = "Giulia è femminile singolare: simpatica."), Exercise(id = "it-foundations-u12-amici-e2", kind = "gap", prompt = "Luca non parla molto: è ___.", options = listOf(), answers = listOf("timido"), explain = "Timido = persona riservata, che parla poco."), Exercise(id = "it-foundations-u12-amici-e3", kind = "order", prompt = "Descrivi due amici simpatici.", options = listOf(), answers = listOf("Marco e Anna sono simpatici"), explain = "Nome + essere + aggettivo plurale."), Exercise(id = "it-foundations-u12-amici-e4", kind = "written", prompt = "Descrivi il tuo amico Marco: simpatico e un po' timido.", options = listOf(), answers = listOf("Marco è simpatico e un po' timido.", "Marco e simpatico e un po timido.", "Marco e simpatico e un po' timido."), explain = "essere + due aggettivi per il carattere.")), skills = listOf("function:describe-people", "grammar:present-simple", "vocab:feelings", "function:ask-simple-questions"), canDo = listOf("describe-people"), prerequisites = listOf("grammar:present-simple")),
    Lesson(id = "it-foundations-u12-chiamata", title = "Una telefonata", goal = "Telefonare: pronto ?, c'è … ? e il richiamo dopo.", intro = LessonIntro(explanation = listOf("Al telefono si inizia con « Pronto ? » e ci si presenta: « Pronto, sono Luca. »", "Per chiedere di una persona si usa c'è: « C'è Anna ? » Le risposte: « Sì, un momento » oppure « No, non c'è. »", "Se la persona non c'è, si lascia un messaggio e si richiama: « Posso lasciare un messaggio ? Richiamo dopo. »"), examples = listOf(ExampleLine(text = "Pronto ? Sono Luca.", meaning = "Ci si presenta al telefono."), ExampleLine(text = "C'è Maria, per favore ?", meaning = "Chiedere di una persona."), ExampleLine(text = "No, non c'è.", meaning = "La persona non è presente."), ExampleLine(text = "Un momento, la chiamo.", meaning = "Chiamare la persona."), ExampleLine(text = "Richiamo dopo, grazie.", meaning = "Chiamare più tardi."))), expressions = listOf(TargetExpression(text = "Pronto ?", meaning = "La prima parola al telefono.", note = "Pronto, sono Carlo."), TargetExpression(text = "C'è … ?", meaning = "Chiedere di una persona.", note = "C'è Maria, per favore ?"), TargetExpression(text = "Non c'è.", meaning = "La persona non c'è.", note = "È uscita."), TargetExpression(text = "Richiamo dopo.", meaning = "Chiamo più tardi.", note = "Richiamo tra dieci minuti."), TargetExpression(text = "Posso lasciare un messaggio ?", meaning = "Chiedere di lasciare un messaggio.", note = "Sì, certo.")), situation = "Telefoni a Giulia ma non c'è: sua madre risponde e tu lasci un messaggio e richiami dopo.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Rispondi al telefono.", expected = listOf("Pronto ?", "Pronto, chi è ?", "Pronto, chi e ?"), focus = "pronto", watch = "Pronto: la prima parola."), PracticeQuestion(prompt = "Anna è a casa ? Chiedi al telefono.", expected = listOf("C'è Anna ?", "C'e Anna ?", "Pronto, c'e Anna ?"), focus = "c'è", watch = "C'è + nome della persona."), PracticeQues