    val unit = CourseUnit(id = "it-foundations-u13", title = "Il tempo", subtitle = "Giorni e meteo", level = "A1", themes = listOf(ConversationTheme("il-tempo-settimana", "La settimana", "Sempre, spesso, mai", "sun.max", "Course", "Una giornata tipo: il caffè sempre la mattina, il lavoro, e la sera — qualche volta un film, mai sport.", 0),
                ConversationTheme("il-tempo-meteo", "Il meteo", "Che tempo fa ?", "cloud.rain", "Course", "Sabato piove, ma domenica c'è il sole: si decide il weekend guardando il cielo.", 1)), lessons = listOf(    Lesson(id = "it-foundations-u13-routine", title = "Dal mattino alla sera", goal = "Raccontare la giornata con sempre, spesso, qualche volta, mai.", intro = LessonIntro(explanation = listOf("La routine si racconta al presente: « La mattina faccio colazione alle sette e vado al lavoro. »", "Gli avverbi di frequenza dicono quante volte: « Bevo sempre un caffè » (ogni giorno), « Spesso torno tardi » (molte volte), « Qualche volta leggo » (a volte), « Non lavoro mai la domenica » (zero volte).", "Posizione: con essere l'avverbio sta dopo, con gli altri verbi prima: « Sono sempre in ufficio alle nove. Esco sempre alle sei. »"), examples = listOf(ExampleLine(text = "La mattina faccio colazione alle sette.", meaning = "La routine al presente."), ExampleLine(text = "Bevo sempre un caffè al bar.", meaning = "Sempre: ogni giorno."), ExampleLine(text = "Spesso torno a casa tardi.", meaning = "Spesso: molte volte."), ExampleLine(text = "Qualche volta leggo la sera.", meaning = "Qualche volta: a volte."), ExampleLine(text = "La domenica non lavoro mai.", meaning = "Mai: zero volte."))), expressions = listOf(TargetExpression(text = "sempre", meaning = "Ogni volta, il 100%.", note = "Bevo sempre un caffè."), TargetExpression(text = "spesso", meaning = "Molte volte.", note = "Spesso vado in bici."), TargetExpression(text = "qualche volta", meaning = "A volte.", note = "Qualche volta guardo la TV."), TargetExpression(text = "(non) … mai", meaning = "Zero volte.", note = "Non mangio mai la carne."), TargetExpression(text = "di mattina / di sera", meaning = "Le parti della giornata.", note = "Di sera ceno alle otto.")), situation = "Una giornata tipo: sempre il caffè alle sette, spesso in bici, e la sera qualche volta un film, mai sport.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di' la tua routine della mattina: sveglia alle sette.", expected = listOf("Mi sveglio alle sette.", "Mi alzo alle sette.", "Faccio colazione alle sette."), focus = "routine", watch = "Presente + ora: alle sette."), PracticeQuestion(prompt = "Bevi un caffè ogni giorno. Rispondi con sempre.", expected = listOf("Sì, bevo sempre un caffè.", "Si, bevo sempre un caffe.", "Bevo sempre un caffe."), focus = "sempre", watch = "Sempre = ogni giorno."), PracticeQuestion(prompt = "Non mangi la carne. Di' la frase con mai.", expected = listOf("Non mangio mai la carne.", "Mai la carne.", "La carne non la mangio mai."), focus = "non … mai", watch = "Non … mai insieme."), PracticeQuestion(prompt = "A volte vai al cinema. Di' con qualche volta.", expected = listOf("Qualche volta vado al cinema.", "Qualche volta vado al cinema con amici."), focus = "qualche volta", watch = "Qualche volta = a volte."), PracticeQuestion(prompt = "La domenica ? Zero lavoro. Di' con mai.", expected = listOf("La domenica non lavoro mai.", "Domenica non lavoro mai.", "La domenica non studio mai."), focus = "la domenica", watch = "La domenica + non … mai."))), exercises = listOf(Exercise(id = "it-foundations-u13-routine-e1", kind = "choice", prompt = "Bevo ___ un caffè la mattina: ogni giorno !", options = listOf("sempre", "mai", "spesso", "qualche volta"), answers = listOf("sempre"), explain = "Ogni giorno = sempre, il 100% delle volte."), Exercise(id = "it-foundations-u13-routine-e2", kind = "gap", prompt = "La domenica non lavoro ___.", options = listOf(), answers = listOf("mai"), explain = "Non … mai = zero volte."), Exercise(id = "it-foundations-u13-routine-e3", kind = "order", prompt = "Racconta cosa fai spesso la sera.", options = listOf(), answers = listOf("Spesso guardo la televisione la sera"), explain = "Avverbio + verbo + complemento."), Exercise(id = "it-foundations-u13-routine-e4", kind = "written", prompt = "Di' la tua giornata: sveglia alle sette e colazio