    Lesson(id = "it-foundations-u13-meteo", title = "Che tempo fa ?", goal = "Parlare del tempo e delle stagioni: fa caldo, piove, in estate.", intro = LessonIntro(explanation = listOf("Per chiedere: « Che tempo fa ? » Per rispondere si usa fa + aggettivo: « Fa caldo. Fa freddo. Fa bel tempo. »", "Pioggia e neve hanno verbi propri: « Piove, prendi l'ombrello. In inverno nevica. » Con il sole si dice « c'è il sole ».", "Le stagioni: la primavera, l'estate, l'autunno, l'inverno. Con in: « In estate fa caldo. In inverno fa freddo. »"), examples = listOf(ExampleLine(text = "Oggi fa bel tempo.", meaning = "Una bella giornata."), ExampleLine(text = "Fa freddo oggi !", meaning = "Temperatura bassa."), ExampleLine(text = "Piove, prendi l'ombrello.", meaning = "Il verbo piovere."), ExampleLine(text = "In estate fa caldo.", meaning = "La stagione con in."), ExampleLine(text = "In inverno nevica in montagna.", meaning = "Il verbo nevicare."))), expressions = listOf(TargetExpression(text = "Che tempo fa ?", meaning = "La domanda sul meteo.", note = "Fa bello !"), TargetExpression(text = "fa caldo / fa freddo", meaning = "La temperatura.", note = "Oggi fa molto caldo."), TargetExpression(text = "piove / nevica", meaning = "La pioggia e la neve.", note = "Piove da stamattina."), TargetExpression(text = "c'è il sole", meaning = "Una giornata soleggiata.", note = "C'è il sole, usciamo ?"), TargetExpression(text = "in estate / in inverno", meaning = "Le stagioni.", note = "In inverno nevica in montagna.")), situation = "Sabato piove e fa freddo: ombrello e un film a casa. Domenica c'è il sole — si esce !", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Chiedi del tempo a un amico.", expected = listOf("Che tempo fa ?", "Che tempo fa oggi ?"), focus = "che tempo fa", watch = "Fa + tempo."), PracticeQuestion(prompt = "Gennaio, zero gradi. Di' il tempo.", expected = listOf("Fa freddo.", "Fa molto freddo."), focus = "fa freddo", watch = "Fa + freddo."), PracticeQ