    Lesson(id = "it-foundations-u13-gusti", title = "Cosa mi piace", goal = "Dire cosa ti piace: mi piace + infinito o sostantivo.", intro = LessonIntro(explanation = listOf("Per le attività si usa mi piace + infinito: « Mi piace leggere. Mi piace cucinare. »", "Con un sostantivo singolare: « Mi piace il caffè. » Con un sostantivo plurale si usa mi piacciono: « Mi piacciono i film. »", "La negazione è non mi piace: « Non mi piace il freddo. » Per rafforzare: « Mi piace molto nuotare. »"), examples = listOf(ExampleLine(text = "Mi piace leggere la sera.", meaning = "Piace + infinito."), ExampleLine(text = "Mi piace il gelato.", meaning = "Piace + singolare."), ExampleLine(text = "Mi piacciono i film italiani.", meaning = "Plurale: mi piacciono."), ExampleLine(text = "Non mi piace il freddo.", meaning = "La negazione."), ExampleLine(text = "Mi piace molto nuotare.", meaning = "Molto rafforza il gusto."))), expressions = listOf(TargetExpression(text = "mi piace + infinito", meaning = "Le attività.", note = "Mi piace camminare."), TargetExpression(text = "mi piace + singolare", meaning = "Una cosa.", note = "Mi piace la musica."), TargetExpression(text = "mi piacciono + plurale", meaning = "Più cose.", note = "Mi piacciono i libri."), TargetExpression(text = "non mi piace …", meaning = "La cosa che non ti piace.", note = "Non mi piace il freddo."), TargetExpression(text = "anche a me", meaning = "Essere d'accordo.", note = "Mi piace il cinema. — Anche a me !")), situation = "Il weekend si avvicina: ti piace leggere e cucinare, ma il freddo no — e con gli amici sei d'accordo.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Di' che ti piace leggere.", expected = listOf("Mi piace leggere.", "Mi piace leggere la sera."), focus = "mi piace", watch = "Mi piace + infinito."), PracticeQuestion(prompt = "Di' che ti piace la pizza.", expected = listOf("Mi piace la pizza.", "A me piace la pizza."), focus = "mi piace", watch = "Mi piace + singolare."), PracticeQuestion(prompt = "Ti piacciono i film. Di' con piacciono.", expected = listOf("Mi piacciono i film.", "Mi piacciono i film italiani."), focus = "mi piacciono", watch = "Plurale: mi piacciono."), PracticeQuestion(prompt = "Non ti piace il freddo. Di' la negazione.", expected = listOf("Non mi piace il freddo.", "Non mi piace il freddo d'inverno."), focus = "non mi piace", watch = "Non + mi piace."), PracticeQuestion(prompt = "Il tuo amico dice: mi piace il cinema. Concorda.", expected = listOf("Anche a me !", "Anche a me piace il cinema."), focus = "anche a me", watch = "Anche a me = sono d'accordo."))), exercises = listOf(Exercise(id = "it-foundations-u13-gusti-e1", kind = "choice", prompt = "Mi ___ il caffè, tanto !", options = listOf("piace", "piacciono", "piaccio", "piacere"), answers = listOf("piace"), explain = "Il caffè è singolare: mi piace."), Exercise(id = "it-foundations-u13-gusti-e2", kind = "gap", prompt = "Mi ___ i gatti e i cani.", options = listOf(), answers = listOf("piacciono"), explain = "Plurale: mi piacciono i gatti."), Exercise(id = "it-foundations-u13-gusti-e3", kind = "order", prompt = "Di' che ti piace fare una cosa la sera.", options = listOf(), answers = listOf("Mi piace leggere la sera"), explain = "Mi piace + infinito + tempo."), Exercise(id = "it-foundations-u13-gusti-e4", kind = "written", prompt = "Di' due cose che ti piace fare nel weekend.", options = listOf(), answers = listOf("Mi piace leggere e cucinare.", "Mi piace nuotare e camminare.", "Mi piace guardare i film e camminare."), explain = "Mi piace + due infiniti.")), skills = listOf("vocab:hobbies", "grammar:present-simple", "function:talk-about-routines", "vocab:social-expressions"), canDo = listOf("talk-about-routines"), prerequisites = listOf("grammar:present-simple"))))
}

object PtFoundationsU1 {
    val unit = CourseUnit(id = "pt-foundations-u1", title = "First sentences", subtitle = "Say who you are", level = "A1", themes = listOf(ConversationTheme("lang-exchange", "Language-exchange café", "Meet and greet", "person.2", "Course", "You are at a friendly language-exchange café in São Paulo. Meet the learner, exchange names, countries and jobs using the verb ser.", 0),
                ConversationTheme("introductions", "Nice to meet you", "Start somewhere small", "hand.wave", "Connection", "Meet the learner for the first time. Learn their interests through natural introductions.", 1)), lessons = listOf(    Lesson(id = "pt-foundations-u1-ser", title = "The verb “ser”", goal = "Introduce yourself and say who people are with eu sou, você é, ele é, nós somos, eles são.", intro = LessonIntro(explanation = listOf("Every Portuguese sentence needs a subject and a verb. The verb for saying who you are is “ser”.", "Brazilian forms: eu sou, você é, ele/ela é, nós somos, eles/elas são. In Brazil you will hear “a gente é” for we are in casual talk.", "Use ser for identity and origin: “Eu sou a Ana”, “Sou do Brasil”, “Ele é professor”. Origin takes de: “Sou de São Paulo”."), examples = listOf(ExampleLine(text = "Eu sou a Ana. Sou do Brasil.", meaning = "Your name and country."), ExampleLine(text = "Você é meu melhor amigo.", meaning = "A close bond with someone."), ExampleLine(text = "Ela é professora.", meaning = "Someone's profession."), ExampleLine(text = "A gente é muito feliz hoje.", meaning = "A feeling that defines right now (casual we)."), ExampleLine(text = "O café é perto da estação.", meaning = "Where a place is."), ExampleLine(text = "Eles são de São Paulo.", meaning = "Someone's origin."))), expressions = listOf(TargetExpression(text = "Eu sou …", meaning = "Introduce yourself.", note = "With your name or job: Eu sou a Ana. Sou professora."), TargetExpression(text = "Sou do / Sou da …", meaning = "Say where you come from.", note = "Masculine do, feminine da: Sou do Brasil. Sou da Espanha."), TargetExpression(text = "Você é … ?", meaning = "Ask about the other person.", note = "Você é professora? Você é daqui?"), TargetExpression(text = "Sou, sim. / Não, não sou.", meaning = "Short answers to a Você é… ? question.", note = "The sim repeats the verb: Sou, sim."), TargetExpression(text = "Ele é / Ela é …", meaning = "Say what someone else is.", note = "Ele é médico — no article with jobs."), TargetExpression(text = "Prazer em conhecer você.", meaning = "The fixed phrase when you meet someone.", note = "Short and natural: Prazer!")), situation = "You meet someone new at a friendly language-exchange café in São Paulo. Introduce yourselves and ask simple questions with the verb ser.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Oi! Eu sou a Ana. Como você se chama?", expected = listOf("Meu nome é <name>.", "Eu sou o <name>.", "Eu sou a <name>.", "Me chamo <name>."), focus = "Meu nome é / Me chamo", watch = "Answering only the name: accept it, then recast “Meu nome é …”."), PracticeQuestion(prompt = "De onde você é?", expected = listOf("Sou do <country>.", "Sou da <country>.", "Sou de <city>."), focus = "ser + de", watch = "“Sou Brasil” — recast “Sou DO Brasil”: the article joins de."), PracticeQuestion(prompt = "Você é estudante?", expected = listOf("Sou, sim.", "Não, não sou."), focus = "short answers with ser", watch = "One-word “Sim” — recast with the verb: Sou, sim."), PracticeQuestion(prompt = "Como você está hoje?", expected = listOf("Estou bem.", "Estou cansado.", "Estou feliz."), focus = "estar for feelings", watch = "“Sou cansado” — recast “Estou cansado”: feelings take estar."), PracticeQuestion(prompt = "Sua cidade é grande ou pequena?", expected = listOf("É grande.", "É pequena.", "Minha cidade é …"), focus = "é with places", watch = "“Minha cidade grande” — recast “Minha cidade É grande”."), PracticeQuestion(prompt = "Agora somos amigos! De onde é sua família?", expected = listOf("É do <country>.", "Minha família é do <country>.", "É da <country>."), focus = "é for a group's origin", watch = "“Minha família de …” — recast with é."))), exercises = listOf(Exercise(id = "pt-foundations-u1-ser-e1", kind = "choice", prompt = "Ela ___ professora.", options = listOf("é", "és", "sou", "somos"), answers = listOf("é"), explain = "With ele/ela/você, ser becomes é."), Exercise(id = "pt-foundations-u1-ser-e2", kind = "gap", prompt = "Nós ___ de São Paulo.", options = listOf(), answers = listOf("somos"), explain = "With nós, ser é sempre somos."), Exercise(id = "pt-foundations-u1-ser-e3", kind = "order", prompt = "Say where you are from.", options = listOf(), answers = listOf("Sou do Brasil"), explain = "Sou + do/da + country: Sou do Brasil."), Exercise(id = "pt-foundations-u1-ser-e4", kind = "written", prompt = "Introduce yourself in one sentence: say your name.", options = listOf(), answers = listOf("Meu nome é <name>", "Me chamo <name>", "Eu sou <name>"), explain = "Meu nome é Ana / Me chamo Ana — the verb is never dropped.")), skills = listOf("grammar:verb-be", "grammar:subject-pronouns", "function:describe-people", "speaking:short-answer"), canDo = listOf("describe-people"), prerequisites = listOf("grammar:verb-be")),
    Lesson(id = "pt-foundations-u1-questions", title = "Questions & negatives", goal = "Ask yes/no questions and say what is not true, with Você é… ? and não sou.", intro = LessonIntro(explanation = listOf("Brazilian Portuguese asks yes/no questions with rising intonation — same words, same order: “Você é a Ana?” You can also add é at the end: “Você é a Ana, né?”", "Question words go first: “De onde você é?”, “O que é isso?” — and they stay in one piece: onde, o que.", "To negate, put não before the verb: “Não sou a Ana”, “Não somos amigos”. In short answers the verb answers alone: “Sou, sim.”"), examples = listOf(ExampleLine(text = "Você é professora?", meaning = "A yes/no question with é."), ExampleLine(text = "Não sou de São Paulo.", meaning = "A negative with sou."), ExampleLine(text = "De onde você é?", meaning = "Question word + é."), ExampleLine(text = "Ele não é meu irmão.", meaning = "A negative about another person."), ExampleLine(text = "Vocês são vizinhos?", meaning = "Asking a group."), ExampleLine(text = "O que é isso?", meaning = "What is this?"))), expressions = listOf(TargetExpression(text = "Você é … ?", meaning = "Ask a yes/no question.", note = "Add né? at the end in casual talk."), TargetExpression(text = "Não sou …", meaning = "Say what is not true about you.", note = "Não always goes before the verb."), TargetExpression(text = "De onde você é?", meaning = "Ask where someone is from.", note = "De onde, two words."), TargetExpression(text = "Ele não é …", meaning = "Say what someone else is not.", note = "Ele não é meu chefe."), TargetExpression(text = "…, né?", meaning = "Tag a statement to check it.", note = "Você é daqui, né? = ¿verdad?"), TargetExpression(text = "Claro.", meaning = "The natural yes in talk.", note = "Also: Com certeza.")), situation = "You chat with a new neighbour in the lift in São Paulo. Ask simple yes/no questions and say what is and isn't true for you.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Você é daqui?", expected = listOf("Sou, sim.", "Não, não sou daqui."), focus = "short answers", watch = "One-word “Sim” — recast with the verb: Sou, sim."), PracticeQuestion(prompt = "Você é professor ou estudante?", expected = listOf("Sou professor.", "Sou estudante.", "Sou professora."), focus = "choice with ser", watch = "Accept either; the article stays dropped."), PracticeQuestion(prompt = "Sua família é grande?", expected = listOf("É, sim.", "Não, não é grande."), focus = "é in questions about others", watch = "“Não é grande” — não before é."), PracticeQuestion(prompt = "De onde você é, exatamente?", expected = listOf("Sou do <country>.", "Sou da <country>.", "Sou de <city>."), focus = "de onde + sou", watch = "“Sou em São Paulo” — recast with de."), PracticeQuestion(prompt = "Me diga uma coisa que você não é.", expected = listOf("Não sou <job>.", "Não sou do <country>."), focus = "negation with não sou", watch = "“Sou não” doesn't work here — não first."), PracticeQuestion(prompt = "A gente é amigo, né?", expected = listOf("É, a gente é amigo.", "Somos, sim."), focus = "a gente é", watch = "“A gente somos” is wrong — a gente takes é."))), exercises = listOf(Exercise(id = "pt-foundations-u1-questions-e1", kind = "choice", prompt = "___ você de Ribeirão?", options = listOf("É", "És", "Sou", "Somos"), answers = listOf("É"), explain = "With você, the question starts with É."), Exercise(id = "pt-foundations-u1-questions-e2", kind = "gap", prompt = "Ela não é ___ irmã.", options = listOf(), answers = listOf("minha"), explain = "minha for feminine things: minha irmã."), Exercise(id = "pt-foundations-u1-questions-e3", kind = "order", prompt = "Say you are not from Rio.", options = listOf(), answers = listOf("Não sou do Rio"), explain = "Não goes first: Não sou do Rio."), Exercise(id = "pt-foundations-u1-questions-e4", kind = "written", prompt = "Make it negative: \"Sou de Curitiba.\"", options = listOf(), answers = listOf("Não sou de Curitiba"), explain = "não + sou: Não sou de Curitiba.")), skills = listOf("grammar:verb-be", "grammar:present-questions", "function:ask-simple-questions", "speaking:short-answer"), prerequisites = listOf("grammar:subject-pronouns")),
    Lesson(id = "pt-foundations-u1-introduce", title = "Introducing yourself", goal = "Give a complete self-introduction: name, city, nationality and job.", intro = LessonIntro(explanation = listOf("A full Brazilian introduction has four pieces: your name, your city, your nationality and your job.", "For the name: “Meu nome é Ana”, “Me chamo Ana” or “Eu sou a Ana”. For origin: “Sou de São Paulo” — do joins the article: do Brasil, da Espanha.", "Nationalities are lower-case: “sou brasileira”. Jobs with ser drop the article: “sou professora”. Close with “Prazer!” and bounce the question back with “E você?”"), examples = listOf(ExampleLine(text = "Meu nome é Ana. Prazer!", meaning = "Your name plus a polite close."), ExampleLine(text = "Sou de São Paulo, capital.", meaning = "City inside country."), ExampleLine(text = "Sou brasileira, de São Paulo.", meaning = "Nationality plus city."), ExampleLine(text = "Sou enfermeira num hospital.", meaning = "Job plus workplace."), ExampleLine(text = "Tenho vinte e cinco anos.", meaning = "Your age — with ter, not ser."), ExampleLine(text = "E você? O que você faz?", meaning = "Bounce the question back."))), expressions = listOf(TargetExpression(text = "Meu nome é …", meaning = "Give your name.", note = "Also: Me chamo … or Eu sou a/o …"), TargetExpression(text = "Sou + nationality", meaning = "Say your nationality.", note = "brasileira, argentina, portuguesa — lower-case in Portuguese."), TargetExpression(text = "Sou do / da …", meaning = "Say your city or country.", note = "do for masculine, da for feminine: do Brasil, da Espanha."), TargetExpression(text = "Trabalho em …", meaning = "Say where you work.", note = "Trabalho num hospital / numa escola."), TargetExpression(text = "Prazer!", meaning = "Polite close when you meet someone.", note = "Answer: Prazer! or O prazer é meu."), TargetExpression(text = "E você?", meaning = "Bounce the question back.", note = "—Sou de São Paulo. E você?")), situation = "Your first day at a language school in São Paulo. Present yourself completely to the class: name, city, nationality and job.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Como você se chama?", expected = listOf("Meu nome é <name>.", "Me chamo <name>."), focus = "name formulas", watch = "Both are fine; recast the shorter one as Meu nome é for variety."), PracticeQuestion(prompt = "De onde você é?", expected = listOf("Sou do <country>.", "Sou da <country>."), focus = "origin with do/da", watch = "The article joins de: DO Brasil, DA Espanha."), PracticeQuestion(prompt = "Qual é a sua nacionalidade?", expected = listOf("Sou <nationality>."), focus = "nationality with ser", watch = "Lower-case: sou brasileira, not Brasileira."), PracticeQuestion(prompt = "O que você faz?", expected = listOf("Sou <job>.", "Trabalho como <job>."), focus = "jobs without article", watch = "“Sou uma professora” — recast dropping the article."), PracticeQuestion(prompt = "E onde você mora?", expected = listOf("Moro em <city>."), focus = "moro em", watch = "“Moro em São Paulo” — em for cities."), PracticeQuestion(prompt = "Prazer! E você, o que faz?", expected = listOf("Sou <job>."), focus = "bounce back and answer", watch = "Recast with Sou + job."))), exercises = listOf(Exercise(id = "pt-foundations-u1-introduce-e1", kind = "choice", prompt = "___ Ana. Prazer!", options = listOf("Meu nome é", "Meu nome de", "Me chamo em", "Estou"), answers = listOf("Meu nome é"), explain = "Meu nome é + name: one piece."), Exercise(id = "pt-foundations-u1-introduce-e2", kind = "gap", prompt = "Sou ___ Itália. (nationality)", options = listOf(), answers = listOf("italiana"), explain = "Nationality is lower-case: italiana, italiano."), Exercise(id = "pt-foundations-u1-introduce-e3", kind = "order", prompt = "Say your name and city.", options = listOf(), answers = listOf("Sou a Ana e sou de São Paulo"), explain = "Two sou pieces, both with their verb."), Exercise(id = "pt-foundations-u1-introduce-e4", kind = "written", prompt = "Give your complete introduction: name and country.", options = listOf(), answers = listOf("Meu nome é <name> e sou do <country>", "Meu nome é <name> e sou da <country>", "Me chamo <name> e sou do <country>"), explain = "Name + origin, each with its verb.")), skills = listOf("grammar:verb-be", "function:introduce-yourself", "vocab:introductions", "pron:word-stress"), canDo = listOf("introduce-yourself"))))
}

