    val unit = CourseUnit(id = "pt-foundations-u2", title = "Meu dia a dia", subtitle = "Rotina e planos", level = "A1", themes = listOf(ConversationTheme("manha-agitada", "Manhã agitada", "Contra o relógio", "sunrise", "Course", "Você conta a sua manhã minuto a minuto: horas, hábitos e esquecimentos.", 0),
                ConversationTheme("sabado-juntos", "Sábado juntos", "O que vamos fazer?", "figure.walk", "Course", "Planos para sábado com um amigo: feira, hora e lugar do encontro.", 1)), lessons = listOf(    Lesson(id = "pt-foundations-u2-rotina", title = "Minha rotina", goal = "Contar o seu dia no presente com as horas.", intro = LessonIntro(explanation = listOf("O presente conta as rotinas: « Acordo às sete. Tomo café com pão de queijo. Saio de casa às oito. »", "Os dias da semana com plural = toda semana: « aos sábados acordo tarde ».", "As horas com às : « às oito », « às oito e meia ». Com a: « a noite eu fico em casa »."), examples = listOf(ExampleLine(text = "Acordo às sete.", meaning = "O primeiro verbo do dia."), ExampleLine(text = "Tomo café com pão de queijo.", meaning = "O café da manhã."), ExampleLine(text = "Saio de casa às oito.", meaning = "A saída."), ExampleLine(text = "Aos sábados acordo tarde.", meaning = "O hábito do fim de semana."), ExampleLine(text = "Vou para a cama às onze.", meaning = "A hora de dormir."))), expressions = listOf(TargetExpression(text = "Acordo às …", meaning = "Acorde.", note = "acordar às + hora."), TargetExpression(text = "Tomo café …", meaning = "O desjejum.", note = "tomar café da manhã."), TargetExpression(text = "Saio de casa às …", meaning = "A saída.", note = "sair DE casa."), TargetExpression(text = "Aos sábados …", meaning = "O hábito.", note = "aos + dia = todos os."), TargetExpression(text = "Vou para a cama às …", meaning = "Dormir.", note = "ir para a cama.")), situation = "Você conta a sua manhã para um amigo novo: hora de acordar, café, saída — e como muda no sábado.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Diga a que hora você acorda na semana.", expected = listOf("Acordo às <hora> na semana."), focus = "acordar às", watch = "acordar ÀS + hora."), PracticeQuestion(prompt = "Diga o que você toma no café da manhã.", expected = listOf("Tomo <comida> e <comida>."), focus = "t