."), PracticeQuestion(prompt = "Diga que já provou a paella.", expected = listOf("Já provei a paella."), focus = "já", watch = "Já + pretérito."), PracticeQuestion(prompt = "Diga que foi a sua primeira vez.", expected = listOf("Foi a minha primeira vez.", "Foi a primeira vez."), focus = "primeira vez", watch = "foi + primeira vez."), PracticeQuestion(prompt = "Devolva a pergunta: e você ?", expected = listOf("E você ?", "E você, já surfou ?"), focus = "e você", watch = "e você devolve."))), exercises = listOf(Exercise(id = "pt-b1-experiencias-e1", kind = "choice", prompt = "Você já ___ a Roma ?", options = listOf("foi", "vou", "ia", "vai"), answers = listOf("foi"), explain = "ir → foi (pretérito)."), Exercise(id = "pt-b1-experiencias-e2", kind = "gap", prompt = "___ esqueei. (nunca)", options = listOf(), answers = listOf("nunca"), explain = "nunca + pretérito."), Exercise(id = "pt-b1-experiencias-e3", kind = "order", prompt = "Pergunte a experiência: você já comeu caracóis ?", options = listOf(), answers = listOf("Você já comeu caracóis"), explain = "Você já + pretérito + objeto ?"), Exercise(id = "pt-b1-experiencias-e4", kind = "written", prompt = "Diga uma experiência: você já viu esse filme.", options = listOf(), answers = listOf("ja vi esse filme", "já vi esse filme"), explain = "Já + vi (ver → vi).")), skills = listOf("grammar:present-perfect", "grammar:past-simple-irregular", "function:describe-past-events"), canDo = listOf("describe-past-events"), prerequisites = listOf("grammar:past-simple-regular")),
