    Lesson(id = "pt-foundations-u10-colega", title = "Meu colega de casa", goal = "Descrever o colega de casa e usar os possessivos meu, minha, seu.", intro = LessonIntro(explanation = listOf("Os possessivos: « meu » (masc), « minha » (fem). « Meu colega cozinha bem ». « Minha colega estuda à noite ».", "Para falar do outro: « seu, sua ». « Como é o seu colega ? » « A sua casa é grande ? »", "Descrever com « ser »: « Ele é alto e tranquilo ». « Ela é organizada e muito calma »."), examples = listOf(ExampleLine(text = "Meu colega de casa é do Rio.", meaning = "meu + masc."), ExampleLine(text = "Minha colega estuda medicina.", meaning = "minha + fem."), ExampleLine(text = "O seu quarto é arrumado.", meaning = "seu = su."), ExampleLine(text = "Ele cozinha muito bem.", meaning = "Descrever."), ExampleLine(text = "Ela é calma e organizada.", meaning = "ser + adjetivo."))), expressions = listOf(TargetExpression(text = "meu / minha", meaning = "Possessivo: mi, mio.", note = "meu quarto, minha casa."), TargetExpression(text = "seu / sua", meaning = "Possessivo dele/dela.", note = "seu colega, sua sala."), TargetExpression(text = "colega de casa", meaning = "Quem mora junto.", note = "Divido a casa com ele."), TargetExpression(text = "Ele/Ela é …", meaning = "Descrever pessoa.", note = "Ele é alto."), TargetExpression(text = "muito + adjetivo", meaning = "Intensidade.", note = "muito calma.")), situation = "O Rafa chega como novo colega de casa: alto, tranquilo e cozinha aos domingos.", practice = LessonPractice(questions = listOf(PracticeQuestion(prompt = "Diga que o seu colega cozinha bem. (use meu)", expected = listOf("Meu colega cozinha bem.", "meu colega cozinha bem"), focus = "meu", watch = "meu + palavra masculina."), PracticeQuestion(prompt = "Diga que a sua casa é pequena. (use minha)", expected = listOf("Minha casa é pequena.", "minha casa e pequena"), focus = "minha", watch = "minha + palavra feminina."), PracticeQuestion(prompt = "Pergunte como é o colega de casa